\subsection{Debate Strategy}\label{appendix:debate_stratey}
\begin{lstlisting}[language=Python, 
                   basicstyle=\ttfamily\footnotesize,
                   breaklines=true,
                   columns=flexible,
                   backgroundcolor=\color{gray!5}
                   ]
def conduct_debate(self, task: str, output_a: str,  output_b: str, num_rounds: int = 3) -> Dict[str, Any]:
    debate_history = []

    try:
        # Opening statements
        logging.info("\nOpening Statements")

        # Agent 1 (Output A) opening statement
        agent_1_prompt = self.format_debate_prompt(task, output_a, output_b, None, True)
        agent_1_response = self.agent_1(agent_1_prompt)

        # Agent 2 (Output B) opening statement
        agent_2_prompt = self.format_debate_prompt(task, output_a, output_b, None, False)
        agent_2_response = self.agent_2(agent_2_prompt)

        debate_history.append(f"Agent 1 and 2 (defending A and B respectively) debate opening summary: {agent_1_response} {agent_2_response}")

        # Debate rounds
        for round_num in range(1, num_rounds + 1):
            logging.info(f"\nStarting Round {round_num}")

            # Agent 1's rebuttal
            agent_1_prompt = self.format_debate_prompt(task, output_a, output_b, debate_history, True)
            agent_1_response = self.agent_1(agent_1_prompt)

            # Agent 2's rebuttal
            agent_2_prompt = self.format_debate_prompt(task, output_a, output_b, debate_history, False)
            agent_2_response = self.agent_2(agent_2_prompt)

            debate_history.append(f'Agent 1 and 2 (defending A and B respectively) debate rebuttal round {round_num} summary: {agent_1_response} {agent_2_response}')

        final_debate_history_text = "\n".join(debate_history)        
        return

    except Exception as e:
        logging.error(f"Error during debate: {str(e)}")
        return
\end{lstlisting}


