\vspace{-0.06in}
\subsection{Trajectory Embedding}
\vspace{-0.05in}
\label{sec:pre_traj_emb}

\noindent\textbf{Trajectory.} The trajectory $T = [p_1,...,p_n]$ is a sequence of points where each point $p_i = (lon_i,lat_i)$ (or $p_i= (lon_i,lat_i,t_i)$) is a tuple, and $lon_i, lat_i$ (and $t_i$) respectively represent longitude, latitude (and timestamp).

\noindent\textcolor{black}{
\textbf{Trajectory Similarity with Distance Measurement.} Given two trajectories $T_a=[p_{a_1},...,p_{a_n}]$ and $T_b=[p_{b_1},...,p_{b_m}]$, the similarity between $T_a$ and $T_b$ is measured by 
% the distance between the corresponding point sequences $[p_{a_1},...,p_{a_n}]$ and $[p_{b_1},...,p_{b_m}]$, measured using 
specific distance metrics on the corresponding point sequences, such as DTW~\cite{dtw}, Hausdorff~\cite{hausdorff}, SSPD~\cite{sspd}, EDR~\cite{edr}, etc. In particular, the higher the similarity, the lower the trajectory distance. For simplicity, we use $\mathbf{Dist}_*(\cdot,\cdot)$ to denote the trajectory distance.
% To avoid potential misunderstandings on this matter, we use \textbf{trajectory distance}, $\mathbf{Dist}_*(\cdot,\cdot)$, to describe this concept in the subsequent sections.
For instance, the DTW trajectory distance can be succinctly described as follows:
}
\vspace{-0.17in}

\begin{small}
\begin{equation}
\label{sim_dtw_equ}
\begin{aligned}
&\mathbf{Dist}_{D}(T_a, T_b) = DTW[p_{a_n},p_{b_m}]\\[-0.02in]
&DTW[p_{a_i},p_{b_j}] = d(p_{a_i},p_{b_j}) + \min \left(DTW[p_{a_{i-1}},p_{b_j}],\right.\\[-0.03in]
&\quad \quad \quad\quad \quad\quad\quad\quad \left.DTW[p_{a_i},p_{b_{j-1}}],DTW[p_{a_{i-1}},p_{b_{j-1}}]\right)\\[-0.08in]
\end{aligned}
\end{equation}
\end{small}


\noindent where $d(p_{a_i}, p_{b_j})$ represents the Euclidean distance between points $p_{a_i}$ and $ p_{b_j}$.  

\textit{Remark.} To prevent potential misunderstandings, we use \(\mathbf{Dist}_*(\cdot,\cdot)\) interchangeably to represent either trajectory similarity or distance in this paper.


\noindent\textbf{Trajectory Embedding.} 
The concept of trajectory embedding involves identifying an encoding function $g(\cdot)$ called the Trajectory Embedding model, which maps a trajectory onto a d-dimensional vector, represented as $\textbf{x}=g(T)\in \mathbb{R}^d$. 

\noindent\textbf{Trajectory Embedding for Similarity Computation.}
The primary objective of trajectory similarity embedding is to develop an encoder model such that the distance of embedding pair $(\textbf{x}_a,\textbf{x}_b)$, for any trajectory pair $(T_a, T_b)$, closely approximates the provided trajectory distance measure, such as $\mathbf{Dist}_D(T_a, T_b)$.
Prior studies have treated the corresponding trajectory embeddings $\textbf{x}_a$ and $\textbf{x}_b$ as vectors within Euclidean space, employing Euclidean distance to gauge the distance between these vectors. Given a database $\mathcal{T}=\{T_1, T_2,...,T_N \}$ comprising $N$ trajectories, alongside a distance measurement function $\mathbf{Dist}_*(\cdot, \cdot)$, the aim of trajectory similarity embedding is to discover a mapping $g(\cdot)$ that reduces the disparity between the Euclidean distance among trajectory embeddings 
$\mathbf{d}_{Eu}(g(T_i), g(T_j))$
and the actual distance $\mathbf{Dist}_*(T_i, T_j)$ to the minimum. This process can be depicted as follows:
\vspace{-0.22in}

\begin{equation}
\small
\label{eu_embedding}
       \underset{g}{\textbf{argmin}} \sum_{T_i, T_j \in \mathcal{T}} \Big|\ \mathbf{Dist}_*(T_i,T_j) - \mathbf{d}_{Eu}(g(T_i), g(T_j))\ \Big|\\[-0.1in]
\end{equation}


\noindent\textbf{Triangle Inequality in Trajectory Embedding.}
\label{sec:pre_traj_ineq}
Because the trajectory embedding space is a d-dimensional Euclidean space, the embedding distance between different trajectories satisfies the triangle inequality constraint as follows:
\vspace{-0.05in}
\begin{equation}
\small
\label{triangle_inequality1}
\begin{aligned}
    \forall T_a, T_b, T_c \in \mathcal{T},\quad \textbf{x}_*&=g(T_*)\\[-0.03in]
    \textbf{s.t.}\ \mathbf{d}_{Eu}(\textbf{x}_a,\textbf{x}_b)+\mathbf{d}_{Eu}(\textbf{x}_b,\textbf{x}_c) &\geq 
    \mathbf{d}_{Eu}(\textbf{x}_a,\textbf{x}_c)\\[-0.05in]
\end{aligned}
\end{equation}


\noindent\textbf{Triangle Inequality Violation in Trajectory Similarity.} Many trajectory distances, such as DTW and SSPD, don't satisfy the triangle inequality. Specifically, we can use a specific example to clarify this issue as follows.

% However, this constraint contradicts certain actual trajectory distances mentioned above, such as DTW, SSPD, and so on, which don't satisfy the triangle inequality. Specifically, we can use a specific example to clarify this issue as follows.


\begin{figure} % [h!] 帮助确定图片的精确位置
\centering % 使图片居中显示
\vspace{-0.05in}
\includegraphics[width=0.72\linewidth]{figures/example5.png}
\vspace{-0.08in}
\caption{An Example of Triangle Inequality Contradiction} % 图片的标题
\vspace{-0.28in}
\label{fig:example} % 用于文内引用的标签
\end{figure}

\vspace{-0.1in}
\begin{example}
% \small
In Figure~\ref{fig:example}, let $T_a=[(0,0),(0,1),(0,3)]$, $T_b=[(2,0),$ $(0,1),$ $(2,3)]$ and $T_c=[(3,0),(3,1),$ $(4,3),(5,3)]$. Using the DTW distance of Formula \ref{sim_dtw_equ}, the calculated trajectory distances are $\mathbf{Dist}_{D}(T_a, T_b) = 4$, $\mathbf{Dist}_{D}(T_b, T_c) = 9$, and $\mathbf{Dist}_{D}(T_a, T_c) = 15$. Notably, $\mathbf{Dist}_{D}(T_a, T_c) > \mathbf{Dist}_{D}(T_a, T_b) + \mathbf{Dist}_{D}(T_b, T_c)$, which is contradicted with the constraint in Formula~\ref{triangle_inequality1}. 
\end{example}

\vspace{-0.08in}
Consequently, for most similarity methods that do not satisfy the triangle inequality, the approximations of similarity through representation learning might inevitably deviate from the true similarity values. In certain cases, this discrepancy could even amplify, leading to distortions in the trajectory embeddings.

\vspace{-0.09in}
\subsection{Hyperbolic Space and Lorentz Distance}
\label{sec:pre_hyper_loren}
\vspace{-0.05in}

% \marginpar{\vspace{9cm}\scriptsize{\textcolor{blue}{R3.D3}}}
\noindent \textbf{Hyperbolic Space.} To avoid the triangle inequality constraint of high-dimensional embeddings in Euclidean space\footnote{\textcolor{black}{In Euclidean space, the metric must satisfy four conditions, one of which is the triangle inequality. In other words, Euclidean distance is already the metric with the fewest constraints in Euclidean space.}}, we introduce the non-Euclidean hyperbolic space, which has the potential to bypass this limitation~\cite{Colla, learningfeature, Learningcont}. 
In particular, this hyperbolic space is built on the Lorentz inner product, denoted as $\langle\textbf{a}, \textbf{b}\rangle = -a_0b_0 + \sum_{i=1}^{n}a_ib_i$, where $\textbf{a}=[a_0,\cdots,a_{n}]\in \mathbb{R}^{n+1} $ and $\textbf{b}=[b_0,\cdots,b_{n}]\in \mathbb{R}^{n+1} $ are two $n+1$-dimensional vectors. This space consists of all high-dimensional vectors that satisfy a specific condition within the Lorentz inner product, as described below.

\vspace{-0.08in}
\begin{definition}[Hyperbolic Space]
\textcolor{white}{23}

\textcolor{white}{123}

\vspace{-0.4in}

\begin{equation} 
\vspace{-0.02in}
\label{hyper_space}
\small
  \mathcal{H}(\beta) = \{\mathbf{a}\in\mathbb{R}^{n+1}:\ \langle\mathbf{a},\mathbf{a}\rangle = -\beta,\ a_0 \geq \sqrt{\beta}\} \quad (\beta >0)\\[-0.05in]
\end{equation}
where $ \langle\mathbf{a},\mathbf{a}\rangle$ represents the self Lorentz inner product, and $\beta$ is a hyper-parameter that influences the shape of the space.
\end{definition}
\vspace{-0.06in}

\noindent \textbf{Lorentz Distance.} Given a hyperbolic space $\mathcal{H}(\beta)$, we define the function \textit{Lorentz Distance} based on the Lorentz inner product as follows:
\vspace{-0.06in}

\begin{definition}[Lorentz Distance]
\textcolor{white}{23}

\textcolor{white}{123}

\vspace{-0.32in}
\begin{equation}
\label{lorenz_dist}
\small
  \mathbf{d}_{Lo}(\mathbf{a},\mathbf{b}) = |\langle\mathbf{a},\mathbf{b}\rangle| -\beta \qquad (\mathbf{a},\mathbf{b} \in \mathcal{H}(\beta))\\[-0.1in]
\end{equation}
where $|\langle\mathbf{a},\mathbf{b}\rangle|$ means the absolute value of $\langle\mathbf{a},\mathbf{b}\rangle$.
\end{definition}
\vspace{-0.07in}


% We can use the function \textit{Lorentz Distance} to measure the distance between any two embeddings in the space due to its non-negativity and minimal value of self-distance as described in Lemma~\ref{lem:distance}. Additionally, it can relax the constraint of the triangle inequality as explained in Lemma~\ref{lem:triangle}.
