We can use the function \textit{Lorentz Distance} to measure the distance between any two embeddings in the space due to its non-negativity and minimal value of self-distance as described in Lemma~\ref{lem:distance}. Additionally, it can relax the constraint of the triangle inequality as explained in Lemma~\ref{lem:triangle}.
\fi

\vspace{-0.06in}

\begin{lemma}
\label{lem:distance}

$\forall\mathbf{a},\mathbf{b}\in \mathcal{H}(\beta)$, $\mathbf{d}_{Lo}(\mathbf{a},\mathbf{b})\geq 0$, and $\mathbf{d}_{Lo}(\mathbf{a},\mathbf{b})=0$ only when $\mathbf{a}=\mathbf{b}$.
\vspace{-0.09in}

\ifnum\tech=0 

\else

\begin{prf}
\small
\setstretch{1.15}
Suppose $\textbf{a}=[a_0,\cdots,a_n] $ and $\textbf{b}=[b_0,\cdots, b_n]$ are any two embeddings in the space $\mathcal{H}(\beta)$. We have $a_0 \geq \sqrt{\beta}$, $b_0 \geq \sqrt{\beta}$, $a_{0}^{2} - \sum_{i=1}^{n} a_{i}^{2} = \beta$, and $b_{0}^{2} - \sum_{i=1}^{n} b_{i}^{2} = \beta$. Define a function $f(x) = \beta x^2 - 2\langle \textbf{a}, \textbf{b} \rangle x + \beta$. We can further express this function by extending the Lorentz inner product and replacing $\beta$ in the quadratic coefficient and constant term with $a_{0}^{2} - \sum_{i=1}^{n} a_{i}^{2}$ and $b_{0}^{2} - \sum_{i=1}^{n} b_{i}^{2}$, respectively, as follows:
\vspace{-0.25in}

\begin{equation}
\small
\begin{aligned}
    f(x) &= (a_0^2 - \sum_{i=1}^{n} a_i^2)x^2 + 2(a_0 b_0 - \sum_{i=1}^{n} a_i b_i)x + (b_0^2 - \sum_{i=1}^{n} b_i^2) \\[-0.13in]
         &= (a_0 x + b_0)^2 - \sum_{i=1}^{n} (a_i x + b_i)^2\\[-0.12in]
\end{aligned}
\end{equation}
Let $x = -\frac{b_0}{a_0} < 0$. We have:
\vspace{-0.12in}
\begin{equation}
\small
    f\left(-\frac{b_0}{a_0}\right) = - \sum_{i=1}^{n} \left(-a_i \frac{b_0}{a_0} + b_i\right)^2 \leq 0\\[-0.08in]
\end{equation}
Since the quadratic coefficient $\beta > 0$, we have $f(-\infty) > 0$ and $f(+\infty) > 0$. Therefore, the quadratic equation $f(x) = 0$ has at least one root. The discriminant $\Delta$ of $f(x) = 0$ is given by:
\vspace{-0.11in}


\begin{equation}
    \Delta = (2\langle \textbf{a}, \textbf{b} \rangle)^2 - 4 \beta^2 \geq 0 \\[-0.06in]
\end{equation}
Thus, we have $\langle \textbf{a}, \textbf{b} \rangle^2 \geq \beta^2 \Rightarrow |\langle \textbf{a}, \textbf{b} \rangle| \geq \beta \Rightarrow \textbf{d}_{Lo}(\textbf{a}, \textbf{b}) = |\langle \textbf{a}, \textbf{b} \rangle| - \beta \geq 0$.
In particular, if $\textbf{d}_{Lo}(\textbf{a}, \textbf{b}) = |\langle \textbf{a}, \textbf{b} \rangle| - \beta = 0$, we have $f(x)\geq 0$ and only one root for the quadratic equation $f(x) = 0$. Considering that $f(-\frac{b_0}{a_0})\leq 0$, the root should be $x = -\frac{b_0}{a_0} < 0$. The root can also be computed as $x = \frac{-(-2 \langle \textbf{a}, \textbf{b} \rangle)}{2\beta} = \frac{\langle \textbf{a}, \textbf{b} \rangle}{\beta}$ according to the root-finding algorithm. Given that $|\langle \textbf{a}, \textbf{b} \rangle| - \beta = 0$ and $x < 0$, we find the root $x = -1$. Therefore, $x = -\frac{b_0}{a_0} = -1 \Rightarrow a_0 = b_0$. Additionally:

\vspace{-0.3in}
\begin{equation}
    f(-1) = (b_0 - a_0)^2 - \sum_{i=1}^{n} (b_i - a_i)^2 = -\sum_{i=1}^{n} (b_i - a_i)^2 = 0\\[-0.1in]
\end{equation}
Thus, $b_i - a_i = 0$ is satisfied for each $i \in [0, n]$, implying $\textbf{b} = \textbf{a}$.
\vspace{-0.2in}
\end{prf}

\fi


\end{lemma}


\begin{lemma}\label{lem:triangle}
$\exists \mathbf{a},\mathbf{b}, \mathbf{c} \in \mathcal{H}(\beta)$, the triangle inequality $\mathbf{d}_{Lo}(\mathbf{a},\mathbf{b})\leq  \mathbf{d}_{Lo}(\mathbf{a},\mathbf{c}) + \mathbf{d}_{Lo}(\mathbf{b},\mathbf{c})$ is not satisfied.
\vspace{-0.06in}

\ifnum\tech=0 

\else


\begin{prf}
\small
\setstretch{1.15}
We need to find at least one set of three embeddings \(\mathbf{a}, \mathbf{b}, \mathbf{c}\) that does not satisfy this inequality. Given any \(a_0 > \sqrt{\beta}\), consider its corresponding embedding \(\mathbf{a} = [a_0, a_1, \ldots, a_n] \in \mathcal{H}(\beta)\). Thus, we have \(\langle \mathbf{a}, \mathbf{a} \rangle = a_0^2 - \sum_{i=1}^n a_i^2 = -\beta\).
Next, consider another embedding \(\mathbf{b} = [a_0, -a_1, \ldots, -a_n]\). We also have \(\langle \mathbf{b}, \mathbf{b} \rangle = a_0^2 - \sum_{i=1}^n (-a_i)^2 = -\beta\). Therefore, \(\mathbf{b}\) also belongs to \(\mathcal{H}(\beta)\).
Finally, consider the embedding \(\mathbf{c} = [\sqrt{\beta}, 0, \ldots, 0]\), which also belongs to the space due to \(\langle \mathbf{c}, \mathbf{c} \rangle = -(\sqrt{\beta} \cdot \sqrt{\beta}) = -\beta\).
Now, we compute the distances between the three embeddings:
\vspace{-0.3in}

\[
\begin{aligned}
\mathbf{d}_{Lo}(\mathbf{a}, \mathbf{b}) &= |\langle \mathbf{a}, \mathbf{b} \rangle| - \beta = |-a_0^2 + \sum_{i=1}^n -a_i^2| - \beta \\[-0.16in]
&= |-2a_0^2 + (a_0^2-\sum_{i=1}^n a_i^2)| - \beta = 2a_0^2 - 2\beta\\[-0.07in]
\mathbf{d}_{Lo}(\mathbf{a}, \mathbf{c}) &= |\langle \mathbf{a}, \mathbf{c} \rangle| - \beta = |-a_0 \sqrt{\beta}| - \beta = a_0 \sqrt{\beta} - \beta\\[-0.02in]
\mathbf{d}_{Lo}(\mathbf{b}, \mathbf{c}) &= |\langle \mathbf{b}, \mathbf{c} \rangle| - \beta = |-a_0 \sqrt{\beta}| - \beta = a_0 \sqrt{\beta} - \beta
\end{aligned}\]
Therefore, we have:
\vspace{-0.1in}
\[
\mathbf{d}_{Lo}(\mathbf{a}, \mathbf{c}) + \mathbf{d}_{Lo}(\mathbf{b}, \mathbf{c}) = 2a_0 \sqrt{\beta} - 2\beta\\[-0.1in]
\]
Comparing this with \(\mathbf{d}_{Lo}(\mathbf{a}, \mathbf{b})\):
\vspace{-0.15in}

\[
2a_0 \sqrt{\beta} - 2\beta < 2a_0^2 - 2\beta = \mathbf{d}_{Lo}(\mathbf{a}, \mathbf{b})\\[-0.1in]
\]
Thus, we have found three embeddings in the space that do not satisfy the triangle inequality.
\vspace{-0.19in}

\end{prf}
\fi

\end{lemma}

