\vspace{-0.06in}
\begin{theorem}\label{lem:prf_cosh>vanilla}
\(\forall \mathbf{a} = (a_0, a_1)\), \(\mathbf{b} = (b_0, b_1)\in\) \(\mathcal{H}_2(\beta)\), derived from the Cosh Hyperbolic Projection of the 1-dimensional values $a,b$ in the Euclidean space \(\mathcal{E}_{1}\), the Lorentz distance \(\mathbf{d}_{Lo}(\mathbf{a}, \mathbf{b})\) depends on \(|b - a|\) and non-diminished.
\vspace{0.01in}

\begin{prf}
\small
According to Definition of $\phi_{cosh}$, we have \(a_0 = \sqrt{\beta}\cosh(a), a_1 = \sqrt{\beta}\sinh(a)\), \(b_0 = \sqrt{\beta}\cosh(b)\) and \( b_1 = \sqrt{\beta}\sinh(b)\). Let \(b > a\) and \(d = b - a\), then we can conclude that:
\vspace{-0.18in}

\begin{align*}
\mathbf{d}_{Lo}(\mathbf{a}, \mathbf{b}) &= \left|\beta\cosh(a)\cosh(b) - \beta\sinh(a)\sinh(b)\right| - \beta \\[-0.07in]
&= \left|\beta\cosh(a - b)\right| - \beta = \beta(\frac{e^d + e^{-d}}{2} - 1)\\[-0.56in]
\end{align*}
\end{prf}
\end{theorem}

\vspace{-0.05in}
\begin{theorem}\label{lem:dim_reduce}
% \small
For any two vectors  \( \mathbf{a}, \mathbf{b}\in\mathcal{H}_{n+1}(\beta)\), if their components from the 1-st to the n-th dimension are linearly related, the $\mathbf{d}_{Lo}$ between them in \(\mathcal{H}_{n+1}(\beta)\) is consistent with that of two corresponding vectors in \(\mathcal{H}_2(\beta)\).

\ifnum\tech=0

% \else


\vspace{0.03in}
\begin{prf}
\small
For a vector  $\mathbf{a}=(a_0,a_1,\cdots,a_n) \in \mathcal{H}_{n+1}(\beta)= \{\mathbf{x} \in \mathbb{R}^{n+1} : \langle \mathbf{x}, \mathbf{x} \rangle = -\beta, x_0 > 1\}$, its corresponding vector that is linearly related to 1-st to n-th components can be represented as \(\mathbf{b} = (a_0 \frac{\sqrt{\sum_{i=1}^n a_i^2 \alpha^2 + \beta}}{\sqrt{\sum_{i=1}^n a_i^2 + \beta}}, \alpha a_1, ..., \alpha a_n)\). In addition, $\mathbf{a}$ and $\mathbf{b}$ can be considered as vectors $\mathbf{a}'=a_0\mathbf{e}_0+\sqrt{\sum_{i=1}^n a_i^2}\mathbf{e}_1$ and $\mathbf{b}'=a_0 \frac{\sqrt{\sum_{i=1}^n a_i^2 \alpha^2 + \beta}}{\sqrt{\sum_{i=1}^n a_i^2 + \beta}}\mathbf{e}_0+\alpha \sqrt{\sum_{i=1}^n a_i^2}\mathbf{e}_1$ in a 2-dimensional space spanned by the basis vectors \(\mathbf{e}_0\) and \(\mathbf{e}_1\), where \(\mathbf{e}_0 = (1, 0, 0, ..., 0)\) and \(\mathbf{e}_1 = \frac{(0, a_1, a_2, ..., a_n)}{\sqrt{\sum_{i=1}^n a_i^2}}\). In particular, $\mathbf{a}'$ and $\mathbf{b}'$ still lie on the 2-dimensional form of \(\mathcal{H}_2(\beta)= \{\mathbf{x} \in \mathbb{R}^2 : \langle \mathbf{x}, \mathbf{x} \rangle = -\beta\}\) according to the following equations:
\vspace{-0.1in}
{\footnotesize
\[
(a_0)^2- \left(\sqrt{\sum_{i=1}^n a_i^2}\right)^2=a_0^2-\sum_{i=1}^n a_i^2=\beta\\[-0.18in]
\]}

{\scriptsize\[
\hspace{-0.05in}\left(a_0 \frac{\sqrt{\sum_{i=1}^n a_i^2 \alpha^2 \hspace{-0.02in}+ \hspace{-0.02in} \beta}}{\sqrt{\sum_{i=1}^n a_i^2 \hspace{-0.02in}+ \hspace{-0.02in} \beta}}\right)^2\hspace{-0.05in}- \left( \alpha \sqrt{\sum_{i=1}^n a_i^2}\right)^2
\hspace{-0.1in}=\hspace{-0.02in}a_0^2\frac{\sum_{i=1}^n a_i^2 \alpha^2 \hspace{-0.02in}+ \hspace{-0.02in}\beta}{\sum_{i=1}^n a_i^2}-\alpha^2\sum_{i=1}^na_i^2\hspace{-0.02in}= \hspace{-0.02in}\beta.\\[-0.09in]
\]}
In particular, the distance $\mathbf{d}_{Lo}(\mathbf{a},\mathbf{b})$ in $\mathcal{H}_{n+1}(\beta)$ and $\mathbf{d}_{Lo}(\mathbf{a}',\mathbf{b}')$ in $\mathcal{H}_{2}(\beta)$ can be computed as follows:
\vspace{-0.07in}
{\small
\[
\mathbf{d}_{Lo}(\mathbf{a},\mathbf{b})=\big|a_0^2\frac{\sqrt{\sum_{i=1}^n a_i^2 \alpha^2 + \beta}}{\sqrt{\sum_{i=1}^n a_i^2 + \beta}}-\sum_{i=1}^n\alpha a_i^2\big| - \beta\\[-0.09in]
\]
\[
\mathbf{d}_{Lo}(\mathbf{a}',\mathbf{b}')=\big|a_0^2\frac{\sqrt{\sum_{i=1}^n a_i^2 \alpha^2 + \beta}}{\sqrt{\sum_{i=1}^n a_i^2 + \beta}}-\alpha \left(\sqrt{\sum_{i=1}^n a_i^2}\right)^2\big|-\beta\\[-0.11in]
\]
}

Therefore, we have $\mathbf{d}_{Lo}(\mathbf{a},\mathbf{b})=\mathbf{d}_{Lo}(\mathbf{a}',\mathbf{b}')$. Next, according to \textbf{Theorem \ref{lem:prf_cosh>vanilla}}, if $\mathbf{a}'$ and $\mathbf{b}'$ are mapped by $\phi_{cosh}$, we can deduce that $\mathbf{d}_{Lo}(\mathbf{a}',\mathbf{b}')$ is non-diminished, and hence the  $\mathbf{d}_{Lo}(\mathbf{a},\mathbf{b})$ is also non-diminished. 

\end{prf}
\vspace{-0.25in}
\fi

\end{theorem}



\begin{theorem}\label{lem:not_zero}
% \small
Given any two vectors in a hyperbolic space $\mathcal{H}_{n+1}(\beta)$ with the projection $\phi_{cosh}$ on  a Euclidean space $\mathcal{E}_{n}$, we can find a lower bound of the Lorentz distance between the two vectors, where the bound is non-dimished. 
% In using $\phi_{cosh}$ to map vectors in a Euclidean space $\mathcal{E}_{n}$ to the hyperbolic space $\mathcal{H}_{n+1}(\beta)$, for any 2 vector in n+1-dimensional $\mathcal{H}_{n+1}(\beta)$, $\mathbf{d}_{Lo}$ always has a none-zero lower boundary, avoiding $\mathbf{d}_{Lo}\rightarrow0$ caused by excessive norm.
\vspace{-0.02in}


\begin{prf}
\small
For Any vector $\mathbf{b}=(p_0,p_1,...p_n),\mathbf{c}=(q_0,q_1,...,q_n) \in \mathcal{H}_{n+1}(\beta)$,
We can always find a vector \(\mathbf{a} \in \mathcal{H}(\beta)\) that is linearly related to \(\mathbf{b}\) from the 1-st to \(n\)-th dimensions and identical to \(\mathbf{c}\) in the 0-th dimension as follows:
\vspace{-0.22in}
\[
\mathbf{a}=(q_0,kp_1,...,kp_n)\quad k = \sqrt{\frac{\sum_{i=1}^nq_i^2}{\sum_{i=1}^np_i^2}}\\[-0.08in]
\]
For the sake of simplicity, we can use \(\mathbf{a}\) to re-express \(\mathbf{b}\) and \(\mathbf{c}\) as follows:
\vspace{-0.21in}
{\footnotesize
\[
\mathbf{a} = (a_0,a_1,...,a_n),\  \mathbf{b}= (a_0\mu_{\mathbf{a}},\alpha a_1,...\alpha a_n), \  \mu_{\mathbf{a}}= \frac{\sqrt{\sum_{i=1}^na_i^2\alpha^2+\beta}}{\sqrt{\sum_{i=1}^na_i^2+\beta}}\\[-0.08in]
\]
}
{\footnotesize
\[
\mathbf{c}= \left(a_0,a_1(1+\delta_1),...,a_{n-1}(1+\delta_{n-1}),\sqrt{a_n^2 -\sum_{i=1}^{n-1}(\delta_i^2+2\delta_i)a_i^2}\right)\\[-0.08in]
\]
}
where we use \(p_i\) and \(q_i\) to inversely solve for the relevant parameters:
\vspace{-0.25in}

\[
\alpha =\frac{1}{k}, \quad \delta_i=\frac{q_i}{kp_i}-1,\quad a_0=q_0, \quad a_i=kp_i\\[-0.08in]
\]
Next, we can compute \(\mathbf{d}_{Lo}(\mathbf{b},\mathbf{c})\) for the arbitrary vectors $\mathbf{b}, \mathbf{c}$ and  \(\mathbf{d}_{Lo}(\mathbf{b},\mathbf{a})\) for $\mathbf{a}, \mathbf{b}$ as follows:
\vspace{-0.16in}
{\scriptsize
\[
\mathbf{d}_{Lo}(\mathbf{a},\mathbf{b})=|a_0^2\mu_{\mathbf{a}}-\alpha\sum_{i=1}^na_i^2|-\beta \\[-0.1in]
\]
}
{\scriptsize
\[
\mathbf{d}_{Lo}(\mathbf{b},\mathbf{c})=\left|a_0^2\mu_{\mathbf{a}}-\sum_{i=1}^{n-1}\alpha(1+\delta_i)a_i^2-\alpha a_n^2\sqrt{1-\sum_{i=1}^{n-1}(\delta_i^2+2\delta_i)\frac{a_i^2}{a_n^2}}\right|-\beta\\[-0.08in]
\]}
Thus, we can demonstrate that \(\mathbf{d}_{Lo(\mathbf{b},\mathbf{c})} \geq \mathbf{d}_{Lo(\mathbf{b},\mathbf{a})}\) as follows:
\vspace{-0.08in}
{\scriptsize
\[
\mathbf{d}_{Lo}(\mathbf{b},\mathbf{c})-\mathbf{d}_{Lo}(\mathbf{b},\mathbf{a})=\alpha a_n^2\left(1-\sqrt{1-\sum_{i=1}^{n-1}\frac{a_i^2}{a_n^2}(\delta_i^2+2\delta_i)}-\sum_{i=1}^{n-1}\frac{a_i^2}{a_n^2}\delta_i\right)\\[-0.08in]
\]
\[
\qquad\qquad\qquad\quad\ \ \,\geq\alpha a_n^2\left(1-\sqrt{1-2\sum_{i=1}^{n-1}\frac{a_i^2}{a_n^2}\delta_i}-\sum_{i=1}^{n-1}\frac{a_i^2}{a_n^2}\delta_i\right)\geq 0 \\[-0.08in]
\]
}
In addition, according to \textbf{Lemma \ref{lem:dim_reduce}}, $\mathbf{d}_{Lo}(\mathbf{b},\mathbf{a})$ cannot collapse to zero due to they are linearly related from the $1$-th to the $n$-th dimension. Thus, if using $\phi_{cosh}$, for any vector $\mathbf{b},\mathbf{c}$ in $\mathcal{H}$, their $\mathbf{d}_{Lo}(\mathbf{b},\mathbf{c})$ has its lower boundary and non-diminished.

\end{prf}
\vspace{-0.25in}
\end{theorem}



The advantage of this approach lies in the proportionality between the input to the hyperbolic cosine function and the area of the shaded region in Figure~\ref{fig:cosh_mapping}. Specifically, the red Euclidean distance \(d\) and the hyperbolic sector (blue shaded area) are linearly correlated. As the Euclidean magnitude increases, the area of the hyperbolic sector also increases proportionally, causing the red angle in the figure to increase correspondingly. This proportional increase significantly mitigates the issue of the Lorentz distance approaching zero due to large magnitudes.

\noindent \textbf{Complexity Analysis of Hyperbolic Projection.} The complexity of our projection layer is linear to the dimensionality $d$ of the vectors, denoted as \(O(d)\). This time complexity is negligible compared to existing embedding models. For instance, the embedding complexities of Neutraj and TrajGAT are \(O(Ld^2)\), which is significantly greater than \(O(d)\), where \(L\) is the average number of trajectory points.



\vspace{-0.06in}
\section{Dynamic Fusion Distance}
\label{sec:Fusion_dist}
\vspace{-0.04in}
In this section, we first introduce the variability of triangle constraints in different trajectory similarity functions in Section~\ref{subsec:triag_vio}. To enhance the robustness of trajectory embeddings by addressing this variability, we design a dynamic fusion distance module that integrates Euclidean distance and Lorentz 

\noindent distance in Section~\ref{subsec:dfd}. 




\vspace{-0.07in}
\subsection{Triangle Constraint Violation Variability}
\label{subsec:triag_vio}
\vspace{-0.04in}

Given a specific trajectory dataset \(\mathcal{T}\), the distances measured by different similarity functions, such as DTW and EDR, tolerate varying degrees of inequality constraint violations. To quantitatively analyze this variability, we use a violation flag to label whether a tuple distance follows the inequality constraint as follows:
\vspace{-0.22in}


\begin{equation*}
\textbf{TVF}\scriptsize(T_i, T_j, T_k) = 
\begin{cases} 
  1 & \text{if} \max(Sim[k | i, j], Sim[i | j, k], Sim[j | i, k]) > 0 \\
  0 & \text{otherwise}
\end{cases}
\vspace{-0.3in}
\end{equation*}

\begin{equation*}
Sim[k | i, j] = f(T_i, T_j) - f(T_i, T_k) - f(T_j, T_k)\quad \\[-0.05in]
\end{equation*}

\noindent where \(f(T_i, T_j)\) denotes a given trajectory similarity function.

Next, we propose two metrics, namely the \textit{Ratio of Violation} and \textit{Average Relative Violation}, to represent the ratio of violating constraints and the average degree of violation, respectively.

\vspace{-0.05in}
\begin{definition}[Ratio of Violation]
The ratio of violation for a given dataset \(\mathcal{T}\) is denoted as \(\textbf{RV}(\mathcal{T})\), and is computed as follows:
\vspace{-0.3in}


\begin{equation*}
\small
  \textbf{RV}(\mathcal{T}) = \sum_{T_i, T_j, T_k \in \mathcal{T}} \frac{\textbf{TVF}(T_i, T_j, T_k)}{\mathcal{C}_N^3} \quad \quad (N = |\mathcal{T}|)\\[-0.1in]
\end{equation*}
\end{definition}


\begin{definition}[Average Relative Violation]
The average relative violation is denoted as \(\textbf{ARVS}(\mathcal{T})\), and is computed as follows:
\vspace{-0.27in}

\small
\begin{align*} 
\small
&\textbf{ARVS}(\mathcal{T})=\frac{\sum_{T_i,T_j,T_k\in\mathcal{T}} \textbf{RVS}(T_i,T_j,T_k)\textbf{TVF}(T_i,T_j,T_k)}{\sum_{T_i,T_j,T_k\in\mathcal{T}}\textbf{TVF}(T_i,T_j,T_k)}
\\[-0.3in]
\end{align*}
\begin{align*} 
\vspace{0.03in}
&\textbf{RVS}\scriptsize{(T_i,T_j,T_k) =} 
    \begin{cases} 
        \frac{\displaystyle Sim[ k | i, j ]}{\displaystyle f(T_k, T_i)+f(T_k, T_j)} & \text{if $f(T_i, T_j)$ is max.} \\
        \frac{\displaystyle Sim[ i | j, k ]}{\displaystyle f(T_i, T_j)+f(T_i, T_k)} & \text{if $f(T_j, T_k)$ is max.} \\
        \frac{\displaystyle Sim[ j | i, k ]}{\displaystyle f(T_j, T_k)+f(T_j, T_i)} & \text{if $f(T_i, T_k)$ is max.}
    \end{cases}
\end{align*}
\vspace{-0.26in}
\end{definition}

% \marginpar{\vspace{-1.3cm}\scriptsize{\textcolor{blue}{R3.D8}}}
\color{black}
\begin{example}
% \marginpar{\vspace{0.2cm}\scriptsize{\textcolor{blue}{R3.D2}}}
\label{exmp3}
Consider a trajectory dataset containing four trajectories $\mathcal{T}=\{T_a,T_b,T_c,T_d\}$, where only the similarity distances between $T_a, T_b, T_c$ do not satisfy the triangle inequality, with $f(T_a,T_b)=5$, $f(T_a,T_b)=2$, and $f(T_a,T_b)=1$. Therefore, $sim[c|a,b]=2$, and $\textbf{TVF}(T_a,T_b,T_c)=1$, where $\textbf{TVF}$ indicates that this trajectory triplet does not satisfy the triangle inequality constraint. Then, $\textbf{RV}(\mathcal{T})=\frac{1}{4}$, which means that $\mathcal{T}$ has one-fourth of its samples violating the triangle constraint. Finally, $\textbf{ARVS}(\mathcal{T})=\frac{2}{3}$, indicating that among the samples violating the triangle constraint, the average relative violation size is $\frac{2}{3}$. The larger this relative violation, the worse the performance of the Euclidean distance on it.
\end{example}
