\noindent where $k = \max(\{i,j\})+1$.
\[ \begin{array}{lcl}
\qbfCloser(\stateVarsi, \stateVarsii, \stateVarsiii) & = & \qbfClosereq(\stateVarsi, \stateVarsii, \stateVarsiii) \wedge \\
& & (\neg \qbfClosereq(\stateVarsi, \stateVarsiii, \stateVarsii)) \\
\end{array} \]
\[ \begin{array}{lcl}
\qbfClosereq(\stateVarsi, \stateVarsii, \stateVarsiii) & = & \bigwedge\limits_{\omega \in \Gamma} ((\statevarbasei \land \statevarbaseii) \rightarrow \statevarbaseiii) \wedge \\
& & \bigwedge\limits_{p \in \Sigma} (((\statevarvali \land \neg \statevarvaliii) \rightarrow \neg \statevarvalii) \wedge \\
& & \phantom{\bigwedge\limits_{p \in \Sigma} (} ((\neg \statevarvali \land \statevarvaliii) \rightarrow \statevarvalii))\\
\end{array} \]
\[ \begin{array}{lcl}
\qbfEq(\stateVarsii, \stateVarsiii) & = & \bigwedge\limits_{\omega \in \Gamma} (\statevarbaseii \leftrightarrow \statevarbaseiii) \wedge 
\bigwedge\limits_{p \in \Sigma} (\statevarvalii \leftrightarrow \statevarvaliii) \\
\end{array} \]
\[ \begin{array}{lcl}
\qbfState(\stateVarsi) & = & \bigwedge_{\omega \in \Gamma} (\statevarbasei \rightarrow \qbfSat(\omega, \stateVarsi))
\end{array}
\]

\subsection{Proof of Theorem \ref{th:model_checking_lower_bound} }

\begin{proof} 

\textbf{PSPACE-membership}:

The encoding of model checking into QBF is given by the following fact:
$\tuple{\state, \univCtxRel{\Gamma}} \models \inputform$
iff a closed QBF formula \[ \tau_0 =  \exists X^0. \qbfInit(\stateVars{0}, \state) \wedge \qbfSat(\inputform, \stateVars{0})
 \] is true, where 
\begin{align*}
\qbfInit(\stateVars{0}, \tuple{\base,\val}) = \bigwedge\limits_{\omega\in\base} \statevarbase{0}{\omega} \wedge \bigwedge\limits_{\omega\notin\base} \neg\statevarbase{0}{\omega} \wedge \\
\bigwedge\limits_{\prop\in\val\cap\Sigma} \statevarval{0}{\prop} \wedge \bigwedge\limits_{\prop\notin\val\cap\Sigma} \neg\statevarval{0}{\prop}.
\end{align*}

To prove it we need to check correctness of all predicates we define (see Section~\ref{sec:QBF_encodings_modal_checking}).

We recall the following notion from Section~\ref{sec:mc}, which reconstructs a state (or, in the general case, tuple of causal base and valuation that are not necessarily consistent) from their encodings by variables $\stateVarsi$: for $\qbfVal \subseteq \stateVarsi$,  $\qbfValToState{\qbfindi}{\qbfVal} = \tuple{\{ \omega \mid \statevarbasei \in \qbfVal \}, \{ \prop \mid \statevarvali \in \qbfVal \}}$. We will also use notation $\subformulas{\inputform}$ to refer to the set of subformulas of the input formula $\inputform$.

We formulate and prove the correctness of predicates one by one.
\begin{enumerate}
\item\label{item:qbf_corr_propsat} For any $\omega \in \Gamma$, and any $\qbfVali \subseteq \stateVarsi$, if $\qbfValToState{\qbfindi}{\qbfVali} = \tuple{\base, \val}$ then $\qbfVali \modelsQBF \qbfSat(\omega, \stateVarsi)$ iff $\val \models \omega$. It can be proved by trivial induction on $\omega$.%, using the fact $\Sigma \subseteq \Sigma$.
\item\label{item:qbf_corr_state} For any $\qbfVali \subseteq \stateVarsi$, $\qbfVali \modelsQBF \qbfState(\stateVarsi)$ iff $\qbfValToState{\qbfindi}{\qbfVali} \in \univCtxRel{\Gamma}$. Using the fact (\ref{item:qbf_corr_propsat}) above, $\qbfVali \modelsQBF \qbfState(\stateVarsi)$ is equivalent to the fact that $\val \models \omega$ (where $\val$ is the valuation of $\qbfValToState{\qbfindi}{\qbfVali}$) for any $\omega \in \Gamma$ such that $\statevarbasei \in \qbfVali$. This is exactly the consistency condition for the state $\qbfValToState{\qbfindi}{\qbfVali}$.
\item\label{item:qbf_corr_eq} For any $\qbfValii \subseteq \stateVarsii$, $\qbfValiii \subseteq \stateVarsiii$, $\qbfValii \cup \qbfValiii \modelsQBF \qbfEq(\stateVarsii, \stateVarsiii)$ iff $\qbfValToState{\qbfindii}{\qbfValii} = \qbfValToState{\qbfindiii}{\qbfValiii}$. This holds trivially.
\item\label{item:qbf_corr_closereq} For ${\qbfVali \subseteq \stateVarsi}$, ${\qbfValii \subseteq \stateVarsii}$, ${\qbfValiii \subseteq \stateVarsiii}$, ${\qbfVali \cup \qbfValii \cup \qbfValiii \modelsQBF \qbfClosereq(\stateVarsi, \stateVarsii, \stateVarsiii)}$ iff ${\qbfValToState{\qbfindii}{\qbfValii} \preceq_{\qbfValToState{\qbfindi}{\qbfVali}} \qbfValToState{\qbfindiii}{\qbfValiii}}$.  The first conjunct in $\qbfClosereq(\stateVarsi, \stateVarsii, \stateVarsiii)$ encodes the fact $\base^{\qbfindi} \cap \base^{\qbfindii} \subseteq \base^{\qbfindiii}$ and the second conjunct encodes the fact $\val^{\qbfindi} \Delta \val^{\qbfindiii} \subseteq \val^{\qbfindi} \Delta \val^{\qbfindii}$ (for ${\qbfValToState{\qbfindi}{\qbfVali} = \tuple{\base^{\qbfindi},\val^{\qbfindi}}}$, ${\qbfValToState{\qbfindii}{\qbfValii} = \tuple{\base^{\qbfindii},\val^{\qbfindii}}}$, ${\qbfValToState{\qbfindiii}{\qbfValiii} = \tuple{\base^{\qbfindiii},\val^{\qbfindiii}}}$), which is exactly the Definition~\ref{def:similarity_relation} of similarity relation.
\item\label{item:qbf_corr_closer} For ${\qbfVali \subseteq \stateVarsi}$, ${\qbfValii \subseteq \stateVarsii}$, ${\qbfValiii \subseteq \stateVarsiii}$, ${\qbfVali \cup \qbfValii \cup \qbfValiii \modelsQBF \qbfCloser(\stateVarsi, \stateVarsii, \stateVarsiii)}$ iff ${\qbfValToState{\qbfindii}{\qbfValii} \prec_{\qbfValToState{\qbfindi}{\qbfVali}} \qbfValToState{\qbfindiii}{\qbfValiii}}$. Trivially by definition of $\prec_{\qbfValToState{\qbfindi}{\qbfVali}}$ (Definition~\ref{def:sat}), relying on the fact~\ref{item:qbf_corr_closereq} above.
\item\label{item:qbf_corr_sat_closest} The correctness of $\qbfClosest(\varphi, \stateVarsi, \stateVarsii)$ and $\qbfSat(\varphi, \stateVarsi)$ we need to prove together by mutual induction.
\renewcommand{\labelenumii}{\arabic{enumi}.\arabic{enumii}.}
\begin{enumerate}
\item\label{item:qbf_corr_sat} For $\varphi \in \subformulas{\inputform}$, ${\qbfVali \subseteq \stateVarsi}$,  ${\qbfVali \modelsQBF \qbfSat(\varphi, \stateVarsi)}$ iff ${\qbfValToState{\qbfindi}{\qbfVali} \models \varphi}$.
\item\label{item:qbf_corr_closest} For $\varphi \in \subformulas{\inputform}$, ${\qbfVali \subseteq \stateVarsi}$, ${\qbfValii \subseteq \stateVarsii}$, ${\qbfVali \cup \qbfValii \modelsQBF \qbfClosest(\varphi, \stateVarsi, \stateVarsii)}$ iff $\qbfValToState{\qbfindii}{\qbfValii} \in \closest(\varphi, \qbfValToState{\qbfindi}{\qbfVali}, \univCtxRel{\Gamma})$.
\end{enumerate}

The fact (\ref{item:qbf_corr_sat}) follows directly by definition from the inductive hypotheses about correctness of $\qbfSat$ for immediate subformulas and about correctness of $\qbfClosest$ for the antecedent in the case of counterfactual.

For the fact (\ref{item:qbf_corr_closest}) notice that the definition of $\closest$ prohibits for each valuation on $\stateVarsiii$ the situation when $\qbfState(\stateVarsiii)$ is true, $\qbfEq(\stateVarsii, \stateVarsiii)$ is true and $\qbfSat(\varphi, \stateVarsiii)$ is false and the situation when $\qbfState(\stateVarsiii)$ and $\qbfCloser(\stateVarsi, \stateVarsii, \stateVarsiii)$ and $\qbfSat(\varphi, \stateVarsiii)$ are all true, and no other situations. Using facts (\ref{item:qbf_corr_state}), (\ref{item:qbf_corr_eq}), (\ref{item:qbf_corr_closer}) above, and the fact (\ref{item:qbf_corr_sat}) for $\varphi$, we get from that exactly ${\qbfValToState{\qbfindii}{\qbfValii} \models \varphi}$ (since the first situation is prohibited) and the fact that $\qbfValToState{\qbfindiii}{\qbfValiii} \in \univCtxRel{\Gamma}$ and ${\qbfValToState{\qbfindii}{\qbfValii} \prec_{\qbfValToState{\qbfindi}{\qbfVali}} \qbfValToState{\qbfindiii}{\qbfValiii}}$ imply $\qbfValToState{\qbfindiii}{\qbfValiii} \not\models \varphi$ (since the second situation is prohibited) with $\qbfValToState{\qbfindiii}{\qbfValiii}$ going through all possible states. This is exactly the definition of the closest state.
\end{enumerate}

Now we are in a position to prove that $\tau_0$ is satisfiable iff $\tuple{\state, \univCtxRel{\Gamma}} \models \inputform$. $\qbfInit(\stateVars{0}, (\base,\val))$ is true exactly on valuation $Y^0$ for which $\qbfValToState{0}{Y^0} = (\base, \val)$. So satifsability of $\tau_0$ is equivalent to $\tuple{\state, \univCtxRel{\Gamma}} \models \inputform$ by the fact (\ref{item:qbf_corr_sat}) for $\inputform$.

It only remains to check that encoding has polynomial size w.r.t. the input. We have the following estimations for the sizes of the predicates (the second and the last case by trivial structural induction on formula):
\begin{itemize}
\item $|\qbfInit(\stateVarsi, S)| = \O{|S|}$
\item $|\qbfSat(\omega, \stateVarsi)| = \O{|\omega|}$ for $\omega \in \Gamma$
\item $|\qbfState(\stateVarsi)| = \O{\sum_{\omega \in \Gamma} |\omega|}$
\item $|\qbfEq(\stateVarsii, \stateVarsiii)| = \O{|\Gamma| + |\Sigma|}$
\item $|\qbfClosereq(\stateVarsi,\stateVarsii, \stateVarsiii)| = \O{|\Gamma| + |\Sigma|}$
\item $|\qbfCloser(\stateVarsi,\stateVarsii, \stateVarsiii)| = \O{|\Gamma| + |\Sigma|}$
\item $|\qbfSat(\varphi,\stateVarsi)| = \\ |\qbfClosest(\varphi,\stateVarsi,\stateVarsii)| = {\O{|\varphi| \cdot (|\Sigma| + \sum_{\omega \in \Gamma} |\omega|)}}$
\end{itemize}

So the reduction output $\tau_0$ indeed has a polynomial size w.r.t. the input.

\textbf{PSPACE-hardness}: We provide a reverse reduction. Suppose that we are given QBF formula $\tau_0$.
We assume that $\tau_0$ is closed (every variable occurring in $\tau$ is bounded by a quantifier) and that different quantifiers in it quantify over different variables from $\Props$ (this can be easily achieved by renaming bounded variables).  For the encoding we will pair each of the bounded variable $x$ in $\tau_0$ by a ``fresh'' variable $\cloneVar(x)$, such that all these variables are different (i.e. $\cloneVar$ is injective) and do not occur in $\tau_0$ (such $\cloneVar$ can be easily chosen since $\Props$ is infinite). Then we have the following encoding for the subformulas of $\tau_0$:
\[ \begin{array}{lcl}
t(\prop) & = & \prop \\
t(\lnot \tau) & = & \lnot t(\tau) \\
t(\tau_1 \land \tau_2) & = & t(\tau_1) \land t(\tau_2) \\
t(\forallqbf{\prop}{\tau}) & = & \condmodal{(\prop \lor \cloneVar(\prop))}{t(\tau)} \\
\end{array} \]
We can prove by structural induction that for every subformula $\tau$ of $\tau_0$ if valuation $V$ does not contain neither $\prop$ nor $\cloneVar(\prop)$ for any variable $\prop$ bounded in $\tau$ then $V \modelsQBF \tau$ iff $((\emptyset, \val), \univCtxRel{\emptyset}) \models t(\tau)$. Base case is trivial, cases of propositional connectives follow directly from the induction hypotheses. If $\tau = \forallqbf{\prop}{\tau'}$ we have $\{\prop, \cloneVar(\prop)\} \cap \val = \emptyset$ since $\prop$ is bounded in $\tau$. ${\closest(\prop \lor \cloneVar(\prop),(\emptyset,\val),\univCtx)} = \{ \tuple{\emptyset, \val \cup \{\prop\}}, (
\tuple{\emptyset, \val \cup \{\cloneVar(\prop)\}} \}$, since $(\prop \lor \cloneVar(\prop))$ is not satisfied in $(\emptyset,\val)$ but is satisfied in these two states, and for every other state in $\univCtxRel{\emptyset}$ satisfying $(\prop \lor \cloneVar(\prop))$ the valuation contains either $\prop$ or $\cloneVar(\prop)$, so one of the states above is strictly more similar to $(\emptyset, \val)$. Therefore $((\emptyset, V), \univCtx) \models t(\forallqbf{\prop}{\tau'})$ iff both ${((\emptyset, V \cup \{\prop\}),\univCtx) \models t(\tau')}$ and ${((\emptyset, V \cup \{\cloneVar(\prop)\}),\univCtx) \models t(\tau')}$; by the inductive hypotheses the first is equivalent to ${(V \cup \{ \prop \}) \modelsQBF \tau'}$ and second is equivalent to $(V \cup \{ \cloneVar(\prop) \}) \modelsQBF \tau'$ which is also equivalent to $V \modelsQBF \tau'$ (since $\cloneVar(\prop)$ does not occur in $\tau'$), and their conjunction is equivalent exactly to $V \modelsQBF \forallqbf{\prop}{\tau'}$ (since $\prop \not\in V$ by the initial assumption on $V$). 

As a result, closed QBF formula $\tau_0$ evaluates to true iff $((\emptyset, \emptyset), \univCtx) \models t(\tau_0)$. Since $|t(\tau_0)| = \mathcal{O}(|\tau_0|)$, the encoding implies PSPACE-hardness of model checking. 
\end{proof}

\subsection{Proof of Lemma \ref{lem:mc_relativized_reduction_unnested} }


\begin{proof}
We first generalize the statement: instead of fixing $\Gamma$, we prove that $\tuple{\tuple{\base, \val}, \univCtx} \models \inputform$ is equivalent to $\tuple{\tuple{\base, \val}, \univCtxRel{\Gamma}} \models \inputform$ for any $\Gamma$ such that $\base \subseteq \Gamma$ and  $\omega \in \Gamma$ for any subfomula $\ltri \omega$ in $\inputform$.
We prove this generalized statement by structural induction on formula $\inputform$.

\begin{itemize}
\item $\inputform = p \in \Props$: Trivially.
\item $\inputform = \top$: Trivially.
\item $\inputform = \Delta \omega$: By the assumption for $\Gamma$.
\item $\inputform = \neg \varphi_1$: By the inductive hypothesis.
\item $\inputform = \varphi_1 \land \varphi_2$: By the inductive hypotheses.
\item $\inputform = \condmodal{\alpha}{\beta}$: Since $\inputform$ does not contain nested counterfactual by assumption, $\alpha, \beta \in \langE$. 

We will use the surjective mapping $\maprel \colon \univCtx \rightarrow \univCtxRel{\Gamma}$ defined as $\maprel(\tuple{\base^\ast, \val^\ast}) = \tuple{\base^\ast \cap \Gamma, \val^\ast}$. We will need the following fact about $\maprel$: for $\gamma \in \{\alpha, \beta\}$, for any $\state \in \univCtx$,
$\tuple{\maprel(\state), \univCtxRel{\Gamma}} \models \gamma$ iff $\tuple{\state, \univCtx} \models \gamma$. It is true since evaluation on these models is the same for all variables (since the valuation is the same) and for all subformulas of the form $\ltri \omega$ in $\gamma$ (since $\omega \in \Gamma$ by the assumption on $\Gamma$), and since $\gamma \in \langE$ the models do not change in the evaluation, so it is sufficient for equivalent evaluation of $\gamma$ on these two models. Another fact about $\maprel$ we will need: for any $\state_1, \state_2 \in \univCtx$, ${\state_1 \prec_{\tuple{\base, \val}} \state_2}$ iff ${\maprel(\state_1) \prec_{\tuple{\base, \val}} \maprel(\state_2)}$. It is true due to the assumption $C \subseteq \Gamma$.

Let us now prove the inductive case. First, let us unfold the definition of ${\tuple{\tuple{\base, \val}, \univCtx} \models \condmodal{\alpha}{\beta}}$:
\begin{multline*} \forall \state_1 \in \univCtx.\; \tuple{\state_1, \univCtx} \models \beta \;\vee\; \tuple{\state_1, \univCtx} \not\models \alpha \;\vee\; \\
(\exists \state_2 \in \univCtx.\; \state_1 \!\prec_{\tuple{\base, \val}}\! \state_2 \;\wedge\; \tuple{\state_2, \univCtx} \models \alpha). \end{multline*}

Using the facts about $\maprel$ we can rewrite it as follows:
\begin{multline*} \forall \state_1 \in \univCtx.\; \tuple{\maprel(\state_1), \univCtxRel{\Gamma}} \models \beta \;\vee\; \tuple{\maprel(\state_1), \univCtxRel{\Gamma}} \not\models \alpha \;\vee\; \\
(\exists \state_2 \in \univCtx.\; \maprel(\state_1) \!\prec_{\tuple{\base, \val}}\! \maprel(\state_2) \;\wedge\; \tuple{\maprel(\state_1), \univCtxRel{\Gamma}} \models \alpha). \end{multline*}

Now, since $\maprel$ is a surjective mapping onto $\univCtxRel{\Gamma}$, quantifying over $\state \in \univCtx$ and using only $\maprel(\state)$ is equivalent to quantifying over $\state' \in \univCtxRel{\Gamma}$ and using $\state'$ directly. We can perform this rewriting for both quantifiers:
\begin{multline*} \forall \state'_1 \in \univCtxRel{\Gamma}.\; \tuple{\state'_1, \univCtxRel{\Gamma}} \models \beta \;\vee\; \tuple{\state'_1, \univCtxRel{\Gamma}} \not\models \alpha \;\vee\; \\
(\exists \state'_2 \in \univCtxRel{\Gamma}.\; \state'_1 \!\prec_{\tuple{\base, \val}}\! \state'_2 \;\wedge\; \tuple{\state'_2, \univCtxRel{\Gamma}} \models \alpha). \end{multline*}

Which is equivalent to ${\tuple{\tuple{\base, \val}, \univCtxRel{\Gamma}} \models \condmodal{\alpha}{\beta}}$.\qedhere
\end{itemize}
\end{proof}


\subsection{QBF Encoding of Actual Cause}

Similarly to the encodings of states, we introduce sets of variables $\litVars{i}$ to encode terms: for $i \in \Nats$, $\litVars{i} = {\{ \litvarpos{i}{\prop} \mid \prop \in \Sigma \}} \cup {\{ \litvarneg{i}{\prop} \mid \prop \in \Sigma \}}$. To encode a term the variables should not have contradicting literals:
\[ \qbfTerm(\litVars{i}) = \bigwedge_{\prop \in \Sigma} \neg (\litvarpos{i}{\prop} \wedge \litvarneg{i}{\prop}))  \]

We first define some operations on terms:

\[\qbfTermRev(\litVars{i}, \litVars{j}) = \bigwedge_{\prop \in \Sigma} ((\litvarpos{i}{\prop} \leftrightarrow \litvarneg{j}{\prop}) \wedge (\litvarneg{i}{\prop} \leftrightarrow \litvarpos{j}{\prop}))\]

\[\begin{array}{l}
\qbfTermMerge(\litVars{i}, \litVars{j}, \litVars{k}) = \bigwedge\limits_{\prop \in \Sigma} ((\litvarpos{i}{\prop} \vee \litvarpos{j}{\prop} \rightarrow \litvarpos{k}{\prop}) \wedge \\ \phantom{\qbfTermMerge(\litVars{i}, \litVars{j}, \litVars{k}) = \bigwedge_{\prop \in \Sigma}} (\litvarneg{i}{\prop} \vee \litvarneg{j}{\prop} \rightarrow \litvarneg{k}{\prop})) 
\end{array} \]

\[\begin{array}{l}
\qbfTermVarsSubseteq(\litVars{i}, \litVars{j}) = \bigwedge\limits_{\prop \in \Sigma} ((\litvarpos{i}{\prop} \vee \litvarneg{i}{\prop}) \rightarrow (\litvarpos{j}{\prop} \vee \litvarneg{j}{\prop})) 
\end{array} \]

\[\begin{array}{l}
\qbfTermVarsSubset(\litVars{i}, \litVars{j}) = \qbfTermVarsSubseteq(\litVars{i}, \litVars{j}) \wedge \\
\phantom{\qbfTermVarsSubset(\litVars{i}, \litVars{j}) =} \neg \qbfTermVarsSubseteq(\litVars{j}, \litVars{i}) 
\end{array} \]

Now auxiliary predicates involving states:

\[\begin{array}{l}
\qbfTermExo(\litVars{i}, \stateVars{j}) = \bigwedge\limits_{\prop \in \exgfunct(\state )} ((\litvarpos{i}{\prop} \leftrightarrow \statevarval{j}{\prop}) \wedge (\litvarneg{i}{\prop} \leftrightarrow \neg \statevarval{j}{\prop})) \\
\phantom{\qbfTermExo(\litVars{i}, \stateVars{j})} \wedge 
 \bigwedge\limits_{\prop \in \Sigma \setminus \exgfunct(\state )} (\neg \litvarpos{i}{\prop} \wedge \neg \litvarneg{i}{\prop})
\end{array}\]

\[\qbfTermSat(\litVars{i}, \stateVars{j}) = \bigwedge_{\prop \in \Sigma} ((\litvarpos{i}{\prop} \rightarrow \statevarval{j}{\prop}) \wedge (\litvarneg{i}{\prop} \rightarrow \neg \statevarval{j}{\prop}))\]

\[
\begin{array}{l}
\qbfTermClosest(\litVars{t}, \stateVars{i}, \stateVars{j}) = \forall \stateVars{k}.\; \forall r.\; \qbfState(\stateVars{k}) \rightarrow \\
\hspace{37mm} (\qbfTermSat(\litVars{t}, \stateVars{k}) \leftrightarrow r) \rightarrow  \\
\hspace{37mm}((\qbfEq(\stateVarsii, \stateVarsiii) \rightarrow r) \wedge \\
\hspace{37mm} (\qbfCloser(\stateVarsi, \stateVarsii, \stateVarsiii) \rightarrow
\neg r)), 
\end{array} \] \noindent where $k = \max(\{t,i,j\})+1$.

\[
%\hspace{-15mm}
\begin{array}{l}
\qbfTermCounterfactual(\litVars{t}, \omega, \stateVarsi) = \forall \stateVars{n}. \; \qbfState(\stateVars{n}) \rightarrow \\
 \phantom{\forall \stateVars{\qbfindi+1}.\;} \qbfTermClosest(\litVars{t}, \stateVarsi, \stateVars{n}) \rightarrow \\
 \phantom{\forall \stateVars{\qbfindi+1}.\;} \qbfSat(\omega, \stateVars{n}), \\
\end{array}
\]
\noindent where $n = \max(\{t,i\})+1$.

Now we can define the main predicate verifying actual cause according to Theorem~\ref{thm:actual_cause_minimal_might}.

\[
%\hspace{-15mm}
\begin{array}{l}
\qbfActualCause(\litVars{t}, \omega, \stateVars{i}) = \qbfTermSat(\litVars{t}, \stateVars{i}) \wedge \\
\quad (\exists \litVars{n}.\; \exists \litVars{n+1}.\; \exists \litVars{n+2}.\; \\
\qquad \qbfTermRev(\litVars{n}, \litVars{t}) \rightarrow \\
\qquad \qbfTermExo(\litVars{n+1}, \stateVars{i}) \rightarrow \\
\qquad \qbfTermMerge(\litVars{n}, \litVars{n+1},\litVars{n+2}) \rightarrow \\
\qquad  \neg\qbfTermCounterfactual(\litVars{n+2}, \omega, \stateVars{i}) ) \\
\quad (\forall \litVars{n}.\; \forall \litVars{n+1}.\; \forall \litVars{n+2}.\; \\
\qquad \qbfTerm(\litVars{n}) \rightarrow \\
\qquad \qbfTermVarsSubset(\litVars{n}, \litVars{t}) \rightarrow \\
\qquad \qbfTermExo(\litVars{n+1}, \stateVars{i}) \rightarrow \\
\qquad \qbfTermMerge(\litVars{n}, \litVars{n+1},\litVars{n+2}) \rightarrow \\
\qquad  \qbfTermCounterfactual(\litVars{n+2}, \omega, \stateVars{i}) ),
\end{array}
\]

\noindent where $n = \max(\{t,i\})+1$.


