Under the non-colluding detection strategy, each warden independently determines whether the BS is transmitting signals based on its own observation. In this scenario, the CC performance of the system is dominated by the most detrimental warden with the minimal $\xi_v^*$. To ensure covertness, the system must guarantee 
$\xi_w=\min_{v\in\Phi_{\text{E}}}\{ \xi_v^*\}\geq 1 - \varsigma.$

\vspace*{-0.2cm}
\section{Statistical Analysis of SINRs}
To obtain the theoretical expressions of key performance metrics, we first investigate the statistics of received SINRs and obtain the following lemmas.
\begin{lemma}\label{CDF_of_gammack}
The CDF of $\gamma_{c,k}$ can be derived as
\begin{small}
\begin{align}\label{closed_form_cdf_of_gammack}
	F_{\gamma_{c,k}}(x)=1-\exp(-\varphi_kx)(\mu_kx+1)^{-D_{\mathcal{Y},k}},
\end{align}
\end{small}where $\mu_k={\hat{\theta}_{\mathcal{Y},k}}/{a_c}$, $	\varphi_k=1/{( \mathcal{P}a_c\beta_k)}$; $D_{\mathcal{Y},k}$ and $\hat{\theta}_{\mathcal{Y},k}$ have been defined in Table \ref{RVs_parameters}.
\end{lemma}
\begin{proof}
	See Appendix \ref{Proof_of_cdf_gammac}.
\end{proof}
\begin{lemma}\label{CDF_of_gammapk}
	The CDF of $\gamma_{p,k}$ can be derived as
\begin{small}
	\begin{align}\label{closed_form_cdf_of_gammapk}
		F_{\gamma_{p,k}}(x) = 1 - \sum_{m=0}^{\lfloor D_{\mathcal{Z}} \rceil - 1} \sum_{n=0}^{\lfloor D_{\mathcal{Z}} \rceil - m - 1}
		\frac{ \exp\left(-\frac{x}{\theta_{\mathcal{Z}}}\right) x^{m+n}\psi_k}
		{\left( x\theta_{\mathcal{L},k} + \theta_{\mathcal{Z}} \right)^{n + D_{\mathcal{L},k}}  },
	\end{align}
\end{small}where
$\psi_k=\frac{\theta_{\mathcal{L},k}^n\theta_{\mathcal{Z}}^{D_{\mathcal{L},k}-m}\Gamma(n+D_{\mathcal{L},k})}{m!n!\Gamma(D_{\mathcal{L},k})}$,  $\theta_{\mathcal{L},k}=\mathcal{P}\beta_k(1-\epsilon^2)\hat{\theta}_{\mathcal{L},k}$, and ${\theta}_{\mathcal{Z}}=\mathcal{P}a_k\beta_k\hat{\theta}_{\mathcal{Z}}$; 
$D_{\mathcal{L},k}$, $D_{\mathcal{Z}}$, $\hat{\theta}_{\mathcal{L},k}$, and $\hat{\theta}_{\mathcal{Z}}$ have been defined in Table \ref{RVs_parameters}.
\end{lemma}
\begin{proof}
	See Appendix \ref{Proof_of_cdf_gammapk}.
\end{proof}
\vspace*{-0.2cm}
\section{Performance Analysis}
In this section, we investigate the key metrics for CC performance of RSMA systems, including covertness constraint, OP, and the ECT.
\vspace*{-0.4cm}
\subsection{Covertness Constraint}
In this subsection, we aim to analyze the system’s covertness by deriving the closed-form expression for the minimum DEP across all wardens, i.e., $\xi_w=\min_{v\in\Phi_{\text{E}}}\{ \xi_v^*\}\geq 1 - \varsigma$. However,
deriving  $\xi_v^*$
is analytically intractable, which complicates the analysis of $\xi_w$. To solve this challenge,  we adopt Pinsker’s inequality, yielding a lower bound for $\xi_v^*$ \cite{ma2021covert,ma2021robust,ma2023covert,zhang2024rate}:
\begin{small}
\begin{align}\label{KL_lower_bound}
	\xi_v^*\geq 1-\sqrt{\frac{1}{2}\mathcal{D}(p_1(y_v)\|p_0(y_v))},
\end{align}
\end{small}where $p_0(y_v)$ and $p_1(y_v)$ respectively denote the likelihood functions of the received signals of $\text{warden-}v$ under $\mathcal{H}_0$
and $\mathcal{H}_1$, and $\mathcal{D}(p_1\|p_0)$ denotes the Kullback-Leibler (KL) divergence  from $p_1(y_v)$ to
$p_0(y_v)$. Then substituting (\ref{KL_lower_bound}) into $\xi_w\geq 1 - \varsigma$, the system covertness can be guaranteed by satisfying the equivalent condition: $\max_{v\in\Phi_{\text{E}}}\left\{\sqrt{\frac{1}{2}\mathcal{D}(p_1(y_v)||p_0(y_v))}\right\}\leq \varsigma$.


Recall that wardens are passive, and thus their instantaneous CSIs are unknown to the BS. Recall that only the statistical CSIs of the wardens are available. To this end, the average KL divergence is adopted in this work, where the expectation is taken over the spatial distribution and the small-scale fading statistics of wardens. Accordingly, the CC constraint for $\text{warden-}v$ can be expressed as \cite{ma2021covert,ma2023covert}:
\begin{small}
\begin{align}\label{average_covert_constraint}
\mathbb{E}\left\{\max_{v\in\Phi_{\text{E}}}\left\{\sqrt{\frac{1}{2}\mathcal{D}(p_1(y_v)||p_0(y_v))}\right\}\right\}\leq \varsigma.
\end{align}
\end{small}Then we can achieve a tractable expression of covertness constraint in the following lemma:
\begin{lemma}\label{expression_of_covertenss_constraint}
The expressions for covertness constraint considering HPPP distributed and non-colluding wardens can be derived as $\nu\mathcal{P}\leq \varsigma$,
where 
\begin{small}
\begin{align}
\nu=\frac{(\lambda_e\pi)^{\frac{\alpha}{4}}\exp\left(\frac{\lambda_e\pi r_p^2}{2}\right)W_{-\frac{\alpha}{4},\frac{1}{2}-\frac{\alpha}{4}}\left(\lambda_e\pi r_p^2\right)}{2r_p^{\frac{\alpha}{2}}}.
\end{align}
\end{small}
\end{lemma}
\begin{proof}
	See Appendix \ref{proof_of_covertness}.
\end{proof}
\begin{remark}
	It is observed that $\nu$ depends only on path loss exponent $\alpha$, protected zone radius $r_p$, and warden density $\lambda_e$, regardless of the power allocation  coefficients or the number of transmit antennas.
\end{remark}

\vspace*{-0.5cm}
\subsection{Outage Probability Analysis}
Given that OP is crucial, we present its analysis below. Under RSMA protocol, an outage occurs at $U_k$ when it fails to decode either $s_c$ or $s_k$. Thus the OP of $U_k$ can be expressed as
\begin{small}
\begin{align}
P_{\text{out},k}
=&\Pr\left(\gamma_{c,k}<\gamma_{k,th}^{s_c}\right)+\Pr\left(\gamma_{p,k}<\gamma_{k,th}^{s_k}\right)\nonumber\\
&-\underbrace{\Pr\left(\gamma_{c,k}<\gamma_{k,th}^{s_c},\gamma_{p,k}<\gamma_{k,th}^{s_k}\right)}_{I_p},
\end{align}
\end{small}where $\gamma_{k,th}^{s_c}$ and $\gamma_{k,th}^{s_p}$ are the SINR thresholds of $s_c$ and $s_k$ at $U_k$,  respectively. Specifically, the theoretical expression of $P_{\text{out},k}$ is summarized in the following lemma.
\begin{lemma}
	The OP of $U_k$ can be derived as
\begin{small}
	\begin{align}\label{Pout}
	P_{\text{out},k}=\max\left\{	F_{\gamma_{c,k}}(\gamma_{k,th}^{s_c}),	F_{\gamma_{p,k}}(\gamma_{k,th}^{s_k})\right\}.
	\end{align}
\end{small} 
\end{lemma}
\begin{proof}
	Due to the shared structure and the presence of Gamma-distributed terms, characterizing $I_p$ becomes intractable. 
Following methods in \cite{zhang2024covert,zhang2025covert,liang2025covert}, $I_p$ can be tightly approximated as $\min\{F_{\gamma_{c,k}}(\gamma_{k,th}^{s_c}),F_{\gamma_{p,k}}(\gamma_{k,th}^{s_k})\}$, which enables a tractable expression of $P_{\text{out},k}$.
\end{proof}
