	\section{Proof of Lemma \ref{CDF_of_gammapk}}\label{Proof_of_cdf_gammapk}
Let $\mathcal{L}=\sum_{\mathcal{K}\backslash k} \mathcal{P}a_j\beta_k|\textbf{g}_k^H\textbf{w}_j|^2$ and $\mathcal{Z}=\mathcal{P}a_k\beta_k|\textbf{g}_k^H\textbf{w}_k|^2$.
Following the moment-matching method in Appendix~\ref{Proof_of_cdf_gammac}, the distributions of $\mathcal{L}$ and $\mathcal{Z}$ can be approximated by $\Gamma(D_{\mathcal{L},k},\theta_{\mathcal{L},k})$ and $\Gamma(D_{\mathcal{Z}},\theta_{\mathcal{Z}})$, respectively. Accordingly, the CDF of $\gamma_{p,k}$ is given by
\begin{small}
	\begin{align}\label{initial_form_of_Fgammapk}
		F_{\gamma_{p,k}}(x)
	=\int_{0}^{\infty}\underbrace{\frac{\gamma\left(D_{\mathcal{Z}},\frac{x(l+1)}{\theta_{\mathcal{Z}}}\right)}{\Gamma(D_{\mathcal{Z}})}}_{I_1}
		\frac{l^{D_{\mathcal{L}}-1}\exp\left(-\frac{l}{\theta_{\mathcal{L}}}\right)}{\Gamma(D_{\mathcal{L}})\theta_{\mathcal{L}}^{D_{\mathcal{L}}}}\,dl.
	\end{align}
\end{small}

Since the closed-form expression for the above integral is not available, we approximate $D_{\mathcal{Z}}$ by $\lfloor D_{\mathcal{Z}} \rceil$. Then $I_1$ can be rewritten as
\begin{small}
	\begin{align}\label{after_form_of_I1}
		I_1 
%		&= 1 - \exp\left(-\frac{x(l+1)}{\theta_{\mathcal{Z}}}\right)
%		\sum_{k=0}^{\lfloor D_{\mathcal{Z}} \rceil - 1}
%		\frac{1}{k!}\left(\frac{x(l+1)}{\theta_{\mathcal{Z}}}\right)^k \nonumber \\
		&\overset{(a)}{=} 1 - \exp\left(-\frac{x(l+1)}{\theta_{\mathcal{Z}}}\right)
		\sum_{m=0}^{\lfloor D_{\mathcal{Z}} \rceil - 1}
		\sum_{k=m}^{\lfloor D_{\mathcal{Z}} \rceil - 1}
		\binom{k}{m} \frac{1}{k!} \left(\frac{x}{\theta_{\mathcal{Z}}}\right)^k l^{k-m} \nonumber \\
		&\overset{(b)}{=} 1 - \sum_{m=0}^{\lfloor D_{\mathcal{Z}} \rceil - 1}
		\sum_{n=0}^{\lfloor D_{\mathcal{Z}} \rceil - m - 1}
		\kappa\, \exp\left(-\frac{x}{\theta_{\mathcal{Z}}}l\right) l^n,
	\end{align}
\end{small}where $(a)$ is derived based on the CDF of $\Gamma(\lfloor D_{\mathcal{Z}} \rceil,\theta_{\mathcal{Z}})$ and the binomial expansion, and $(b)$ stands for $n = k - m$ and $\kappa = \frac{\exp\left(-\frac{x}{\theta_{\mathcal{Z}}}\right)\left(\frac{x}{\theta_{\mathcal{Z}}}\right)^{m+n}}{m!n!}$. Substituting  (\ref{after_form_of_I1}) into (\ref{initial_form_of_Fgammapk}) and applying~\cite[Eq. (3.326.2)]{gradshteyn2014table}, we finally arrive at (\ref{closed_form_cdf_of_gammapk}).





\vspace*{-0.1cm}
\section{Proof of Lemma \ref{expression_of_covertenss_constraint}}\label{proof_of_covertness}
\setcounter{equation}{0}
Before deriving the closed-form expression for the covertness constraint, we first characterize the probability distribution of $y_v$. According to (\ref{hypotheses}), the likelihood functions of $y_v$ under hypotheses $\mathcal{H}_0$ and $\mathcal{H}_1$ are given by
$p_0(y_v)={\exp(-|y_v|^2/\lambda_0)}/{(\pi\lambda_0)}$ and $p_1(y_v)={\exp(-|y_v|^2/\lambda_0)}/{(\pi\lambda_1)}$, where
$\lambda_0 = \sigma^2$ and $\lambda_1 = Pa_c|\textbf{h}_v^H\textbf{w}_c|^2 + \sum_{k=1}^{K} Pa_k|\textbf{h}_v^H\textbf{w}_k|^2+\sigma^2$. Then  the KL divergence  is given by [\citen{ma2021robust}, (11b)]:
\begin{small}
\begin{align}\label{KL_1}
	\hspace*{-0.26cm}\mathcal{D}(p_1(y_v)||p_0(y_v))\!\!=\!\!\!\int_{-\infty}^{+\infty}\!\!p_1(y_v)\ln\!\frac{p_1(y_v)}{p_0(y_v)}\!dy_v\!\!=\!\!m\!\!-\!\!\ln\!\left(1\!+\!m\right),
\end{align}
\end{small}where $m=\frac{\lambda_1-\lambda_0}{\lambda_0}=\mathcal{P}d_v^{-\alpha}\mathcal{M}$ and  $\mathcal{M}=a_c|\textbf{g}_v^H\textbf{w}_c|^2+\sum_{j\in\mathcal{K}}a_j|\textbf{g}_v^H\textbf{w}_j|^2$. Since $\textbf{w}_c$ and $\textbf{w}_j$ are isotropically  distributed and independent of $\textbf{g}_v$, RVs $a_c|\textbf{g}_v^H\textbf{w}_c|^2$ and $\sum_{j\in\mathcal{K}}a_j|\textbf{g}_v^H\textbf{w}_j|^2$ respectively follow  $\Gamma(1,a_c)$ and $\Gamma(D_1,\hat{\theta}_1)$. As a result,  $\mathcal{M}$ can be approximated by $\Gamma(D_{\mathcal{M}},\theta_{\mathcal{M}})$, where $D_{\mathcal{M}} = \frac{(a_c+D_1\hat{\theta}_1)^2}{a_c^2+D_1\hat{\theta}_1^2}$ and $\theta_{\mathcal{M}} = \frac{a_c^2+D_1\hat{\theta}_1^2}{a_c+D_1\hat{\theta}_1}$.

Using the inequality $\ln(1 + x) \geq x - {x^2}/{2}$ for $x > 0$, we obtain an upper bound for (\ref{KL_1}), i.e., $\mathcal{D}(p_1(y_v)||p_0(y_v))\leq m^2/2$. Substituting this bound into (\ref{average_covert_constraint}), we arrive at $\zeta=\max_{v\in\Phi_{\text{E}}}\mathbb{E}_{\Phi_{\text{E}}}\left\{d_v^{-\alpha}\right\}\mathcal{P}m_0/2\leq\varsigma$, where $m_0=D_{\mathcal{M}}\theta_{\mathcal{M}}=1$ is the mean of RV $\mathcal{M}$. In the following, we show how to evaluate $\zeta$. 
\begin{small}
\begin{align}
\zeta&=\frac{\mathcal{P}m_0}{2}\int_{r_p}^{\infty}r^{-\alpha}f_{d_v}(r)dr\nonumber\\
&\overset{(a)}{=}\frac{\mathcal{P}m_0\lambda_e\pi}{\exp(-\lambda_e\pi r_p^2)}\int_{r_p}^{\infty}r^{1-\alpha}\exp(-\lambda_e\pi r^2)dr\nonumber\\
&\overset{(b)}{=}\frac{\mathcal{P}m_0(\lambda_e\pi)^{\alpha/2}}{2\exp(-\lambda_e\pi r_p^2)}\int_{\pi\lambda_er_p^2}^{\infty}\frac{\exp(-z)}{z^{\frac{\alpha}{2}}}dz,
\end{align}
\end{small}where $(a)$ can be arrived by using  void probability over a HPPP \cite{haenggi2013stochastic}; $(b)$ comes from $z=\lambda_e\pi r_p^2$. Finally, by applying [\citen{gradshteyn2014table}, Eq. (3.381.6)], we arrive at $\nu\mathcal{P}\leq \varsigma$. 
