\subsection{Document \& Dialogue Graph Traversal Algorithms}
\label{sec:algos}

The algorithms for sampling the document graph in Stage 1 and the dialogue graph in Stage 2 is provided in Algorithm \ref{alg:doc_sampling} and \ref{alg:dial_sampling}, respectively.

\begin{algorithm*}
\caption{Document Graph traversal in Stage 1}
\label{alg:doc_sampling}
\begin{algorithmic}
\REQUIRE Directed, weighted document graph $G_{doc} = (V_{doc}, E_{doc})$, number of documents $n$, start vertex $v_{\text{start}}$, out-degree centrality $deg^{\text{-}}(v)$ for all $v \in V_{doc}$
\ENSURE A set of $n$ related documents $D$

\STATE $D \gets \{v_{\text{start}}\}$
\STATE $v_{\text{current}} \gets v_{\text{start}}$

\FOR{$k \gets 2$ to $n$}
    \STATE Let $O_{v_{\text{current}}} = \{ v_j \mid (v_{\text{current}} \rightarrow v_j) \in E_{doc} \}$
    \IF{$O_{v_{\text{current}}} = \emptyset$}
        \STATE \textbf{break} \COMMENT{No outgoing edges; cannot sample further}
    \ENDIF

    \FORALL{$v_j \in O_{v_{\text{current}}}$}
        \STATE $p_j \gets \frac{deg^{\text{-}}(v_j)}{\sum_{v_{u} \in O_{v_{\text{current}}}} deg^{\text{-}}(v_{u})}$
    \ENDFOR

    \STATE \text{Sample $v_{\text{next}}$ from $O_{v_{\text{current}}}$ according to probabilities $\{p_j\}$}
    \STATE $D \gets D \cup \{v_{\text{next}}\}$
    \STATE $v_{\text{current}} \gets v_{\text{next}}$
\ENDFOR

\RETURN $D$
\end{algorithmic}
\end{algorithm*}


\begin{algorithm*}
\caption{Dialogue Graph traversal in Stage 2}
\label{alg:dial_sampling}
\begin{algorithmic}
\REQUIRE Directed dialogue graph $G_{dial} = (V_{dial}, E_{dial})$, number of utterances $m$, start vertex $v_{\text{start}}$, CR scores $r_{(u \rightarrow v)}$ for all edges $(u \rightarrow v) \in E_{dial}$
\ENSURE A sequence of $m$ Assistant utterances $U$

\STATE $U \gets \{v_{\text{start}}\}$
\STATE $v_{\text{current}} \gets v_{\text{start}}$
\STATE $V_{\text{visited}} \gets \{v_{\text{start}}\}$

\FOR{$t \gets 2$ to $m$}
    \STATE Let $O_{v_{\text{current}}} = \{ v_j \mid (v_{\text{current}} \rightarrow v_j) \in E_{dial} \}$
    \STATE $O_{v_{\text{current}}} \gets O_{v_{\text{current}}} \setminus V_{\text{visited}}$ \COMMENT{Prune previously visited vertices}

    \IF{$O_{v_{\text{current}}} = \emptyset$}
        \STATE \textbf{break} \COMMENT{No more valid next utterances}
    \ENDIF

    \FORALL{$v_j \in O_{v_{\text{current}}}$}
        \STATE $r_j \gets r_{(v_{\text{current}} \rightarrow v_j)}$
    \ENDFOR

    \STATE Let $Z = \sum_{v_j \in O_{v_{\text{current}}}} r_j$
    \FORALL{$v_j \in O_{v_{\text{current}}}$}
        \STATE $p_j \gets \frac{r_j}{Z}$
    \ENDFOR

    \STATE \text{Sample $v_{\text{next}}$ from $O_{v_{\text{current}}}$ with probability distribution $\{p_j\}$}

    \STATE $U \gets U \cup \{v_{\text{next}}\}$
    \STATE $V_{\text{visited}} \gets V_{\text{visited}} \cup \{v_{\text{next}}\}$
    \STATE $v_{\text{current}} \gets v_{\text{next}}$
\ENDFOR

\RETURN $U$

\end{algorithmic}
\end{algorithm*}

