\subsection{Semantic-guided Diffusion Model Decoding}
At the receiver, we adopt a conditional diffusion model for image reconstruction, received latent feature $\hat{\boldsymbol{z}} = f_d(\hat{\boldsymbol{s}};\boldsymbol{\phi}_f)$ serves as the condition for the reverse process. The diffusion process (denoeted by $q$) gradually adds Gaussian noise to an image $\boldsymbol{x}_0$ over a series of time steps, resulting in a sequence of noisy data $\boldsymbol{x}_1, \boldsymbol{x}_2, \ldots, \boldsymbol{x}_N$. The reverse diffusion process (denoted by $q_\theta$) learns to denoise the data step by step. At step $n$, the two Markov processes $q$ and $p_\theta$ can be respectively described as
\begin{equation}
\label{eq:forward}
    q\left(\boldsymbol{x}_n \mid \boldsymbol{x}_{n-1}\right)=\mathcal{N}\left(\boldsymbol{x}_n | \sqrt{1-\beta_n} \boldsymbol{x}_{n-1}, \beta_n \boldsymbol{I}\right),
\end{equation}
% \begin{equation}
%     p_\theta\left(\boldsymbol{x}_{n-1} \mid \boldsymbol{x}_n\right)=\mathcal{N}\left(\boldsymbol{x}_{n-1} \mid M_\theta\left(\boldsymbol{x}_n, n\right), \beta_n \boldsymbol{I}\right),
% \end{equation}
\begin{equation}
    p_\theta\left(\boldsymbol{x}_{n-1} \mid \boldsymbol{x}_n, \hat{\boldsymbol{z}}\right)=\mathcal{N}\left(\boldsymbol{x}_{n-1} \mid M_\theta\left(\boldsymbol{x}_n, \hat{\boldsymbol{z}}, n\right), \beta_n \boldsymbol{I}\right).
\end{equation}
where variable $\beta_n $ serves as a constant hyperparameter. The reverse process is parameterized by a neural network (NN) $M_\theta\left(\boldsymbol{x}_n, \hat{\boldsymbol{z}}, n\right)$. We use a pixel-space prediction NN $\mathcal{X}_\theta$ to learn to directly  reconstruct image  $x_0$ instead of noise $\epsilon$ \cite{salimans2022progressive}. The loss function can be described as follows
% \begin{equation}
% \label{Eq_noise}
%     \mathcal{L}\left(\theta, x_0\right)=\mathbb{E}_{\boldsymbol{x}_0, n, \epsilon}\left\|\epsilon-\epsilon_\theta\left(\boldsymbol{x}_n, n\right)\right\|^2,
% \end{equation}
\begin{equation}
    \mathcal{L}\left(\theta, x_0\right) = \mathbb{E}_{\boldsymbol{x}_0, n, \epsilon} \frac{\alpha_n}{1-\alpha_n}\left\|\boldsymbol{x}_0-\mathcal{X}_\theta\left(\boldsymbol{x}_n, \hat{\boldsymbol{z}}, \frac{n}{N_{\text {train }}}\right)\right\|^2,
\end{equation}
where $n \sim \operatorname{Unif}\{1, \ldots, N\}$, with $\operatorname{Unif}$ denoting a uniform distribution over the set ${1, 2, \ldots, N}$, $\epsilon \sim \mathcal{N}(\boldsymbol{0}, \boldsymbol{I})$ and $\alpha_n=\prod_{i=1}^n\left(1-\beta_i\right)$.We condition the model on the pseudo-continuous variable $\frac{n}{N_{\text {train}}}$ which offers additional flexibility in choosing the number of denoising steps for decoding. 

Once the model is trained, image can be generated by the denoising diffusion implicit model (DDIM) \cite{song2020denoising} that follows a deterministic generation, which is 
\begin{equation}
    \boldsymbol{x}_{n-1}=\sqrt{\alpha_{n-1}} \mathcal{X}_\theta\left(\boldsymbol{x}_n, \hat{\boldsymbol{z}}, \frac{n}{N}\right)+\sqrt{1-\alpha_{n-1}} \epsilon_\theta\left(\boldsymbol{x}_n, \hat{\boldsymbol{z}}, \frac{n}{N}\right).
\end{equation}






