        \State $\overline{\boldsymbol{x}}_0=\mathcal{X}_\theta\left(\overline{\boldsymbol{x}}_n, n / N_{\text {train }}, {\boldsymbol{z}}\right)$
        \State $\begin{aligned}  \mathcal{L} = \mathbb{E}_{\boldsymbol{x}_0}[
    d(\boldsymbol{x}_0, \overline{\boldsymbol{x}}_0) 
   + \lambda[-\log p_{{\boldsymbol{z}}\mid {y}}({\boldsymbol{z}} \mid {\boldsymbol{y}})-\log p_{{y}}({\boldsymbol{y}})]\end{aligned}$
        \State Update the parameters $\left(\boldsymbol{\theta}_g, \boldsymbol{\phi}_g, \boldsymbol{\theta}_h, \boldsymbol{\phi}_h\right)$
   \EndFor


    \State \textbf{Stage 2: Train $f_e,$ $f_d$}
    \State Load and freeze the parameters trained in Stage 1 and randomly initialize $f_e$ and $f_d$
    \For{each epoch} % 第二阶段循环
        \State Sample $\boldsymbol{x} \sim p_{\boldsymbol{X}}$
        \State Calculate the loss function based on Eq.(\ref{loss})
        \State Update parameters: $\left(\boldsymbol{\theta}_f, \phi_f\right)$
    \EndFor

    \State \textbf{Stage 3: Fine-tune the whole model}
    \State Load the parameters trained in the previous stages
    \For{each epoch} % 第三阶段循环
        \State Repeat steps 14 to 16
        \State Update parameters $\left(\boldsymbol{\theta}_g, \boldsymbol{\theta}_h, \phi_g, \phi_h, \boldsymbol{\theta}_f, \phi_f\right)$
    \EndFor

        \renewcommand{\algorithmicensure}{\textbf{Output:}}
    \Ensure Parameters $\left(\boldsymbol{\theta}_g^*, \phi_g^*, 
    \boldsymbol{\theta}_h^*, \phi_h^*, \boldsymbol{\theta}_f^*, \phi_f^*\right)$

\end{algorithmic}
\end{algorithm}






To ensure training stability and enhance overall performance, we propose a multi-stage training strategy. Initially, we train each module individually~\cite{Xwei} to reduce complexity and facilitate convergence~\cite{W2V_}. Once all modules have been trained separately, we fine-tune the entire model. The complete multi-stage training process is shown in Algorithm 1. First, train $g_e$, $g_d$, $h_e$ and $h_d$. Secondly, train JSCC codecs $f_e$ and $f_d$ with channel data. At last, fine-tune all modules from the aforementioned two steps in an end-to-end optimization manner.







\section{Simulation Analysis and Discussions}
%In this section, we conduct simulations to assess the performance of the proposed LRISC. 



\subsection{Simulation Settings}
For our experiments, we use the COCO dataset %\cite{lin2015microsoftcococommonobjects}%
for training, and we select 50,000 images, which are randomly cropped to 256 × 256, and the Kodak dataset for testing. We implement the proposed LRISC model using the PyTorch framework. We exploit the Adam optimizer with an initial learning rate of $1 \times 10^{-4}$, and the batch size is set to 16. 
In the first stage, we randomly initialize the model parameters and train $g_e$, $g_d$, $h_e$ and $h_d$, the training steps set to $10^{6}$. In the second stage, we first train JSCC codec $f_e$ and $f_d$ with a fixed channel state (SNR = 10dB) except for the snr adaptive module. Then, the whole JSCC codec is trained with snr adaptive module with variable channel state. Finally, during fine-tuning, all model parameters are unfrozen, and the model is trained on the full COCO training dataset for another 20 epochs, with a gradually decaying learning rate.
 The scaling factor $\beta$ is set to 0.2 at SNR = 10dB, the perception and distortion trade-off parameter $\eta$ is set to 0.5. The training process is conducted on an NVIDIA RTX 4090 GPU to accelerate computation. 
