 \section{Metric Space Preliminaries}\label{sec:metricpreliminaries}


The following are basic definitions of metric spaces used throughout this work. 


\begin{definition}[Metric Space]
A pair $(\mathcal{X}, d)$, where $d : \mathcal{X} \times \mathcal{X} \to [0,1]$, is a metric space if:
\begin{enumerate}
    \item $d(x,x) = 0$ for all $x \in \mathcal{X}$ (identity),
    \item $d(x,y) = d(y,x)$ for all $x,y \in \mathcal{X}$ (symmetry),
    \item $d(x,z) \leq d(x,y) + d(y,z)$ for all $x,y,z \in \mathcal{X}$ (triangle inequality).
\end{enumerate}
The $r$-ball centered at $x \in \mathcal{X}$ is defined as $B_r(x) = \{ y \in \mathcal{X} \mid d(x,y) \leq r \}$.
\end{definition}

We also define a covering of a metric space.

\begin{definition}[$\epsilon$-Covering]\label{def:covering}
A set $(x_1, \dots, x_k) \in \mathcal{X}^k$ is an $\epsilon$-covering of $(\mathcal{X}, d)$ if the union of $\epsilon$-balls covers the entire space, i.e., $\mathcal{X} \subseteq \bigcup_{i=1}^k B_\epsilon(x_i)$. The covering number $N(\mathcal{X}, d, \epsilon)$ is the minimal size of an $\epsilon$-covering of $(\mathcal{X}, d)$.
\end{definition}


\begin{remark}[Covering Number of Euclidean Space]\label{rem:euclidean_covering}
For every $p \geq 0$ and $m \geq 1$, the Euclidean space $([0,1]^m, \|\cdot\|_p)$ is defined as $([0,1]^m, d)$, where $d(x,y) = \|x - y\|_p$.
The covering number of the Euclidean space satisfies $N([0,1]^m, \|\cdot\|_p, \epsilon) = O((1/\epsilon)^m)$.
\end{remark}




















\section{Missing Remarks of Section 2}\label{sec:examplesthree}




\begin{remark}[Minimzing Sum of Distances is Not Representative]\label{rem:sumdist}
\citet*{DBLP:journals/corr/abs-2406-00913} consider a model in which agents are embedded in a similarity metric space.
They argue that, intuitively, selecting a panel to minimize the sum of distances from each agent to their nearest panel member does not necessarily yield a representative panel \cite[Example 7]{DBLP:journals/corr/abs-2406-00913}.
To illustrate this, they construct an example with two agents located at extreme positions $A$ and $B$, far from all other agents and from each other. The remaining $n - 2$ agents are evenly split between two locations, $C$ and $D$, which are 10 units apart.

For a panel size of $k = 3$, this distance-minimizing method would select the two outliers at $A$ and $B$, along with only one agent from the majority group, resulting in a highly non-representative panel. This is problematic because most of the population resides in either $C$ or $D$.

Using our notation, this example corresponds to a feature vector
$f = (-\infty, -5, \ldots, -5, 5, \ldots, 5, \infty)$,
where the number of $-5$ values is $(n - 1)/2$ and the number of $5$ values is also $(n - 1)/2$.
To satisfy our definition of $\epsilon$-representativeness (\Cref{def:representativeness}) for any $\epsilon > 0$, the panel would need to include the entire population, i.e., it must be that $k = n$.
Thus, our definition aligns with the intuition of \citet*{DBLP:journals/corr/abs-2406-00913}.
\end{remark}

\begin{remark}[Comparing Sampling With and Without Replacement]\label{remark:withwithout}
Intuitively, sampling without replacement yields a more representative panel than sampling with replacement.

Consider first the case where the population size $n$ is large. By the union bound, the probability of selecting the same individual more than once when sampling with replacement is at most $\binom{k}{2}/n$. Thus, as $n$ grows large, the two sampling schemes become nearly equivalent.

In the other extreme case of a small population with $n = 2$, sampling without replacement guarantees that a panel of size $k = 2$ includes both agents. In contrast, sampling with replacement requires a panel of size at least $\log(1/\delta) + 1$ to ensure, with probability at least $1 - \delta$, that both individuals are included. This illustrates that sampling with replacement can lead to higher panel complexity to achieve certain desirable guarantees.

\Cref{lem:W1expectation} extends this intuition beyond these extreme cases.
\end{remark}

\begin{remark}[Counterexample to Stochastic Dominance]\label{ex:sd}
    Using the notation of \Cref{lem:W1expectation}, we show that there exists a population of $n$ agents and a feature $f : [n] \to [0,1]$ such that:
    \begin{align}
        \mathbb{P}_{S \sim \mathcal{R}_{k,n}} \left[ W(\phi_f^{[n]}, \phi_f^{S}) \leq \delta \right] 
        > 
        \mathbb{P}_{S \sim \mathcal{U}_{k,n}} \left[ W(\phi_f^{[n]}, \phi_f^{S}) \leq \delta \right] 
        \quad \text{for some } \delta > 0,
        \label{eq:stochdominance}
    \end{align}
    meaning that the (first-order) stochastic dominance condition may fail.

    Consider a population of size $n = 5$ with feature values given by the vector $f = (0, 1/2, 1/2, 1/2, 1)$. Let the panel size be $k = 2$. We will demonstrate that:
    \begin{align}
        \mathbb{P}_{S \sim \mathcal{R}_{k,n}} \left[ W(\phi_f^{[n]}, \phi_f^{S}) \leq 0.2 \right] 
        \geq 
        9/25 = 0.36,
        \quad\text{while}\quad 
        \mathbb{P}_{S \sim \mathcal{U}_{k,n}} \left[ W(\phi_f^{[n]}, \phi_f^{S}) \leq 0.2 \right] 
        = 
        3/10 = 0.3.
        \label{eq:exam}
    \end{align}
    This contradicts the inequality in \Cref{eq:stochdominance}.
    We first compute the Wasserstein distance for different panels based on the feature values of their members:
    \begin{align*}
        \text{If } f(S) &= \{0, 1/2\}, \text{ then } 
        W(\phi_f^{S}, \phi_f^{[n]}) = (1/2) \cdot \left( 1/2 - 1/5 \right) + (1/2) \cdot (1/5) = 1/4 = 0.25. \\
        \text{If } f(S) &= \{1/2, 1/2\}, \text{ then } 
        W(\phi_f^{S}, \phi_f^{[n]}) = (1/2) \cdot (1/5) + (1/2) \cdot (1/5) = 1/5 = 0.2. \\
        \text{If } f(S) &= \{0, 1\}, \text{ then } 
        W(\phi_f^{S}, \phi_f^{[n]}) = (1/2) \cdot \left( 1/2 - 1/5 \right) + (1/2) \cdot \left( 1/2 - 1/5 \right) = 0.3.
    \end{align*}
    The case $f(S) = \{1/2, 1\}$ is symmetric to $f(S) = \{0, 1/2\}$.

    Note that $W(\phi_f^{S}, \phi_f^{[n]}) \leq 0.2$ holds only when $f(S) = \{1/2, 1/2\}$. Thus, \Cref{eq:exam} follows since the probability of drawing two agents with feature value $1/2$ when sampling with replacement is $(3/5)^2 = 9/25$, and when sampling without replacement it is $\binom{3}{2} / \binom{5}{2} = 3/10$.

    Note that the calculations above yield only a lower bound on 
    $\mathbb{P}_{S \sim \mathcal{R}_{k,n}} [ W(\phi_f^{[n]}, \phi_f^{S}) \leq 0.2 ]$, 
    since we did not consider panels with $f(S) = \{0,0\}$ or $f(S) = \{1,1\}$. However, these combinations occur with zero probability when sampling without replacement.
\end{remark}


\section{Missing Proofs of Section 2}\label{sec:missingthree}

\subsection{Proof of Lemma 2.3}
The following lemma follows from the proof of \citet*[Theorem 4]{Hoeffding63}. Although \citet*{Hoeffding63} established the result only for the case $V = \mathbb{R}$, it has been noted by \citet*{polaczyk2023concentrationboundssamplingreplacement} and \citet*{gross2010notesamplingreplacingfinite} that the proof extends to any normed vector space without modification.

\begin{lemma}[\citet*{Hoeffding63}]\label{lem:hoeffdingexpectation}
    Let $V$ be a normed vector space,  $x_1, \ldots, x_n \in V$, and $\psi : V \to \mathbb{R} \cup \{+\infty\}$ be a convex function. Then, it holds that:
    \begin{align*}
    \mathbb{E}_{S \sim \uniformpanel} \left[ \psi\left( \sum_{i \in S} x_i \right) \right] 
    \leq \mathbb{E}_{S \sim \mathcal{R}_{k,n}} \left[ \psi\left( \sum_{i \in S} x_i \right) \right].
\end{align*}
\end{lemma}

To apply \Cref{lem:hoeffdingexpectation}, we first establish the convexity of the Wasserstein distance.
\begin{lemma}[Convexity]\label{lem:w_convexity}
Let $\phi, \psi_1, \psi_2$ be discrete probability distributions over a metric space $(\mathcal{X}, d)$, and let $\psi = t \cdot \psi_1 + (1-t) \cdot \psi_2$ be their convex combination for some $t \in (0,1)$. Then, the following holds:  
\[
W(\phi, \psi) \le t \cdot W(\phi, \psi_1) + (1-t) \cdot  W(\phi, \psi_2).
\]
\end{lemma}
\begin{proof}
Let $\gamma_1$ and $\gamma_2$ be optimal couplings attaining the minimum in the definition of $W(\phi, \psi_1)$ and $W(\phi, \psi_2)$, respectively. That is,  
\[
\gamma_1 \in \argmin_{\gamma \in \Gamma(\phi, \psi_1)} \mathbb{E}_{(x,y) \sim \gamma} [d(x,y)]
\quad \text{and} \quad  
\gamma_2 \in \argmin_{\gamma \in \Gamma(\phi, \psi_2)} \mathbb{E}_{(x,y) \sim \gamma} [d(x,y)].
\]
Consider a coupling $\gamma=t \cdot \gamma_1+(1-t) \cdot \gamma_2$. It is easy to see that $\gamma \in \Gamma(\phi, \psi)$ since, given any $A \subseteq \mathcal{X}$, it holds that:
\begin{align*}
    \gamma(\mathcal{X} \times A) = t \cdot \phi(A) + (1-t) \cdot \phi(A) = \phi(A), \quad
    \gamma(A \times \mathcal{X}) = t\cdot \psi_1(A) + (1-t) \cdot \psi_2(A) = \psi(A).
\end{align*}
It follows that:
\begin{align*}
   \mathbb{E}_{(x,y) \sim \gamma}\left[ d(x,y) \right] &= t \cdot \mathbb{E}_{(x,y) \sim \gamma_1}\left[ d(x,y) \right] + (1-t) \cdot \mathbb{E}_{(x,y) \sim \gamma_2}\left[ d(x,y) \right]  = t \cdot W(\phi, \psi_1) + (1-t) \cdot  W(\phi, \psi_2).
\end{align*}
which concludes the proof.
\end{proof}

We are now ready to prove \Cref{lem:W1expectation}.

\SamplingWithoutReplacementExpectation*
\begin{proof}
Let $F = \{f_1, \ldots, f_n\}$, and consider the normed vector space $(\mathbb{R}^F, \|\cdot\|_1)$. 
We interpret any $v \in \mathbb{R}^F$ satisfying $v_j \geq 0$ for all $j \in F$ and $\sum_{j \in F} v_j = 1$ as a probability distribution over $F$, assigning mass $v_j$ to the element $j \in F$.
We define $\psi : \mathbb{R}^F \to \mathbb{R} \cup \{+\infty\}$ by:
\begin{align*}
    \psi(v) = \begin{cases}
        W(\phi_f^{[n]}, v) & \text{if } v_j \geq 0 \text{ for all } j \in F \text{ and } \sum_{j \in F} v_j = 1,\\
        +\infty & \text{otherwise.}
    \end{cases}
\end{align*}
Next, for each $i \in [n]$ we define the vector $x_i \in \mathbb{R}^F$ by setting for each $j \in F$:
\begin{align*}
    x_{i,j} = \begin{cases}
        1/k & \text{if } j = f(i), \\
        0 & \text{otherwise.}
    \end{cases}
\end{align*}
Then, by \Cref{lem:hoeffdingexpectation}, we obtain:
\begin{align*}
    \mathbb{E}_{S \sim \uniformpanel} \left[ W(\phi_f^{[n]}, \phi_f^S) \right] =  \mathbb{E}_{S \sim \uniformpanel} \left[ \psi\left( \sum_{i \in S} x_i \right) \right] \leq \mathbb{E}_{S \sim \mathcal{R}_{k,n}} \left[ \psi\left( \sum_{i \in S} x_i \right) \right]
    = \mathbb{E}_{S \sim \mathcal{R}_{k,n}} \left[ W(\phi_f^{[n]}, \phi_f^{S}) \right].
\end{align*}
as needed.
\end{proof}



\subsection{Proof of Lemma 2.4}
The following lemma follows directly from the proof of \citet*[Proposition 20]{weed2017sharpasymptoticfinitesamplerates}. 
\begin{lemma}[\citet*{weed2017sharpasymptoticfinitesamplerates}]\label{lem:weed}
   Let $f: [n] \to \mathcal{X}$ be a feature.
   Suppose that $d(x,y) \leq 1$ for all $x,y \in \mathcal{X}$.
    Let $x_1, \ldots, x_k \in \mathcal{X}$ and $x_i' \in \mathcal{X}$. Then, it holds that:
    \begin{align*}
        W(\phi_f^{[n]}, \phi_f^{(x_i, x_{-i})}) -  W(\phi_f^{[n]}, \phi_f^{(x_i', x_{-i})}) \leq 1/k.
    \end{align*}
\end{lemma}

We also use of the following McDiarmid-style inequality of \citet*[Proposition 2]{sambale2022concentration}.
\begin{lemma}[\citet*{sambale2022concentration}]\label{lem:sambale}
Let $g : [n]^k \to \mathbb{R}$ be a symmetric function; that is, for any permutation $\pi : [k] \to [k]$, we have $g(x_1, \ldots, x_k) = g(x_{\pi(1)}, \ldots, x_{\pi(k)})$.
Suppose there exists  $c > 0$ such that for all $x_1, \ldots, x_k, x_i' \in [n]$, it holds that $|g(x_i, x_{-i}) - g(x_i', x_{-i})| \leq c$.
Then, we have:
\begin{align*}
     \mathbb{P}_{S \sim \uniformpanel} \left[ g(x_S) \geq \mu + t \right] 
    \leq \exp\left( \frac{-t^2}{4 (1-k/n) c^2 k }\right) \quad\text{where }\mu = \mathbb{E}_{S \sim \uniformpanel}\left[g(x_S)\right].
\end{align*}
\end{lemma}

We are now ready to prove \Cref{lem:W1concentration}.

\SamplingWithoutReplacementConcentration*
\begin{proof}
Since $W(\phi_f^{[n]}, \cdot)$ is a symmetric function, and by \Cref{lem:weed}, we may apply \Cref{lem:sambale} with $c = 1/k$ to obtain:
\begin{align*}
    \mathbb{P}_{S \sim \uniformpanel} \left[ W(\phi_f^{[n]}, \phi_f^S) \geq \mu + t \right] \leq \exp\left( \frac{-t^2}{4 (1-k/n) c^2 k }\right) =  \exp\left( \frac{-t^2k}{4 (1-k/n) }\right) \leq  \exp\left( \frac{-t^2k}{4 }\right)
\end{align*}
as needed.
\end{proof}

\subsection{Proof of Lemma 2.6}

\WassersteinImpliesAvg*
\begin{proof}
Let $\phi^{[n]}_f$ and $\phi^S_f$ denote the population and panel distributions with respect to $f$, respectively, and let $f(A) \subseteq [0,1]$ represent the image of a subset $A \subseteq [n]$. 
The result follows from the Kantorovich–Rubinstein duality~\cite{villani2008optimal}, which provides an alternative expression for the Wasserstein distance:
\begin{equation*}
        W(\phi^{[n]}_f, \phi^S_f) = \sup_{||g||_{\mathsf{Lip}} \le 1} \left \{ \sum_{y \in f([n])} g(y) \cdot \phi^{[n]}_f(y) - \sum_{z \in f(S)} g(z) \cdot \phi^S_f(z) \right \},
\end{equation*}
where the supremum is taken over all Lipschitz functions $g : [0,1] \rightarrow \mathbb{R}$ with Lipschitz constant at most $1$, i.e., $||g||_{\mathsf{Lip}} \le 1$. The functions $g_1(y) = y$ and $g_2(y) = -y$ clearly satisfy this condition. Together with the assumption of $\epsilon$-representativeness, this implies:
\begin{align*}
       \epsilon \geq W(\phi^{[n]}_f, \phi^S_f) &\ge \sum_{y \in f([n])} y \cdot \phi^{[n]}_f(y) - \sum_{z \in f(S)} z \cdot \phi^S_f(z) = \frac{1}{n}\sum_{i \in[n]} f(i) - \frac{1}{|S|}\sum_{j \in S} f(j),\\
       \epsilon \geq W(\phi^{[n]}_f, \phi^S_f) &\ge \sum_{z \in f(S)} z \cdot \phi^S_f(z) - \sum_{y \in f([n])} y \cdot \phi^{[n]}_f(y) = \frac{1}{|S|}\sum_{j \in S} f(j) - \frac{1}{n}\sum_{i \in[n]} f(i).
\end{align*}
The result follows.
\end{proof}


\subsection{Proof of Lemma 2.8}

\panelcamouflaged*
\begin{proof}
Let us define $\mathcal{R}_{k,n}$ as the probability distribution corresponding to sampling \emph{with} replacement from the population.
We use the following result of \citet*[Lemma 5.10]{duetting2025pseudodimensioncontracts}, which guarantees if it holds that:
\begin{align*}
    \mathbb{P}_{(i_1, \ldots, i_k) \sim \mathcal{R}_{k,n}} \left[ \| g(f_{i_1, \ldots, i_k}(z,h,w,r)) - z \|_1 \leq  h/4 \right] \geq 3/4
\quad \text{for all } z \in \{-1,+1\}^{h},
\end{align*}
then it must be that $k = \Omega(h \cdot w^2)$.
A key distinction between this statement and that of the lemma is how the panel is formed. In the lemma, the panel consists of $k$ uniformly sampled agents without repetition, ensuring that set $S$ contains distinct elements. In contrast, \citet*{duetting2025pseudodimensioncontracts} considers drawing $k$ agents uniformly at random, allowing for possible repetitions. 

 We choose an integer parameter $r$ large enough such that $k^2/(2n) = k^2/(4 hwr) \leq 1/8$.

    Next, we define the event that no repetition occurs:
    \begin{align*}
        E = \{(i_1, \ldots, i_k) \in [n]^k \,:\, i_a \neq i_b \text{ for all }a,b \in [k]\}.
    \end{align*}
   We bound the probability of repetition using the union bound: 
    \begin{align*}
        \mathbb{P}_{(i_1,\ldots,i_k) \sim \mathcal{R}_{k,n}} [E] \geq 1- \sum_{a \neq b} \mathbb{P}_{(i_1,\ldots,i_k) \sim \mathcal{R}_{k,n}} [i_a = i_b] = 1-  {\binom{k}{2}} \cdot \frac{1}{n} \geq  1- \frac{k^2}{2n} \geq \frac{7}{8}.
    \end{align*}
    Thus, for all $z \in \{-1,+1\}^{\ell}$, we have:
\begin{align*}
   \mathbb{P}_{(i_1,\ldots,i_k) \sim \mathcal{R}_{k,n}} &\left[ \| g(f_{i_1, \ldots, i_k}(z,h,w,r)) - z \|_1 \leq h/4 \right] \\
   &\geq \mathbb{P}_{(i_1,\ldots,i_k) \sim \mathcal{R}_{k,n}} \left[ \| g(f_{i_1, \ldots, i_k}(z,h,w,r)) - z \|_1 \leq h/4 \text{ and } E \text{ holds}\right] \\
   &\geq \mathbb{P}_{(i_1,\ldots,i_k) \sim \mathcal{R}_{k,n}} \left[ \| g(f_{i_1, \ldots, i_k}(z,h,w,r)) - z \|_1 \leq h/4  \,|\, E\right] \cdot \mathbb{P}_{(i_1,\ldots,i_k) \sim \mathcal{R}_{k,n}} [E] \\
   &\geq \mathbb{P}_{(i_1,\ldots,i_k) \sim \mathcal{R}_{k,n}} \left[ \| g(f_{i_1, \ldots, i_k}(z,h,w,r)) - z \|_1 \leq h/4  \,|\, E\right] \cdot (7/8) \\
   &= \mathbb{P}_{S \sim \uniformpanel} \left[ \| g(f_S(z,h,w,r)) - z \|_1 \leq h/4 \right] \cdot (7/8) \\
   &\geq (6/7) \cdot (7/8) \\
   &\geq 3/4.
\end{align*}
This concludes the proof.
\end{proof}


\section{Missing Proofs of Section 3}\label{sec:missingfour}

\pbimpossibilityefficiency*
\begin{proof}
    Let $B_1, B_2 \geq 0$ satisfy $B_1 + B_2 = B$ and $B_1 + B_2 / m \leq 1$. When $B \geq 1$, choosing $B_1 = (m-B)/(m-1)$ and $B_2 = (m \cdot B - m) / (m-1)$ ensures that $B_1 + B_2 = (m-B+m\cdot B - m)/(m-1) = B$ and $B_1 + B_2/m = (m-B + B-1)/(m-1) = 1$. When $B < 1$, setting $B_1 = B$ and $B_2 = 0$ satisfies the conditions.
    For any $x \in [0,1]^m$, define three cost functions as:
    \begin{align*}
        \cost^{(0)}(x) &= (1/B_2) \cdot \sum_{i=1}^{m} \max(B_2/m - x_i, 0), \\
        \cost^{(1)}(x) &= B_1 + B_2/m - x_1, \\
        \cost^{(2)}(x) &= B_1 + B_2/m - x_2.
    \end{align*}
    These are valid cost functions in our model since $B_2 \leq m$ and $B_1 + B_2 / m \leq 1$.

Consider the following two participatory budgeting instances: $\langle m, B, (\cost^{(0)}, \ldots, \cost^{(0)}, \cost^{(1)}) \rangle$ and $\langle m, B, (\cost^{(0)}, \ldots, \cost^{(0)}, \cost^{(2)}) \rangle$. These instances differ only in the cost function assigned to the $n$-th agent.
In the first instance, an allocation $x$ with $x_i = B_2 / m$ for $i \neq 1$ and $x_1 = B_1 + B_2/m$ results in zero cost for all agents. 
This is a feasible budget allocation since $B_1 + B_2 = B$.
Similarly, in the second instance, setting $x_i = B_2 / m$ for $i \neq 2$ and $x_2 = B_1 + B_2/m$ also yields a cost of zero for all agents. Thus, the optimal cost in both instances is $\socialopt = 0$.

Now, let $y = \widetilde{x}(\cost^{(0)}, \ldots, \cost^{(0)})$. Since $\sum_{j=1}^{m} y_j \leq B$ and $B_1 + B_2 = B$, at least one of the following must hold: $y_1 < B_1 + B_2/m$, $y_2 < B_1 + B_2/m$, or $y_j < B_2/m$ for some $j \geq 3$.

In the first case, we obtain 
\begin{align*}
\mathbb{E}_{S \sim \uniformpanel} [ \social(\widetilde{x}(S)) ] \geq \mathbb{P}_{S \sim \uniformpanel}[S \subseteq \{1, \ldots, n-1\}] \cdot (B_1 + B_2/m - y_1) > 0.    
\end{align*}
The cases where $y_2 < B_1 + B_2/m$ or $y_j < B_2/m$ follow analogously.
\end{proof}


