\subsection{Proofs of Section 4.2}\label{sec:starsandthings}









\MultiplicativePACGuarantee*

\begin{proof}[Proof of~\Cref{thm:reduction}]
    We analyze the following formulation of the expected panel cost:
    \begin{align*}
        \mathbb{E}_{S \sim \uniformpanel}[\social(\overline{q}(S)) ] &= \int_{0}^\infty \mathbb{P}_{S \sim \uniformpanel}[\social(\overline{q}(S)) \geq x ] \,\mathrm{d}x.
    \end{align*}
    We split the analysis of this integral into different intervals of $x\in [0,\infty)$.
    We denote $\opt = \socialopt$.
    First, since probabilities are always bounded by $1$:
    \begin{align*}
        \int_{0}^{(1+\epsilon) \cdot \opt} \mathbb{P}_{S \sim \uniformpanel}[\social(\overline{q}(S)) \geq x ] \,\mathrm{d}x \leq (1 + \epsilon) \cdot \opt.
    \end{align*}
    Second, by the PAC-style guarantee with multiplicative error:
    \begin{align*}
        \int_{(1+\epsilon) \cdot \opt}^{4 \cdot \opt} \mathbb{P}_{S \sim \uniformpanel}[\social(\overline{q}(S)) \geq x ] \,\mathrm{d}x \leq \int_{(1+\epsilon) \cdot \opt}^{4 \cdot \opt} \epsilon \,\mathrm{d}x  \leq 3\epsilon \cdot \opt.
    \end{align*}
    Third, for $x > 4\cdot \opt$, we prepare to apply \Cref{thm:tail_bound}. To do so, observe that by triangle inequality 
    \[
    d(q^{\star},\overline{q}(S)) + \social(q^\star) =   d(q^{\star},\overline{q}(S)) + \opt \geq \social(\overline{q}(S)),
    \]
    implying for any $X>0$,
    \begin{align*}
        \mathbb{P}_{S \sim \uniformpanel}[\social(\overline{q}(S)) \geq (1+X)\cdot \opt ] \leq \mathbb{P}_{S \sim \uniformpanel}[d(q^\star, \overline{q}(S)) \geq X \cdot \opt].
    \end{align*}
    This gives us
    \begin{align*}
        \int_{4 \cdot \opt}^{\infty} &\mathbb{P}_{S \sim \uniformpanel}[\social(\overline{q}(S)) \geq x ] \,\mathrm{d}x \\
        & =  \int_{4 \cdot \opt}^{\infty} \mathbb{P}_{S \sim \uniformpanel}[\social(\overline{q}(S)) \geq (1 + (x/\opt - 1)) \cdot \opt ] \,\mathrm{d}x \\
        & \leq \int_{4\cdot \opt}^\infty \mathbb{P}_{S \sim \uniformpanel}[d(q^\star, \overline{q}(S)) \geq (x/\opt - 1) \cdot \opt] \ \mathrm{d}x.
    \end{align*}
For $x \geq 4 \cdot \opt$, we wish to apply \Cref{thm:tail_bound} with parameters $T = x/\opt - 1$ and $\delta = {3\epsilon}/{T^2}$. First, observe that $T > 2$ since in this case $T \geq 4 \cdot \opt/{\opt} - 1 = 3$.
We then compute the required panel size as:
    \[
    \frac{2 \cdot \log{(1/\delta)}}{\log \left(T^2/(4(T-1))\right)} = \frac{\log\left(T^2/(3\epsilon)\right)}{\log(T/8)}=  \frac{2\log(T) + \log\left(1/(3\epsilon))\right)}{\log(T) - \log(8)} = O\left(\log\left(\frac{1}{\epsilon}\right)\right).
    \]
Thus,  \Cref{thm:tail_bound} gives:
    \begin{align*}
       \int_{4\cdot \opt}^\infty &\mathbb{P}_{S \sim \uniformpanel}[d(q^\star, \overline{q}(S)) \geq (x/\opt - 1) \cdot \opt] \ \mathrm{d}x 
        \leq  \int_{4 \cdot \opt}^{\infty} \frac{3\epsilon}{(x/\opt - 1)^2} \,\mathrm{d}x  \\
        &=  3\epsilon \cdot \frac{\opt^2}{\opt-x} \Big|_{4 \cdot \opt}^{\infty} = 
3 \epsilon \cdot \frac{\opt}{3} = \epsilon \cdot \opt, 
    \end{align*}
as desired.
\end{proof}




\StarLowerBound*

\begin{proof}
Consider a population of $n = 2k + 1$ agents located at $x_1, \ldots, x_{k} = 0$ and $x_{k+1}, \ldots, x_{2k} = 1$.
We leave the location of $x_{2k + 1}$ unspecified for now.
Let $\mathcal{C} = \mathcal{X} = [0,1]$ and $d(x,y) = |x-y|$.
Notice that the unique optimal location is $q^\star = x_{2k + 1}$, regardless of $x_{2k+1}$. We compute: \begin{align*} \opt \leq \left({T}/2 + \left(1 - {T}/{2}\right)\right) \cdot (1/2) = 1/2. \end{align*}

Notice that the probability that a panel $S \sim \mathcal{U}_{k,n}$ contains agent $2k + 1$ is at most $1/2$.
Conditioned on the event that the panel does not contain agent $2k + 1$, we have that $\widetilde{x}(S)$ selects either $0$ with probability at least $1/2$ or $1$ with probability at least $1/2$.
Assume without loss of generality that the latter case holds, and let $x_{2k + 1} = 0$.
Now, with probability at least $1/4$ over the draw of a panel $S \sim \mathcal{U}_{k,n}$, the panel decision function $\widetilde{q}$ selects the facility at $1$. For each such panel $S$ we have:
\begin{align*} d(\widetilde{q}(S), q^\star) = d(1, 0) = 1 \geq 2 \cdot \opt, \end{align*} since $\opt \leq 1/2$ as shown above. This concludes the proof.
\end{proof}










\subsection{Proofs of Section 4.3} \label{apx:facility_efficiency}

\AssouadLowerBound*








\begin{proof}
   Our goal is to construct a function $g$ that satisfies the assumption of \Cref{lem:sample_lower_bound}, establishing a necessary lower bound on $k$.
    Let $w = \lfloor (1/64) \cdot (1 / \epsilon) \rfloor$. 
    Note that $\epsilon \leq (1/64) \cdot (1/w)$
    {and that $1/w = \Omega(1/\epsilon)$}.
    Let $r > 1$ be {an integer parameter} large enough to satisfy the conditions of \Cref{lem:sample_lower_bound}. 

    For every $z \in \{-1,+1\}^{t}$, consider a camouflaged population of size $n = 2twr$ with a feature $f(z,t,w,r)$ as in \Cref{def:almost_uniform}.
    We will now define a facility location instances $\mathcal{I}(z) = \langle \mathcal{X}, \mathcal{C}, d, (x_1^{(z)}, \ldots, x_n^{(z)}) \rangle$ as follows.
    Let $c = (1/2, 1/2, \ldots, 1/2) \in \mathcal{X}$ and let $e_j = (0, \ldots, 0, 1/2, 0, \ldots, 0)$ for $j \in [t]$ where the $1/2$ entry is in the $j$-th position.
    For every agent $i \in [n]$, we set:
   \begin{align*}
        x_i^{(z)} = \begin{cases}
            c + e_j & \text{if } f_i(z,t,r,w) = 2j,\\
            c - e_j & \text{if } f_i(z,t,r,w) = 2j-1.
        \end{cases}
    \end{align*}
    Note that exactly a $(1+z_j/w)/(2t)$-fraction of the population has location $c + e_j$, while exactly a $(1-z_j/w)/(2t)$-fraction has location  $c - e_j$. 
    It follows that:
    \begin{align*}
         \social(q) = \sum_{j=1}^t \left(\frac{1+z_j/w}{2t} \right) \cdot 
         \| c + e_j - q \|_{\infty}
         + \left( \frac{1-z_j/w}{2t} \right) \cdot \| c - e_j - q \|_{\infty}.
    \end{align*}
To obtain an upper bound on the optimal social cost, fix any $z \in \{-1, +1\}^t$ and consider the location:
\begin{align*}
    q^\star = c + \sum_{j \in [t]} (1/2) \cdot z_j \cdot e_j \in \mathcal{C}.  
    \end{align*}
    We obtain:
    \begin{align*}
       \socialopt(\mathcal{I}(z)) \leq \social(q^\star)
       = \sum_{j=1}^t \left(\frac{1+1/w}{2t} \right) \cdot (1/4) + \left( \frac{1-1/w}{2t} \right) \cdot (3/4) = \frac{1}{2} - \frac{1/w}{4}.
    \end{align*}
    Now, fix an arbitrary candidate location $q \in \mathcal{C}$. We aim to derive a concrete lower bound on $\social(q)$.
First, for any $j \in [t]$, since $1/4 \leq q_j \leq 3/4$, we have:     \begin{align*}
        \left(\frac{1+z_j/w}{2t} \right) \cdot \| c + e_j - q \|_{\infty} + \left( \frac{1-z_j/w}{2t} \right) \cdot  \| c - e_j - q \|_{\infty} \geq   \frac{1}{2t} - \frac{1/w}{4t}.
    \end{align*}
    Furthermore, if $q_j \leq 1/2$ and $z_j = +1$, then:  
    \begin{align*}
         \left(\frac{1+z_j/w}{2t} \right) \cdot \| c + e_j - q \|_{\infty} + \left( \frac{1-z_j/w}{2t} \right) \cdot  \| c - e_j - q \|_{\infty}  &\geq  \left(\frac{1+1/w}{2t}\right) \cdot (1-q_j) + \left( \frac{1-1/w}{2t} \right) \cdot q_j \\
        &= \frac{1}{2t} + \frac{(1/w) \cdot (1-2q_j)}{2t}  \\
        &\geq \frac{1}{2t}.
    \end{align*}
Similarly, if $q_j \geq 1/2$ and $z_j = -1$, then:
    \begin{align*}
         \left(\frac{1+z_j/w}{2t} \right) \cdot \| c + e_j - q \|_{\infty} + \left( \frac{1-z_j/w}{2t} \right) \cdot  \| c - e_j - q \|_{\infty}  &\geq  \left(\frac{1+1/w}{2t}\right) \cdot q_j + \left( \frac{1-1/w}{2t} \right) \cdot (1-q_j) \\
        &= \frac{1}{2t} + \frac{(1/w) \cdot (2q_j-1)}{2t}  \\
        &\geq \frac{1}{2t}.
    \end{align*}
     Define $g : \mathcal{X}^k \to \{-1,+1\}^{t}$ as follows: 
\begin{align*}
    g_j(x_1, \ldots, x_k) =
    \begin{cases}
        +1 & \text{if } \widetilde{q}_{j}(x_1, \ldots, x_k) > 1/2, \\
        -1 & \text{otherwise}.
    \end{cases}
\end{align*}
Note that $g$ is independent of $z$.
We use $g(f_S(z,t,w,r))$ for $S \subseteq [n]$ to denote $g((x_i^{(z)})_{i \in S})$.

Let $S \subseteq [n]$ be such that  
$\|g(f_S(z,t,w,r)) - z\|_1 > (1/4) \cdot t$. From the analysis above, we get:  
\begin{align*}
    \social(\widetilde{q}(S))- \socialopt(\mathcal{I}(z))  \geq \left(\frac{t}{4} \right) \cdot \left( 
\frac{1/w}{4t} \right) = \frac{1}{16w} \geq \frac{1}{8w} \cdot \socialopt(\mathcal{I}(z))
\end{align*}
Combining this with our assumption on $\overline{q}(S)$, and the fact that $\epsilon \leq (1/64) \cdot (1/w)$, we obtain:
\begin{align*}
    \frac{1}{64w} \cdot \socialopt(\mathcal{I}(z)) &\geq \epsilon \cdot \socialopt(\mathcal{I}(z)) \\ &\geq \mathbb{E}_{S \sim \uniformpanel} \left[\social (\widetilde{q}(S)) - \socialopt(\mathcal{I}(z)) \right] \\
    &> \frac{1}{8w} \cdot \socialopt(\mathcal{I}(z))\cdot \mathbb{P}_{S \sim \uniformpanel} \left[ \|g(f_S(z,t,w,r)) - z\|_1 > (1/4) \cdot t \right] 
\end{align*}
It follows that:
\[
\mathbb{P}_{S \sim \uniformpanel} \left[ \|g(f_S(z,t,w,r)) - z\|_1 \leq (1/4) \cdot t \right] \geq 7/8 \quad \text{for all $z \in \{-1,+1\}^{t}$}.
\]
Hence, $g$ satisfies the assumption of \Cref{lem:sample_lower_bound}, which concludes the proof.
\end{proof}


\subsection{Proofs of Section 4.4}\label{apx:multifacilities}


Next, we will prove the panel complexity upper bound, based on the lemma above.
\PanelComplexityMultifacilities*
\begin{proof}
Let us again consider the feature $f(i) = x_i$ for $i \in [n]$.
We adopt the following notation:
\begin{align*}
       \mu_f =  \mathbb{E}_{S \sim \uniformpanel}\left[W(\phi_f^{[n]}, \phi_f^S)\right] \quad \text{and}\quad  \mu'_f =  \mathbb{E}_{S \sim \mathcal{R}_{k,n}}\left[W(\phi_f^{[n]}, \phi_f^S)\right].
    \end{align*}
Applying the result of \citet*[Proposition 2.1]{chewi2024statisticaloptimaltransport}, we can choose $k = O(1/\epsilon^2)$ such that $\mu'_f \leq \epsilon$.
Then, by \Cref{lem:W1expectation}, it follows that $\mu_f \leq \epsilon$.
Finally, by \Cref{lem:multifacilities}, we obtain:
\begin{equation*}
    \mathbb{E}_{S \sim \uniformpanel} \left[ \social(\overline{y}(S)) \right] \leq \socialopt + \mu_f \leq \socialopt + \epsilon
\end{equation*}
as needed.
\end{proof}


