\subsection{Analysis}
%-----------------------------------------------------------------------

In this section, we analyze the distance that the algorithm maintains with the ground truth. Recall that the initial hypotheses are based on the bounding ball $\mc B_0$, which is centered at the origin. Letting $R_0 = \radius(\mc B_0)$, we have $H_i \spr 0 (\vctr x) = f_{\vctr 0,R_0}(\vctr x)$, as defined in Eq.~\eqref{Eqn:HypDef}. Using Eq.~\eqref{Eqn:PotDef}, the initial potential function satisfies:
\begin{equation}\label{eqn:pot-zero}
    \Phi_i \spr 0 = \log \sqrt{R_0/l_i \spr 0}, \quad \text{and} \quad \Phi \spr 0 \in O(n \log \Lambda_0) \quad\quad (\Lambda_0\text{:Aspect Ratio})
\end{equation}

%Suppose the condition in line \ref{alg:line:exzoc}, and \ref{alg:line:kzic} are satisfied. We prove the following lemma to justify the expansion factor $\frac{3}{1-2\beta}$.

%-----------------------------------------------------------------------
% \begin{lemma} \label{lem:exp-factor}
%     If $\mc O(i,\vctr k_i,h_i) = (Y,\cdot)$, and $\mc O(i,\vctr k_i,h_i/\beta) = (Y,+)$, then $\mc B_i \subset \mc B\left(\vctr k_i,\frac{3}{1-2\beta}h_i\right)$
% \end{lemma}
% %-----------------------------------------------------------------------
% \begin{proof}
%     See Appendix \ref{prf:lem:exp-factor}.
% \end{proof}
%-----------------------------------------------------------------------

Let us consider how \cref{Alg:TrackByZoom} affect the potential. For a particular index $i$, during the \emph{zoom-out} process, we double the radius $h_i$ of the hypothesis ball. If the Euclidean distance between the centers of the hypothesis and the local-feature ball is much larger than $h_i$, then $\Phi = \log(\max(s_i,l_i,h_i)/\sqrt{l_ih_i}) = \log(s_i/\sqrt{l_ih_i})$ decreases by an additive constant. However, once $h_i$ is larger than $s_i$, the algorithm risks increasing $\Phi$. We show that number of steps where $\Phi$ increases is a constant for every index $i$. During the zoom-in process however, we maintain the invariant that the hypothesis ball contains the local-feature ball (\cref{lem:exp-factor}), implying that $\max(s_i,l_i,h_i) = h_i$. Therefore, $\Phi$ decreases by a constant amount whenever we shrink the hypothesis ball by a constant factor. However, if the evolver moves $q_i$ while index $i$ is being processed, our algorithm may transition to the zoom-out process again. Hence, if the evolver executes some $\eps \itr z$ steps in the $z$th iteration, our algorithm may increase $\Phi$ by only $O\left(n+\eps \itr z\right)$. We obtain the following lemma. The proof is deferred to  \cref{prf:lem:alg-steps}

%-----------------------------------------------------------------------
\begin{lemma}[Algorithm’s contribution towards $\Phi$]\label{lem:alg-steps}
    For any iteration $z$, let $\eps \itr z$ denote the number steps executed by the evolver. Then \ref{Alg:TrackByZoom} increases $\Phi$ in $O\left(n+\eps \itr z\right)$ steps, each time by $O(1)$. In each of the remaining steps of the $z$th iteration it decreases $\Phi$ by $\Theta(1)$ in an amortized sense.
\end{lemma}
%-----------------------------------------------------------------------

Let $\Phi \itr z$ be the potential function at the start of the $z$th iteration. And let $\Delta \itr z$ be the time taken by the $z$th iteration of the algorithm. At the conclusion of the \emph{zoom-in} process for a particular index $i$, the algorithm fixes a hypothesis $H_i$ which is at a reasonable distance from the truth $P_i$. In fact we show in \cref{lem:almst-trckd} that at this point in time, $\Phi_i$ is $\phi_0$, a constant. Therefore by \cref{lem:alg-steps}, \ref{Alg:TrackByZoom} running at a constant speedup $\sigma$ roughly spends $\sim \Phi \itr z _i$ time (within constant factors), in reducing $\Phi \itr z _i$ to $\phi_0$. Summing up over all indices, we see that time taken by $z$th iteration, $\Delta \itr z$, is $\sim \Phi \itr z$. Intuitively, for a large enough speedup, the actions of the evolver can only affect $\Delta \itr z$ by a small fraction of this amount. We summarize these observations in the following lemma. The proof is deferred to \cref{prf:lem:iter-time-pot}

%-----------------------------------------------------------------------
\begin{lemma}[Iteration time proportional to Potential]\label{lem:iter-time-pot}
    There exists a constant speedup factor $\sigma$ for \ref{Alg:TrackByZoom} such that $\Delta \itr z \in \Theta_\sigma\left(n+\Phi \itr z\right)$.
\end{lemma}
%-----------------------------------------------------------------------

We are now ready to derive how $\Phi \itr z$ changes over the course of multiple iterations. We show that for a sufficiently large (constant) speedup $\sigma$, after $\sim \log \log \Lambda_0$ iterations $\Phi$ converges to $O(n)$. (Recall that $\Lambda_0$ is the initial aspect ratio.)

%-----------------------------------------------------------------------
\begin{lemma}\label{lem:Pot-converge}
    There exists a constant speedup factor $\sigma$ for \cref{Alg:TrackByZoom} and $z_0 \in \ZZ$, such that for all $z > z_0$, $\Phi \itr z \in O(n)$
\end{lemma}
%-----------------------------------------------------------------------
\begin{proof}
    By \cref{lem:EvoStep}, the $z$th iteration the evolver takes at most $\eps \itr z  = O(\Delta \itr z)$ steps and increases $\Phi$ by at most $O(\Delta \itr z)$. Therefore, by \cref{lem:alg-steps}, \ref{Alg:TrackByZoom} increases $\Phi$ by $O(n+\Delta \itr z)$. Since the algorithm runs at a speedup factor $\sigma$ it takes $\sigma \Delta \itr z$ steps, and by \cref{lem:alg-steps}, it decreases $\Phi$ by at least $\lambda (\sigma~ \Delta \itr z - O(n+\Delta \itr z))$, for some $\lambda \in O(1)$. Accounting for all the increases and decreases we have:
    \begin{align*}
        \Phi \itr {z+1} 
            & ~ \leq ~ \Phi \itr z + O(\Delta \itr z) + O(n+\Delta \itr z) - \lambda (\sigma~ \Delta \itr z - O(n+\Delta \itr z))\\
            & ~ \leq ~ \Phi \itr z + O(\Delta \itr z) - \sigma\lambda \Delta \itr z + O(n).
    \end{align*}
    There exists a sufficiently large $\sigma \in O(1)$ such that $\sigma \lambda \Delta \itr z - O(\Delta \itr z) \geq a \Delta \itr z$, for $0 < a \in O(1)$. So,
    \[
        \Phi \itr {z+1} 
            ~ \leq ~ \Phi \itr z  - a\Delta \itr z + O(n).
    \]
    By \cref{lem:iter-time-pot}, for a sufficiently large (constant) $\sigma$, there exists $c_\sigma > 0$ such that $\Delta \itr z \geq c_\sigma \left(n+ \Phi \itr z\right)$. Therefore,
    \begin{align*}
        \Phi \itr {z+1} 
            & ~ \leq ~ (1-a c_\sigma)\Phi \itr z + (1-a c_\sigma) O(n)\\
            & ~ \leq ~ (1-a c_\sigma)^{z+1}\Phi \itr 0 + \left(\sum_{y=1}^{z+1}(1-a c_\sigma)^y\right) O(n).
    \end{align*}
    By Eq.~\eqref{eqn:pot-zero}, $\Phi \itr 0 = \Phi \spr 0 \in O( n \log \Lambda_0)$, and since there exists $b > 1$ such that $(1 - a c_\sigma) < 1/b < 1$, we have
    \begin{align}
        \Phi \itr {z+1}\label{eq:conv-after-burn}
            & ~ \leq ~ \frac{O( n \log \Lambda_0)}{b^{z+1}}  ~+~ O(n)\\ 
            & ~ \leq ~ O(n), \quad\qquad \text{where}~ z > \log \log \Lambda_0. \notag
    \end{align}
\end{proof}
%-----------------------------------------------------------------------

If $\Phi \itr {z} \in O(n)$, then by \cref{lem:iter-time-pot}, $\Delta \itr z \in \Theta(n)$ as well. Thus, $\Phi$ increases by at most $O(n)$ throughout iteration $z$. Therefore, for any time $t$ during iteration $z$, $\Phi \spr t \in O(n)$ as well.

Using Eq.~\eqref{eq:conv-after-burn} we observe that for all $z > 1$, $\Phi \itr z \leq O(n\log \Lambda_0)$. By \cref{lem:iter-time-pot}, this implies that $\Delta \itr z \in \Theta(n \log \Lambda_0)$. Hence, for some $t_0 \in O(n \log \Lambda_0\cdot\log\log \Lambda_0)$, we have $\Phi \spr {t} \in O(n)$, for all $t > t_0$.

By combining Lemmas~\ref{lem:Pot-converge} and~\ref{lem:PotDist}, we complete the proof of \cref{thm:main}. It is noteworthy that there is a trade-off between the speedup factor $\sigma$ and the motion parameter $\alpha$. Recall that with each step, the evolver can move $q_i$ by a distance of up to $\alpha N_i$. If we reduce this parameter to $\alpha' = (1+\alpha)^\frac{1}{c}-1$, then it takes the evolver at least $c$ steps to effect the same change as before. Thus, by reducing the local motion factor, it is possible to achieve a speed up factor of $\sigma = 1$. Formally we have,

%-----------------------------------------------------------------------
\begin{corollary}
    There exists a motion parameter $\alpha' < 1$ such that for a set of $n$ evolving objects in $\RE^d$ under the $(\alpha',\beta)$-local motion model, where $\beta < \frac{1}{3}$, \cref{Alg:TrackByZoom} (with speedup factor 1) maintains a distance of $O(n)$ for all $t \geq t_0$, $t_0 \in O(n \log \Lambda_0 \log\log \Lambda_0)$
\end{corollary}
