\subsection{Detailed Algorithm}\label{sec:Det-Algo}
%=======================================================================
%-----------------------------------------------------------------------
%The Algorithm
%-----------------------------------------------------------------------
\begin{algorithm}[H]
  \renewcommand{\thealgorithm}{\textsc{TrackByZoom}} % Rename the Algorithm Counter  
  \caption{\textsc{Tracking Evolving Distributions}} \label{Alg:TrackByZoom}
  \begin{algorithmic}[1]
    \Procedure{TrackByZoom}{$\mc O,n,\beta, \mc B_0$}
    \Statex \LineComment{Maintain hypothesis $\mc H$ by running the procedure at a speedup factor $\sigma$, given the membership Oracle:$\mc O$, the input size:$n$, the local feature parameter:$\beta$, and the the maximum bounding ball centred at origin:$\mc B_0$} 
    %\Statex
    \For{$i \leftarrow$ 1 to $n$}
        \Statex \LeftComment{2}{Initially set the hypotheses according to the given bounding ball}
        \State $h_i \leftarrow \radius(\mc B_0)$, $\vctr k_i \leftarrow \vctr 0$ \Comment{Set $H_i(\vctr x) \leftarrow f_{\vctr 0,R_0}(\vctr x)$, as in Eq.(\ref{Eqn:HypDef}})
    \EndFor 
    %\Statex
    \State $i \leftarrow 1$ \Comment{Start with the first point}
    \Statex


    \Label \texttt{\textbf{ZOOM\_OUT:}} \label{alg:line:zoomout}
    %\Statex
    \State $\mf O_i \leftarrow \mc O(i,\vctr k_i,h_i)$, $\mf O_i^* \leftarrow \mc O(i,\vctr k_i,h_i/\beta)$ \Comment{Store values to use later}
    \If{$\mf O_i ~ = ~ (Y,\cdot)$ \textbf{and} $\mf O_i^* ~ = ~ (Y,+)$}\label{alg:line:exzoc}
    \Statex \LeftComment{1}{If $\mc B^H_i$ (hypothesis ball) contains $X_i$, and its $1/\beta$-expansion contains some $X_j$}
    \State $h_i \leftarrow \frac{3}{1-2\beta}h_i$ \Comment{Update $\mc B^H_i$ so that it contains $\mc B_i$ (local feature of $\vctr q_i$) }\label{alg:line:exzo}
        \State \Goto \texttt{ZOOM\_IN}
    \EndIf
    %\Statex
    \State $h_i \leftarrow 2h_i$ \Comment{Zoom out by expanding $\mc B^H_i$}\label{alg:line:kzo}
    \State \Goto \texttt{ZOOM\_OUT} 
    \Statex \LeftComment{1}{Keep zooming out until $X_i \in \mc B^H_i$, and its $1/\beta$-expansion contains another $X_j$}
    \Statex

    \Label \texttt{\textbf{ZOOM\_IN:}} \label{alg:line:zoomin}
    %\Statex
    \State $\mf O_i \leftarrow \mc O(i,\vctr k_i,h_i)$, $\mf O_i^* \leftarrow \mc O(i,\vctr k_i,h_i/\beta)$ \Comment{Store values to use later}
    \If{$\mf O_i~ = ~ (N,\cdot)$} \Comment{$X_i$ no longer in $\mc B^H_i$} \label{alg:line:exevzic}
    \State \Goto \texttt{ZOOM\_OUT}
    \EndIf
    %\Statex

    \If{$\mf O_i~ = ~ (Y,\cdot)$ \textbf{and} $\mf O_i^*~ = ~ (Y,-)$} \label{alg:line:exzic}
    \Statex \LeftComment{1}{$X_i \in \mc B^H_i$, and its $1/\beta$-expansion doesn't contain another $X_j$}
        \State $i\leftarrow 1+i\mod n$ \Comment{$\Phi_i$ is a constant, ready to move to the next point}\label{alg:line:nxpt}
        \State \Goto \texttt{ZOOM\_OUT}
    \EndIf
    %\Statex

    \If{$\mf O_i~ = ~ (Y,\cdot)$ \textbf{and} $\mf O_i^*~ = ~ (Y,+)$} \label{alg:line:kzic}
    \Statex \LeftComment{1}{If $\mc B^H_i$ (hypothesis ball) contains $X_i$, and its $1/\beta$-expansion contains some $X_j$}
        \For{$\mc B(\vctr x,r) \in \Psi(\mc B^H_i,2\lceil \frac{3}{1-2\beta} \rceil )$} \label{alg:line:zinested}
        \Statex \LeftComment{2}{$\Psi$ is the set of balls of radius $h_i/\left(2\lceil \frac{3}{1-2\beta} \rceil\right)$ which cover $\mc B^H_i$}
            \If{$\mc O(i,\vctr x,r) ~ = ~ (Y, \cdot)$} \Comment{Found the nested ball that contains $X_i$}
            \State $\vctr k_i \leftarrow \vctr x$, $h_i \leftarrow \frac{3}{1-2\beta}r$ \Comment{Expand the nested ball so that it contains $B_i$}\label{alg:line:ziexp}
            \EndIf
        \EndFor
    \EndIf
    \State \Goto \texttt{ZOOM\_IN} 
    \Statex \LeftComment{1}{Keep zooming in until $X_i \in \mc B^H_i$, and its $1/\beta$-expansion contains no other $X_j$}
    \Statex

  \EndProcedure
\end{algorithmic}
\end{algorithm}
