\subsection{Deferred Proofs}\label{para:App-proofs}
%=======================================================================

Note that some of the restatements of the lemmas given her provide additional details, which were not present in the original statements.

%-----------------------------------------------------------------------
%\phantomsection\label{prf:lem:exp-factor}
\begin{lemma}[Expansion Factor]\label{lem:exp-factor}
    If $\mc O(i,\vctr k_i,h_i) = (Y,\cdot)$, and $\mc O(i,\vctr k_i,h_i/\beta) = (Y,+)$, then $\mc B_i \subset \mc B\left(\vctr k_i,\frac{3}{1-2\beta}h_i\right)$
\end{lemma}
%-----------------------------------------------------------------------
\begin{proof}
    $\mc O(i,\vctr k_i,h_i) = (Y,\cdot)$ implies $\mc B_i$ and $\mc B^H_i~=~\mc B(\vctr k_i,h_i)$ intersect. And since \\$\mc O(i,\vctr k_i,h_i/\beta) =~(Y,+)$, $\exists j \neq i \ST$ $\|X_j-\vctr k_i\| \leq h_i/\beta$. Figure \ref{fig:expfactor} illustrates the situation. 

    \begin{figure}[h]
    \centering
    \includegraphics[scale=0.35]{Figs/Exp_factor}
    \caption{Illustration of the situation when the conditions in line \ref{alg:line:exzoc}, and \ref{alg:line:kzic} of the \ref{Alg:TrackByZoom} is satisfied (see \cref{lem:exp-factor}).}
    \label{fig:expfactor}
    \end{figure}

    If $l_j \geq l_i$, then $\|X_j - \vctr q_i\| \geq (1/\beta -1) l_j \geq (1/\beta - 1)l_i$. If $l_i > l_j$, then $\|X_j - \vctr q_i\| \geq l_i/\beta - l_j > (1/\beta - 1)l_i$ as well. Therefore by triangle inequality, we have, $(1/\beta - 1)l_i \leq \|X_j - \vctr q_i\| \leq \|X_j - \vctr k_i\| + \|\vctr k_i - \vctr q_i\| \leq h_i/\beta + h_i + l_i$. Simplifying we have $l_i \leq \frac{1+\beta}{1-2\beta}h_i$.

    Next we observe that $\mc B(\vctr k_i, h_i+2l_i)$ contains the entire $\mc B_i$. Using the previous result we have $h_i + 2l_i \leq \frac{3}{1-2\beta}h_i$ giving us the required expansion factor. 
\end{proof}
%-----------------------------------------------------------------------

%-----------------------------------------------------------------------
\begin{lemma}[Done tracking $X_i$]\label{lem:almst-trckd}
    When \ref{Alg:TrackByZoom} moves on from index $i$ to the next (via line \ref{alg:line:nxpt}), $\Phi_i \leq \phi_0 \in O(1)$
\end{lemma}
%-----------------------------------------------------------------------
%-----------------------------------------------------------------------
\begin{proof}
    The algorithm moves on to the next point when the condition in line \ref{alg:line:exzic} is satisfied, also implying that the condition in line \ref{alg:line:kzic} is no longer satisfied. Therefore using a very similar approach as the proof of \cref{lem:exp-factor}, we have $\frac{1+\beta}{1-2\beta}h_i < l_i$.    
    However the condition was obviously satisfied in the penultimate zoom-in step, implying $l_i \leq \frac{1+\beta}{1-2\beta}(2h_i)$. Therefore $h_i \in \Theta(l_i)$, and $\Phi_i$ is a constant.
\end{proof}
