%-----------------------------------------------------------------------
\phantomsection\label{prf:lem:EvoStep}
\begin{relemma}{\ref{lem:EvoStep}}[Evolver's contribution to $\Phi$]
    Every step of the evolver increases the potential function $\Phi$ by a constant.
\end{relemma}
%-----------------------------------------------------------------------
\begin{proof}
    Let's say the evolver chooses to move $\vctr q_i$ at time $0$. Now $l \spr 0 _i/\beta$ is the nearest neighbor distance of $\vctr q_i$ at time $0$. Therefore $\vctr q_i$ moves by at most $(\alpha/\beta) l\spr 0_i$ distance, implying $s_i \spr 1 \leq s_i \spr 0 + (\alpha/\beta) l_i \spr 0 \leq \left(1+ \alpha/\beta\right)\max \left(s_i \spr 0,l_i \spr 0,h_i \spr 0\right)$. Similarly $(1-\alpha)l_i \spr 0 \leq l_i \spr 1 \leq (1+\alpha)l_i \spr 0$. Therefore,

\begin{flalign}
\begin{split}
    \Phi_i \spr 1 - \Phi_i \spr 0 & ~\leq~ \log \frac{\max \left(s_i \spr 1,l_i \spr 1,h_i \spr 1\right)}{\sqrt{l_i \spr 1 h_i \spr 1}} 
        - \log \frac{\max \left(s_i \spr 0,l_i \spr 0,h_i \spr 0\right)}{\sqrt{l_i \spr 0 h_i \spr 0}}\\
        & ~\leq~ \log \frac{\max \left(s_i \spr 0 + (\alpha/\beta) l_i \spr 0,(1+\alpha)l_i \spr 0,h_i \spr 0\right)}{\sqrt{(1-\alpha)l_i \spr 0 h_i \spr 0}} 
        ~ - ~ \log \frac{\max \left(s_i \spr 0,l_i \spr 0,h_i \spr 0\right)}{\sqrt{l_i \spr 0 h_i \spr 0}}\\
        & ~\leq~ \log \left(\frac{1+\alpha/\beta}{\sqrt{1-\alpha}} \frac{\max \left(s_i \spr 0,l_i \spr 0,h_i \spr 0\right)}{\sqrt{l_i \spr 0 h_i \spr 0}}\right)
        ~ - ~\log \frac{\max \left(s_i \spr 0,l_i \spr 0,h_i \spr 0\right)}{\sqrt{l_i \spr 0 h_i \spr 0}}\\
        & ~ = ~ \log \frac{1+\alpha/\beta}{\sqrt{1-\alpha}} \in O(1) \label{Eqn:EvoPotSelf}
\end{split}
\end{flalign}

Let $\mc N_i$ be the set of indices of points whose nearest neighbor at time 0 was $\vctr q_i\spr 0$, or whose nearest neighbor at time 1 was $\vctr q_i \spr 1$. Only points with indices in this set have their potential function changed. If $j \in \mc N_i$, $s_j \spr 0$, and $h_j \spr 0$ do not change. Since $\vctr q_i$  moves by at most $(\alpha/\beta) l\spr 0_i$ distance, the nearest neighbor distance $N_j = l_j/\beta$ changes by at most $(\alpha/\beta) l\spr 0_i$ as well. Therefore,
\begin{gather}
        -(\alpha/\beta)l_i \spr 0 ~ \leq ~ N_j \spr 1 - N_j \spr 0 ~ \leq ~ (\alpha/\beta)l_i \spr 0 \notag\\
        \implies -\alpha l_i \spr 0 ~ \leq ~ l_j \spr 1 - l_j \spr 0 ~ \leq ~ \alpha l_i \spr 0 \label{Eqn:LDiff1}
        \intertext{Since $(1-\alpha)l_i \spr 0 ~ \leq ~ l_i \spr 1$, we also have}
        -\frac{\alpha}{1-\alpha}l_i \spr 1 ~\leq ~ l_j \spr 1 - l_j \spr 0 ~ \leq ~ \frac{\alpha}{1-\alpha}l_i \spr 1 \label{Eqn:Ldiff2}
\end{gather}

If $\vctr q_i \spr 0$ was the nearest neighbor of $\vctr q_j \spr 0$, then $N_j \spr 0 \leq N_i \spr 0$, and hence $l_j \spr 0 \leq l_i \spr 0$. Using the last fact, and dividing Eq.~\eqref{Eqn:LDiff1} by $l_j \spr 0$, we have $(1-\alpha) \leq l_j \spr 1 / l_j \spr 0 \leq (1+\alpha)$. Similarly, If $\vctr q_i \spr 1$ was the nearest neighbor of $\vctr q_j \spr 1$, then using Eq.~\eqref{Eqn:Ldiff2} we have $(1-\alpha/(1-\alpha)) \leq l_j \spr 1 / l_j \spr 0 \leq (1+\alpha/(1-\alpha))$. Therefore $ l_j \spr 1 / l_j \spr 0 \in \Theta(1)$ for $j \in \mc N_i$. And hence,

\begin{flalign}
\begin{split}
    \Phi_j \spr 1 - \Phi_j \spr 0 & ~ = ~ \log \frac{\max \left(s_i \spr 1,l_i \spr 1,h_i \spr 1\right)}{\sqrt{l_i \spr 1 h_i \spr 1}} 
        ~ - ~ \log \frac{\max \left(s_i \spr 0,l_i \spr 0,h_i \spr 0\right)}{\sqrt{l_i \spr 0 h_i \spr 0}}\\
        & ~ = ~ \log \frac{\max \left(s_i \spr 0,l_i \spr 1,h_i \spr 0\right)}{\max \left(s_i \spr 0,l_i \spr 0,h_i \spr 0\right)} 
        ~ - ~ \log \frac{\sqrt{l_i \spr 1 h_i \spr 0}}{\sqrt{l_i \spr 0 h_i \spr 0}}\\
        & ~ \leq ~ \left| \log \frac{l_i \spr 1}{l_i \spr 0} \right| ~ + ~ \left|\log \frac{l_i \spr 0}{l_i \spr 1}\right| ~ \in ~ O(1), \quad \forall ~ j \in \mc N_i\label{Eqn:EvoPotOth}
\end{split}
\end{flalign}

Finally, we show that $|\mc N_i| \in O(1)$. To that effect we solve a general problem: What is the maximum number of points in $Q$, whose nearest neighbor is $\vctr q_1$? Without loss of generality, let $\vctr q_2$ be the nearest neighbor of $\vctr q_1$, such that $\|\vctr q_2 - \vctr q_1\| = 1$. Let $\vctr q_3$'s nearest neighbor be $\vctr q_1$. Consider the line segment $\overline{\vctr q_1 \vctr q_3}$, and its intersection with $\mc B (\vctr q_1, 1)$ the ball centered at $\vctr q_1$, and passing through $\vctr q_2$. Call the intersection point $\vctr q_3'$. For any general point $\vctr q_x \in Q$, we similarly define $\vctr q_x'$. Note $\vctr q_2' = \vctr q_2$. By triangle inequality, we have $\|\vctr q_3' - \vctr q_2'\| \geq \|\vctr q_3 - \vctr q_2\| - \|\vctr q_3 - \vctr q_3'\| = \|\vctr q_3 - \vctr q_2\| - \|\vctr q_3 - \vctr q_1\| + \|\vctr q_1 - \vctr q_3'\|$. Since $\vctr q_1$ is the nearest neighbor of $\vctr q_3$, we have $\|\vctr q_3 - \vctr q_2\| \geq \|\vctr q_3 - \vctr q_1\|$. Therefore $\|\vctr q_3' - \vctr q_2'\| \geq \|\vctr q_1 - \vctr q_3'\| = 1$. Therefore, for any $x,y\in [n], x\neq y$, such that $\vctr q_1$ is the nearest neighbor of $\vctr q_x$ and $\vctr q_y$, we have $\|\vctr q_x' - \vctr q_y'\| \geq 1$. Let $\mc M_1 = \{\vctr q_x' \mid \vctr q_1 \text{is the nearest neighbor of } \vctr q_x\}$. Draw a ball of radius 1/2 around $\vctr q_1$, and every member of $\mc M_1$. Each of these balls are non-overlapping. However all of them are contained within a ball around $\vctr q_1$ of radius $3/2$. Therefore $|\mc M_1| < (3/2)^d/(1/2)^d = 3^d \in O(1)$. Observing that $\mc N_i \leq 2\mc M_1$, and using Eq.~\eqref{Eqn:EvoPotSelf}, and \ref{Eqn:EvoPotOth} we have the result.
\end{proof}
