\section{Numerical discretization and main results}\label{sec-main}

In this section, we design a fully discrete convex-splitting  finite element scheme for the CH-MHD model \eqref{PDE1}-\eqref{PDE5} and then present the main convergence results.

\subsection{Variational formulation}
Let $W^{k,p}(\Omega)$ denote the standard Sobolev spaces equipped with the norms $\|\cdot\|_{W^{k,p}}$ for integer $k\geq0$ and $p\in[1, \infty]$. As general, we denote by $H^{k}(\Omega)=W^{k,2}(\Omega)$ and $L^{p}(\Omega)=W^{0,p}(\Omega)$, and the vector-valued spaces by $\W^{k,p}(\Omega) = [W^{k,p}(\Omega)]^d$. The $L^2/\L^2$ inner product and norm are denoted by $(\cdot, \cdot)$ and $\|\cdot\|$, respectively.
%{\color{red}We define $\mathring{H}^{1}(\Omega)$:=$H^{1}(\Omega)\cap L^{2}_{0}(\Omega)$ and its dual space $(\mathring{H}^{1}(\Omega))'$.} 
The admissible spaces are defined as follows:
\begin{align*}
&\H_{0}^{1}(\Omega) = 
	\big\{\v\in  \H^{1}(\Omega): \v|_{\partial\Omega}=\0\, \big\},
&&L_{0}^{2}(\Omega) = 
	\big\{q\in L^{2}(\Omega): (q, 1)=0\, \big\},	\\
&\H({\rm curl}, \Omega) = 
	\big\{\C\in \L^{2}(\Omega): \nabla\times \C\in \L^{2}(\Omega) \, \big\}, 
&&\H_{0}({\rm curl}, \Omega) = 
	\big\{\C\in \H({\rm curl}, \Omega): \boldsymbol{n}\times \C|_{\partial\Omega}=\0\, \big\},	
\end{align*}
Then, it is natural to obtain that the exact solution of the CH-MHD system \eqref{PDE1}-\eqref{PDE5} satisfies the following variational formulation: for any test function $(\varphi, \psi, \v, q, \C)\in (H^{1}(\Omega), H^{1}(\Omega), \H_{0}^{1}(\Omega), L_{0}^{2}(\Omega), \H_{0}( {\rm curl}, \Omega) )$ and $t\in(0, T]$, it holds
\begin{align}
	&(\phi_{t}, \varphi) + (\nabla \phi \cdot\u, \varphi) + (\nabla \omega, \nabla \varphi) =  0,  \label{weak1} \\
	&(\nabla\phi, \nabla \psi) + (\phi^{3}-\phi, \psi) - (\omega, \psi) =0,   \label{weak2}\\
	&(\u_{t}, \v)+b(\u, \u,\v) + (\nabla\u, \nabla\v) - (\nabla\cdot \v, p) 
			+ (\nabla\times\B, \v\times\B) - (\omega \nabla \phi, \v) = 0,  \label{weak3}\\
	&(\nabla \cdot \u, q)=0, \label{weak4} \\
	&(\B_{t}, \C)+ (\nabla\times\B, \nabla\times \C) - (\u\times\B, \nabla\times\C) =0,	\label{weak5}
\end{align}
where we define the trilinear form $b(\u, \v,\w)=\frac12[( \u\cdot \nabla \v, \w)- ( \u\cdot \nabla  \w, \v) ]$, which is anti-symmetric respect to the two last arguments.

\begin{lemma}[\cite{2019A}]
Let ($\phi, \omega, \u, p, \B$) be the solution of the  two-phase MHD model \eqref{PDE1}-\eqref{PDE5}. Then, for any $t\in(0,T]$, the mass is conserved
	\begin{equation*}
		\big(\phi(t), 1\big) = \big(\phi_0, 1\big)
	\end{equation*}
	and the system is energy-stable,
	\begin{equation*}%\label{model-energy}
		\frac{dE(\phi, \u, \B)}{dt} =-\Big(\lambda\varepsilon\|\sqrt{M(\phi)} \nabla\omega\|^{2}+ \|\sqrt{\nu (\phi)}\nabla\u\|^{2}+ \frac{1}{\mu} \|\frac{1}{\sqrt{\sigma (\phi)}} \nabla\times \B\|^{2} \Big)\leq 0,
	\end{equation*}
	where the total energy  is given by
	\begin{equation}\label{system-energy}
		E(\phi, \u, \B)
		= \frac{\lambda\gamma}{2}\|\nabla\phi\|^{2} 
		+\frac{\lambda}{4\gamma}\|\phi^{2}-1\|^2
		+\frac{1}{2}\|\u\|^{2}+\frac{1}{2\mu}\|\B\|^{2}.
	\end{equation} 
\end{lemma}

Hereafter, for brevity, we consider the physical parameters $\gamma=M(\phi)=\nu(\phi)=\mu=\lambda=\sigma (\phi)$=1, and note that for any positive constants there are no more essential difficulties. Moreover, we denote by $C $ a generic positive constant independent of $\Delta t$ and $h$, which may take different values at different places.

\subsection{Numerical scheme}
Let $\mathfrak{T}_{h}$ be a quasi-uniform partition of domain $\Omega$ into the simplices $K_{j}$ 
with mesh size $h=\max_j {\rm diam} (K_{j})$. We define the following finite element spaces, 
\begin{equation*}
\begin{array}{l l}
S_{h}^{r}=\{\phi_{h}\in C^0(\overline{\Omega}): 
	\, \phi_{h}|_{K_{j}}\in P_{r}(K_{j}), \forall K_{j} \in \mathfrak{T}_{h}\},	
& \mathring{S}_{h}^{r}=S_{h}^{r}\cap L_{0}^{2}(\Omega),	
			\vspace{0.06in} \\
\X_{h}^{r+1}=\{\v_{h}\in \H_{0}^{1}(\Omega):
	 \v_{h}|_{K_{j}}\in \P_{r+1}(K_{j}), \forall K_{j} \in \mathfrak{T}_{h}\},
&\X_{h}^{1b} 
	= (S_{h}^{1}\oplus B_{d+1})^{d}\cap \H_{0}^{1}(\Omega),	\vspace{0.06in} \\
\Y_{h}^{l}=\{\C_{h}\in \H_{0}( {\rm{curl}}, \Omega): 
\C_{h}|_{K_{j}}\in \P_{l-1}(K_{j})\oplus D_{h}^{l}(K_{j}), \forall K_{j} \in \mathfrak{T}_{h}\}, 
& 	\vspace{0.06in} \\
\Z_{h}^{l}=\{\C_{h}\in\boldsymbol{Z}_{h}^{l}: (\C_{h}, \nabla w_{h})=0, \forall\, w_{h} \in H_{0}^{1}(\Omega)\cap P_{l}(K_{j}) \}. 
&
\end{array}
\end{equation*}
where $P_{r}(K_{j})$ is the polynomial space of total degree $r$ on $K_{j}$ with its vector-valued form $\P_{r}(K_{j}):=[P_{r}(K_{j})]^d$.  
Note that $\X_{h}^{r+1}\times\mathring{S}_{h}^{1}$ is the standard Taylor--Hood elements and $\X_{h}^{1b} \times \mathring{S}_{h}^{1}$ is the MINI element, where we denote by $B_{3}$ and $B_{4}$ the spaces of cubic bubbles and quartic bubbles, respectively. According to the classical finite element theory  \cite{1986FiniteG, 1991BF}, we have the following discrete inf-sup condition:
\begin{equation*}%\label{infsup}
	\begin{aligned}
		\inf_{0\neq q_{h}\in \, \mathring{S}_{h}^{r}/\mathring{S}_{h}^{1} } \,
		\sup_{\0\neq\v_{h}\in \, \X_{h}^{r+1}/\X_{h}^{1b} }
			\frac{(\nabla\cdot \v_{h}, q_{h})}{\|q_{h}\| \, \|\nabla \v_{h}\|}
		\geq \beta_{0},
	\end{aligned}
\end{equation*}
where $\beta_{0}$ is a positive constants depending only on $\Omega$.
Furthermore, $\Y_{h}^{l}$ is an $l$-th order N\'{e}d\'{e}lec element space of the first type, with $D_{h}^{l}(K_{j}) := \{\boldsymbol{p}(\x) \in [\tilde{P}_{l}(K_{j})]^{d}: \boldsymbol{p}(\x)\cdot \x=0, \forall \x \in K_{j} \}$, where $\tilde{P}_{l}(K_{j})$ is homogeneous polynomial subsets of $P_{l}(K_{j})$.
For the sake of presentation, we use the following notations
\begin{equation*}%\label{spaceB}
\mathring{\boldsymbol \chi }_{h}^{r}:=\left\{
\begin{array}{l l}
S_{h}^{r}\times S_{h}^{r}\times \X_{h}^{r+1} \times \mathring{S}_{h}^{r}\times \Y_{Bh}^{l }, 
	\quad 		&r\geq2, \; l\geq 3, \vspace{0.05in}\\
S_{h}^{1}\times S_{h}^{1}\times \X_{h}^{1b} \times \mathring{S}_{h}^{1}\times \Y_{Bh}^{1},  
	\quad 		&r=1,\;  l=1,		\vspace{0.05in}\\
S_{h}^{1}\times S_{h}^{1}\times \X_{h}^{2} \times \mathring{S}_{h}^{1}\times \Y_{Bh}^{2}, 
	\quad 		&r=1,\;  l=2.
\end{array}
\right.
\end{equation*}

Let $\big\{t_k = k\Delta t\big\}_{k=0}^{N_T}$ denote a uniform partition of the temporal interval $[0, T]$ with the time stepsize $\Delta t={T}/{N_T}$ for any positive integer $N_T$. 
By denoting $f^{k}=f (\x, t_{k})$ and $d_{t}f^{k+1} = (f^{k+1} - f^{k})/{\Delta t}$, then we propose the fully discrete convex splitting finite element scheme for the CH-MHD system \eqref{PDE1}-\eqref{PDE5}: Find ($\phi_{h}^{k+1}, \omega_{h}^{k+1}, \u_{h}^{k+1}, p_{h}^{k+1}, \B_{h}^{k+1})\in \mathring{\boldsymbol \chi }_{h}^{r}$ such that it holds
\begin{align}
&\big(d_{t}\phi_{h}^{k+1}, \varphi_{h}\big) 
		+ \big(\nabla\phi_{h}^{k}\cdot \u_{h}^{k+1},  \varphi_{h}\big) 
		+ \big( \nabla\omega_{h}^{k+1}, \nabla\varphi_{h}\big)=0,		\label{scheme1}\\
&\big(\nabla\phi_{h}^{k+1}, \nabla\psi_{h}\big)
		+ \big((\phi_{h}^{k+1})^{3}-\phi_{h}^{k}, \psi_{h}\big)
		- \big(\omega_{h}^{k+1}, \psi_{h}\big) = 0, 			\label{scheme2}\\
&\big(d_{t}\u_{h}^{k+1},\v_{h}\big) 
		+ b \big(\u_{h}^{k}, \u_{h}^{k+1},\v_{h}\big)
		+ \big( \nabla\u_{h}^{k+1},\nabla\v_{h} \big)
		- \big( \nabla\cdot \v_{h},  p_{h}^{k+1}\big) 
		+ \big(\nabla\times \B_{h}^{k+1}, \v_{h}\times \B_{h}^{k}\big)
		- \big(\omega_{h}^{k+1} \nabla \phi_{h}^{k}, \v_{h} \big) =0,	\label{scheme3}\\
&\big(\nabla\cdot\u_{h}^{k+1}, q_{h}\big) =0,									\label{scheme4}\\
&\big(d_{t}\B_{h}^{k+1}, \C_{h}\big) 
		+ \big( \nabla\times \B_{h}^{k+1}, \nabla\times \C_{h} \big)
		- \big(\u_{h}^{k+1}\times \B_{h}^{k}, \nabla\times \C_{h}\big) = 0,	\label{scheme5}
\end{align}
for all $(\varphi_{h}, \psi_{h}, \v_{h}, q_{h},  \C_{h})\in \mathring{\boldsymbol \chi }_{h}^{r}$ and $k=0,1,\cdots, N_T-1$. 
The initial data is set as
\begin{align*}
	\phi_{h}^{0}=R_h\phi_{0},
		\qquad
	\u_{h}^{0}= \I_{h}\u_{0}, 
		\qquad
	\B_{h}^{0}=\PPi_h\B_{0},
\end{align*}
where $R_h$, $\I_{h}$, and $\PPi_h$ are the standard Ritz, $\L^{2} $, and Maxwell quasi-projection operators, respectively, and the definitions will be given in the next section.   


The energy stability \eqref{scheme1}-\eqref{scheme5} has been presented in \cite{2019A}, and here we omit the proof for compactness.
\begin{lemma}[Theorem 4.1, \cite{2019A}]
The scheme \eqref{scheme1}-\eqref{scheme5} is mass-conserved
\begin{equation}\label{mass-conservetion}
	\big(\phi_h^{k+1}, 1\big) = \big(\phi_h^0, 1\big)
\end{equation}
and admits the following discrete energy decaying law
\begin{equation}\label{menergy}
E_h^{k+1} - E_h^k
	\leq -\Delta t\,\Big(\| \nabla\omega_{h}^{k+1}\|^{2}
	+ \|\nabla\u_{h}^{k+1} \|^{2}
	+ \| \nabla\times \B_{h}^{k+1}\|^{2} \Big),
\end{equation}
for $k=0,1,\cdots,N_T-1$, where the total energy is given by
\begin{equation}\label{algorithm-energy}
E_h^{k}
	= \frac{1}{2}\|\nabla\phi_{h}^{k}\|^{2}+\frac{1}{4}\|(\phi_{h}^{k})^{2}-1\|^2 +\frac{1}{2}\|\u_{h}^{k}\|^{2}+\frac{1}{2}\|\B_{h}^{k}\|^{2}.
\end{equation}
\end{lemma}

