\subsection{Main results}
It is supposed that the unique solution of CH-MHD model \eqref{PDE1}-\eqref{PDE5} exists and satisfies the regularity assumption
\begin{equation}\label{regularity_ass}
	\begin{aligned}
		& \phi \in H^{2}(0,T; L^{2}(\Omega))\cap H^{1}(0,T; H^{r+1}(\Omega))\cap C(0,T; W^{2, 4}(\Omega)), \quad  \omega\in H^{1}(0,T; H^{r+1}(\Omega)),\\
		&\u\in \H^{2}(0,T; \L^{2}(\Omega))\cap \H^{1}(0,T; \H^{r+2}(\Omega)),\quad p\in L^{2}(0,T; H^{r+1}(\Omega)\cap L_{0}^{2}(\Omega)),\\
		&\B,\, \nabla\times \B \in \L^{\infty}(0,T; [\L^{\infty}(\Omega)\cap \H^{l}(\Omega)\cap \W^{1,3}(\Omega)]).
	\end{aligned}
\end{equation}
with $r\geq1$ and $l\geq1$.
Then, we obtain the main results of this work in the following theorem.


\begin{The}\label{theorem2-2}
Supposing that CH-MHD model \eqref{PDE1}-\eqref{PDE5} admits a unique solution $(\phi, \omega, \u, p, \B)$ satisfying the regularity assumptions \eqref{regularity_ass}, then the numerical solution $(\phi_{h}^{k}, \omega_{h}^{k}, \u_{h}^{k}, p_{h}^{k}, \B_{h}^{k}) \in \mathring{\boldsymbol \chi }_{h}^{r}$ of fully discrete scheme \eqref{scheme1}-\eqref{scheme5}, $k=1,\cdots, N_T$,  satisfies the following error estimates:
\begin{align*}
&\max\limits_{1\leq k\leq N_T}\|\phi^{k}-\phi_{h}^{k} \| + \bigg(\Delta t\sum_{k=1}^{N_T} 
	\|\omega^{k}-\omega_{h}^{k}\|^{2}\bigg)^{\frac{1}{2}} \leq C \Big(\Delta t+h^{l+1}+h^{r+1}\Big), \\
&\max\limits_{1\leq k\leq N_T}  \|\u^{k}-\u_{h}^{k} \|
    \leq C \Big(\Delta t+h^{l+1}+\beta_{h}\Big),\\
&\max\limits_{1\leq k\leq N_T} \|\B^{k}-\B_{h}^{k} \|
	\leq C \Big(\Delta t+h^{l }+\beta_{h}\Big),	\\
&\max\limits_{1\leq k\leq N_T}\|\nabla(\phi^{k}-\phi_{h}^{k}) \|\leq C \Big(\Delta t+h^{l+1}+h^{r}\Big),	\\
&\bigg(\Delta t\sum_{k=1}^{N_T}  \|\nabla (\u^{k}-\u_{h}^{k} )  \|^{2}  \bigg)^{\frac{1}{2}}
	\leq C \Big(\Delta t+h^{l+1}+\beta_{h}^{\star}\Big),\\
&\bigg(\Delta t\sum_{k=1}^{N_T} \|\nabla\times(\B^{k}-\B_{h}^{k} )\|^{2} \bigg)^{\frac{1}{2}}\leq C \Big(\Delta t+h^{l }+\beta_{h}^{\star}\Big),
\end{align*}
with
\begin{equation*}%\label{bta}
\beta_{h}=\left\{
\begin{aligned}
& h^{r+2},\quad r\geq2,\\
& h^{r+1},\quad  r=1,
\end{aligned}
\right.\qquad
\beta_{h}^{\star}=\left\{
\begin{array}{ll}
  	h^{r+1},\quad  &r\geq2,	\\
 	h^{r+1},\quad  &r=1 \quad ( (\u_{h}^{k},p_{h}^{k})\in \X_{h}^{2}\times \mathring{S}_{h}^{1} ),\\
 	h^{r},\quad    &r=1 \quad ( (\u_{h}^{k},p_{h}^{k})\in \X_{h}^{1b}\times \mathring{S}_{h}^{1} ).
\end{array}
\right.
\end{equation*}
\end{The}

\section{Projections and their properties}\label{sec-projections}

We first present the classic projection operators \cite{wheeler1973priori}:

(1) The $L^{2}/\L^2$ projection $I_{h}: L^{2}(\Omega)\rightarrow S_{h}^{r}$ and $\I_{h}: \L^{2}(\Omega)\rightarrow \X_{h}^{r+1}/\X_{h}^{1b}$ are defined as follows,
\begin{equation*}
\begin{aligned}
&(v -I_{h}v, \varphi_{h})=0,  \quad		&&\forall \varphi_{h}\in S_{h}^{r},\\
&(\v-\I_{h}\v, \v_{h})=0,	\quad	&&\forall \v_{h}\in \X_{h}^{r+1}/\X_{h}^{1b}.\\
\end{aligned}
\end{equation*}
For these projections, the following estimates hold
\begin{equation*}
\begin{aligned}
& \|v -I_{h}v \| +h \|\nabla (v -I_{h}v)\|\leq C  h^{r+1}\|v\|_{H^{r+1}},	\quad	&I_hv&\in S_h^r, \\
& \|\v-\I_{h}\v\| +h \|\nabla (\v-\I_{h}\v)\|\leq C  h^{r+2}\|\v\|_{H^{r+2}},\quad &\I_{h}\v&\in \X_{h}^{r+1},  \\
& \|\v-\I_{h}\v\| +h \|\nabla (\v -\I_{h}\v)\|\leq C  h^{2}\|\v\|_{H^{2}},\quad &\I_{h}\v &\in \X_{h}^{1b}.
\end{aligned}
\end{equation*}


(2) The classic Ritz projection $R_h: H^{1}(\Omega)\rightarrow S_{h}^{r}$ is defined by,
\begin{equation*}
(\nabla (\varphi-R_h\varphi), \nabla\psi_{h})=0,	\quad	\forall\, \psi_{h}\in S_{h}^{r},
\end{equation*}
with $\int_{\Omega}(\varphi-R_h\varphi) \mathrm{d}\x$=0 for the uniqueness. The Ritz projection satisfies with following estimates:
\begin{equation*}
\begin{aligned}
&\|\varphi-R_h\varphi\|_{L^{s}}+h\|\varphi-R_h\varphi\|_{W^{1, s}}\leq C h^{r+1}\|\varphi\|_{W^{r+1, s}},\\
&\|\varphi-R_h\varphi\|_{H^{-1}}\leq C \beta_{h}\|\varphi\|_{H^{r+1}},\\
&\|d_{t}(\varphi^{k}-R_h\varphi^{k})\|+h\|d_{t}(\varphi^{k}-R_h\varphi^{k})\|_{H^{1}}\leq C h^{r+1}\|d_{t}\varphi^{k}\|_{H^{r+1}},\\
&\|d_{t}(\varphi^{k}-R_h\varphi^{k})\|_{H^{-1}}\leq C \beta_{h}\|d_{t}\varphi^{k}\|_{H^{r+1}},
\end{aligned}
\end{equation*}
for $s\in[2, \infty]$ and $k=1, 2, \cdots, N_T$.

However, suffering from the high coupling nonlinearity, the previous works failed to obtain optimal error estimate in $L^{2}$-norm due to the limitations of the traditional approach. Thanks to the introduction of the Ritz quasi-projection, Stokes quasi-projection in \cite{2023Optimalwang} and the Maxwell quasi-projection in \cite{2023New}, we manage to improve the theoretical results.

(3) The Ritz quasi-projection $\widetilde{R}_h: H^{1}(\Omega)\rightarrow S_{h}^{r}$ is defined by
\begin{equation*}
(\nabla (\omega-\widetilde{R}_h\omega), \nabla\varphi_{h})+  (\nabla (\phi-R_h\phi)\cdot \u,   \varphi_{h})=0,
\end{equation*}
for all $\varphi_{h}\in S_{h}^{r}$ and $\int_{\Omega}(\omega-\widetilde{R}_h\omega) \mathrm{d}\x$=0, and its estimates are as follows:
\begin{equation*}
\begin{aligned}
&\|\omega-\widetilde{R}_h\omega\| +h\|\nabla(\omega-\widetilde{R}_h\omega)\|\leq C h^{r+1}\big(\|\u\|_{L^{\infty}}\|\phi\|_{H^{r+1}}+ \|\omega\|_{H^{r+1}}\big),\\
&\|\omega-\widetilde{R}_h\omega\|_{H^{-1}}\leq C \beta_{h}\big(\|\u\|_{W^{1, 4}}\|\phi\|_{H^{r+1}}+ \|\omega\|_{H^{r+1}}\big),\\
&\|\nabla(d_{t}(\omega^{k+1}-\widetilde{R}_h\omega^{k+1}) )\|\leq C h^{r}\big(  \|\u^{k+1}\|_{L^{\infty}}\|d_{t}\phi^{k+1}\|_{H^{r}}+ \|d_{t}\u^{k+1}\|_{L^{\infty}}\|\phi^{k}\|_{H^{r}} +\|d_{t}\omega^{k+1}\|_{H^{r+1}}   \big),\\
&\|d_{t}(\omega^{k+1}-\widetilde{R}_h\omega^{k+1})\|_{H^{-1}}\leq C \beta_{h}\big(  \|\u^{k+1}\|_{W^{1,4}}\|d_{t}\phi^{k+1}\|_{H^{r+1}}+ \|d_{t}\u^{k+1}\|_{W^{1, 4}}\|\phi^{k}\|_{H^{r+1}} +\|d_{t}\omega^{k+1}\|_{H^{r+1}}   \big),
\end{aligned}
\end{equation*}
for $k=0, 1, 2, \cdots, N_T-1$.

(4) The Stokes quasi-projection $(\P_{h}, P_{h}): \H_{0}^{1}(\Omega)\times L_{0}^{2}(\Omega)\rightarrow \X_{h}^{r+1}\times \mathring{S}_{h}^{r}/ \X_{h}^{1b}\times \mathring{S}_{h}^{1}$ is given by
\begin{equation*}
\begin{aligned}
&\big(\nabla (\u-\P_{h}(\u, p)), \nabla \v_{h}\big) - \big(p-P_{h}(\u, p), \nabla\cdot \v_{h}  \big)=\big( \omega \nabla( \phi- R_h\phi), \v_{h} \big),\\
&\big(\nabla\cdot (\u-\P_{h}(\u, p)), q_{h}\big) = 0,
\end{aligned}
\end{equation*}
for all $(\v_{h}, q_{h})\in \X_{h}^{r+1}\times \mathring{S}_{h}^{r}/ \X_{h}^{1b}\times \mathring{S}_{h}^{1}$, and we denote $\P_{h}\u:=\P_{h}(\u, p)$ and $P_{h}p:=P_{h}(\u, p)$ for simplicity. Further, the Stokes quasi-projection has the following estimates: 
\begin{equation}\label{err-U}
\|\u-\P_{h}\u\|=\left\{
\begin{aligned}
&Ch^{r+2} \big(\|\u\|_{H^{r+2}}+  \|p\|_{H^{r+1}} +  \|\phi\|_{H^{r+1}}\|\omega\|_{H^{2}}\big), &&r\geq2,	\\
&Ch^{r+1} \big(\|\u\|_{H^{r+1}} +  \|p\|_{H^{r}} +  \|\phi\|_{H^{r+1}}\|\omega\|_{H^{2}}\big), &&r=1,
\end{aligned}
\right.
\end{equation}
\begin{equation}\label{err-UH1}
\|\nabla (\u-\P_{h}\boldsymbol{u})\|+\|p-P_{h}p\|=\left\{
\begin{aligned}
&Ch^{r+1} \big(\|\u\|_{H^{r+2}}+  \|p\|_{H^{r+1}} +  \|\phi\|_{H^{r+1}}\|\omega\|_{W^{1, 4}}\big), &&r\geq2,	\\
&Ch^{r+1} \big(\|\u\|_{H^{r+2}}+  \|p\|_{H^{r+1}} +  \|\phi\|_{H^{r+1}}\|\omega\|_{W^{1, 4}}),  &&r=1 \, (\X_{h}^{2}\times \mathring{S}_{h}^{1}\big),	\\
&Ch^{r} \big(\|\u\|_{H^{r+1}}+  \|p\|_{H^{r}} +  \|\phi\|_{H^{r}}\|\omega\|_{W^{1, 4}}\big),  &&r=1 \, (\X_{h}^{1b}\times \mathring{S}_{h}^{1}),
\end{aligned}
\right.
\end{equation}
\begin{equation*}\label{Stokes3}
\|d_{t} (\u^{k+1} -\P_{h}\u^{k+1} )\| =\left\{
\begin{aligned}
&Ch^{r+2} \big(\|d_{t}\u^{k+1} \|_{H^{r+2}}+  \|d_{t}p^{k+1} \|_{H^{r+1}} +  \|d_{t}\phi^{k+1} \|_{H^{r+1}}\|\omega^{k+1} \|_{H^{2}}+\|\phi^{k} \|_{H^{r+1}}\|d_{t}\omega^{k+1} \|_{H^{2}} \big), &&r\geq2, \\
&Ch^{r+1}\big(\|d_{t}\u^{k+1} \|_{H^{r+1}}+  \|d_{t}p^{k+1} \|_{H^{r}} +  \|d_{t}\phi^{k+1} \|_{H^{r+1}}\|\omega^{k+1} \|_{H^{2}}+\|\phi^{k} \|_{H^{r+1}}\|d_{t}\omega^{k+1} \|_{H^{2}} \big), &&r=1 ,
\end{aligned}
\right.
\end{equation*}


