\section{The Proof of Theorem \ref{theorem2-2} }\label{sec-proof}

%The well-posedness of the convex-splitting scheme for the two-phase MHD model (\ref{numerical-scheme}) has been given in \cite{2019A}. 
In this section, we will provide the proof of Theorem \ref{theorem2-2}, and some essential inequality are introduced.

\begin{lemma}[\cite{heywood1990finite}]\label{Gronwall}
Let $\alpha_{k}, \beta_{k}, c_{k}, \gamma_{k}$ and $g_{0}$ be a sequence of nonnegative numbers for integers $k\geq 0$ such that
\begin{equation*}
\alpha_{k}+\Delta t\sum_{j=0}^{k}\beta_{j}\leq \Delta t\sum_{j=0}^{k}\gamma_{j}\alpha_{j}+\Delta t\sum_{j=0}^{k}c_{j}+g_{0}.
\end{equation*}
Assume that $\gamma_{j}\Delta t\leq 1$ for all $j$, and set $\sigma_{j}=(1-\gamma_{j}\Delta t)^{-1}$. Then, for all $k\geq 0$, we have
\begin{equation*}
\alpha_{k}+\Delta t\sum_{j=0}^{k}\beta_{j}\leq {\rm exp}\bigg(\Delta t\sum_{j=0}^{k}\sigma_{j} \gamma_{j} \bigg)\bigg(  \Delta t\sum_{j=0}^{k}c_{j}+g_{0}\bigg).
\end{equation*}
\end{lemma}

\begin{lemma}[\cite{2023New, hiptmair2002finite}]\label{lemmaita}
For any $\boldsymbol \eta \in \L^{2}(\Omega)$ and $\y_{h}\in \Z_{h}^{l}$, we have
\begin{align*}
|(\y_{h}, \boldsymbol \eta)|\leq C (h\|\boldsymbol \eta \|+ \|\boldsymbol \eta \|_{(H^{1})'} )\|\nabla\times \y_{h}\|.
\end{align*}

\end{lemma}

\begin{lemma}[\cite{Jean2006Mathematical, 2019A, 1975Sobolev, 1986On}]
	We have the following Poincar\'{e}  inequalities and embedding inequalities
	\begin{align}
		&\|\psi\|_{L^{q}}\leq C \|\psi\|_{H^{1}},
				\qquad 
			\forall \psi\in H^{1}(\Omega)\cap L^2_0(\Omega), \H_{0}^{1}(\Omega),
				\qquad 
			1\leq q \leq 6,\label{i2}\\
		& \|v_{h}\|_{W^{m,s}}\leq C h^{n-m+\frac{d}{s}-\frac{d}{q}}\|v_{h}\|_{W^{n,q}},
				\qquad 
			v_{h}\in S_{h}^{r}, \mathring{S}_{h}^{r}, \X_{h}^{r+1}, \X_{h}^{1b},
				\quad 
			0\leq n\leq m\leq1,\quad  1\leq q\leq s\leq\infty.	 \label{i4}
	\end{align}
\end{lemma}

\subsection{Error equations}
For simplicity, we introduce the following error functions
\begin{align*}
e_{\phi}^{k}:=R_h\phi^{k}-\phi^{k}_{h},	
	\quad e_{\omega}^{k}:=\widetilde{R}_h\omega^{k}-\omega^{k}_{h}, 
	\quad e_{p}^{k}:=P_{h}p^{k}-p^{k}_{h},
	\quad e_{\u}^{k}:=\P_{h}\u^{k}-\u^{k}_{h}, 
	\quad e_{\B}^{k}:=\PPi_h\B^{k}-\B^{k}_{h}.
\end{align*}

With the help of projection operators defined in the previous section, we subtract \eqref{weak1}-\eqref{weak5} at $t=t_{k+1}$ from \eqref{scheme1}-\eqref{scheme2} to get the following error equations for ($e_{\phi}^{k+1}, e_{\omega}^{k+1}, e_{\u}^{k+1}, e_{p}^{k+1}, e_{\B}^{k+1}$),
\begin{align}
 &\big(d_{t}e_{\phi}^{k+1}, \varphi_{h} \big) 
		+\big(\nabla e_{\omega}^{k+1}, \nabla  \varphi_{h}\big)
		=\big(d_{t}(R_h\phi^{k+1}- \phi^{k+1}  ), \varphi_{h}\big)
		 +\big(\nabla \phi_{h}^{k}\cdot\u_{h}^{k+1},   \varphi_{h}\big)
		-\big( \nabla R_h\phi^{k+1}\cdot\u^{k+1},   \varphi_{h}\big)
		+\big(R_{1}^{k+1}, \varphi_{h}\big), 	\label{error1}\\
&\big( \nabla e_{\phi}^{k+1}, \nabla\psi_{h}  \big)
		-\big(e_{\omega}^{k+1}, \psi_{h} \big)
		+\frac{1}{2} \big( Z^{k+1}(e_{\phi}^{k+1}-e_{\phi}^{k}  ),  \psi_{h} \big)  
		=  -\big(Z^{k+1}\bar{e}_{\phi}^{k+\frac{1}{2}},  \psi_{h}  \big)
		+ \big(e_{\phi}^{k},  \psi_{h} \big)
		- \big((\phi^{k+1})^{3}-(R_h \phi^{k+1})^{3} , \psi_{h} \big)	\nonumber\\
&\hspace{0.5in}
		+ \big(\phi^{k}-R_h\phi^{k}, \psi_{h} \big)
		+ \big(\omega^{k+1}-\widetilde{R}_h\omega^{k+1}, \psi_{h} \big)
		+ \big(R_{2}^{k+1} ,\psi_{h} \big), 	\label{error2}\\
&\big(d_{t}e_{\u}^{k+1}, \v_{h} \big)
		+ \big(\nabla  e_{\u}^{k+1}, \nabla\v_{h} \big)
		- \big(\nabla\cdot \v_{h}, e_{p}^{k+1} \big)
		= \Big[ b (\u_{h}^{k}, \u_{h}^{k+1}, \v_{h} ) -b (\u^{k}, \u^{k+1}, \v_{h})\Big] \nonumber  \\
&\hspace{0.5in} 
		+\Big[ \big(\nabla R_h\phi^{k+1}\cdot \v_{h}, \omega^{k+1}\big) 
		- (\nabla \phi_{h}^{k}\cdot \v_{h}, \omega_{h}^{k+1}) \Big]	
	 	+ \big(d_{t}(\P_{h}\u^{k+1}-\u^{k+1}), \v_{h}\big) \nonumber\\
&\hspace{0.5in}  
		+\big(\nabla\times \B_{h}^{k+1}, \v_{h} \times\B_{h}^{k}\big) 
		-\big(\nabla\times \B^{k+1}, \v_{h}\times\B^{k}\big)+ \big( R_{3}^{k+1} ,\v_{h}  \big),  \label{error3}\\
&\big(\nabla\cdot e_{\u}^{k+1}, q_{h} \big)=0, 	\label{error4}\\
&\big(d_{t} e_{\B}^{k+1}, \C_{h}\big)
		+ \big(\nabla\times e_{\B}^{k+1},  \nabla\times  \C_{h}  \big) 
		=\big(d_{t}( \PPi_h\B^{k+1}-\B^{k+1}), \C_{h}\big)
		+\big(\nabla\times (\PPi_h\B^{k+1}-\B^{k+1}), \nabla\times\C_{h} \big)	\nonumber \\
&\hspace{0.5in}  
		-\big( (\u_{h}^{k+1}\times \B_{h}^{k}, \nabla\times \C_{h}\big)
		-\big(\u^{k+1}\times \B^{k}, \nabla\times \C_{h})\big)+\big(R_{4}^{k+1} ,\C_{h}\big)  ,		 \label{errorBT}
\end{align}
for any $(\varphi_{h}, \psi_{h}, \v_{h}, q_{h},  \C_{h})\in \mathring{\boldsymbol \chi }_{h}^{r}$  and $k=0, 1, \cdots, N_T-1$, where we define
\begin{equation*}
\begin{aligned}
&e_{\phi}^{k+1}=\bar{e}_{\phi}^{k+\frac{1}{2}}+\frac{1}{2}(e_{\phi}^{k+1}-e_{\phi}^{k}),\quad \bar{e}_{\phi}^{k+\frac{1}{2}}:=\frac{1}{2}(e_{\phi}^{k+1}+e_{\phi}^{k} ),\\
&(R_h\phi^{k+1})^{3}-(\phi_{h}^{k+1})^{3}=3e_{\phi}^{k+1}\int_{0}^{1}\left((1-\theta)\phi_{h}^{k+1} +\theta R_h \phi^{k+1}   \right)^{2}d\theta= \frac{1}{2}(e_{\phi}^{k+1}-e_{\phi}^{k} )Z^{k+1}+\bar{e}_{\phi}^{k+\frac{1}{2}} Z^{k+1},\\
&Z^{k+1}:=3\int_{0}^{1}\left((1-\theta)\phi_{h}^{k+1} +\theta R_h \phi^{k+1}   \right)^{2}d\theta.
\end{aligned}
\end{equation*}
In addition, $R_{1}^{k+1}, R_{2}^{k+1}, R_{3}^{k+1}$, and $R_{4}^{k+1}$ are the truncation terms satisfying
\begin{equation*}
\begin{aligned}
\big(R_{1}^{k+1}, \varphi_{h}\big)= &\big(d_{t}\phi^{k+1} - \phi_t^{k+1}, \varphi_{h}\big),	\qquad
\big(R_{2}^{k+1}, \psi_{h}\big)=  \big(\phi^k, \psi_{h}\big) -\big(\phi^{k+1}, \psi_{h}\big),	\\
\big(R_{3}^{k+1}, \v_{h}\big) = &\big(d_{t}\u^{k+1} - \u_{t}^{k+1}, \v_{h}\big)  + b\big(\u^{k} - \u^{k+1}, \u^{k+1}, \v_{h}\big)  + \big(\nabla\times \B^{k+1}, \v_{h}\times(\B^k-\B^{k+1}) \big),  \\
\big(R_{4}^{k+1}, \C_{h}\big)= &\big(d_{t}\B^{k+1} - \B_{t}^{k+1}, \C_{h}\big) - \big(\u^{k+1}\times (\B^{k}-\B^{k+1}) , \nabla\times \C_{h}\big).
\end{aligned}
\end{equation*} 
By utilizing the Taylor expansion, it is easy to obtain the truncation error estimates 
\begin{equation*}%\label{Taylor}
\bigg(\Delta t\sum_{k=0}^{N_T-1}(\|R_{1}^{k+1}\|^{2} + \|R_{2}^{k+1}\|^{2} + \|d_tR_{2}^{k+1}\|^{2} +\|R_{3}^{k+1}\|^{2}+\|R_{4}^{k+1}\|^{2}   ) \bigg)^{\frac{1}{2}}\leq C \Delta t.
\end{equation*}

Next, we give the error estimates of the numerical solutions in the following lemma, which will be repeatedly used in later analysis.
\begin{lemma}[(4.21) and (4.22), \cite{2023Optimalwang}]\label{lemmaphi}
By taking $\varphi_{h}=e_{\omega}^{k+1}$ and $\psi_{h}=d_{t}e_{\phi}^{k+1}$ in equations (\ref{error1})-(\ref{error2}), respectively, we can get the following estimate:
\begin{align}\label{phi}
\quad \|\nabla e_{\phi}^{k+1}\|^{2}+\Delta t\sum_{m=0}^{k}\|\nabla e_{\omega}^{m+1}\|^{2}\leq & C_{\epsilon}\Delta t\sum_{m=0}^{k}\Big(\|e_{\textbf{u}}^{m+1}\|^{2} + \|\nabla e_{\phi}^{m+1}\|^{2} + \|  e_{\phi}^{m}\|^{2}    \Big)+C_{\epsilon} \Big(\beta_{h}^{2}+\Delta t^{2}  \Big) +\varepsilon \Delta t \sum_{m=0}^{k} \|  e_{\omega}^{m+1}\|^{2}        \nonumber  \\
&   + C \Delta t \sum_{m=0}^{k}\|d_{t}Z^{m+1}\|_{L^{\frac{3}{2}}}\| e_{\phi}^{m}\|^{2}_{H^{1}}+ \big(2+\epsilon  \big)\|e_{\phi}^{k+1}\|^{2}.
\end{align}
By additionally taking $\varphi_{h}=(-\Delta_{h})^{-1}e_{\phi}^{k+1}$
and $\psi_{h}=e_{\phi}^{k+1}-\frac{1}{|\Omega|}( e_{\phi}^{k+1}, 1)$ in equations (\ref{error1})-(\ref{error2}), there exists a small positive constant $\Delta t_{1}$ such that for $\Delta t \leq\Delta t_{1}$,  the $L^{2}$-norm estimates for $e_{\phi}^{k+1}$ and $e_{\omega}^{k+1}$ are as follows:
\begin{align*}
&\quad \|e_{\omega}^{k+1}\|\leq C \Big(\|\nabla e_{\omega}^{k+1}\|+  \|\nabla e_{\phi}^{k+1}\| +\|\nabla e_{\phi}^{k}\| +\beta_{h}+\Delta t \Big),	\\
&\quad \| e_{\phi}^{k+1}\|^{2}\leq \varepsilon \|\nabla e_{\phi}^{k+1}\|^{2}+C_{\varepsilon}\Delta t\sum_{m=0}^{k}\|e_{\u}^{k+1}\|^{2}+ C_{\varepsilon} (\beta_{h}^{2}+\Delta t^{2}),
\end{align*}
where $\beta_{h}$ is given in Theorem \ref{theorem2-2}. Here, the discrete Laplacian operator $\Delta_{h}:\mathring{S}_{h}^{r}\rightarrow \mathring{S}_{h}^{r}$ is defined by
	\begin{equation*}
		(-\Delta_{h}\psi_{h}, \varphi_{h})=(\nabla\psi_{h}, \nabla\varphi_{h}),\quad \forall \psi_{h}, \varphi_{h}\in \mathring{S}_{h}^{r}.
	\end{equation*}
	%In addition, if $v_{h}$ is constant, we define  $(-\Delta_{h})^{\frac{1}{2}}v_{h}= (-\Delta_{h})^{-\frac{1}{2}}v_{h}:=0$.

%Hereafter,  we employ  $C_{\epsilon}$ to denote a generic positive constant, independent of $\Delta t$, $h$, and discretization parameters, and $\epsilon$ as a small generic constant, which may take different values at different places.
\end{lemma}

\subsection{Estimates for $e_{\textbf{u}}^{k+1}$. }

Taking $\v_{h}=e_{\u}^{k+1}$,  $q_{h}=e_{p}^{k+1}$ in equations (\ref{error3})-(\ref{error4}), we have
\begin{align}\label{error-u}
&\frac{1}{2}d_{t}\|e_{\u}^{k+1}\|^{2} + \frac{1}{2\Delta t}\|e_{\u}^{k+1}-e_{\u}^{k}\|^{2} + \|\nabla e_{\u}^{k+1}\|^{2} 	\nonumber	\\
&= 
	\Big[ b\big(\u_{h}^{k}, \u_{h}^{k+1}, e_{\u}^{k+1}\big)-b\big(\u^{k}, \u^{k+1}, e_{\u}^{k+1}\big) \Big]  
	+ \Big[ \big(\nabla R_h\phi^{k+1}\cdot e_{\u}^{k+1}, \omega^{k+1}\big) - \big(\nabla \phi_{h}^{k}\cdot e_{\u}^{k+1}, \omega_{h}^{k+1}\big)\Big]	 \nonumber \\
&\ \ \ \
		+ \Big[\big(d_{t}(\P_{h}\u^{k+1}-\u^{k+1}), e_{\u}^{k+1}\big) + \big( R_{3}^{k+1} ,e_{\u}^{k+1} \big) \Big]
		+ \Big[\big(\nabla\times \B_{h}^{k+1}, e_{\u}^{k+1} \times\B_{h}^{k}\big) - \big(\nabla\times \B^{k+1}, e_{\u}^{k+1}\times\B^{k}\big)\big] \nonumber	\\
&:=
	\sum_{i=1}^{4} I_{i}.
\end{align}

\begin{lemma}[Section 4.2, \cite{2023Optimalwang}]\label{lemmaI}
We have the following known results 
\begin{align*}
&I_{1} \leq\varepsilon\|\nabla e_{\u}^{k+1}\|^{2}+C_{\varepsilon}\Big(\beta_{h}^{2} +\|e_{\boldsymbol{u}}^{k}\|^{2} \Big),\\
&I_{2} \leq C_{\varepsilon}\Big(\|e_{\u}^{k+1}\|^{2} + \|\nabla e_{\phi}^{k}\|^{2} + \beta_{h}^{2}+\Delta t^{2} \Big)+  \varepsilon\Big( \| e_{\omega}^{k+1}\|^{2}+  \|\nabla e_{\u}^{k+1}\|^{2}\Big),\\
&I_{3} \leq C \Big( \beta_{h}^{2}+ \| e_{\u}^{k+1}\|^{2}+ \|R_{3}^{k+1}\|^{2}    \Big).
\end{align*}
\end{lemma}

