Next, we can estimate $I_{4}$ as
\begin{align}\label{II}
I_{4}
=&\, \big(\nabla\times \B_{h}^{k+1}, e_{\u}^{k+1} \times\B_{h}^{k}\big) - \big(\nabla\times \B^{k+1}, e_{\u}^{k+1}\times\B^{k}\big)	\nonumber	\\
=&\,  \big(\nabla\times (\B_{h}^{k+1}-\PPi_h\B^{k+1}), e_{\u}^{k+1} \times\B_{h}^{k}\big) 
	+ \big(\nabla\times (\PPi_h\B^{k+1} - \B^{k+1}), e_{\u}^{k+1} \times\B_{h}^{k}\big) \nonumber \\
& 
 	+ \big(\nabla\times \B^{k+1}, e_{\u}^{k+1} \times(\B_{h}^{k}-\PPi_h\B^{k})\big)	
	+ \big(\nabla\times \B^{k+1}, e_{\u}^{k+1} \times(\PPi_h\B^{k}-\B^k)\big)		\nonumber \\
\leq&\, \Big[\big(\nabla\times  e_{\B}^{k+1}, e_{\u}^{k+1}\times (\B^{k}-\B_{h}^{k}) \big) 
	+ C\|\nabla\times e_{\B}^{k+1}\|\,\|e_{\u}^{k+1}\|\,\|\B^k\|_{L^\infty}\Big]	\nonumber	\\
&
	+ \Big[Ch^{l-\frac{d}{6}}\,\|\nabla e_{\u}^{k+1}\|\,\|e_{\B}^k\|_{L^2}
	+ Ch^{2l} \,\|\nabla e_{\u}^{k+1}\| + Ch^{l+1}\|\nabla e_{\u}^{k+1}\|\Big] \nonumber	\\
&
	+ \|\nabla\times \B^{k+1}\|_{L^\infty}\| e_{\u}^{k+1}\|\,\|e_{\B}^k\|
	+ \|\nabla\times \B^{k+1}\|_{L^\infty}\|e_{\u}^{k+1}\|_{H^1}\|\PPi_h\B^{k}-\B^k\|_{(H_0^1)'}	\nonumber	\\
\leq&
	\,\big(\nabla\times  e_{\B}^{k+1}, e_{\u}^{k+1}\times (\B^{k}-\B_{h}^{k}) \big) 
	+ \varepsilon (\|\nabla e_{\u}^{k+1}\|^{2} + \|\nabla\times e_{\B}^{k+1}\|^{2}) + C_{\varepsilon} \big( \|e_{\u}^{k+1}\|^2 + \| e_{\B}^{k}\|^2 + h^{2l+2} \big),
\end{align} 
for some sufficiently small $h$, where we utilize
\begin{align*}
&\big(\nabla\times (\B_{h}^{k+1}-\PPi_h\B^{k+1}), e_{\u}^{k+1} \times\B_{h}^{k}\big) \\
&= 
	\big(\nabla\times(\B_{h}^{k+1}-\PPi_h\B^{k+1}), e_{\u}^{k+1}\times(\B_{h}^{k}-\B^k)\big)	
	+  \big(\nabla\times (\B_{h}^{k+1}-\PPi_h\B^{k+1}), e_{\u}^{k+1} \times\B^{k}\big)	\\
&\leq 
	\big(\nabla\times  e_{\B}^{k+1}, e_{\u}^{k+1}\times (\B^{k}-\B_{h}^{k}) \big) 
	+ C\|\nabla\times e_{\B}^{k+1}\|\,\|e_{\u}^{k+1}\|\,\|\B^k\|_{L^\infty},
\end{align*}
and
\begin{align*}
&\big(\nabla\times (\PPi_h\B^{k+1} - \B^{k+1}), e_{\u}^{k+1} \times\B_{h}^{k}\big)	\\
&=
	\big(\nabla\times (\PPi_h\B^{k+1} - \B^{k+1}), e_{\u}^{k+1} \times(\B_h^{k}-\PPi_h\B^k)\big)
	+ \big(\nabla\times (\PPi_h\B^{k+1} - \B^{k+1}), e_{\u}^{k+1} \times(\PPi_h\B^k-\B^k)\big) \\
&\quad\: \big(\nabla\times (\PPi_h\B^{k+1} - \B^{k+1}), e_{\u}^{k+1} \times\B^k\big)	\\
&\leq 
	\|\nabla\times (\PPi_h\B^{k+1} - \B^{k+1})\|\,\|e_{\u}^{k+1}\|_{L^6}\|e_{\B}^k\|_{L^3}
	+ \||\nabla\times (\PPi_h\B^{k+1} - \B^{k+1})\|\,\|e_{\u}^{k+1}\|_{L^6}\|\PPi_h\B^k-\B^k\|_{L^3} \\
&\quad +\|\nabla\times (\PPi_h\B^{k+1} - \B^{k+1})\|_{(H_0^1)'}\|e_{\u}^{k+1}\|_{H^1}\|\B^k\|_{L^\infty}	\\
&\leq 
	Ch^l \,\|\nabla e_{\u}^{k+1}\|\, h^{-\frac{d}{6}}\|e_{\B}^k\|_{L^2}
	+ Ch^l \,\|\nabla e_{\u}^{k+1}\|\, h^l + Ch^{l+1}\|\nabla e_{\u}^{k+1}\|.
\end{align*}
Combining Lemma \ref{lemmaI} and choosing a sufficiently small $\varepsilon$, equation (\ref{error-u}) reduces to
\begin{align*}
d_{t}\|e_{\u}^{k+1}\|^{2} +\|\nabla e_{\u}^{k+1}\|^{2} \leq 
& C_{\varepsilon}\big(\|e_{\u}^{k+1}\|^{2} + \|e_{\u}^{k}\|^{2} + \|\nabla e_{\phi}^{k}\|^{2}
   +\beta_{h}^{2} +h^{2(l+1)}+\Delta t^{2} +\|e_{\B}^{k}\|^{2}\big) \\
& +\varepsilon \big(\|e_{\omega}^{k+1}\|^{2}+\|\nabla\times  e_{\B}^{k}\|^{2}\big) + \big(\nabla\times  e_{\B}^{k+1}, e_{\u}^{k+1}\times (\B^{k}-\B_{h}^{k}) \big).
\end{align*}
Consequently, summing up the above estimate from time step $t_{0}$ to $t_{k}$ leads to
\begin{align}\label{Nu}
\|e_{\u}^{k+1}\|^{2} + \Delta t\sum_{m=0}^{k}\|\nabla e_{\u}^{m+1}\|^{2}\leq 
&C_{\varepsilon}\Delta t \sum_{m=0}^{k} 
  \big(\|e_{\u}^{m+1}\|^{2} + \|\nabla e_{\phi}^{m+1}\|^{2} \big)
  + C_{\varepsilon} \big(\beta_{h}^{2}+h^{2(l+1)} +\Delta t^{2}\big)  \nonumber \\
&+\varepsilon \Delta t \sum_{m=0}^{k} \big(\|e_{\omega}^{m+1}\|^{2} + \|\nabla\times  e_{\B}^{m+1}\|^{2}\big) + \Delta t \sum_{m=0}^{k}  \big(\nabla\times e_{\B}^{m+1},   e_{\u}^{m+1}\times (\B^{m}-\B_{h}^{m}) \big).
\end{align}
%where $\|e_{\u}^{0}\|^{2}\leq C\beta_{h}$.

\subsection{Estimates for $e_{\textbf{B}}^{k+1}$.}

Taking $\C_{h}= e_{\B}^{k+1}$ in equation (\ref{errorBT}), we have
\begin{align}\label{error-BB}
&\frac{1}{2}d_{t}\| e_{\B}^{k+1}\|^{2} + \frac{1}{2\Delta t}\|e_{\B}^{k+1}-e_{\B}^{k}\|^{2} + \|\nabla \times e_{\B}^{k+1}\|^{2} 
		= \big(d_{t}(  \PPi_h\B^{k+1}-\B^{k+1}), e_{\B}^{k+1} \big)  
		+ \big(R_{4}^{k+1} ,e_{\B}^{k+1}\big) 	 \nonumber \\
&\ \ \ \ 
	+ \Big[ \big(\nabla\times (\PPi_h\B^{k+1}-\B^{k+1}), \nabla\times e_{\B}^{k+1}\big) 
		 - (\u_{h}^{k+1}\times \B_{h}^{k}, \nabla\times e_{\B}^{k+1}) +  (\u^{k+1}\times \B^{k}, \nabla\times e_{\B}^{k+1}) \Big] 	\nonumber	\\
&:= \sum_{i=1}^{3}Q_i.
\end{align}
According to Lemma \ref{lemmaita} and \eqref{error-dcurl}-\eqref{error-dH1}, we obtain the estimates of $Q_1$
\begin{align}\label{ets_Q1}
	Q_{1} 
	&\leq  \Big(h\|d_{t}(\PPi_h\B^{k+1}-\B^{k+1})\| + \|d_{t}(  \PPi_h\B^{k+1}-\B^{k+1})\|_{(H^{1})'} \Big) \|\nabla\times e_{\B}^{k+1}\|  	\nonumber	\\
	&\leq C_{\varepsilon}\Big(h^{2(l+1)}+  \Delta t^{2} \Big) + \varepsilon\|\nabla\times e_{\B}^{k+1}\|  ^2,
\end{align}
and by using the Taylor expansion, we can estimate $Q_2$ as 
\begin{align}\label{ets_Q2}
	Q_2 \leq \|R_{4}^{k+1}\|\, \|\nabla\times e_{\B}^{k+1}\|  
			\leq C_{\varepsilon}\Delta t^{2} + \varepsilon\|\nabla\times e_{\B}^{k+1}\|^{2}.
\end{align}
Employing the definition of the Maxwell quasi-projection \eqref{def-Max}, we know
\begin{align*}\label{QQ3}
Q_{3}
= &
	\big(\nabla\times e_{\B}^{k+1}\times(\B^{k+1}-\PPi_h\B^{k+1}), \u^{k+1}\big)
	+ \big(7(|\u^{k+1}|^2+1)(\B^{k+1}-\PPi_h\B^{k+1}), e_{\B}^{k+1}\big)	\nonumber	\\
& 
	+ \big(\nabla\times e_{\B}^{k+1}\times\B_h^{k}, \u_h^{k+1}\big) 
	- \big(\nabla\times e_{\B}^{k+1}\times\B^k, \u^{k+1}\big)	\nonumber\\
=&
	\big(\nabla\times e_{\B}^{k+1}\times[(\B^{k+1}-\PPi_h\B^{k+1}) - (\B^k-\PPi_h\B^k)], \u^{k+1}\big)
	+ \big(\nabla\times e_{\B}^{k+1}\times(\B^k-\PPi_h\B^k), \u^{k+1}\big)	\nonumber	\\
&
	+ \big(7(|\u^{k+1}|^2+1)(\B^{k+1}-\PPi_h\B^{k+1}), e_{\B}^{k+1}\big)	
	+ \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\B^k), \u_h^{k+1}\big)		\nonumber	\\
&
	+ \big(\nabla\times e_{\B}^{k+1}\times\B^k, \u_h^{k+1}-P_h\u^{k+1}\big)	
	+ \big(\nabla\times e_{\B}^{k+1}\times\B^k, P_h\u^{k+1}-\u^{k+1}\big)			\\
:=&
	\sum_{i=1}^{6}Q_{3,i}
\end{align*}
Applying the estimates of quasi-projections and Lemma \ref{lemmaita},  we can estimate $Q_{3,1}-Q_{3,6}$ as
\begin{align*}
	Q_{3,1} &\leq \|\nabla\times e_{\B}^{k+1}\|\, \Delta t\|d_t(\B^{k+1}-\PPi_h\B^{k+1})\|\,\|\u^{k+1}\|_{L^\infty}
	\leq C_{\varepsilon}\big(\Delta t^2 + h^{4l}\big) + \varepsilon\|\nabla\times e_{\B}^{k+1}\|^2,		\\
	Q_{3,2} + Q_{3,4} 
		&= \big(\nabla\times e_{\B}^{k+1}\times(\B^k-\PPi_h\B^k), \u^{k+1}\big)
			+ \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\B^k), \u_h^{k+1}\big)		\\
		& = \big(\nabla\times e_{\B}^{k+1}\times(\B^k-\B_h^k), \u^{k+1}\big)
			+ \big(\nabla\times e_{\B}^{k+1}\times(\B_h^k-\PPi_h\B^k), \u^{k+1}\big) 	\\
		&\quad
			+ \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\B^k), \u_h^{k+1}-\P_h\u^{k+1}\big)	
			+ \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\B^k), \P_h\u^{k+1}-\u^{k+1}\big)	\\
		&\quad 
			+ \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\B^k), \u^{k+1}\big)		\\
		&= -\big(\nabla\times e_{\B}^{k+1}\times e_{\B}^k, \u^{k+1}\big) 
			- \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\B^k), e_{\u}^{k+1}\big)	 \\
		&\quad
			+ \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\PPi_h\B^k), \P_h\u^{k+1}-\u^{k+1}\big)
			+ \big(\nabla\times e_{\B}^{k+1}\times(\PPi_h\B^k-\B^k), P_h\u^{k+1}-\u^{k+1}\big)	\\
		&\leq 
			\|\nabla\times e_{\B}^{k+1}\|\,\|e_{\B}^k\|\,\|\u^{k+1}\|_{L^\infty}	
			+ \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\B^k), e_{\u}^{k+1}\big) \\
		&\quad
			+ \|\nabla\times e_{\B}^{k+1}\|\,\|e_{\B}^k\|_{L^3}\|\P_h\u^{k+1}-\u^{k+1}\|_{L^6}	
			+ \|\nabla\times e_{\B}^{k+1}\|\,\|\PPi_h\B^k-\B^k\|_{L^3}\|\P_h\u^{k+1}-\u^{k+1}\|_{L^6} \\
		&\leq 
			C \|\nabla\times e_{\B}^{k+1}\|\,\|e_{\B}^k\| 
			+ \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\B^k), e_{\u}^{k+1}\big) 	
			+ C \|\nabla\times e_{\B}^{k+1}\|\, h^{-\frac{d}{6}}\|e_{\B}^k\| h^r	
			+ C  \|\nabla\times e_{\B}^{k+1}\| h^{l+r}	\\
		&\leq
			C_{\varepsilon}\big(\|e_{\B}^k\|^2 + h^{2l+2r}\big) + \varepsilon\|\nabla\times e_{\B}^{k+1}\|^2 + \big(\nabla\times e_{\B}^{k+1}\times(\B_h^{k}-\B^k), e_{\u}^{k+1}\big), 	\\
	Q_{3,3} &\leq \|7(|\u^{k+1}|^2+1)\|_{L^{\infty}}\big|\big((\B^{k+1}-\PPi_h\B^{k+1}), e_{\B}^{k+1}\big)\big|	\\
		&\leq C\big(h\|\B^{k+1}-\PPi_h\B^{k+1}\| + \|\B^{k+1}-\PPi_h\B^{k+1}\|_{(H^1)'}\big) \|\nabla\times e_{\B}^{k+1}\|	\\
		&\leq C_{\varepsilon}h^{2l+2} + \varepsilon\|\nabla\times e_{\B}^{k+1}\|^2,	\\
	Q_{3,5} &\leq \|\nabla\times e_{\B}^{k+1}\|\,\|\B^k\|_{L^\infty} \|e_{\u}^{k+1}\|
		\leq C_{\varepsilon}\|e_{\u}^{k+1}\|^2 + \varepsilon\|\nabla\times e_{\B}^{k+1}\|^2,	\\
	Q_{3,6} &\leq \|\nabla\times e_{\B}^{k+1}\|\,\|\B^k\|_{L^\infty}\|P_h\u^{k+1}-\u^{k+1}\|	
		\leq C_{\varepsilon}\beta_h^2 + \varepsilon\|\nabla\times e_{\B}^{k+1}\|^2,	
\end{align*}
Combining the above estimates, we have
\begin{align*}
Q_{3} \leq C_{\varepsilon}\Big(\Delta t^{2} + h^{2l+2} + \beta_{h}^{2}+ \|e_{\u}^{k+1} \| ^{2}+\|e_{\B}^{k }\|^{2} \Big) 
          + \varepsilon \|\nabla\times e_{\B}^{k+1}\|^{2}
          + \big(\nabla\times e_{\B}^{k+1}\times (\B^{k }- \B_{h}^{k }), e_{\u}^{k+1}  \big).
\end{align*}
Thus, using the estimate $Q_1$, $Q_2$ and $Q_3$, \eqref{error-BB} can be rewritten as
\begin{align*}
d_{t}\|e_{\B}^{k+1}\|^{2} +\|\nabla \times e_{\B}^{k+1}\|^{2}
	\leq C_{\varepsilon}\Big(\Delta t^{2}+ h^{2(l+1)}+ \beta_{h}^{2}+ \|e_{\u}^{k+1} \| ^{2}+\|e_{\B}^{k }\|^{2} \Big)  
	+ \big(\nabla\times e_{\B}^{k+1}\times (\B^{k}- \B_{h}^{k}), e_{\u}^{k+1}  \big),
\end{align*}
with a sufficiently small $\varepsilon$. Given $e_{\B}^{0}=\0$ and summing up the above inequality from time step $t_{0}$ to $t_{k}$, we obtain
\begin{align*}
  \|e_{\B}^{k+1}\|^{2} +\Delta t\sum_{m=0}^{k}\|\nabla \times e_{\B}^{m+1}\|^{2}\leq 
&  C_{\varepsilon}\Big(\Delta t^{2}+ h^{2(l+1)}+ \beta_{h}^{2}\Big)
  + C_{\varepsilon}\Delta t\sum_{m=0}^{k}\Big(\|e_{\u}^{m+1} \| ^{2}+\| e_{\B}^{m }\|^{2} \Big) \\
&+  \Delta t\sum_{m=0}^{k} \Big(\nabla\times e_{\B}^{m+1}\times (\B^{m}- \B_{h}^{m}), e_{\u}^{m+1}  \Big).
\end{align*}
which together with Lemma \ref{lemmaphi} and \eqref{Nu} finally leads to
\begin{align*}
&\|\nabla e_{\phi}^{k+1}\|^{2}+\|e_{\u}^{k+1}\|^{2}+\|e_{\B}^{k+1}\|^{2}+\Delta t\sum_{m=0}^{k}\Big(\|\nabla e_{\omega}^{m+1}\|^{2}+ \|\nabla e_{\u}^{m+1}\|^{2}+\|\nabla \times e_{\B}^{m+1}\|^{2}   \Big)\nonumber \\
\leq 
& C_{\epsilon}\Delta t\sum_{m=0}^{k}\Big(\|e_{\u}^{m+1}\|^{2} + \|\nabla e_{\phi}^{m+1}\|^{2}  +\| e_{\B}^{m }\|^{2}  \Big)
 + C_{\epsilon} \Big(\beta_{h}^{2}+h^{2(l+1)}+\Delta t^{2}  \Big)
 + C \Delta t \sum_{m=0}^{k}\|d_{t}Z^{m+1}\|_{L^{\frac{3}{2}}}\| e_{\phi}^{m}\|^{2}_{H^{1}}.
\end{align*} 
By using the discrete Gronwall's inequality in Lemma \ref{Gronwall}, there exists a positive constant $\Delta t_{2}$ such that for $\Delta t\leq \min\{\Delta t_{1}, \Delta t_{2}\}$, 
\begin{align}
\|\nabla e_{\phi}^{k+1}\|^{2}+\|e_{\u}^{k+1}\|^{2}+\|e_{\B}^{k+1}\|^{2}+\Delta t\sum_{m=0}^{k}\Big(\|\nabla e_{\omega}^{m+1}\|^{2}+ \|\nabla e_{\u}^{m+1}\|^{2}+\|\nabla \times e_{\B}^{m+1}\|^{2}   \Big)\leq C_{\epsilon} \Big(\beta_{h}^{2}+h^{2(l+1)}+\Delta t^{2}  \Big).
\end{align}
Combining the estimates of projection operators in Section \ref{sec-projections} and the triangle inequality, the proof of convergence results in Theorem \ref{theorem2-2} is completed. 



