\section{Probability theory}\label{sec:probabilty}
\subsection{Review of probability spaces, independence and expectations}\label{subsec:elementary-probability}
As mentioned in the introduction, our goal is to provide a concise and mostly self-contained document describing the probability space model and the random variable that counts comparisons in the QuickSort algorithm. Before proceeding, we will review some elementary concepts from probability theory that will be used later. All the facts of this subsection can be found in any standard references on probability theory, such as~\cite{SR14}. Throughout, we will focus exclusively on finite probability spaces, which further simplifies our analysis.

A (finite) probability space is a pair $(S,p)$, where $S$ is a finite set and $p\colon S\to [0,1]$ is a functions satisfying \[ \sum_{s\in S}p(s)=1.\] 
The set $S$ is referred to as the \emph{sample space}, and its elements represent the possible outcomes of a given experiment. The function $p(s)$ assigns a probability to each outcome $s\in S$.
Subsets $A\subseteq S$ are called \emph{events}, and their probability is defined as
\[ p(A) = \sum_{s\in A} p(s).\]

Events $A$ and $B$ are called \emph{independent} if $p(A\cap B) = p(A)\cdot p(B)$. 

Now consider two experiments modeled by probability spaces  \( W_1=(S_1, p_1) \) and \(W_2= (S_2, p_2) \). One defines the \emph{product} of the probability spaces as  $W=W_1\times W_2 = (S,p)$ as $S= S_1\times S_2$ and $p(a,b)= p_1(a)\cdot p_2(b)$. 
\begin{lemma}\label{lem:W1xW2-is-space}
	Let \( (S_1, p_1) \) and \( (S_2, p_2) \) be probability spaces. Then, $W= (S_1\times S_2,p_1\cdot p_2)$ is a probability space.
\end{lemma}


To see that $W$ models the independent execution of the original experiments embed events $A\subseteq S_1$ and $B\subseteq S_2$ into the joint probability space by
\[ e_1(A) = A \times S_2 \ , \ e_2(B) = S_1 \times B \]
and verify
\[ p(e_1(A)) = p_1(A) \ , \ p(e_2(B)) = p_2(B) \ , \ p(e_1(A) \cap e_2(B)) = p_1(A)\cdot p_2(B) \]

A \emph{random variable} is a function $X\colon S\to \R$. Its \emph{expected value} resp. \emph{expectation} is 
	\[E(X)= \sum_{s\in S}p(s)\cdot X(s).\]
%For random variables of the same probability space expectation is linear: 
%\begin{lemma}\label{lem:expectation-is-linear}
%Let $(S,p)$ be a probability space and let $X,Y \colon S \to \R$ be random variables. Then
%\[ E(aX+bY) = a\cdot E(X) + b\cdot E(Y) \]
%\end{lemma}
Expectation of random variables from independent experiments is additive
	\begin{lemma} \label{lem:E-of-sum} 
		For $i\in\{1,2\}$ let $(S_i,p_i)$ be probability spaces  and let
		\(X_i\colon S_i \to \R \) be random variables. For
		\( X \colon S_1 \times S_2 \to \R,\) defined by \( X(a,b) = X_1(a) + X_2(b), \) we have 
		\[ 	E(X ) = E(X_1) + E(X_2).\]
	\end{lemma}
	\begin{proof}
		\begin{align*}
		E(X)&= \sum_{(a,b) \in S_1 \times S_2} p(a,b ) \cdot X(a,b)\\
		&= \sum_{a \in S_1} \sum_{b \in S_2}p_1(a) \cdot p_2(b)\cdot  (X_1(a) + X_2(b)) \\
		&= \sum_{a \in S_1} p_1(a) \cdot( \sum_{b \in S_2} p_2(b)\cdot  (X_1(a) + X_2(b)) \\
		&= \sum_{a \in S_1} p_1(a) \cdot X_1(a) \cdot( \sum_{b \in S_2} p_2(b) ) + \sum_{a \in S_1} p_1(a)  \cdot( \sum_{b \in S_2} p_2(b)\cdot X_2(b) )\\
		&= \sum_{a \in S_1} p_1(a) \cdot X_1(a) \cdot 1 + \sum_{a \in S_1} p_1(a)  \cdot E(X_2)\\
		&= E(X_1) + E(X_2) \qedhere
		\end{align*}
	\end{proof}




	\subsection{Conditional expectation}\label{subsec:conditional-expectation}
For events $A,B\subseteq S$ with $p(A)>0$ (\emph{i.e.} $A$ is not impossible) the conditional probability of $A$ given $B$ is defined as\[ p(A\mid B) = \frac{p(A\cap B)}{p(A)}.\]

\begin{definition}
	For random variable $X\colon S \to \R$ its \emph{conditional expectation} given~$A$ is
	\[ E(X\mid A) = \sum_{s\in S} p(s\mid A)\cdot X(s).\]
\end{definition}
For $s\notin A$ we have $p(\{s\} \cap A) = p(\emptyset) =0$ and for $s\in A$ we have $\{s\}\cap A = \{s\}$. Thus
	\[ E(X\mid A) = \sum_{s\in A} \frac{p(s)}{p(A)}\cdot X(s) = \frac{1}{p(A)} \sum_{s\in A} p(s) \cdot X(s).\]
The law of conditional expectation, also called the law of complete expectation, to which Hoare refers in~\cite{DBLP:journals/cj/Hoare62} is then
\begin{lemma}\label{lem:law-of-conditional-expextation}
For a partition $S = \stackrel{.}{\bigcup}_i  A_i$ of $S$ into not impossible events, that is, with $p(A_i)>0$ for all $i,$ the expected value of random variable $X$ is
\[ E(X) = \sum_i p(A_i)\cdot E(X \mid A_i). \]
\end{lemma}
\begin{proof}
	\begin{align*}
			\sum_i p(A_i)\cdot E(X \mid A_i) &= \sum_i p(A_i) \cdot \frac{1}{p(A_i)} \sum_{s\in A_i} p(s) \cdot X(s)\\
			= \sum_i  \sum_{s\in A_i} p(s)\cdot X(s)&=E(X). \qedhere
	\end{align*}
\end{proof}


\subsection{Conditional Experiments}\label{subsec:conditional-experiments} Let \( X_{\textup d} \colon \{1,2,\dots,6\} \to \mathbb{R} \) be the random variable on the sample space of dice rolls, defined as the identity map. Now, consider two experiments: flipping a coin and rolling a dice. First, flip a coin. If the result is heads (\emph{i.e.}, \( X_{\text c} = 0 \)), flip the coin again; otherwise, roll the dice. What is the expected total number of points in the long run? One might intuitively suspect the expected value to be  
\[E(X_{\text c})+ \frac{1}{2}\cdot E(X_{\text c})+\frac{1}{2}\cdot E(X_{\text d}) = \frac{10}{4}.\] 
We will show that this intuition holds in general.

Think of a first experiment as $(S,p)$. For every outcome $i\in S$ define a corresponding second experiment $(R_i,p_i)$. We construct the combined probability space corresponding to the conditional experiment.
\begin{lemma}\label{lem:W_Q}
	Let $(S,p)$ be a probability space. Let $(R_i,p_i)$ be probability spaces indexed by elements $i\in S$. Let $(Q, q)$ be defined by $Q=\cup_{i\in S}\{i\}\times R_i$ and $q(i,a)= p(i)\cdot p_i(a)$ for $a\in R_i$. Then $(Q, q)$ is a probability space.
\end{lemma}

\begin{proof}
	\[
		\sum_{(i,a) \in Q} q(i,a) = \sum_{i \in S} \sum_{a \in R_i} p(i)\cdot p_i(a)
		=\sum_{i \in S} p(i) \cdot (\sum_{a \in R_i}  p_i(a) )
		=\sum_{i \in S} p(i) \cdot 1
		=1.\qedhere
	\]	
\end{proof}

To see that this models the conditional execution of experiments $(R_i,p_i)$ as a function of the outcome of experiment $(S,p)$ consider an arbitrary event $A\subset R_i$. Embed $\{i\}$ and $A$ into $Q$ by
\[ e_1(i) = \{i\} \times \bigcup_j R_j \ , \ e_2(A) = \{i\} \times A \]
and verify
	\[ q(e_1(i)) = p(i),\, \ q(e_2(A)) = p_i(A) =  q(e_2(A) \mid  e_1(i)).  \]

The following lemma justifies the  usual analysis of probabilistic algorithms. Its statement is similar to the law of conditional expectation (Lemma~\ref{lem:law-of-conditional-expextation} above), and could be shown with the help of it. However, we prefer a direct proof. 

\begin{lemma}[Principle of Deferred Decision] \label{lem:conditional} Say we are given random variables
\( X_0\colon S \to \R \), \( X_i\colon R_i \to \R \) for each $i\in S$ and \( X\colon  Q \to \R \). Define $X\colon Q\to R$ by \( X(i,r) = X_0(i) + X_i(r).\) Then
	\[ E(X) = E(X_0) + \Sigma_{i\in S} p(i) \cdot E(X_i) \]
\end{lemma}

\begin{proof}
	\begin{align*}
		E(X) &= \sum_{i\in S}\sum_{r\in R_i}q(i,r) \cdot X(i,r) \\
		&= \sum_{i\in S}\sum_{r\in R_i}p(i) \cdot p_i(r)  \cdot (X_0(i) + X_i(r))\\
		&= \sum_{i\in S}p(i)\cdot(\sum_{r\in R_i}p_i(r)  \cdot (X_0(i) + X_i(r))\\
		&= \sum_{i\in S}p(i)\cdot X_0(i)\cdot(\sum_{r\in R_i}p_i(r) ) +  \sum_{i\in S}p(i)\cdot (\sum_{r\in R_i}p_i(r) \cdot  X_i(r))\\
			&= \sum_{i\in S}p(i)\cdot X_0(i)\cdot 1 + \sum_{i\in S}p(i)\cdot E(X_i)\\
			&= E(X_0) + \sum_{i\in S}p(i)\cdot E(X_i). \qedhere
	\end{align*}
\end{proof}
\section{Expected run time of QuickSort}\label{sec:expected-runtime-of quicksort} A short specification of the QuickSort algorithm can be given as follows. An input is a set $A=\{a_1,a_2,\dots, a_n\}$. We may assume that $a_i$ are mutually distinct. Choose a ``splitter'' $s\in A$. Each element is equally likely to get chosen as a splitter. Let
\[A_< = \{a\in A \mid a<s\}\quad \text{and} \quad A_> = \{a\in A \mid a>s\}.\] Then define the result recursively as
\begin{equation}\label{eq:quicksort}
\text{QuickSort}(A) = \text{QuickSort}(A_<)\circ s\circ \text{QuickSort}(A_>). 
\end{equation}

We inductively define a probability space \( (Q_n, q_n) \), where the elements represent possible runs of the QuickSort algorithm on \( A \). The random variable \( t_n \colon Q_n \to \mathbb{R} \) represents the number of comparisons performed in a given run.

\begin{definition} \label{def:quicksort}\hfill
\begin{description}
\item[Base case] For $n=0,1$ let $Q_n =\{\bot\}$, with $q_n(\bot)=1$ and $t_n(\bot)=0$.
\item[Induction] For $n\geq 2,$ let $(S_n,r_n)$ be the probability space with $S_n =\{1,\dots,n\}$ and a uniform probability $r_n(i)=\nicefrac{1}{n}.$ Define
\[Q_n = \cup_{i\in S_n}\{i\}\times(Q_{i-1}\times Q_{n-i}),\]
\[q_n\big(i,(a,b)\big)= \frac{1}{n}\cdot q_{i-1}(a)\cdot q_{n-1}(b).\]
\end{description}
A random variable $t_n\colon Q_n\to \R$ is defined as
\[t_n\big(i,(a,b)\big)= n-1+ t_{i-1}(a)+t_{n-i}(b).\]
\end{definition}
Elements \( i \in S_n \) represent the possible ranks of the chosen splitter, meaning \( i = |A_<| + 1 \). Once the splitter with rank \( i \) is selected (with probability \( \nicefrac{1}{n} \)), there are \( i-1 \) elements to sort on the ``left'' and \( n-i \) on the ``right,'' as given by~\eqref{eq:quicksort}. This leads to the sets \( Q_{i-1} \) and \( Q_{n-i} \). The first term in the formula for \( t_n \) accounts for the \( n-1 \) comparisons required to determine the splitter.  

\begin{example}
\[Q_2 = \{1\}\times Q_0\times Q_1 \cup \{2\}\times Q_1\times Q_0 =\{(1,\bot,\bot),(2,\bot, \bot)\}  \] with $q_2((1,\bot,\bot)=q_2((1,\bot,\bot))=\nicefrac{1}{2}$. This represents sorting a two-element set, which is completed in a single step. We either select the smaller element first, with probability $\nicefrac{1}{2}$, or the larger element first, also with probability $\nicefrac{1}{2}$.  These two cases correspond to the elements $(1,\bot,\bot)$ and $(2,\bot,\bot)$, respectively. Thus $t_2\big((1,\bot,\bot)\big)=t_2\big((2,\bot,\bot)\big)=1.$

\begin{align*}
Q_3 &= \{1\}\times Q_0\times Q_2 \cup \{2\}\times Q_1\times Q_1 \cup \{3\}\times Q_2\times Q_0 \\
 &=\{\big(1,\bot,(1,\bot,\bot)\big),\big(1,\bot,(2,\bot,\bot)\big), \big(2,\bot,\bot\big),\big(3,(1,\bot,\bot),\bot\big), \big(3,(2,\bot,\bot),\bot\big)\}.
\end{align*}
with $q_3\big((2,\bot,\bot)\big)=\nicefrac{1}{3}$ and $q_3(x)=\nicefrac{1}{6}$ for all $x\neq (2,\bot,\bot)$. The probability space \( (Q_3, q_3) \) represents sorting a three-element set. For example, the element \( \big(1,\bot,(2,\bot,\bot)\big) \) describes the scenario where the smallest element is chosen first, followed by the larger of the two remaining elements on the right. Note that \( t_3\big((2,\bot,\bot)\big) = 2 \), while \( t_3(x) = 3 \) for all other elements \( x \neq (2,\bot,\bot) \). This shows that sorting sequences requiring fewer comparisons occur with higher probability.  
\end{example}
\begin{lemma}
Let $(Q_n,q_n)$ be as in Definition~\ref{def:quicksort}. For all $i$ and $n$, $(Q_n,q_n)$ is a probability space.
\end{lemma}
\begin{proof}
We use induction on $n$. $n=0,1$ is trivial. Assume statement is true for $j<n$. Then $i-1<n$ and $n-i<n,$ thus  $(Q_{i-1}\times Q_{n-i}, q_{i-1}\cdot q_{n-1})$ is a probability space by Lemma~\ref{lem:W1xW2-is-space}. We conclude by Lemma~\ref{lem:W_Q}.
\end{proof}
\begin{lemma}\label{lem:expecQuickSort}
Let $t_n\colon Q_n\to \R$ be as in Definition~\ref{def:quicksort}. For all $n$, 
\[E(t_n) = n-1+\frac{1}{n}\cdot\sum_{i=1}^n\big( E(t_{i-1})+E(t_{n-i})\big).\]
\end{lemma}
\begin{proof}
By Lemma~\ref{lem:E-of-sum}, $E(t_{i-1}+t_{n-i}) =E(t_{i-1})+E(t_{n-i}).$ Observe that the expected value of a constant random variable is simply the constant itself. We conclude by Lemma~\ref{lem:conditional}.
\end{proof}

To adopt the usual notation we write $T(n)= E(t_n)$, and Lemma~\ref{lem:expecQuickSort} translates to
\begin{equation}\label{eq:Tn}
T(n)= n-1+\frac{1}{n}\cdot\sum_{i=1}^n\big( T(i-1)+T(n-i)\big).
\end{equation}

For completeness we present the derivation of the time bound from {\cite{DBLP:books/aw/AhoHU74}}.

\begin{lemma}
Let $T\colon \mathbb{N} \to \R$ be defined by~\eqref{eq:Tn}. Then $T(n)\leq 2n\cdot\ln(n)$.
\end{lemma}
\begin{proof}
The proof is by induction on $n$. For $n=1$, $T(1)= 0=2\cdot 1\cdot \ln(1)$. For $n>1,$
\begin{align*}
	T(n) &< n + \frac{1}{n} \cdot \sum_{i=1}^n \big(T(i-1) + T(n-i)\big)
	= n+ \frac{1}{n} \cdot \left(\sum_{i=0}^{n-1} T(i)  + \sum_{i=0 }^{n-1} T(i)\right)\\
	&= n+ \frac{2}{n} \cdot \sum_{i=0}^{n-1} T(i)
	= n+ \frac{2}{n} \cdot \sum_{i=1}^{n-1} T(i) \quad (\text{as } T(0) =T(1) = 0 )\\
	&\le n+ \frac{2}{n} \cdot \sum_{i=2}^{n-1} 2i\cdot \ln(i) \quad\text{(by induction hypothesis)}\\
	&\le n+ \frac{2}{n} \cdot \int_{2}^{n} 2x\cdot \ln(x) \,\textup{d}x \quad\text{(as the area under the curve is larger than the sum)}\\
	&= n+ \frac{2}{n} \cdot \big((n^2 \ln (n) - \frac{n^2}{2}) 
	 - (2^2\ln 2 - 2^2/2)\big)\\
	&< 2n \cdot \ln (n) \quad (\text{as }\ln 2 >0.69> \nicefrac{1}{2}). \qedhere
\end{align*}
\end{proof}

\section{Alternative analyses of Quicksort}\label{sec:future-work}
\subsection{Deterministic QuickSort} This refers to a deterministic version of the algorithm, where always the first element of a sequence is used as a splitter and the sequence of ranks of the input is assumed to be uniformly distributed. The obvious probability space of problem size $n$ has as sample space the permutations~$\pi$ of $\{1,\ldots,n\}$, each with probability $p(\pi)=1/n!$ for all $\pi$. Compared with the above analysis of randomize QuickSort the induction step now requires extra work: one has to show that the sequence of ranks of the generated subsequences continue to be uniformly distributed. This extra work is indeed treated in~\cite{DBLP:books/sp/SandersMDD19} and the combined probability space, where expectations can be summed, can be obtained from Lemma~\ref{lem:conditional}.
\subsection{Analyzing randomized QuickSort using indicator variables} As described in~\cite{DBLP:books/cu/MotwaniR95} and~\cite{DBLP:books/daglib/0012859}, one counts for inputs $x_i$ and $x_j$ of ranks $i$ and $j>i$ the occurrence of the event that $x_i$ is compared with $x_j$ with index variables $X_{i,j}$.  Then one sums the expectations $E(X_{i,j})$ of these variables. Formally this summation has to be done in the same probability space. For randomized QuickSort we can reuse the probability space constructed in Section~\ref{sec:expected-runtime-of quicksort}, because it belongs to the algorithm, not to its analysis.

The key observation of the analysis is, that 
\begin{enumerate}[label=\roman*)]
\item every run of the algorithm splits every interval of ranks of inputs $\{x_i,\ldots x_j\}$;
\item for every $x_q\in\{x_i,\ldots ,x_j\},$ the probability that the element  $x_q$ is the splitter is 
\end{enumerate} 
\begin{equation}\label{eq:indicator}
	p(x_q) = \frac{1}{j-i+1}.
\end{equation}
This gives $E(X_{i,j}) = p(x_i) + p(x_j) = 2/(j-i+1)$. Equation \ref{eq:indicator} is considered in \cite{DBLP:books/cu/MotwaniR95} and \cite{DBLP:books/daglib/0012859} as self evident, or at best supported by informal arguments. Below we give a short, but not a completely trivial proof.

 For $1\le i < j \le n$ and any element $x_q\in S=\{x_i,\ldots x_j \}$ denote by $p_n(x_q,i,j)$ the probability, that element $x_q$ splits the elements of $S$ in a run of the algorithm with inputs of size~$n$.
\begin{lemma}
	The probablities $p_n(x_q,i,j)$ only depend on the size $s=j-i+1$ of $S$ and are
	\[ p_n(x_q,i,j) =\frac{1}{s}. \]
\end{lemma}
\begin{proof}
	By induction on $n$. Trivial for $n=2$. In the induction step element $x_q$ can be chosen first among elements in $S$ as splitter in the following cases.
	\begin{enumerate}[label=\roman*)]
\item $x_q$ is chosen overall as the first splitter. This happens with probability $1/n$.
\item  for the $n-s$ choices of first splitters outside of $S,$ the set $S$ still lies in one of the subsequences generated by the algorithm. We can apply the induction hypothesis to each of them, because they all have a length smaller than $n$.
\end{enumerate} 
Thus, we get
	\[
	p_n(x_q,i,j) = \frac{1}{n} + \frac{n-s}{n}\cdot\frac{1}{s} =\frac{1}{n} + \frac{1}{s} - \frac{1}{n} = \frac{1}{s}. \qedhere
	\]
\end{proof}

