\subsection{Details of Example~\ref{ex:interventions-depend-on-effects-problematic}}
\label{appendix:details:counterexample-all-fail}
\paragraph{Interventions that are influenced by effects may cause performative invalidity}
The conditional probability $P(L=1  \mid X=(1, 1))=0.55$ follows from the fact that $X_E$ is
uninformative if $X_C=1$, and if $X_C = 1$,  $U_L $ has to be above  $0.45$, 
which happens with probability $0.55$. In the other cases, 
the variable $X_E$ is completely informative. So we get
 %
\begin{align*}
    P(L = 1 \mid X=(0, 0)) &= 0 \\
    P(L = 1 \mid X=(0, 1)) &= 1
.\end{align*}
%
To get the abducted distribution of $U_L$ given a rejected point, we
condition on the target label $L$, 
 %
\begin{align*}
    p(u_L  \mid  X=(0, 0))
    &= p(u_L \mid  L=1, X=(0, 0))P(L=1  \mid X=(0, 0))\\
    &\phantom{=}+ p(u_L \mid  L=0, X=(0, 0))P(L=0  \mid X=(0, 0))\\
    &=p(u_L \mid  L=0, X=(0, 0))
.\end{align*}
%
We remark that $U_L \independent X_E  \mid L, X_C$. Then, if $L=0$, $U_L$
has to come from  $[0, 0.55]$. It still
has to be uniformly distributed however. Altogether this gives 
the result
%
\begin{align*}
    p(U_L \mid  X=(0, 0))
    = \text{Unif}(0, 0.55)
.\end{align*}
%
If we mix this distribution, with a mixing weight of $0.2$, with the original 
distribution, we see that the observation $X=(1,1)$ now gets a conditional
probability of 
%
\begin{align*}
    P(L^{m}=1  \mid X^{m}=(1, 1)) = 
    0.2* \frac{0.1}{0.55} + 0.8 * 0.55 = 0.4844\ldots < t_c
.\end{align*}
%
The point $X=(1,1)$ will now get rejected. 
\qed

