We restate the assumption and stability results again for completeness sake. 
\funcasump*

\paragraph{Linear Additive and Multiplicative SCMs satisfy Assumption~\ref{asmp:func-form}}
In the Section~\ref{sec:func-proofs} we mention that Linear Additive models and
Multiplicative SCMs satisfy Assumption~\ref{asmp:func-form}. Here we will 
quickly show that this is the case. 
In general, the structural equations for the effect variables $X_E$ and $Y$ are given by the following structural equations:
%
\begin{align*}
    Y &= l_Y(X_C) + \eY\\
    X_E &= l_E(Y, X_C, X_S) + \eE,
.\end{align*}
%
where $l_Y$ and $l_E$ are linear functions (for example, $l_E(Y, X_C, X_S) = \beta_Y Y + \beta_C + X_C + \beta_S + X_S + \beta_0$). By substituting the expression of $Y$ into the equation for $X_E$ we get
%
\begin{align*}
    X_E &= l_E(l_Y(X_C) + \eY, X_C, X_S) + \eE\\
    &= l_E(l_Y(X_C), X_C, X_S) + \beta \eY + \eE.
\end{align*}
%
We can rewrite the structural equations as
%
\begin{align*}
    b_{\text{agg}}(x) &= \beta \eY + \eE\\
    f_{\text{agg}}(x_C, x_S, u_{\text{agg}}) &= l_E(l_Y(x_C), x_C, x_S) + u_{\text{agg}}\\
    f_{\text{agg}}^{-1}(x_C, x_S, x_E) &= x_E - l_E(l_Y(x_C), x_C, x_S).
\end{align*}
%
and thus Assumption~\ref{asmp:func-form} is satisfied.

In multiplicative settings with multilinear aggregation functions $m$ (linear in each argument, for example $m_E(X_C, Y, X_S) = X_C Y X_S \beta$), we get 
%
\begin{align*}
    Y &= m_Y(X_C) U_Y \\
    X_E &= m_E(X_C, Y, X_S) U_E
\end{align*}
%
Substituting the expression for $Y$ we get
%
\begin{align*}
    X_E &= m_E(X_C, Y, X_S) U_E\\
    &= m_E(X_C, m_Y(X_C)U_Y, X_S) U_E\\
    &= m_E(X_C, m_Y(X_C), X_S) U_Y U_E.\\
\end{align*}
%
We can rewrite the structural equations as
%
\begin{align*}
    u_{\text{agg}} &= b_{\text{agg}}(u) := (U_Y U_E)\\
    f_{\text{agg}}(x_C, x_S, u_{\text{agg}}) &:= m_E(x_C, m_Y(x_C), x_S) u_{\text{agg}} \\
    f_{\text{agg}}^{-1}(x_C, x_S, x_E) &= \frac{x_E}{m_E(x_C, m_Y(x_C), x_S)},
\end{align*}
%
and thus Assumption~\ref{asmp:func-form} is satisfied.

\ICRStable*

\begin{proof}
We will again use the characterization given in Proposition~\ref{prop:characterization}.
Using Assumption~\ref{asmp:func-form}, we can show that the required conditional
independence is present. Let $I_A$ be the index set on which an intervention $A$ is performed. 
We write,
%
\begin{align*}
    P(L^{p}, I_A=\varnothing  \mid X^{p}=x^{p})
    = 
    P(L^{p}   \mid I_A= \varnothing, X^{p} = x^{p}) P(I = \varnothing  \mid X^{p} =x^{p})
.\end{align*}
%
We can rewrite the first probability as 
%
\begin{align*}
    P(L^{p}   \mid I_A= \varnothing, X^{p} = x^{p})
    &=\int\limits_{\mathcal{U}_Y} P(L^{p}=1  \mid x^{p}, u_Y, I_A=\varnothing) 
    p(u_Y  \mid x^{p}, I_A=\varnothing) \D u_Y\\
    &=\int\limits_{\mathcal{U}_Y} P(L^{p}=1  \mid x_C^{p}, u_Y) 
    p(u_Y  \mid x^{p}, I_A=\varnothing) \D u_Y
.\end{align*}
%
Where the second equality follows from the fact that $L^{p}$ is completely determined by
$X^{p}_C$ and $\eY$. 
For the conditional probability on the noise we have the following sequence
of equalities, because we can condition on no intervention being performed
%
\begin{align*}
    p(u_Y  \mid X^{p}=x^{p}, I_A=\varnothing)
    = p(u_Y  \mid X=x^{p}, I_A=\varnothing)
    = p(u_Y  \mid X=x^{p})
.\end{align*}
%
The first equality here follows from the fact that $X^{p}$  and $X$ have the same functional
equations, when no intervention is performed. The last equality follows as
$I_A$ is deterministic function of $X$. 

What rests to show is that 
$p(u_Y  \mid X^{p}=x^{p}) = p(u_Y  \mid X=x^{p})$. 
The basis for this proof is that $X_C, X_E$ and $X_C^p, X_E^p$ constrain $U = (\eY, \eE)$
in the same way, whenever no interventions on the effects are performed.
That is, for  $p(x, x^{p}) > 0$ it holds that either  
the conditionals $p(x_E\mid x_C, x_S, u_Y, u_E)$ and $p(x_E^p\mid x_C^p, x_S^{p}, U_Y, U_E)$
are exactly zero or exactly one.
The reason is Assumption~\ref{asmp:func-form} on the structural equations. We know that
%
\begin{align*}
    p(x_E\mid x_C, x_S, u_Y, u_E) &= \ind[x_E = f_s(x_C, x_S, b_s(u_Y, u_E))]\\
    p(x_E^p\mid x_C^p, x_S^{p}, u_Y, u_E) &= \ind[x_E^p = f_s(x_C^p, x_S^{p}, b_s(u_Y, u_E))].
\end{align*}
%
We can reformulate the constraints as
%
\begin{align*}
b_s(u_Y, u_E) &= f_s^{-1}(x_C, x_E, x_S)\\
b_s(u_Y, u_E) &= f_s^{-1}(x_C^p, x_E^p, x_S^{p}).
\end{align*}
We recall that 
%
\begin{align*}
p(u_Y, u_E\mid X=x) &= \frac{p(u_Y, u_E, x)}{p(x)}
\end{align*}
%
and that
%
\begin{align*}
p(u_Y, u_E\mid X^{p}=x^p) &= \frac{p(u_Y, u_E, x^p)}{p(x^p)}.
\end{align*}
%
The joint distribution $p(u_Y, u_E, x)$, can be written out as
%
\begin{align*}
    p(u_Y, u_E, x) = p(u_Y) p(u_E) p(x_C) p(x_S)p(x_E  \mid x_C, x_S, u_Y, u_E)
,\end{align*}
giving a conditional distribution of
\begin{align}
    p(u_Y, u_E\mid X=x) 
    &= \frac{
        p(u_Y) p(u_E) p(x_C) p(x_S)p(x_E  \mid x_C, x_S, u_Y, u_E)
    }{
        \int_{\mathcal{U}} p(u_Y') p(u_E') p(x_C) p(x_S)p(x_E  \mid x_C, x_S, u_Y', u_E')\D u'}\notag\\
    &= \frac{
        p(u_Y) p(u_E) p(x_E  \mid x_C, x_S, u_Y, u_E)
    }{
    \int_{\mathcal{U}} p(u_Y') p(u_E') p(x_E  \mid x_C, x_S, u_Y', u_E')\D u'}\label{eq:first_cond}
.\end{align}
%
Now, for the second conditional we can write it as 
%
\begin{align*}
    p(u_Y, u_E, x^p) 
&= \int\limits_{\mathcal{X}_C}p(u_Y, u_E, x^p,x_C) \D x_C\\
&= \int\limits_{\mathcal{X}_C} p(u_Y, u_E, x_C) p(x_C^p\mid x_C, u_Y, u_E) p(x_E^p, x_S^{p}\mid x_C^{p}, u_Y,u_E) \D x_C\\
&= p(u_Y)p(u_E)p(x_E^p, x_S^{p}\mid x_C^p, u_Y, u_E) \int\limits_{\mathcal{X}_C} p(x_C)p(x_C^p\mid x_C, u_Y, u_E) \D x_C\\
&= p(u_Y)p(u_E)p(x_E^p, x_S^{p}\mid x_C^p, u_Y, u_E) \int\limits_{\mathcal{X}_C}p(x_C)p(x_C^p\mid x_C, u_s=b_s(u_Y, u_E)) \D x_C
\end{align*}
%
Because of the assumption, we know that $p(x_E^p, x_S^{p}\mid x_C^p, u_Y, u_E)$ is zero unless 
$b_s(u_Y, u_E) = f_s^{-1}(x_C^p, x_E^{p}, x_S^{p})$. Thus we can replace $p(x_C^p\mid x_C, u_s=b_s(u_Y, u_E))$ 
with $p(x_C^p\mid x_C, u_s=f_s^{-1}(x_C^p, x_E^{p}, x_S^{p}))$ and get 
%
\begin{align*}
p(u_Y, u_E, x^p) 
    &= p(u_Y)p(u_E)p(x_E^p, x_S^{p}\mid x_C^p, u_Y, u_E) \int\limits_{\mathcal{X}_C} p(x_C)p(x_C^p\mid x_C, u_s=f_s^{-1}(x^p)) \D x_C.\\
\end{align*}
%
Remark that the final integral only depends on $x^{p}$, we will shorten this
integral by setting
%
\begin{align*}
    Z(x^{p}) = \int\limits_{\mathcal{X}_C} p(x_C)p(x_C^p\mid x_C, u_s=f_s^{-1}(x^p)) \D x_C
.\end{align*}
%
Plugging everything together we get
%
\begin{align}
p(u_Y, u_E\mid X^{p}=x^p)
    &= \frac{
        p(u_Y)p(u_E)p(x_E^p, x_S^{p}\mid x_C^p, u_Y, u_E) Z(x^{p})
    }{
        \int_{\mathcal{U}} p(u_Y')P(u_E')p(x_E^p, x_S^{p}\mid x_C^p, u_Y', u_E') Z(x^{p}) \D u'}\notag\\
    &= \frac{
        p(u_Y)p(u_E)p(x_S^{p})p(x_E^p\mid x_C^p,x_S^{p},  u_Y, u_E) Z(x^{p})
    }{
        \int_{\mathcal{U}} p(u_Y')P(u_E')p(x_S^{p})p(x_E^p, \mid x_C^p, x_S^{p}, u_Y', u_E') Z(x^{p}) \D u'}\notag\\
    &= \frac{p(u_Y)p(u_E)p(x_E^p\mid x_C^p, x_S^{p}, u_Y, u_E)}{\int_{\mathcal{U}} p(u_Y')p(u_E')p(x_E^p\mid x_C^p, x_S^{p}, u_Y', u_E') \D u'}\label{eq:second_cond}.
\end{align}
%
If we now substitute $x=x^{p}$ into Equation~\eqref{eq:first_cond}, we observe
that the expressions in Equations~\eqref{eq:first_cond} and \eqref{eq:second_cond} are equal.
\end{proof}
%
\begin{theorem}
\label{thm:cr-unstable}
    Consider the causal graph in Figure~\ref{fig:causal-model}(a). Assume
