\subsection{Details of Example~\ref{ex:interventions-effects-problematic}}
\label{appendix:details:counterexample}

It can be shown that $P(L=1  \mid X = x) = \Phi\left((x_C + x_E)/\sqrt{2}\right) $, 
where $\Phi$ is the cdf of the standard normal distribution. In
particular, we see that the decision boundary is at $x_C = -x_E$, when
we pick as threshold $t_c = \tfrac{1}{2}$.
Additionally,  it can be shown that $P(L=1  \mid X_C =x_C) = \Phi(x_C)$. The property
to note is that $\Phi(x_C) < \frac{1}{2}$ whenever $x_C < 0$. Now, for any point with $x_C <0$,
but $x_C = -x_E$ we observe
 %
\begin{align*}
    h^{p}(x) 
    = \alpha h(x)  + \beta P(L=1  \mid X_C =x_c)
    < \frac{\alpha}{2} + \frac{\beta}{2} = \frac{1}{2}
.\end{align*}
%
So, all points on the decision boundary with $x_C < 0$, are invalidated. 
On top of that, because the recourse recommendation moves a non-zero mass
towards the decision boundary. The probability mass of the people that get rejected
that were originally accepted is non-zero. 

To see that  $P(L=1 \mid X=x)=\Phi((x_C + x_E)/ \sqrt{2})$, note that the
conditional distribution can be rewritten:
%
\begin{align*}
    P(L=1  \mid X = x) 
    &=P(Y \ge 0  \mid X=x) \\
    &=\int\limits_{0}^{\infty} p(y \mid x) \D y
.\end{align*}
%
The conditional density can be obtained through a markov decomposition
and Bayes rule
%
\begin{align}
    \label{eq:y_given_x}
    p(y  \mid x) = \frac{p(x_C, x_E, y)}{p(x_C, x_E)}
    = \frac{p(x_C) p(y  \mid x_C) p(x_E \mid y)}{p(x_C) p(x_{E} \mid x_C)}
    = \frac{p(y  \mid x_C) p(x_E \mid y)}{p(x_{E} \mid x_C)}
.\end{align}
%
By the form of the structural equations, we can see that 
%
\begin{align*}
    Y    &\mid X_C=x_c \sim \mathcal{N}(x_C, 1), \\
    X_E  &\mid Y=y \sim \mathcal{N}(y, 1)\\
    X_E  &\mid X_C = x_C \sim \mathcal{N}(x_C, 2).   
\end{align*}
%
Substituting the densities of these random variables into 
Equation~\eqref{eq:y_given_x} gives
%
\begin{align*}
    p(y  \mid x) 
    &= \frac{
        \sqrt{\frac{1}{2\pi}} \e^{-\frac{1}{2}(y - x_c)^2}
        \sqrt{\frac{1}{2\pi}} \e^{-\frac{1}{2}(x_E  - y)^2}
        }{
        \sqrt{\frac{1}{4\pi}} \e^{-\frac{1}{4}(x_E  - x_C)^2}
        }   \\
    &= \sqrt{\frac{1}{\pi}} 
    \frac{
         \e^{-\frac{1}{2}y^2 + x_c y -\frac{1}{2}x_c^2
         -\frac{1}{2}x_E^2 + x_E y -\frac{1}{2}y^2}
        }{
        \e^{-\frac{1}{4}x_E^2 + \frac{1}{2}x_Ex_C  - \frac{1}{4}x_C^2}
        } \\
    &= \sqrt{\frac{1}{\pi}} 
         \e^{-y^2 + (x_C + x_E) y -\frac{1}{4}x_c^2
         -\frac{1}{4}x_E^2 
     - \frac{1}{2}x_Ex_C }\\
    &= \sqrt{\frac{1}{\pi}} 
         \e^{-\left(y - \frac{x_C + x_E}{2}\right)^2 }
.\end{align*}
%
The last expression we recognize as the density of a 
$\mathcal{N}\left( \frac{x_C + x_E}{2}, \frac{1}{2} \right) $ distribution.
Finally, we use that we can translate and rescale the cdf of a standard
normal to the cdf of this standard normal, and we get
%
\begin{align*}
    P(L=1  \mid X=x)
    &= P(Y \ge 0  \mid X=x)\\
    &= 1 - P(Y \le 0  \mid X=x) \\
    &= 1 - \Phi\left( \frac{0 - \frac{x_C + x_E}{2}}{\sqrt{1 / 2} }\right)\\
    &= \Phi\left( (x_C + x_E) / \sqrt{2}  \right) 
.\end{align*}
%
The final equality follows from the symmetry of the standard normal distribution 
around $0$. 


