        &\leq (1 + k_1 \sqrt{\alpha}) \cdot \text{cost}(R \cup R_2, C_{P \cap P^*}) 
        + k_1 \sqrt{\alpha} \cdot \text{cost}(R_1, C_B) \notag \\
        &\quad + (1 + k_1 \sqrt{\alpha}) \cdot \left( 2D \cdot \sum_{r \in R_1} d(r, C_B) 
        + |R_1| \cdot D^2 \right). \notag
    \end{align}
    By the Cauchy-Schwarz inequality, \( \sum_{r \in R_1} d(r, C_B) \leq \sqrt{|R_1| \cdot \text{cost}(R_1, C_B)} \) holds. Also, by substituting $D$ by \eqref{eq:4}, the above inequality becomes as follow:
    \begin{align}
        &\qquad \text{cost}(P \cap P^*, C_B) \notag \\
        &\leq (1 + k_1 \sqrt{\alpha}) \cdot \text{cost}(R \cup R_2, C_{P \cap P^*}) 
        + k_1 \sqrt{\alpha} \cdot \text{cost}(R_1, C_B) \notag \\
        &\quad + 2 (1 + k_1 \sqrt{\alpha}) \cdot \sqrt{\frac{|R_1|}{|R|}}
        \left( \sqrt{\text{cost}(R, C_B) \cdot \text{cost}(R_1, C_B)} 
        + \sqrt{\text{cost}(R, C_{P \cap P^*}) \cdot \text{cost}(R_1, C_B)} \right) \notag \\
        &\quad + (1 + k_1 \sqrt{\alpha}) \cdot \frac{|R_1|}{|R|} 
        \left( \sqrt{\text{cost}(R, C_{P \cap P^*})} + \sqrt{\text{cost}(R, C_B)} \right)^2 \notag \\
        &\leq (1 + k_1 \sqrt{\alpha}) \cdot \text{cost}(P \cap P^*, C_{P \cap P^*}) 
        + k_1 \sqrt{\alpha} \cdot \text{cost}(R_1, C_B) \notag \\
        &\quad + (1 + k_1 \sqrt{\alpha}) \cdot \sqrt{\frac{\alpha}{1 - \alpha}}
        \left( \text{cost}(R, C_B) + \text{cost}(R_1, C_B) 
        + \text{cost}(R, C_{P \cap P^*}) + \text{cost}(R_1, C_B) \right) \notag \\
        &\quad + 2 (1 + k_1 \sqrt{\alpha}) \cdot \frac{\alpha}{1 - \alpha} 
        \left( \text{cost}(R, C_{P \cap P^*}) + \text{cost}(R, C_B) \right)
        \label{eq:5}
    \end{align}
    where the last inequality follows from the simple AM-GM inequality $2\sqrt{ab} \leq a+b$.

    Our second goal is to bound the remaining term \( \text{cost}(P^* \setminus P, C_B) \). By the triangle inequality,
    \begin{align}
        \text{cost}(P^* \setminus P, C_B) &= \sum_{p \in P^* \setminus P} d(p, C_B)^2 \notag \\
        &\leq \sum_{p \in P^* \setminus P} \left( d(p, C_{P \cap P^*}) + D \right)^2 \notag \\
        &= \text{cost}(P^* \setminus P, C_{P \cap P^*}) 
        + 2D \cdot \sum_{p \in P^* \setminus P} d(p, C_{P \cap P^*}) 
        + |P^* \setminus P| \cdot D^2. \notag
    \end{align}
    Note that \( |R| = |B \cap P \cap P^*| = |B| + |P \cap P^*| - |B \cup (P \cap P^*)| \geq |P \cap P^*| - \alpha |P| \). Also, since \( (1-\alpha) |P| \leq |P \cap P^*| \leq |P^*| \), thus \( |R| \geq \frac{1-2\alpha}{1-\alpha} |P^*| \).  
    Substituting $D$ by \eqref{eq:4} and applying the Cauchy-Schwarz inequality, we obtain:
    \begin{align}
        &\quad \text{cost}(P^* \setminus P, C_B) \notag \\
        &\leq \text{cost}(P^* \setminus P, C_{P \cap P^*}) \notag \\
        &\quad + 2 \sqrt{\frac{|P^* \setminus P|}{|R|}}
        \left( \sqrt{\text{cost}(R, C_B) \cdot \text{cost}(P^* \setminus P, C_{P \cap P^*})} 
        + \sqrt{\text{cost}(R, C_{P \cap P^*}) \cdot \text{cost}(P^* \setminus P, C_{P \cap P^*})} \right) \notag \\
        &\quad + \frac{|P^* \setminus P|}{|R|} 
        \left( \sqrt{\text{cost}(R, C_B)} + \sqrt{\text{cost}(R, C_{P \cap P^*})} \right)^2 \notag \\
        &\leq \text{cost}(P^* \setminus P, C_{P \cap P^*}) \notag \\
        &\quad + \sqrt{\frac{\alpha (1-\alpha)}{1-2\alpha}} 
        \left( \text{cost}(R, C_B) + \text{cost}(P^* \setminus P, C_{P \cap P^*}) 
        + \text{cost}(R, C_{P \cap P^*}) + \text{cost}(P^* \setminus P, C_{P \cap P^*}) \right) \notag \\
        &\quad + \frac{2\alpha (1-\alpha)}{1-2\alpha} 
        \left( \text{cost}(R, C_B) + \text{cost}(R, C_{P \cap P^*}) \right).
        \label{eq:6}
    \end{align}
    where the last inequality follows from the simple AM-GM inequality $2\sqrt{ab} \leq a+b$.
    Finally, for \( \alpha < \frac{1}{8} \), adding \eqref{eq:5} and \eqref{eq:6} gets us:
    \begin{align}
        \text{cost}(P^*, C_B) 
        &\leq \left( 1 + k_1 \sqrt{\alpha} \right) \cdot \text{cost}(P \cap P^*, C_{P \cap P^*}) \notag \\
        &\quad + \left( 2(1 + k_1 \sqrt{\alpha}) \sqrt{\frac{\alpha}{1-\alpha}} + k_1 \sqrt{\alpha} \right) 
        \cdot \left( \text{cost}(R, C_B) + \text{cost}(R_1, C_B) \right) \notag \\
        &\quad + \left( (1 + k_1 \sqrt{\alpha}) \left( \sqrt{\frac{\alpha}{1-\alpha}} + \frac{2\alpha}{1-\alpha} \right) 
    + \sqrt{\frac{\alpha(1-\alpha)}{1-2\alpha}} + \frac{2\alpha(1-\alpha)}{1-2\alpha} \right) \notag \\
    &\qquad \cdot \left( \text{cost}(R, C_{P \cap P^*}) + \text{cost}(P^* \setminus P, C_{P \cap P^*}) \right).
\end{align}

Since \( \text{cost}(R, C_B) + \text{cost}(R_1, C_B) \leq \text{cost}(B, C_B) \leq \text{cost}(P \cap P^*, C_{P \cap P^*}) \leq \text{cost}(P^*, C_{P^*}) \),  
and by Lemma \ref{lemma:dominant-set-cost},  
\[
\text{cost}(R, C_{P \cap P^*}) + \text{cost}(P^* \setminus P, C_{P \cap P^*}) 
\leq \text{cost}(P^*, C_{P \cap P^*}) \leq (1 + k_1 \sqrt{\alpha}) \cdot \text{cost}(P^*, C_{P^*}).
\]
Therefore, for $\alpha < 1/8$, it can be proved that:
\[
\text{cost}(P^*, C_B) \leq (1 + 45\sqrt{\alpha}) \cdot \text{cost}(P^*, C_{P^*}).
\]
However, we have not attempted to optimize this constant factor, and it seems there is room for improvement.
\end{proof}


\section{Query Complexity Lower Bound}

In this paper, we define query complexity as follows: the predictor assigns expected labels to input points, and obtaining the label of a point is considered issuing one query. This definition is consistent with prior work in \citep{learning_augmented_kmeans}. In this section, we investigate the hardness of query complexity in clustering. The goal is to determine whether we can achieve the same performance as the main theorem (full-information scenario), while only predicting labels for a subset of points. In the Euclidean setting, \citep{learning_augmented_kmeans} shows that for any $\delta \in (0, 1]$, any $(1+\alpha)$-approximation algorithm runs in time $O(2^{n^{1-\delta}})$ must make $\omega(\frac{k^{1-\delta}}{\alpha \log k})$ queries under the ETH. Their proof proceeds in two steps, building on the result of \cite{lee2017improved}, which improves the inapproximability of the \(k\)-means problem by a reduction from the vertex cover problem on $4$-regular graph.

First, they prove that the vertex cover problem remains APX-hard even when a sublinear portion (e.g., of size \(O(n^{1-\delta})\)) of a minimum vertex cover in an \(n\)-vertex graph \(G\) is known. Second, they construct a \(k\)-means instance that embeds the instance constructed by \cite{lee2017improved}, thereby translating the ability to query the predictor into revealing partial solutions of the optimal vertex cover. The hardness of query complexity can be intuitively understood as follows: even if a part of the optimal solution is known (e.g., corresponding to $O(k^{1-\delta})$ centers), it remains impossible to approximate the vertex cover arbitrarily closely to $1$ (as $\alpha \rightarrow 0$) because the remaining problem instance, stripped of the known part, still corresponds to a vertex cover problem, which is APX-hard.

We show similar results to those in \citep{learning_augmented_kmeans} also hold in a general metric setting. Our proof starts from establishing a reduction from the vertex cover problem on $4$-regular graphs to our $k$-clustering problem. \citep{lee2017improved} converts the 4-regular graph into a Euclidean $k$-means instance, which can be used to approximate the minimum vertex cover of the original graph. Its NP-hardness is derived from the results of \citep{chlebik2006complexity}, which showed that it is NP-hard to approximate the minimum vertex cover problem within a factor of $\alpha_{max} / \alpha_{min}$, where $\alpha_{min} = (2 \mu_{4,k}+8)/(4\mu_{4,k} + 12)$ and $\alpha_{max} = (2 \mu_{4,k}+9)/(4\mu_{4,k} + 12)$ for $\mu_{4,k} \leq 21.7$.

Moreover, in \citep{learning_augmented_kmeans}, the authors mentioned that assuming ETH, approximate it within the same approximation ratio in time $O(2^{n^{1-\delta}})$ is also impossible. We note that we use this more strong result in the proof of Theorem~\ref{thm:lower-bound-main}.

The conversion in \citep{lee2017improved}, from a $4$-regular graph $G$ to $G'$, is as follows: since $\card{E(G)} = 2n$, and given the well-known fact that every graph has a cut of size at least half of its edges, there exists a set $E_2 \subseteq E(G)$ such that $\card{E_2} = n$. Let $E_1 = E(G) \setminus E_2$. Then $G'$ is created by replicating each edge in $E_1$ three times, specifically:

$$ V(G') = V(G) \bigcup_{e=(u, v) \in E_1} \{ v'_{e,u}, v'_{e,v} \}, $$
$$ E(G') = E(G) \bigcup_{e=(u, v) \in E_1} \{ (u, v'_{e,u}), (v'_{e,u}, v'_{e,v}), (v'_{e,v}, v) \}, $$
which implies that $\card{V(G')} = 3n$, $\card{E(G')} = 4n$. 
\begin{lemma}
    [\citep{lee2017improved}] For a given $4$-regular graph $G$ and its converted graph $G'$, the following holds:
    \begin{itemize}
        \item If the size of the minimum vertex cover of $G$ is at most $\alpha_{min} n$, then $G'$ has a vertex cover of size at most $(\alpha_{min}+1) n$.
        \item If every vertex cover of $G$ has a size of at least $\alpha_{max} n$, then every vertex cover of $G'$ has a size of at least $(\alpha_{max}+1) n$.
    \end{itemize}
    \label{lemma:gprime-vertex-cover}
\end{lemma}

Our goal is to construct a $k$-clustering problem instance, a weighted graph $G''=(V(G''), E(G''))$, as follows. Let $V(G'') = \{ v_{e'} \, | \, e' \in E(G') \} \cup \{ s \}$, meaning that the nodes of $G''$ correspond to the edges of $G'$, plus a special node $s$. For $E(G'')$, there are two types of edges. First, an edge $(v_{e_1}, v_{e_2})$ with weight $1$ exists if and only if $e_1$ and $e_2$ are incident in $G'$. Second, for any node $u \in V(G'')$, an edge $(u, s)$ with weight $2^{1/q}$ exists. In summary, $G''$ is the union of the line graph of $G'$, $L(G')$ (with weight $1$), and a star centered at $s$ with weight $2^{1/q}$. Also, let $k = (\alpha_{min}+1) n$. The lemma from \citep{lee2017improved}, originally proposed in \citep{awasthi2015hardness}, states that a similar property holds in $G''$.
\begin{lemma}
    Let $X = \{ v_{e_1}, \ldots, v_{e_l} \}$ be a cluster on $G''$. Then $l-1 \leq cost(X, C_X) \leq 2l$, and there exist two nodes in $V(G')$ that are incident with at least $2l-1-cost(X, C_X)$ edges of $G'$. Furthermore, $cost(X, C_X) = l-1$ if and only if $X$ is a star.
    \label{lemma:center-concentrate}
\end{lemma}
\begin{proof}
    When the special node $s$ is selected as the center, we have $cost(X, s) = 2l \geq cost(X, C_X)$. Since any distance between two distinct nodes in $V(G'')$ is at least 1, $cost(X, C_X) \geq l-1$. Additionally, if $cost(X, C_X) = l-1$, then at least one node contributes a cost of $0$, implying $C_X \in X$. Other nodes in $X \setminus { C_X }$ are adjacent to $C_X$ in $G''$, meaning $X$ is a star in $G'$.

    When $cost(X, C_X) < 2l-1$, if $C_X \notin X$, there are at least $2l-cost(X, C_X)$ nodes at a distance of exactly 1 from $C_X$. Otherwise, if $C_X \in X$, then at least $2l-2-cost(X, C_X)$ nodes are at distance 1 from $C_X$, with $C_X$ itself at distance 0. Since the edges of $G''$ with weight 1 form the line graph of $G'$, there exists an edge $e$ such that $C_X = v_e$. Consequently, at least $2l-1-cost(C_X)$ edges are incident to $v_e$, so the endpoints of $e$ are the desired two nodes in $V(G')$.
\end{proof}

\begin{lemma}
    [Completeness] For $q=1, 2$, if $G$ has a vertex cover of size at most $\alpha_{min} n$, then the optimal clustering cost of $G''$ is at most $(3-\alpha_{min}) n + 2^{1/q}$.
    \label{lemma:completeness-k-clustering}
\end{lemma}
\begin{proof}
    By Lemma~\ref{lemma:gprime-vertex-cover}, there exists a vertex cover $S'$ of $G'$ with size at most $(\alpha_{min}+1) n$. We construct a clustering as follows: each cluster corresponds to the nodes in $S'$. Each $e \in E(G')$ is grouped with one of its endpoints in $S'$ (chosen arbitrarily if both endpoints are in $S'$). By construction, each cluster is star-shaped in $G'$. The special node $s \in G''$ is connected to all other nodes, contributing at most $2^{1/q}$ to the clustering cost. Therefore, the total clustering cost is:
    $$ 2^{1/q} + \sum_{i=1}^{k} cost(C_i) = 2^{1/q} + \sum_{i=1}^{k} (\card{C_i} - 1) = 4n-k = (3-\alpha_{min})n + 2^{1/q}. $$
\end{proof}

\begin{lemma}
    [Soundness] If every vertex cover of $G$ has a size of at least $\alpha_{max} n$, then the optimal clustering cost of $G''$ is at least $(3-\alpha_{min} + \frac{1}{3} (\alpha_{max}-\alpha_{min})) n$.
    \label{lemma:soundness-k-clustering}
\end{lemma}
\begin{proof}
    Ignoring the special node $s$, let $\mathcal{C}$ be any clustering of $G''-s$. By Lemma~\ref{lemma:center-concentrate} and Lemma~\ref{lemma:gprime-vertex-cover}, we can apply the proof of Lemma 5 from \citep{lee2017improved}. Since the contribution of $s$ to the clustering cost is non-negative, the result holds.
\end{proof}


By Lemma~\ref{lemma:completeness-k-clustering} and Lemma~\ref{lemma:soundness-k-clustering}, it is NP-hard to distinguish the following cases:
\begin{itemize}
    \item The optimal cost of the $k$-clustering problem is at most $(3-\alpha_{min}) n + 2^{1/q}$.
    \item Every feasible clustering cost is at least $(3-\alpha_{min} + \frac{1}{3} (\alpha_{max}-\alpha_{min})) n$.
\end{itemize}

Therefore, there exists a constant $C$ such that it is NP-hard to approximate the general metric $k$-clustering problem on a graph within a factor of $(1+C)$. We establish the following hardness result:
\begin{theorem}
    For $\delta \in (0, 1)$ and $q=1, 2$, no algorithm can produce $(1+O(\alpha^{1/q}))$-approximation solutions to the optimal $k$-clustering problem on a general metric in $O(2^{n^{1-\delta}})$ time while performing at most $O(\frac{k^{1-\delta}}{\log k})$ queries to the predictor $\Pi$ with label error rate $\alpha$, assuming the Exponential Time Hypothesis.
    \label{thm:lower-bound-main}
\end{theorem}
\begin{proof}
    The proof is by contradiction. Let $\mathcal{I}$ be the instance of the general metric $k$-clustering problem constructed via the process described above. Assume for contradiction that there exists an algorithm running in time $O(2^{n^{1-\delta}})$ and making at most $O(\frac{k^{1-\delta}}{\log k})$ queries, which achieves a $(1+O(\alpha^{1/q}))$-approximation. Then, we can convert this algorithm into one that does not use the predictor. This is because we can simulate all $k^{O(\frac{k^{1-\delta}}{\log k})} = O(2^{k^{1-\delta}})$ possible predictor outputs. For each set of simulated outputs, we can compute the corresponding solution for the base problem (vertex cover on $4$-regular graphs) and select the one with minimum cost. Thus, when $\alpha$ is sufficiently small, the properties of our reduction used to construct $\mathcal{I}$ imply the existence of an approximation algorithm for the vertex cover problem on $4$-regular graphs that surpasses its known approximation hardness, runs in time $O(2^{n^{1-\delta}})$.
\end{proof}

