\begin{algorithm}[htb]
   \caption[Blocked stage 1]{Blocked reduction to r-Hessenberg-triangular form \cite{dackland1998scalapack}}
	\label{alg:blockedstage1}
	\begin{algorithmic}[1]
		\REQUIRE $n \times n$ pencil $(A,B)$, with $B$ upper triangular
		\ENSURE decomposition $(A_{orig},B_{orig}) = Q(A,B)Z^*$, with $(A,B)$ in r-Hessenberg-triangular form

      \STATE{$Q = I$}
      \STATE{$Z = I$}
		\FOR{$j = 1:n_b:n-2$}
			\STATE{$j_1 = j$}
			\STATE{$j_2 = \min(n,j+n_b-1)$}
      	\STATE{$n_{blocks} = \lceil(n-nb-j+1)/((p-1)n_b)\rceil$}
			\FOR{$k = n_{blocks}-1:-1:0$}\label{alg:blockedstage1:leftmul}
				\STATE{$i_1 = j+n_b + k(p-1)n_b$}
				\STATE{$i_2 = \min(n,i_1+p*n_b-1)$}
				\STATE{$A(i_1:i_2,j_1:j_2) = \hat{Q}_k^j\hat{R}$}
				\COMMENT{QR factorization}
				\STATE{$A(i_1:i_2,j_1:j_2) = \hat{R}$}
				\STATE{$A(i_1:i_2,j_2+1:n) = \hat{Q}_k^{j*}A(i_1:i_2,j_2+1:n)$}\label{line:stage1-1}
				\STATE{$B(i_1:i_2,i_1:n) = \hat{Q}_k^{j*}B(i_1:i_2,i_1:n)$}\label{line:stage1-2}
				\STATE{$Q(1:n,i_1:i_2) = Q(1:n,i_1:i_2)\hat{Q}_k^{j}$}\label{line:stage1-3}
			\ENDFOR\label{alg:blockedstage1:leftmul2}

			\FOR{$i = j+n_b + (n_{blocks}-1)(p-1)n_b:-(p-1)n_b:j+n_b$}\label{alg:blockedstage1:rightmul}
				\STATE{$i_1 = i$}
				\STATE{$i_2 = \min(n,i+p*n_b-1)$}

				\STATE{$B(i_1:i_2,i_1:i_2) = \tilde{R}\tilde{Q}$}\COMMENT{RQ factorization}
				\STATE{$\tilde{Q}(1:\min(n_b,i_2-i_1+1),1:i_2-i_1+1) = L\hat{Z}$}\COMMENT{LQ factorization}
				\STATE{$A(1:n,i_1:i_2) = A(1:n,i_1:i_2)\hat{Z}$}\label{line:stage1-4}
				\STATE{$B(1:i_2,i_1:i_2) = B(1:i_2,i_1:i_2)\hat{Z}$}\label{line:stage1-5}
				\STATE{$Z(1:n,i_1:i_2) = Z(1:n,i_1:i_2)\hat{Z}$}\label{line:stage1-6}
			\ENDFOR\label{alg:blockedstage1:rightmul2}
		\ENDFOR
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}[htb]
   \caption[Unblocked stage 2]{Reduction to Hessenberg-triangular form without blocking}
	\label{alg:unblockedstage2}
	\begin{algorithmic}[1]
		\REQUIRE $n \times n$ pencil $(A,B)$ in r-Hessenberg-triangular form
		\ENSURE decomposition $(A_{orig},B_{orig}) = Q(A,B)Z^*$, with $(A,B)$ in Hessenberg-triangular form

      \STATE{$Q = I$}
      \STATE{$Z = I$}
		\FOR{$j = 1:n-2$}
			\STATE{$n_{blocks} = 1 + \lfloor \frac{n-j-2}{r} \rfloor$}
			\FOR{$k = 0:n_{blocks}-1$}
				\STATE{$j_b = j + \max(0,(k-1)r + 1) $}
				\STATE{$i_1 = j+kr+1$}
				\STATE{$i_2 = \min(j + (k+1)r,n)$}
				\STATE{$i_3 = \min(j + (k+2)r,n)$}
				\STATE{Generate a reflector $\hat{Q}_k^j = I - \tau_l v_lv_l^*$ that reduces $A(i_1:i_2,j_b)$}
				\STATE{$A(i_1:i_2,j_b:n) = \hat{Q}_k^jA(i_1:i_2,j_b:n)$}
				\STATE{$B(i_1:i_2,i_1:n) = \hat{Q}_k^jB(i_1:i_2,i_1:n)$}
				\STATE{$Q(:,i_1:i_2) = Q(:,i_1:i_2)\hat{Q}_k^j$}
				\STATE{$B(i_1:i_2,i_1:i_2) = \tilde{R}\tilde{Q}$}\COMMENT{RQ factorization}
				\STATE{Generate a reflector $\hat{Z}_k^j = I - \tau_r v_rv_r^*$ that reduces $\tilde{Q}(1,1:i_2-i_1+1)$}
				\STATE{$A(1:i_3,i_1:i_2) = A(1:i_3,i_1:i_2)\hat{Z}_k^j$}
				\STATE{$B(1:i_2,i_1:i_2) = B(1:i_2,i_1:i_2)\hat{Z}_k^j$}
				\STATE{$Z(:,i_1:i_2) = Z(:,i_1:i_2)\hat{Z}_k^j$}
			\ENDFOR
		\ENDFOR
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}
   \caption[Generate stage of stage 2]{Generate phase of stage two}
	\label{alg:stage2generate}
	\begin{algorithmic}[1]
		\REQUIRE $n \times n$ pencil $(A,B)$ in r-Hessenberg-triangular form, where $A$ is in Hessenberg form in columns $1:j_1-1$.
		\FOR{$j = j_1:j_1+q-1$}
			\STATE{$n_{blocks} = 2 + \lfloor \frac{n-j-1}{r} \rfloor$}
			\FOR{$k = 0:n_{blocks}-1$}
				\STATE{$j_b = j + \max(0,(k-1)r + 1) $}
				\STATE{$i_1 = j+kr+1$}
				\STATE{$i_2 = \min(j + (k+1)r,n)$}
				\STATE{$i_3 = \min(j + (k+2)r,n)$}
				\STATE{$i_4 = j_1+1+\max(0,(k+j-j_1-q+2)r)$}

				\FOR{$\hat{j} = j_1:j-1$}
					\STATE{$\hat{i_1} = \hat{j} + kr+1$}
					\STATE{$\hat{i_2} = \min(\hat{j} + (k+1)r,n)$}
					\IF{$\hat{i_2} - \hat{i_1} \ge 1$}
						\STATE{$A(\hat{i_1}:\hat{i_2},j_b) = \hat{Q}_k^{\hat{j}}A(\hat{i_1}:\hat{i_2},j_b)$}
						\IF{$i_1 + r - 1 \le n$}
							\STATE{$B(\hat{i_1}:\hat{i_2},i_1+r-1) = \hat{Q}_k^{\hat{j}}B(\hat{i_1}:\hat{i_2},i_1+r-1)$}
						\ENDIF
					\ENDIF
				\ENDFOR
				\STATE{Generate a reflector $\hat{Q}_k^j = I - \tau_l v_lv_l^*$ that reduces $A(i_1:i_2,j_b)$}
				\STATE{$A(i_1:i_2,j_b) = \hat{Q}_k^jA(i_1:i_2,j_b)$}
				\STATE{$B(i_1:i_2,i_1:i_2) = \hat{Q}_k^jB(i_1:i_2,i_1:i_2)$}
				\STATE{$B(i_1:i_2,i_1:i_2) = \tilde{R}\tilde{Q}$}\COMMENT{RQ factorization}
				\STATE{Generate a reflector $\hat{Z}_k^j = I - \tau_r v_rv_r^*$ that reduces $\tilde{Q}(1,1:i_2-i_1+1)$}
				\STATE{$A(i_4:i_3,i_1:i_2) = A(i_4:i_3,i_1:i_2)\hat{Z}_k^j$}
				\STATE{$B(i_4:i_2,i_1:i_2) = B(i_4:i_2,i_1:i_2)\hat{Z}_k^j$}
			\ENDFOR
		\ENDFOR
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}
   \caption[Application stage of stage 2]{Application phase of stage two}
	\label{alg:stage2application}
	\begin{algorithmic}[1]
		\REQUIRE $n \times n$ pencil $(A,B)$ in r-Hessenberg-triangular form, where $A$ is in Hessenberg form in columns $1:j_1-1$.
		\STATE{$n_{blocks} = 1 + \lfloor \frac{n-j_1-2}{r} \rfloor$}
		\FOR{$k = n_{blocks}-1:-1:0$}
			\STATE{$i_5 = j_1+1+\max(0,(k-q+2)r)$}
			\FOR{$j = j_1+1:j_1+q-1$}
				\STATE{$i_1 = j+kr+1$}
				\STATE{$i_2 = \min(j + (k+1)r,n)$}
				\STATE{$i_4 = j_1+\max(0,(k+j-j_1-q+2)r)$}
				\STATE{$A(i_5:i_4,i_1:i_2) = A(i_5:i_4,i_1:i_2)\hat{Z}_k^j$}
				\STATE{$B(i_5:i_4,i_1:i_2) = B(i_5:i_4,i_1:i_2)\hat{Z}_k^j$}
			\ENDFOR
			\STATE{$\hat{Z}_k = \hat{Z}_k^{j_1}\hat{Z}_k^{j_2} \dots \hat{Z}_k^{j_1+q-1} $}\COMMENT{Form compact WY}
			\STATE{$i_1 = j_1+kr+1$}
			\STATE{$i_2 = \min(j_1+q-1+(k+1)r,n)$}
			\STATE{$i_5 = j_1+\max(0,(k-q+2)r)$}
			\STATE{$A(1:i_5,i_1:i_2) = A(1:i_5,i_1:i_2)\hat{Z}_k$}
			\STATE{$B(1:i_5,i_1:i_2) = B(1:i_5,i_1:i_2)\hat{Z}_k$}
			\STATE{$Z(:,i_1:i_2) = Z(:,i_1:i_2)\hat{Z}_k$}
		\ENDFOR
		\FOR{$k = n_{blocks}-1:-1:0$}
			\STATE{$\hat{Q}_k = \hat{Q}_k^{j_1}\hat{Q}_k^{j_2} \dots \hat{Q}_k^{j_1+q-1} $}\COMMENT{Form compact WY}
			\STATE{$i_1 = j_1+kr+1$}
			\STATE{$i_2 = \min(j_1+q-1+(k+1)r,n)$}
			\STATE{$i_5 = j_1+q-1 + \max(0,(k-1)r + 1) $}
			\STATE{$i_6 = j_1+q+(k+1)r-1 $}
			\STATE{$A(i_1:i_2,i_5:n) = \hat{Q}_k^*A(i_1:i_2,i_5:n)$}
			\STATE{$B(i_1:i_2,i_6:n) = \hat{Q}_k^*B(i_1:i_2,i_6:n)$}
			\STATE{$Q(:,i_1:i_2) = Q(:,i_1:i_2)\hat{Q}_k$}
		\ENDFOR
	\end{algorithmic}
\end{algorithm}
\end{document}

