\begin{algorithm}[t]
\caption{Recursive Jacobi for the Symmetric Eigenproblem}
\label{alg:Jacobi3} \begin{algorithmic}[1] \Require $\M{A} \in {\mathbb R}^{n \times n}$ is symmetric and partitioned as follows for log block size $0 < f < 1$:
\[
\Mb{A}{IJ}=\Me{A}{(I{-}1)b{+}1:Ib,(J{-}1)b{+}1:Jb} \; \; \; \; \text{for} \; \; \; \; b = n^f, \;  1 \leq I,J \leq n^{1-f}.
\]
\Ensure On output, $\M{A}$ is an (approximately) diagonal matrix $\M{D}$ containing the eigenvalues of $\M{A}$. If eigenvectors are requested, the additional output $\M{Q}$ is an orthogonal matrix of (approximate) eigenvectors satisfying $\M{A} = \M{Q}\M{D}\M{Q}^{T}$. 
\algrule
\Function{$[\M{Q},\M{A}]=$ Recursive\_Jacobi}{$\M{A}$,$f$}
\State
If eigenvectors are requested, $\M{Q}=\M{I}$ \If{$n$ is small enough (less than $n_{\text{threshold}}$) or $2b \geq n$}
\State Solve directly: $\M{A}=\M{Q}\M{D}\M{Q}^{T}$; $\M{A} = \M{D}$ \Comment{Base case}
\Else \Repeat \For{all off-diagonal blocks $(I,J)$ of $\M{A}$, $I<J$, in some order,} \State $\M{\hat{A}}=\M{A}([I,J],[I,J])$ \Comment{$\M{\hat{A}}=$ the $2b \times 2b$ submatrix of
$\M{A}$ in block rows/columns $I$ and $J$} \If{$\M{\hat{A}}$
is far enough from diagonal} \State $[\M{\hat{Q}},\M{\hat{A}}]=$
\textsc{Recursive}\_\textsc{Jacobi}($\M{\hat{A}}$,$f$) 
\State $\M{\hat{Q}}_1 = \M{\hat{Q}}(1:b,1:2b)$
\State $[\M{P},\sim,\sim] =$ \textsc{Recursive}\_LUPP$(\M{\hat{Q}}_1^T)$
\rlap{\smash{$\left.\begin{array}{@{}c@{}}\\{}\\{}\end{array}\color{black}\right\}%
          \color{black}\begin{tabular}{l}Optional\end{tabular}$}}
\State $\M{\hat{Q}} = \M{\hat{Q}}\M{P}^T$
 \State Multiply block rows $I$ and $J$ of $\M{A}$ by $\M{\hat{Q}}^{T}$
\State Multiply block columns $I$ and $J$ of $\M{A}$ by $\M{\hat{Q}}$
\State Multiply block columns $I$ and $J$ of $\M{Q}$ by $\M{\hat{Q}}$
\EndIf \EndFor \Until{all off-diagonal entries of $\M{A}$ are
small enough} \EndIf \EndFunction \end{algorithmic}
\end{algorithm}

\indent Once again, LUPP is included in Algorithm~\ref{alg:Jacobi3} to guarantee convergence. This can be shown easily by bootstrapping the proof of convergence in the blocked case (see Proposition~\ref{prop:recursive_convergence}). Note that the practical considerations from the previous section again apply here:\ failure cases are rare, so LUPP should realistically be employed only when $\Xi(\M{A})$ fails to decrease sufficiently. 

\begin{prop}\label{prop:recursive_convergence} 
    If each sweep of Algorithm ~\ref{alg:Jacobi3} works through off-diagonal blocks according to the column-cyclic ordering \eqref{eqn: column_cyclic} and executes the optional pivoting step (lines 11-13), 
    then it converges for any symmetric input matrix $\M{A} \in {\mathbb R}^{n \times n}$. 
\end{prop}
\begin{proof}
    Let $k$ be the number of recursive steps performed by Algorithm~\ref{alg:Jacobi3}. We prove convergence for any value of $k$ inductively. The base case $k = 1$ corresponds to standard blocked Jacobi from Section~\ref{section: block}, and follows from \cite[Theorem 2.7]{Drmac2009} and Lemma~\ref{lemma: singular_value_bound}. Suppose now $k > 1$. At the highest level, Algorithm~\ref{alg:Jacobi3} calls itself on $2b \times 2b$ submatrices $\M{\hat{A}}$. By our induction hypothesis we can assume that each of these calls is successful and in particular that $\Xi(\M{\hat{A}})$ is reduced by a multiplicative factor $0 < \rho < 1$. Since Drmač's proof of convergence in the blocked case requires only this characterization of approximate diagonalization, we can simply repeat his argument to obtain $\Xi(\M{A}) \rightarrow 0$, where executing lines 11-13 at the highest level ensures convergence via Lemma~\ref{lemma: singular_value_bound}.
\end{proof} \\


