\indent We now present complexity bounds for Algorithm~\ref{alg:Jacobi3}, which -- as in the previous section ---apply whether or not the optional calls to (fast) LUPP are made. This result should be parsed carefully, as its conditions highlight some of the subtleties of constructing a recursive algorithm. First, we note that the log block size $f$ cannot be chosen completely arbitrarily; if it is too close to one, the blocking parameter $b$ may be too large, prompting the algorithm to repeatedly call itself on the input matrix $\M{A}$. Going further, even if the problem size shrinks initially it may stagnate before reaching the threshold for direct diagonalization. The second condition of Theorem~\ref{Thm:complexity_recursive_Jacobi} ensures that neither of these problematic cases occurs. %Hereafter, for the complexity analysis, we assume that the loop in lines~6-19 of Algorithm \ref{alg:Jacobi3} is executed at most $O(1)$ times, which is evidenced by empirical results in Section \ref{section: numerical_ex}. %To build further intuition, Figure~\ref{fig:recursive_structure} depicts the changing block structure for $n = 64$ and $f = 0.8$.

\begin{theorem}\label{Thm:complexity_recursive_Jacobi} 
Let $F(n)$ and $W(n)$ denote, respectively, the arithmetic and (sequential) communication complexities of Algorithm~\ref{alg:Jacobi3} under the following conditions:
\begin{enumerate}
    \item $O(n^{\omega_0})$ matrix multiplication is used.
    \item $0 < f < 1$ and $n_{\text{\normalfont threshold}}$ are constants satisfying $(1-f)^{-1} < \log_2(n_{\text{\normalfont threshold}})$ and $n_{\text{\normalfont threshold}} \leq \sqrt{M/2}$ for $M$ the size of available fast memory.
    \item The loop in lines~6-19 is executed at most $O(1)$ times.
\end{enumerate} 
Then $F(n)=O\left( n^{3(1-f)+\omega_{0}f}\right)$ and $W(n) = O\left( \frac{n^{3(1-f)+\omega_0f}}{M^{\omega_0/2 - 1}} \right)$.
\end{theorem}

% while the term $-\log f \approx 1-f$ in the denominator gets smaller.

\begin{proof}
We start with computational complexity, noting the following for one sweep of Algorithm ~\ref{alg:Jacobi3}:
\begin{enumerate}
\item Line~10 costs $F(2b)=F(2n^{f})$ flops by the inductive definition of $F$. 
\item Recalling the discussion in Section~\ref{section: block}, lines 11-13 require $O((2b)^{\omega_0}) = O(n^{\omega_0f})$ flops.
\item If we implement line 14 by doing $\left\lceil \frac{n}{2b}\right\rceil $ $2b \times 2b$ matrix multiplications, it will cost 
\begin{equation}\label{eqn: cost_of_block_mult}
    O\left(\left\lceil \frac{n}{2b}\right\rceil \cdot(2b)^{\omega_{0}}\right)=O\left(n^{1-f+\omega_{0}f}\right)
\end{equation}
flops. We can do the same in lines~15 and 16.
%\item The loop in lines~7-18 is executed $O\left(\left\lceil \frac{n}{b}\right\rceil ^{2}\right)=O\left(n^{2-2f}\right)$
%times, as we need up to $\left\lceil \frac{n}{b}\right\rceil ^{2}$
%blocks to cover $\M{A}$. 
\item In total, lines~11-16 contribute $O\left(n^{3(1-f)+\omega_{0}f}\right)$ flops, as there are $O\left(\left\lceil \frac{n}{b}\right\rceil ^{2}\right) = O(n^{2-2f})$ blocks to iterate through, each of which requires $O\left(\left\lceil \frac{n}{b}\right\rceil \cdot(2b)^{\omega_{0}} + (2b)^{\omega_0}\right)$ operations. Hence the total cost is
\begin{equation}\label{eqn: total_non_recursive_flops}
    O\left(\left\lceil \frac{n}{b}\right\rceil ^{2}\right)\cdot O\left(\left\lceil \frac{n}{2b}\right\rceil \cdot(2b)^{\omega_{0}} + (2b)^{\omega_0}\right)=O\left(n^{3(1-f)+\omega_{0}f}\right).
\end{equation}
\item Combining the preceding items, the total arithmetic cost for each sweep (i.e., lines~6-19) is 
\begin{equation}\label{eqn:Jacobi1}
F(n)=O(n^{3(1-f)+\omega_{0}f})+O(n^{2-2f})F(2n^{f}).
\end{equation}
\item Since $0<f<1$ and $2 < \omega_0 \leq 3$, the exponent of the first term in \eqref{eqn:Jacobi1} satisfies
\begin{equation}\label{eqn: exponent_range}
    \omega_{0}=\omega_{0}(1-f)+\omega_{0}f < 3(1-f)+\omega_{0}f \leq 3.
\end{equation}
To approach $O(\omega_{0})$ we therefore want $f \rightarrow 1$. At the same time $f$ cannot be so close to one that $2n^f$ is actually larger than $n$. In particular we need $n^{1-f} > 2$, which is implied by $(1-f)^{-1} < \log_2(n_{\text{threshold}})$ since $n_{\text{threshold}}\ll n$.
\end{enumerate}

We now sum \eqref{eqn:Jacobi1} recursively. Moving one level deeper yields
\begin{equation}\label{eqn: sum_recursively_one}
    \aligned
    F(n) &= O(n^{3(1-f)+\omega_0f}) + O(n^{2-2f})\left[O((2n^f)^{3(1-f)+\omega_0f)})+O((2n^f)^{2-2f})F(2(2n^f)^f) \right] \\
    & = O(n^{3(1-f)+\omega_0f}) + O(2^{3(1-f)+\omega_0f}n^{2+f-(3-\omega_0)f^2}) + O(2^{2-2f}n^{2-2f^2})F(2^{1+f}n^{f^2}).
    \endaligned
\end{equation}
Going an additional $k$ steps down, and letting $\alpha_f = 3(1-f)+\omega_0f$ and $S_k = \sum_{i=1}^k f^i$ for convenience, we have 
\begin{equation}\label{eqn: sum_recursively_two}
    \aligned
    F(n) = O(n^{\alpha_f}) &+ \sum_{j=0}^k O(2^{2j + \alpha_f + (1-(3-\omega_0)f)S_j} n^{2+f^{j+1}-(3-\omega_0)f^{j+2}}) \\
     &+ O(2^{2(k+1)-2 S_{k+1}} n^{2-2f^{k+2}})F(2^{1+S_{k+1}}n^{f^{k+2}}).
    \endaligned
\end{equation}
Each term in this sum represents the number of flops required to handle block multiplications on problems of size $2^{1+S_j}n^{f^{j+1}}$.
%\hl{I think we need monotonicity of F below...}
Note that $k = 0$ recovers \eqref{eqn: sum_recursively_one}. \\
\indent To simplify this expression, we note that 
\begin{equation}\label{eqn: ratio_of_n_terms}
    2+f^{j+2} - (3-\omega_0)f^{j+3} = [2+f^{j+1} - (3-\omega_0)f^{j+2}] - [f^{j+1}(1-f)(1-(3-\omega_0)f)]
\end{equation}
where $f^{j+1}(1-f)(1-(3-\omega_0)f) > 0$ since $0 < f < 1$. In other words, the powers of $n$ in the sum of \eqref{eqn: sum_recursively_two} are decreasing in $j$. At the same time, treating $f$ as a constant so that $2^{S_j} = O(1)$, the corresponding powers of two satisfy
\begin{equation}\label{eqn: bound_powers_of_two}
    2^{2j+\alpha_f+(1-(3-\omega_0)f)S_j}  = O(4^j).
\end{equation}
Together, these observations allow us to bound \eqref{eqn: sum_recursively_two} as
\begin{equation}\label{eqn: improve_bound}
    \aligned
    F(n) &= O(n^{\alpha_f}) + \sum_{j=0}^kO(4^jn^{2+f-(3-\omega_0)f^2}) + O(2^{2(k+1)-2 S_{k+1}} n^{2-2f^{k+2}})F(2^{1+S_{k+1}}n^{f^{k+2}}) \\
    & = O(n^{\alpha_f}) + O(4^kn^{2+f-(3-\omega_0)f^2}) + O(2^{2(k+1)-2S_{k+1}}n^{2-2f^{k+2}})F(2^{1+S_{k+1}}n^{f^{k+2}}).
    \endaligned 
\end{equation}
Assuming that Algorithm~\ref{alg:Jacobi3} defaults to direct diagonalization after $k+1$ recursive steps, equivalently that $2^{1+S_{k+1}}n^{f^{k+2}} \leq n_{\text{threshold}}$, we have 
\begin{equation}\label{eqn: base_case_comp}
    F(2^{1+S_{k+1}}n^{f^{k+2}}) \lesssim O(n_{\text{threshold}}^3) = O(1)
\end{equation}
which implies a final, non-recursive bound
\begin{equation}\label{eqn: improve_bound3}
    \aligned
    F(n) &= O(n^{\alpha_f}) + O(4^kn^{2+f-(3-\omega_0)f^2}) + O(2^{2(k+1)-2S_{k+1}}n^{2-2f^{k+2}}) \\
    & = O(n^{\alpha_f}) + O(4^kn^{2+f-(3-\omega_0)f^2}).
    \endaligned
\end{equation}
\indent One question remains:\ how large must $k$ be to guarantee $2^{1+S_{k+1}} n^{f^{k+2}} \leq n_{\text{threshold}}$? We note the following:
\begin{equation}\label{eqn: bound_k}
    \aligned
    \hspace{1mm} 2^{1+S_{k+1}}n^{f^{k+2}} \leq n_{\text{threshold}} &\iff \sum_{i=0}^{k+1}f^i + \log_2(n) f^{k+2} \leq \log_2(n_{\text{threshold}}) \\
    & \iff \frac{1-f^{k+2}}{1-f} + \log_2(n)f^{k+2} \leq \log_2(n_{\text{threshold}}) \\
    & \iff f^{k+2} \left[ (1-f)\log_2(n) - 1\right] \leq (1-f)\log_2(n_{\text{threshold}})-1.
    \endaligned
\end{equation}
Since our restriction on $f$ and $n_{\text{threshold}}$ ensures that both $(1-f)\log_2(n)-1$ and $(1-f)\log_2(n_{\text{threshold}})-1$ are positive, \eqref{eqn: bound_k} is equivalent to 
\begin{equation}\label{eqn: bound_k_2}
    f^{k+2} \leq \frac{(1-f)\log_2(n_{\text{threshold}}) - 1}{(1-f)\log_2(n) - 1}.
\end{equation}
Hence, it is sufficient to take
\begin{equation}\label{eqn: bound_k_3}
    k \geq \frac{\log_2((1-f)\log_2(n)-1) - \log_2((1-f)\log_2(n_{\text{threshold}})-1)}{\log_2(1/f)} - 2,
\end{equation}
meaning we can assume $k$ is at most $\frac{\log_2((1-f)\log_2(n))}{\log_2(1/f)}$ plus a constant. We can now bound $4^k$ asymptotically as
\begin{equation}\label{eqn: bound_4k}
    4^k \lesssim  \left(2^{\log_2((1-f)\log_2(n))}\right)^{2/\log_2(1/f)} = \left[(1-f)\log_2(n)\right]^{2/\log_2(1/f)}.
\end{equation}
In other words, $4^k$ is at most polylogarithmic in $n$. Since $n^{2+f-(3-\omega_0)f^2}$ is a (constant) power of $n$ smaller than $n^{\alpha_f}$, specifically
\begin{equation}\label{eqn: power_rations}
    \frac{n^{2+f-(3-\omega_0)f^2}}{n^{\alpha_f}} = n^{-(1-f)(1-(3-\omega_0)f)}
\end{equation}
this suffices to show that $O(4^k n^{2+f-(3-\omega_0)f^2})$ is dominated by $O(n^{\alpha_f})$ as $n \rightarrow \infty$. \\
\indent Since both Strassen-like matrix multiplication and fast, recursive LUPP (as formulated in Algorithm ~\ref{alg:LUPP}) attain communication lower bounds for their respective operations, extending this analysis to $W(n)$ is straightforward. In particular, the communication cost associated with a single $2b \times 2b$ matrix multiplication or a call to Algrotihm~\ref{alg:LUPP} is $\Theta(\frac{b^{\omega_0}}{M^{\omega_0/2 - 1}}) = \Theta(\frac{n^{f\omega_0}}{M^{\omega_0/2 - 1}})$ (see \cite{BDHS12-FastLA} for the details). This implies a communication analog of \eqref{eqn:Jacobi1}:
\begin{equation}\label{eqn: recursive_comm}
    W(n) = O \left( \frac{n^{3(1-f)+\omega_0f}}{M^{\omega_0/2-1}} \right) + O(n^{2-2f})W(2n^f).
\end{equation}
We can now simply repeat the argument given above, noting that the base case can be handled entirely in fast memory since $n_{\text{threshold}} \leq \sqrt{M/2}$. 
\end{proof} \\

\indent In essence, Theorem~\ref{Thm:complexity_recursive_Jacobi} implies that Algorithm~\ref{alg:Jacobi3} can reach near-optimal complexity, both in terms of arithmetic and sequential communication costs. It should be noted that the constants suppressed in these bounds are dependent on both $f$ and the fast matrix multiplication routine used. In particular, note that to apply \eqref{eqn: bound_powers_of_two} we absorbed a constant with exponential dependence on $(1-f)^{-1}$. In this sense, the algorithm is ``galactic."

\begin{remark}
    \normalfont{Note that if QRCP replaces LUPP in Algorithm~\ref{alg:Jacobi3} then lines~11-13 require $O((2b)^3) = O(n^{3f})$ flops and \eqref{eqn: total_non_recursive_flops} becomes $O(n^{3(1-f)+\omega_0f} + n^{2+f})$, which grows to $O(n^3)$ as $f \rightarrow 1$. In this way, QRCP prevents recursive Jacobi from reaching optimal complexity. Indeed, like the non-recursive blocked algorithm, $n^{3(1-f)+\omega_0 f} + n^{2+f}$ is always at least $n^{2.5}$.}
\end{remark} 

\subsection{Variations and Potential Accelerations}
\indent The relegation to near-optimal complexity in Theorem~\ref{Thm:complexity_recursive_Jacobi} is a consequence of the condition $(1-f)^{-1} < \log_2(n_{\text{threshold}})$, which places a restriction on how far we can reduce $3(1-f)+\omega_0f$. When $n_{\text{threshold}}$ is relatively small, which recall depends on the available fast memory $M$, this may be fairly limiting. In practice, it can be relaxed by allowing $f$ to vary through the recursion -- for example by taking a sequence of log block sizes $f_1 \geq f_2 \geq \cdots $, where at recursive step $i$ (with $i=1$ corresponding to the highest level) the algorithm works with $f_i$ but passes $f_{i+1}$ in its recursive calls. Setting $f_i = f$ for all $i$ recovers Algorithm~\ref{alg:Jacobi3}.\\
\indent Repeating the analysis above, and reusing the notation $\alpha_f = 3(1-f)+\omega_0f$, we can easily compute the arithmetic complexity $F(n)$ for such a formulation of recursive Jacobi:
\begin{equation}\label{eqn: varying_f_recursive}
    \aligned
    F(n) &= O(n^{3(1-f_1)+\omega_0f_1})+O(n^{2-2f_1})F(2n^{f_1}) \\
    & = O(n^{\alpha_{f_1}}) + O(2^{3(1-f_2)+\omega_0f_2}n^{2+f_1-(3-\omega_0)f_1f_2})+ O(2^{2-2f_2}n^{2-2f_1f_2})F(2^{1+f_2}n^{f_1f_2}) \\
    & = O(n^{\alpha_{f_1}}) + \sum_{j=0}^k O(2^{2j+\alpha_{f_{j+2}}+(1-(3-\omega_0)f_{j+2})S_{j+1}'} \cdot n^{2+\prod_{i=1}^{j+1}f_i - (3-\omega_0) \prod_{i=1}^{j+2}f_i}) \\
    & \; \; \; \; \; \; \; \; \; \; \; \; \; \;  \; \; \; + O(2^{2(k+1)-2S_{k+2}'} \cdot n^{2 - 2\prod_{i=1}^{k+2}f_i})F(2^{1+S_{k+2}'} \cdot n^{\prod_{i=1}^{k+2} f_i}).
    \endaligned
\end{equation}
Here, $S'_i = \sum_{j=0}^{i-2} \prod_{l=1}^{i-j} f_l$ with $S_1' = 0$ (to be compared with $S_i$ from \eqref{eqn: sum_recursively_two}). Since we can again bound the powers of two in this sum by $O(4^j)$,\footnote{Note in particular that $S_i' \leq -1 + \sum_{j=0}^{i-1} f_1^j \leq -1+\frac{1}{1-f_1}$ for all $i >1$ since the $f_i$'s are decreasing.} the same argument used to prove Theorem~\ref{Thm:complexity_recursive_Jacobi} will go through here, and imply $F(n) = O(n^{3(1-f_1)+\omega_0f_1})$, provided the following hold:
\begin{enumerate}
    \item The powers of $n$ in the sum \eqref{eqn: varying_f_recursive} are decreasing in $j$.
    \item We reach $n_{\text{threshold}}$ after roughly $O(\log(\log(n))$ recursive steps.
\end{enumerate}
Item one is guaranteed provided
\begin{equation}\label{eqn: varyingf_conditon1}
    f_{i+1} > 1 - \frac{1-f_i}{(3-\omega_0)f_i},
\end{equation}
equivalently as long as the log block size does not shrink too aggressively. The latter, meanwhile, can be accomplished by fixing $f_i$ after a constant number of recursive steps. If, for example, $f_i = f$ for $i \geq p$ and $(1-f)^{-1}<\log_2(n_{\text{threshold}})$, the same argument made in the proof of Theorem~\ref{Thm:complexity_recursive_Jacobi} will imply $2^{1+S_{k+2}'} \cdot n^{\prod_{i=1}^{k+2}}f_i \leq n_{\text{threshold}}$ for $k-p \lesssim \log_2(\log_2(n))$ if $n$ is sufficiently large -- that is, large enough for the problem size to have decreased through the first $p-1$ recursive steps. \\
\indent This is of course the same restriction as in Theorem~\ref{Thm:complexity_recursive_Jacobi}, only now it applies a few steps into the recursion instead of immediately. While this will propagate to a lower bound on $1-f_1$ via \eqref{eqn: varyingf_conditon1}, we can simply increase $p$ to compensate (the tradeoff being an even larger constant hidden by the big-O). As in the proof of Theorem~\ref{Thm:complexity_recursive_Jacobi}, we can repeat this argument with \eqref{eqn: recursive_comm} to similarly remove the restriction on $f$ from the communication bound. \\
% {
%\input{Wn_varyf_computation}} \\
