\begin{prop}\label{prop: communication_Jacobi_SVD_2}
    Let $W(m,n)$ denote the sequential communication complexity of Algorithm~\ref{alg:Jacobi_SVD} with $b = 1$. Assume that the loop in lines 3-15 is executed at most $O(1)$ times. If $M$ is the size of available fast memory and $\sqrt{M}\leq m < M$, 
    %\jwd{I presume we also need $\sqrt{M} \leq m$
    %here, as in Thm 1. Do we also need $\sqrt{M} \leq n$?}
    then $W(m,n) = \Omega(m^2n^2/M)$. This lower bound is attainable.
\end{prop}
\begin{proof}
    This follows from the same argument used to prove Theorem~\ref{thm: classical_lower_bound}. In this case, reading in $\Theta(M/m)$ columns of $\M{G}$ allows us to work through an $\Theta(M/m) \times \Theta(M/m)$ block of $\M{G}^T \M{G}$. We can do at most $\Theta(M^2/m)$ flops on this data -- i.e., $\Theta(m)$ flops for each of the $\Theta(M^2/m^2)$ currently available off-diagonal entries of $\M{G}^T\M{G}$. Since Proposition~\ref{prop: arithmetic_Jacobi_SVD} implies that a total of $O(mn^2)$ flops are required by Algorithm~\ref{alg:Jacobi_SVD} with $b = 1$, we conclude that $\Omega(mn^2/(M^2/m)) = \Omega(m^2n^2/M^2)$ references are required. Since each of these references corresponds to $M$ reads and writes, we conclude $W(m,n) = \Omega(m^2n^2/M)$.
\end{proof} 

% \input{prop4_generic_b}

\begin{prop}\label{prop: communication_Jacobi_SVD}
    Let $W(m,n)$ denote the sequential communication complexity of Algorithm~\ref{alg:Jacobi_SVD} under the following conditions:
    \begin{enumerate}
        \item $O(n^{\omega_0})$ matrix multiplication is used.
        \item $b = O(\sqrt{M})$ is chosen so that lines 7-10 can take place entirely in fast memory, which has size $M$.
        \item The loop in lines~3-15 is executed at most $O(1)$ times. 
    \end{enumerate}
    Then $W(m,n) = O(mn^2/b)$, and in particular $W(m,n) = O(mn^2/\sqrt{M})$ for $b = \Theta(\sqrt{M})$.
\end{prop}
\begin{proof}
    For each $I < J$, forming $\M{\hat{A}}$ in line 5 requires $\Theta(mb^{\omega_0-1})$ flops. If we do this by allocating $\M{\hat{A}}$ and updating it by (1) reading in each $2b \times 2b$ block of $\M{G}(:,[I,J])$ and (2) adding to $\M{\hat{A}}$ the product of the block and its transpose, we can execute line 5 with computational intensity $(2b)^{\omega_0}/(2b)^2 = (2b)^{\omega_0-2}$. Hence, the communication required to obtain $\M{\hat{A}}$ is $O(mb^{\omega_0-1}/b^{\omega_0-2}) = O(mb)$. In each sweep of Algorithm~\ref{alg:Jacobi_SVD}, the cumulative communication attributable to line 5 is therefore $O(\lceil \frac{n}{b} \rceil^2 mb) = O(mn^2/b)$. Since the communication cost of lines 11 and 12 is the same as line 5, and moreover since the diagonalization/optional pivoting in lines 7-10 can be done entirely in fast memory, we conclude $W(m,n) = O(mn^2/b)$
\end{proof} 

\begin{prop}\label{prop: communication_Jacobi_SVD_3}
Let $W(m,n)$ denote the sequential communication complexity of Algorithm~\ref{alg:Jacobi_SVD} under the following conditions:
\begin{enumerate}
    \item $O(n^{\omega_0})$ matrix multiplication is used.
    \item $b > \sqrt{M}/2$ for $M$ the size of available fast memory.
    \item The method used to diagonalize $\M{\hat{A}}$ in line~7 has communication cost $U(n)$ when applied to an $n \times n$ symmetric matrix. 
    \item The loop in lines 3-15 is executed at most $O(1)$ times.
\end{enumerate}
Then  $W(m,n) = O\left(\frac{mn^2b^{\omega_0-3}}{M^{\omega_0/2-1}} + \lceil \frac{n}{b} \rceil^2U(2b)\right)$.    
\end{prop}
\begin{proof}
    As in the proof of Theorem~\ref{Thm:complexity_recursive_Jacobi} we apply the communication bounds from \cite{BDHS12-FastLA}, noting that, for $b > \sqrt{M}/2$, neither $2b \times 2b$ matrix multiplication nor the diagonalization in line 7 can take place in fast memory. For each pair $I < J$ in the main loop of Algorithm~\ref{alg:Jacobi_SVD} we have the following communication costs:
    \begin{itemize}
        \item Line~5 (done as $\lceil \frac{m}{2b} \rceil$ square $2b \times 2b$ multiplications): $O( \frac{mb^{\omega_0-1}}{M^{\omega_0/2 - 1}})$
        \item Line~7: $U(2b)$
        \item Lines~9-10: $O(\frac{b^{\omega_0}}{M^{\omega_0/2 - 1}})$
        \item Lines~11-12 (again done in $2b \times 2b$ pieces): $O(\frac{mb^{\omega_0-1}}{M^{\omega_0/2 -1}})$.
    \end{itemize}
    Hence, each sweep of one-sided Jacobi has communication complexity
    \begin{equation}\label{eqn: one_sweep_comm}
        O\left(\left\lceil \frac{n}{b}\right\rceil^2 \left( \frac{mb^{\omega_0-1}}{M^{\omega_0/2 -1}} + U(2b)\right) \right) = O\left( \frac{mn^2b^{\omega_0-3}}{M^{\omega_0/2 - 1}} + \left\lceil \frac{n}{b} \right\rceil^2 U(2b)\right).
    \end{equation}
    Since only $O(1)$ sweeps are executed, and moreover since the communication associated with lines 16 and 17 is negligible compared to \eqref{eqn: one_sweep_comm}, we conclude that this is a bound for $W(m,n)$.
\end{proof} \\

\indent Note that the bound in Proposition~\ref{prop: communication_Jacobi_SVD_2} is smaller than that of Proposition~\ref{prop: communication_Jacobi_SVD} only when $m < \sqrt{M}$, in which case no communication is required since $\M{G}$ fits in fast memory (recalling our assumption that $m \geq n$). Like standard Jacobi, Proposition~\ref{prop: communication_Jacobi_SVD_3} implies that Algorithm~\ref{alg:Jacobi_SVD} can reach (nearly) optimal complexity by allowing the block size $b$ to grow with $n$, though this requires that the diagonalization in line~7 be done optimally itself (e.g., via recursive Jacobi).


