    \State $\M{L} = \M{A}/\M{A}(1)$; $\M{U} = \M{A}(1)$
\Else
    \State $[\M{L}_L, \M{U}_L, \M{P}_L] =$ \textsc{Recursive}\_LUPP($\M{A}(\; : \;  , 1:\lfloor \frac{n}{2} \rfloor$)) \Comment{Apply LUPP to left half of $\M{A}$}
    \State $\M{P} = \M{P}_L \M{P}$
    \setstretch{1.2}
    \State $\M{A}(\; : \; , \lfloor \frac{n}{2} \rfloor + 1:n) = \M{P}_L^T \M{A}(\; : \; ,\lfloor \frac{n}{2} \rfloor + 1:n)$ \Comment{Update right side of $\M{A}$}
    \State $\M{A}(1:\lfloor \frac{n}{2} \rfloor, \lfloor \frac{n}{2} \rfloor + 1 : n) = \M{L}_L(1:\lfloor \frac{n}{2} \rfloor, \; : \;)^{-1}\M{A}(1:\lfloor \frac{n}{2} \rfloor, \lfloor \frac{n}{2} \rfloor + 1 : n)$
    \State $\M{A}(\lfloor \frac{n}{2} \rfloor + 1 : m, \lfloor \frac{n}{2} \rfloor + 1: n) \mathrel{{-}{=}} \M{L}_L(\lfloor \frac{n}{2} \rfloor +1:m, \; : \; ) \M{A}(1:\lfloor \frac{n}{2} \rfloor,\lfloor \frac{n}{2} \rfloor + 1:n)$ 
    \State $[\M{L}_R, \M{U}_R, \M{P}_R] =$ \textsc{Recursive}\_LUPP($\M{A}(\lfloor \frac{n}{2} \rfloor + 1: m, \lfloor \frac{n}{2} \rfloor + 1 
    : n)$) \Comment{Factor lower right block}
    \State $\M{P}(\lfloor \frac{n}{2} \rfloor + 1 : m, \; : \; ) = \M{P}_R \M{P}(\lfloor \frac{n}{2} \rfloor + 1 : m, \; : \; )$ \vskip 3pt
    \State $\M{L} = \begin{bmatrix} \M{L}_L(1:\lfloor \frac{n}{2} \rfloor, \; : \;) & 0 \\
    \M{P}_R \M{L}_L(\lfloor \frac{n}{2} \rfloor +1 : m, \; : \;) & \M{L}_R \end{bmatrix}; \; \; \M{U} = \begin{bmatrix} \M{U}_L & \M{A}(1:\lfloor \frac{n}{2} \rfloor, \lfloor \frac{n}{2} \rfloor + 1: n) \\
    0 & \M{U}_R \end{bmatrix} $ \Comment{Assemble}

\EndIf
\EndFunction \end{algorithmic}
\end{algorithm}

%\indent It is easy to verify that Algorithm~\ref{alg:LUPP} produces a lower trapezoidal/triangular matrix whose sub-diagonal entries are bounded by one in magnitude. This can be seen inductively from Line~17, as multiplying the lower block of $\M{L}_L$ by $\M{P}_R$ simply permutes its rows. Note also that this version of LUPP requires inverting a triangular matrix at each step (Line~13). While triangular inversion can be done in $O(n^{\omega_0})$ operations, such fast algorithms are only \textit{logarithmically stable} in general \cite[Section 3.1]{demmel2007fast}. Hence, the stability of (one step of) fast LUPP is dependent on the condition number of $\M{L}_L(1 : \lfloor \frac{n}{2} \rfloor, \; : \;)$. We showed in the proof of Lemma~\ref{lemma: singular_value_bound} that we can always bound this condition number, though the quality of the bound -- in particular its exponential dependence on the size of the matrix -- may not provide much reassurance. \\
%\indent In practice, we have good reason to expect that this condition number is actually quite manageable. Trefethen and Schreiber present qualitative evidence of this phenomenon in \cite{Trefethen_Schreiber}. If $\M{L}$ is the lower triangular/trapezoidal factor obtained from LUPP, their observations can be summarized as follows:\ while $||\M{L}^{-1}||_2$ can be large for particular input matrices, it is modest ``on average." This not only implies that Algorithm \ref{alg:LUPP} is likely to be stable but also that the Lemma~\ref{lemma: singular_value_bound} is extremely pessimistic. \\

\noindent \textbf{Restatement of Lemma~\ref{lemma: singular_value_bound}}
 \textit{Let $\M{Q} \in {\mathbb R}^{2b \times 2b}$ be an orthogonal matrix with leading rows $\M{Q}_1 \in {\mathbb R}^{b \times 2b}$. Suppose that $\M{Q}_1^T = \M{P}^T\M{L}\M{U}$ is a PLU decomposition computed with partial pivoting. If $\widetilde{\M{Q}}_{11}$ is the upper left $b \times b$ block of $\M{Q}\M{P}^T$ then
     $$ \sigma_{\min}(\widetilde{\M{Q}}_{11}) \geq 6 (3b^2 + b)^{-1} (4^b + 6b - 1)^{-1/2}. $$} 
\begin{proof} Let $\M{L} = \begin{pmatrix} \M{L}_1 \\ \M{L}_2 \end{pmatrix}$ for $\M{L}_1 \in {\mathbb R}^{b \times b}$ unit lower triangular (i.e., diagonal entries are all one). In this case $\widetilde{\M{Q}}_{11} = \M{U}^T \M{L}_1^T$ and therefore
\begin{equation}\label{eqn: sv_inequality}
    \sigma_{\min}(\widetilde{\M{Q}}_{11}) \geq \sigma_{\min}(\M{U}) \sigma_{\min}(\M{L}_1).
\end{equation}
Since the columns of $\M{Q}_1^T$ are orthonormal, the decomposition $\M{Q}_1^T = \M{P}^T\M{L}\M{U}$ implies $\M{U}^{-1} = \M{Q}_1\M{P}^T\M{L}$. Hence,
\begin{equation}\label{eqn: bound_Ui}
    ||\M{U}^{-1}||_2 = ||\M{Q}_1\M{P}^T\M{L}||_2 \leq ||\M{L}||_2
\end{equation}
and \eqref{eqn: sv_inequality} becomes 
\begin{equation}
    \sigma_{\min}(\widetilde{\M{Q}}_{11}) \geq \frac{\sigma_{\min}(\M{L}_1)}{||\M{L}||_2}.
\end{equation}
We now bound each of $||\M{L}_1^{-1}||_2$ and $||\M{L}||_2$ using our guarantee from partial pivoting -- i.e., $|\M{L}_{ij}| \leq 1$ for $i > j$. The latter is straightforward:\ $\M{L}$  has at most $\frac{1}{2}(3b^2 + b)$ nonzero entries, each bounded by one in modulus, so
\begin{equation}\label{eqn: bound_L}
    ||\M{L}||_2 \leq ||\M{L}||_F \leq \frac{1}{2}(3b^2 + b).
\end{equation}
Consider next $\M{T} = \M{L}_1^{-1}$. Fixing an index $j$, the nonzero entries in the $j$-th column of $\M{T}$ can be written recursively as
\begin{equation}\label{eqn: recursive_T}
    \M{T}_{ij} = \begin{cases}
   \M{L}_{jj}^{-1} & i = j \\
    - \M{L}_{ii}^{-1} \sum_{k=j}^{i-1} \M{L}_{ik}\M{T}_{kj} & i > j.
    \end{cases}
\end{equation}
Since $|\M{L}_{ik}| \leq 1 = |\M{L}_{ii}|$ for all $k < i$, we have
\begin{equation}\label{eqn: entry_norm_bound}
    |\M{T}_{ij}| \leq \sum_{k=j}^{i-1} \frac{|\M{L}_{ik}|}{|\M{L}_{ii}|} |\M{T}_{kj}|  \leq \sum_{k=j}^{i-1} |\M{T}_{kj}|, \; \; \; i > j, 
\end{equation}
which by induction guarantees $|\M{T}_{ij}| \leq 2^{i-j-1}$ when $i > j$ and therefore
\begin{equation}\label{eqn: norm_via_frob}
    ||\M{T}||_2 \leq ||\M{T}||_F \leq \frac{1}{3} \left(4^b + 6b - 1\right)^{1/2}.
\end{equation}
For the details, see \cite[Chapter 6]{Solving_LS}. Together, \eqref{eqn: norm_via_frob} and \eqref{eqn: bound_L} yield the final bound on $\sigma_{\min}(\widetilde{\M{Q}}_{11})$.
\end{proof} 

