				child{node[] (v11) {$\fmpproj{\sys{a}{b}}{2}{1}$}
					child{node[] (v21) {$(0 \leq 2)\land (0 \leq 2)$}}
					child{node[] (v22) {$(0 \leq 4) \land (0 \leq -2)$}}
				}
