An important observation is that we can decide independently for each node of the search tree which variable to eliminate next and whether to branch on lower or on upper bounds.
This freedom of choice is formalized in the following definition.

\begin{defi}[Branch Choices]
	The set of \emph{branch choices} for a system $\sys{a}{b}$ is
	\begin{align*}
		\textit{branch\_choices}(\sys{a}{b})\ =&\ \ \{\; (x_j, I^{*}_j(A)) \mid * \in \{-,+\} \;\wedge\; j \in [n]\;\wedge\; \lbs{a}{j} \neq \emptyset \neq  \ubs{a}{j}\;\} \\
		&\ \cup\ \{\; (x_j, \{\bot\}) \mid j \in [n]\;\wedge\; (\lbs{a}{j} = \emptyset \vee \ubs{a}{j} = \emptyset) \;\}.
	\end{align*}
\end{defi}

For an initial input $\widehat{\matr{a}}\vect{x} \leq \widehat{\vect{b}}$ with $\widehat{m}$ rows, we define the depth-first search using the recursive method $\texttt{FMplex}(\widehat{\matr{a}}\vect{x} \leq \widehat{\vect{b}};\sys{a}{b},\matr{f})$ in \Cref{algo:base} where $\sys{a}{b}$ is the currently processed sub-problem in the recursion tree. The original system $\widehat{\matr{a}}\vect{x} \leq \widehat{\vect{b}}$ with $\widehat{m}$ is not used in the algorithm itself, but included for illustrational purposes.
We track the relation of $\sys{a}{b}$ to $\widehat{\matr{a}}\vect{x} \leq \widehat{\vect{b}}$ in terms of linear combinations using the parameter $\matr{f}$.
The initial call is defined as $\texttt{FMplex}(\widehat{\matr{a}}\vect{x} \leq \widehat{\vect{b}}) = \texttt{FMplex}(\widehat{\matr{a}}\vect{x} \leq \widehat{\vect{b}};\widehat{\matr{a}}\vect{x} \leq \widehat{\vect{b}},\matr{e})$.
We allow that $\sys{a}{b}$ contains identical rows when they are obtained in different ways (which is reflected by $\matr{f}$).
We need to keep these duplicates for proving the results of this section.

\begin{algorithm}[b]%
	\linespread{1.25}\selectfont
    \caption{$\texttt{FMplex}(\widehat{\matr{a}}\vect{x} \leq \widehat{\vect{b}};\sys{a}{b},\matr{f})$}\label{algo:base}
	\SetKwInOut{Data}{Data}
    \SetKwInOut{Input}{Input}
    \SetKwInOut{Output}{Output}
    \DontPrintSemicolon
    \SetKwFunction{FCheck}{FMplex}
    \SetKwProg{Fn}{Function}{:}{}
	\Data{$\widehat{\matr{a}} \in \rationals^{\widehat{m} \times n},\ \widehat{\vect{b}}\in \rationals^{\widehat{m}}$}
    \Input{$\matr{a} \in \rationals^{m \times n},\ \vect{b}\in \rationals^{m}$, $\matr{f} \in \rationals^{m \times \widehat{m}}$ s.t. $\matr{f}\widehat{\matr{a}} = \matr{a}$ and $\matr{f}\widehat{\vect{b}} = \vect{b}$}
    \Output{(\sat, $\alpha$) with $\alpha \models \matr{a}\vect{x} \leq \vect{b}$, or (\unsat, $K$) where the rows $K \subseteq [\widehat{m}]$ of $\widehat{\matr{a}}\vect{x} \leq \widehat{\vect{b}}$ build a minimal unsatisfiable subset of constraints $\{ \vect{\widehat{a}_{k,-}} \vect{x} \leq \widehat{b_k} \mid k \in K \}$, or
	\partialunsat\\\hspace*{-4em}\hrulefill}
	\lIf{$\matr{a} = 0 \land \vect{b} \geq 0$} {
		\Return{$($\sat, $\alpha: \emptyset \to \reals)$\tcp*[f]{trivial sat}} 
	}
    \If(\tcp*[f]{global conflict}){$\exists i \in [m].\; \rvect{a}{i} = 0 \land b_i < 0 \land \rvect{f}{i} \geq 0$}{
            \Return{$(\unsat, \{ i' \mid f_{i,i'} \neq 0 \})$} 
    }
	\textbf{choose} $(x_j,V) \in \textit{branch\_choices}(\matr{a}\vect{x} \leq \vect{b})$\;
    \ForEach{$i \in V$}{
		\textbf{compute} $\matr{a'}\vect{x} \leq \vect{b'} := \fmpproj{\matr{a}\vect{x} \leq \vect{b}}{j}{i}$ with projection matrix $\matr{f'}$ \;
        \Switch{\FCheck($\sys{\widehat{a}}{\widehat{b}};\matr{a'}\vect{x} \leq \vect{b'},\matr{f'}\cdot\matr{f}$)}{
			\lCase{$(\unsat, K)$}{\Return{$(\unsat, K)$}}
        	\lCase{$(\sat, \alpha)$}{\Return{$(\sat, \alpha[x_j \mapsto r])$} for a suitable $r \in \rationals$, e.g. $r = \bnd{j}{\vect{a_{i,-}}\vect{x}\leq b_i}$}
			\lCase{\partialunsat}{\textbf{continue}}
    	}
    }
	\Return{\partialunsat}
\end{algorithm}

\paragraph{Solutions} If a trivially satisfiable node is found, the algorithm constructs an assignment starting with the empty assignment and extending it with values for all eliminated variables in reverse elimination order. 
For every variable $x_j$, the assignment $\alpha$ is extended by assigning to $x_j$ a value that us not below any lower bound and not above any upper bound on $x_j$, when the bounds are evaluated under $\alpha$.
By the semantics of the projection, the value of the designated (largest lower or smallest upper) bound on $x_j$ is suitable.

\paragraph{Conflicts} We distinguish inconsistencies in $\sys{a}{b}$ by the following notions: 
We call a row $i$ of $\sys{a}{b}$ a \emph{conflict} if it is of the form $\rvect{a}{i} = \vect{0}$ with $b_i < 0$.
We call the conflict \emph{global} if $\rvect{f}{i} \geq 0$  and \emph{local} otherwise.
In case of a global conflict, Farkas' Lemma allows to deduce the unsatisfiability of $\sys{\widehat{a}}{\widehat{b}}$, thus stopping the search before the whole search tree is generated.
Then a set of conflicting rows $K$ of the input system corresponding to $\rvect{f}{i}$ is returned.
In particular, the set $\{\rvect{\widehat{a}}{j}\; \vect{x} \leq \widehat{b}_j \mid f_{i,j} \neq 0\}$ is a minimal unsatisfiable subset of the constraints in $\sys{\widehat{a}}{\widehat{b}}$.
In case of a local conflict, the current node is unsatisfiable, but we need to continue the search in the other branches.
The algorithm returns $\partialunsat$ to indicate that $\sys{a}{b}$ is unsatisfiable, but the unsatisfiability of $\sys{\widehat{a}}{\widehat{b}}$ cannot be derived.
This approach, formalized in \Cref{algo:base}, guarantees that the initial call will never return $\partialunsat$; we always find either a global conflict or a solution.

\vspace{0.75em}
\noindent The correctness and completeness of \texttt{FMplex} follows from \Cref{thm:correctness-elim} and \Cref{thm:global-conflict}.
As an immediate consequence of \Cref{thm:correctness-elim}, \texttt{FMplex} returns \sat~ if and only if the input is satisfiable.
On the other hand, if the input is unsatisfiable, then the initial call to \Cref{algo:base} will always return \unsat~ and never \partialunsat, as is shown in \Cref{thm:global-conflict}.

\begin{thm} \label{thm:global-conflict}
	Let $\matr{\widehat{a}} \in \rationals^{\widehat{m} \times n}$, and $\vect{\widehat{b}} \in \rationals^{\widehat{m}\times 1}$.
	Then $\sys{\widehat{a}}{\widehat{b}}$ is unsatisfiable if and only if the call $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}})$ to \Cref{algo:base} terminates with a global conflict.
\end{thm}
\begin{proof}
	We show the two directions of the equivalence separately:

\vspace{0.5em}
\noindent$\Leftarrow$:\quad Assume the call $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\matr{{a}}\vect{x} \leq \vect{{b}},F)$ in the recursion tree returns \unsat, i.e. $\sys{a}{b}$ contains a global conflict in some row $i$.
Then $\rvect{a}{i} = \rvect{f}{i} \matr{\widehat{a}} = 0$, $b_i = \rvect{f}{i} \cdot \vect{\widehat{b}} < 0$ and $\rvect{f}{i} \geq 0$, thus Farkas' Lemma (\Cref{thm:farkas}) implies that $\sys{\widehat{a}}{\widehat{b}}$ is unsatisfiable.

\vspace{0.5em}
\noindent$\Rightarrow$:\quad Assume $\sys{\widehat{a}}{\widehat{b}}$ is unsatisfiable.
Then there is a minimal subset $\widehat{K} \subseteq [\widehat{m}]$ with size $|\widehat{K}| \leq n + 1$ such that the corresponding rows $\{ \vect{\widehat{a}_{i,-}} \vect{x} \leq \widehat{b}_i \mid i \in \widehat{K} \}$ are together unsatisfiable.
We show that the algorithm will eventually construct a conflict from such a minimal unsatisfiable subset.
Then, we prove that this will be a global conflict, which will prompt the algorithm to return \unsat.

Let $(x_j,V) \in \textit{branch\_choices}(\sys{\widehat{a}}{\widehat{b}})$ and $i^*\in V$.
If $\widehat{K}\subseteq\nbs{\widehat{a}}{j}$, then each of the rows in $\widehat{K}$ are contained also in $\fmpproj{\sys{\widehat{a}}{\widehat{b}}}{j}{i^*}$.
Note that since $|\widehat{K}|>0$, this case cannot always apply until termination (except for the degenerate case where a row contains only zeros).

Otherwise, both $\lbs{\widehat{a}}{j} \cap \widehat{K} \neq \emptyset$ and $\ubs{\widehat{a}}{j} \cap \widehat{K}  \neq \emptyset$ must hold due to the minimality of $\widehat{K}$ (if only one intersection was non-empty, we could remove it from $\widehat{K}$ to still obtain an infeasible subset). Thus, at some point the algorithm will choose  $i^*=i$ for some $i \in \widehat{K}$.

Let $(\sys{a}{b})=\fmpproj{\sys{\widehat{a}}{\widehat{b}}}{j}{i}$ be the resulting partial projection.
Since $\sys{\widehat{a}}{\widehat{b}}$ is unsatisfiable, also $\sys{a}{b}$ is unsatisfiable by \Cref{lma:restricted-projection}.
With the same reasoning, $\matr{a'}\vect{x}\leq\vect{b'} := \fmpproj{\subsys{\widehat{a}}{\widehat{b}}{\widehat{K}}}{j}{i}$ is unsatisfiable.
We observe that all rows of $\sys{a'}{b'}$ are contained in $\sys{a}{b}$, thus there exists a minimal set $K$ of rows of $\sys{a}{b}$ that are also contained in $\sys{a'}{b'}$ such that the corresponding rows are a minimal unsatisfiable subset.
In particular, we have $0<\abs{K} < |\widehat{K}|$, because $\sys{a'}{b'}$ has less than $|\widehat{K}|$ rows.

We can repeat this reasoning for the successive elimination of all variables to obtain a system $\sys{a}{b}$ where the corresponding minimal unsatisfiable set has size $1$.
By construction, there exists a matrix $\matr{f}$ such that $\matr{a}=\matr{f}\matr{\widehat{a}}$ and $\vect{b}=\matr{f}\vect{\widehat{b}}$.
This means that there is a conflicting row $i$ in $\sys{a}{b}$ which is a linear combination of rows from $\subsys{\widehat{a}}{\widehat{b}}{\widehat{K}}$.

It remains to show that  $\rvect{f}{i} \geq 0$.
By construction, $f_{i,i} > 0$ holds, and for all $i' \in [m] \setminus \widehat{K}$ holds $f_{i,i'} = 0$.
Towards a contradiction, assume that there was some $i' \in \widehat{K}$ with $f_{i,i'} < 0$.
Since $\widehat{K}$ induces a minimal unsatisfiable subset, by Farkas' Lemma there is some other vector $\vect{f'} \in \rationals^{m\times 1}$ with $\vect{f'} \geq 0$ such that $(f'_i \neq 0 \Leftrightarrow i \in \widehat{K})$, $\vect{f'}\matr{\widehat{a}} = 0$ and $\vect{f'}\vect{\widehat{b}} < 0$.
Now let 
\[\lambda := \max\{\frac{-f_{i,j}}{f'_j}\mid f_{i,j} < 0\}\qquad \text{ and }\qquad \vect{g} := \rvect{f}{i} + \lambda \vect{f'}.\]
We get $\vect{g} \matr{\widehat{a}} = 0$ and $\vect{g}\vect{\widehat{b}} < 0$ because $\lambda > 0$.
But now, $\vect{g} \geq 0$, $g_{i'} = 0$ for all $i' \in [\widehat{m}] \setminus \widehat{K}$ and $g_{i'} = 0$ for some $i' \in \widehat{K}$, which implies that $\widehat{K}$ does not induce a minimal unsatisfiable subset.
As this is a contradiction, $\rvect{f}{i} \geq 0$ must already hold.
\end{proof}

In the next two subsections, we look at ways to prune the recursion tree, eventually leading to \Cref{algo:combined}. Additionally, the first improvement is based on insights that reveal a connection to the simplex method.

\subsection{Avoiding Redundant Checks}\label{subsec:avoiding-redundancies}

We observe that each row in a sub-problem $\sys{a}{b}$ in the recursion tree of $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}})$ corresponds to a unique row $\hat{\imath}$ in $\sys{\widehat{a}}{\widehat{b}}$ in the sense that it is a linear combination of the rows $\{ \hat{\imath} \} \cup \mathcal{N}$ of $\sys{\widehat{a}}{\widehat{b}}$, where $\mathcal{N} \subseteq [\widehat{m}]$ corresponds to the lower/upper bounds designated as largest/smallest one to compute $\sys{a}{b}$.

The intuition is simple for a single elimination: for a restricted projection $\fmpproj{\sys{\widehat{a}}{\widehat{b}}}{j}{i}$, we have $\mathcal{N} = \{i\}$ containing only the designated bound.
Each row $\fmpproj{\sys{\widehat{a}}{\widehat{b}}}{j}{i}$ is a linear combination of the row $i$ and a unique row different from $i$.
This gives a one-to-one correspondence, which we can use to identify the next row that is added to $\mathcal{N}$ in the subsequent elimination.

\begin{thm} \label{thm:basis-nonbasis-correspondence}
	Let $\matr{\widehat{a}} \in \rationals^{\widehat{m} \times n}$ and $\vect{\widehat{b}} \in \rationals^{\widehat{m}\times 1}$.
	Let $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\matr{{a}}\vect{x} \leq \vect{{b}},\matr{f})$ be a call in the recursion tree of the call $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}})$ to \Cref{algo:base}, where $\matr{A}\in \rationals^{m\times n}$ and $\vect{b} \in \rationals^{m\times 1}$ (by construction $m\leq \widehat{m}$).

	Then there exist a set $\mathcal{N} \subseteq [\widehat{m}]$ and an injective mapping $\mathcal{B}: [m] \to [\widehat{m}]$ such that
	\begin{enumerate}
		\item $\sys{a}{b}$ is satisfiable if and only if $(\sys{\widehat{a}}{\widehat{b}}) \wedge (\submatr{\widehat{a}}{\mathcal{N}}\vect{x} = \subvect{\widehat{b}}{\mathcal{N}})$ is satisfiable,
		\item For each $i \in [m]$ holds $\{ \mathcal{B}(i) \} = \{ i' \in [\hat{m}] \mid f_{i,i'} \neq 0 \} \setminus \mathcal{N}$.
	\end{enumerate}
\end{thm}
\begin{proof}
	By assumption, there exists a sequence of calls of the form $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\_,\_)$ starting from $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\sys{\widehat{a}}{\widehat{b}},\matr{e})$ and ending in $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\matr{{a}}\vect{x} \leq \vect{{b}},\matr{f})$ such that each of these calls is called by its predecessor in the sequence.
	We prove the property by induction over this sequence.

	In the base case $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\sys{\widehat{a}}{\widehat{b}},\matr{e})$, we choose $\mathcal{N} = \emptyset$ and $\mathcal{B}$ as the identity.
  Then both properties are trivially fulfilled.

	Now assume $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\matr{{a'}}\vect{x} \leq \vect{{b'}},\matr{f'})$ for which an $\mathcal{N}'$ and $\mathcal{B}'$ fulfilling the desired properties exist, and let $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\matr{{a}}\vect{x} \leq \vect{{b}},\matr{f})$ be the succeeding call in the sequence.
	If $\matr{{a}}\vect{x} \leq \vect{{b}} = \fmpproj{\matr{a'}\vect{x} \leq \vect{b'}}{j}{\bot}$, then we simply choose $\mathcal{N} = \mathcal{N}'$ and $\mathcal{B}=\mathcal{B}'$.
	The first property holds by \Cref{lma:restricted-projection}, the second property is trivial.

	Otherwise, $(\matr{{a}}\vect{x} \leq \vect{{b}}) = \fmpproj{\matr{a'}\vect{x} \leq \vect{b'}}{j}{i}$ for some row $i$.
	We choose $\mathcal{N} := \mathcal{N}' \cup \{ \mathcal{B}'(i) \}$ and for every row $i'$ of $\matr{{a}}\vect{x} \leq \vect{{b}}$, we choose $\mathcal{B}(i'):=\mathcal{B}'(k)$ for the unique $k$ such that the row $i'$ of $\matr{{a}}\vect{x} \leq \vect{{b}}$ is the linear combination of the rows $i$ and $k$ of $\matr{{a'}}\vect{x} \leq \vect{{b'}}$ (according to the restricted projection).
	The second property obviously holds.
	We prove the first property:
	\begin{align*}
		\matr{{a}}\vect{x} \leq \vect{{b}} \text{ satisfiable} & \iff (\matr{{a'}}\vect{x} \leq \vect{{b'}}) \wedge (\rvect{a'}{i}\;\vect{x} = b'_i) \text{ satisfiable} \\
		& \iff (\sys{\widehat{a}}{\widehat{b}}) \wedge (\submatr{\widehat{a}}{\mathcal{N}'} \vect{x} = \subvect{\widehat{b}}{\mathcal{N}'}) \wedge (\rvect{a'}{i}\;\vect{x} = b'_i)   \text{ satisfiable} \\
		& \iff (\sys{\widehat{a}}{\widehat{b}}) \wedge (\submatr{\widehat{a}}{\mathcal{N}'} \vect{x} = \subvect{\widehat{b}}{\mathcal{N}'}) \wedge (\vect{\widehat{a}}_{\mathcal{B}'(i),-}\vect{x} = \widehat{b}_{\mathcal{B}'(i)})  \text{ satisfiable} \\
		& \iff (\sys{\widehat{a}}{\widehat{b}}) \wedge (\submatr{\widehat{a}}{\mathcal{N}} \vect{x} = \subvect{\widehat{b}}{\mathcal{N}})  \text{ satisfiable}
	\end{align*}

	\noindent The first equivalence holds due to \Cref{lma:restricted-projection}, the second due to the induction hypothesis.
\end{proof}

We call the above defined set $\mathcal{N}$ the \emph{non-basis}, inspired from the analogies to the simplex algorithm (discussed in \Cref{sec:simplex}).
By the above theorem, the order in which a non-basis is constructed has no influence on the satisfiability of the induced sub-problem.
In particular:

\begin{thm} \label{thm:redundancies}
	Let $\matr{a} \in \rationals^{m \times n}$, $\vect{b} \in \rationals^{m\times 1}$, $j \in [n]$, and let $i,i' \in [m]$ with $a_{i,j} \neq 0$ and $a_{i',j} \neq 0$.
	If $\fmpproj{\matr{a}\vect{x} \leq \vect{b}}{j}{i}$ is unsatisfiable, then $\fmpproj{\matr{a}\vect{x} \leq \vect{b}}{j}{i'} \wedge  (\rvect{a}{i}\;\vect{x} = b_i) $ is unsatisfiable.
\end{thm}
\begin{proof}
	By \Cref{thm:basis-nonbasis-correspondence}, if $\fmpproj{\matr{a}\vect{x} \leq \vect{b}}{j}{i}$ is unsatisfiable, then $(\matr{a}\vect{x} \leq \vect{b}) \wedge  (\rvect{a}{i}\vect{x} = b_i)$ is unsatisfiable, and trivially $(\matr{a}\vect{x} \leq \vect{b}) \wedge  (\rvect{a}{i}\vect{x} = b_i) \wedge (\rvect{a}{i'}\vect{x} = b_{i'})$ is unsatisfiable as well.
	Using \Cref{thm:basis-nonbasis-correspondence} in the other direction yields that $(\matr{a}\vect{x} \leq \vect{b}) \wedge (\rvect{a}{i'}\vect{x} = b_{i'})$ is equivalent to $\fmpproj{\matr{a}\vect{x} \leq \vect{b}}{j}{i'}$; thus $\fmpproj{\matr{a}\vect{x} \leq \vect{b}}{j}{i'} \wedge (\rvect{a}{i}\vect{x} = b_i )$ is unsatisfiable.
\end{proof}

Accordingly, if we know that a non-basis $\mathcal{N}$ induces an unsatisfiable sub-problem, then we also know that all supersets of $\mathcal{N}$ will do so.
We apply this insight to our algorithm:
Assume a call $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\sys{a}{b},\matr{f})$, with corresponding $\mathcal{N}$ and $\mathcal{B}$, has a child call for row $i$ which returns $\unsat$ or $\partialunsat$.
Then every call in the recursion tree of $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\sys{a}{b},\matr{f})$ whose corresponding non-basis contains $\mathcal{B}(i)$ will also return $\unsat$ or $\partialunsat$.
Hence, after we checked the child call for row $i$, we can ignore $\mathcal{B}(i)$ as designated bound in the remaining recursion tree of $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\sys{a}{b},\matr{f})$.

\begin{exa}\label{example:nonbasis}
	Consider the system from \Cref{example:fmplex-idea}, extended by $c_5 : (-x_2 \leq 0)$, depicted in the top left of the \Cref{fig:nonbasis} below. That figure also shows a (partial) trace of our algorithm.
	In front of each row is indicated how it was constructed from the original constraints; $\mathcal{B}$ would give the row corresponding to this combination's first term.
	Note that we omit the eliminated variables and corresponding zero-columns.

	\begin{figure}[h]
		\begin{tikzpicture}
			\node[draw, align=center] (root) at (0,0) {
				Input\\
				$
				\begin{blockarray}{ccc}
					\begin{block}{c[cc]}
						c_1 &  -1 & -1 \bigstrut[t] \\
						c_2 &   0 &  -2 \\
						c_3 &  -2 &  1 \\
						c_4 &   0 &  1 \\
						c_5 &   0 &  -1 \bigstrut[b]\\
					\end{block}
				\end{blockarray}
				\cdot
				\left[ {\begin{array}{cc}
					x_1 \\ x_2
				\end{array} } \right] 
				\leq
