We update the $\texttt{FMplex}$ algorithm as shown in \refalgobounds using the following definition:

\begin{defi}
	The set of \emph{branch choices} for $\sys{a}{b}$ with $m$ rows w.r.t. $I \subseteq [m]$ is
	\begin{align*}
		\textit{branch\_choices}(\sys{a}{b}, I) := \{(x_j, V\setminus I) \mid (x_j, V) \in \textit{branch\_choices}(\sys{a}{b})\}.
	\end{align*}
\end{defi}

\noindent This modification clearly prevents visiting the same non-basis twice in the following sense:

\begin{thm}
	Let $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\matr{a}\vect{x} \leq \vect{b},\_,\mathcal{N},\_)$ and $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\matr{a'}\vect{x} \leq \vect{b'},\_,\mathcal{N}',\_)$ be two calls in the recursion tree of a call to \refalgobounds\!\!.
	Then either $\mathcal{N} \neq \mathcal{N'}$ or one of the systems occurs in the subtree below the other and only unbounded variables are eliminated between them (i.e. one results from the other by deleting some rows).\qed
\end{thm}

\Cref{thm:unique-base-termination} states that, still, every initial call to \refalgobounds terminates with $\sat$ or a global conflict.
This follows by a slight modification of the proof of \Cref{thm:global-conflict}.

\begin{thm}\label{thm:unique-base-termination}
	Let $\matr{\widehat{a}} \in \rationals^{\widehat{m} \times n}$, and $\vect{\widehat{b}} \in \rationals^{\widehat{m}\times 1}$.
	Then $\sys{\widehat{a}}{\widehat{b}}$ is unsatisfiable if and only if the call $\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}})$ to \refalgobounds terminates with a global conflict.
\end{thm}
\begin{proof}
	Consider the proof of \Cref{thm:global-conflict} again: We showed that there exists a path in the recursion tree leading to a global conflict.
	We now show that we can still construct such a path.
	We first fix the earliest path in the recursion tree that leads \Cref{algo:base} to a global conflict, which does exist according to \Cref{thm:global-conflict}; let $\widehat{K} \subseteq [\widehat{m}]$ be the corresponding subset inducing the minimal unsatisfiable subset.
	Along this path, all but one element of $\widehat{K}$ are chosen into the non-basis, as can be deduced from the proof of \Cref{thm:global-conflict}.
	Without loss of generality, we can assume that this path does not insert anything else into the non-basis (otherwise, it would not be the earliest global conflict, or there would be variables not occurring in the conflict, whose elimination is irrelevant).

	We now execute \refalgobounds on the same input.
	Towards a contradiction, we assume that there is a state on the given path where the choice to the next element is forbidden in \refalgobounds\!\!, that is, an element $k \in \widehat{K}$ is ignored ($k \in I$).
	This is only possible if there has been an earlier call in the execution trace of \refalgobounds where $k$ was added to the non-basis, this call returned $\partialunsat$, and its parent call is on the given path (otherwise, $k$ would already have been removed from the set of ignored rows). 
	But then, still only elements from $\widehat{K}$ were in the non-basis of that call.
	But this means, there would be a earlier path that leads to the same global conflict $\widehat{K}$, which is a contradiction to the above assumption.
\end{proof}

\begin{algorithm}[p]%
	\linespread{1.2}\selectfont
	\caption{$\texttt{FMplex}(\sys{\widehat{a}}{\widehat{b}};\sys{a}{b},\matr{f},$\chng{$\mathcal{N},\mathcal{B},I$}$,$\chngd{$\texttt{lvl},\texttt{bt\_lvl}$}$)$}\label{algo:combined}

	  \begin{description}
		\item[Algorithm 2a] \label{algo:combined-base} The base method consists of the plain parts (as in \Cref{algo:base}).
		\item[Algorithm 2b] \label{algo:leaving-out-bounds} Consists of the base method and the \chng{framed parts}.
		\item[Algorithm 2c] \label{algo:backtracking} Consists of the base method, the \chng{framed} and the \chngd{filled} parts.
	\end{description}
	\hrulefill\\
	\SetKwInOut{Data}{Data}
	\SetKwInOut{Input}{Input}
	\SetKwInOut{Output}{Output}
	\DontPrintSemicolon
	\SetKwFunction{FCheck}{FMplex}
	\SetKwProg{Fn}{Function}{:}{}
	\Data{$\matr{\widehat{a}} \in \rationals^{\widehat{m} \times n},\ \vect{\widehat{b}}\in \rationals^{\widehat{m}}$}
	\Input{$\matr{a} \in \rationals^{m \times n},\ \vect{b}\in \rationals^{m}$, $\matr{f} \in \rationals^{m \times \widehat{m}}$ s.t. $\matr{f}\matr{\widehat{a}} = \matr{a}$ and $\matr{f}\vect{\widehat{b}} = \vect{b}$, \chng{$\mathcal{N}\subseteq [\widehat{m}]$, $\mathcal{B}\colon [m] \rightarrow [\widehat{m}]$, $I\subseteq [\widehat{m}]$}, \chngd{$\texttt{lvl} \in [n] \cup \{ 0 \}$, $\texttt{bt\_lvl}\colon [m] \to [n] \cup \{ 0 \}$}}
	\Output{(\sat, $\alpha$) with $\alpha \models \matr{a}\vect{x} \leq \vect{b}$, or (\unsat, $K$) where $K \subseteq [\widehat{m}]$, or\\
	(\partialunsat, \chngd{$l, K$}) \chngd{where $l \in [n]$ and $K \subseteq [\widehat{m}]$}\\\hspace*{-4em}\hrulefill}
	\lIf{$\matr{a} = 0 \land \vect{b} \geq 0$} {
		\Return{$($\sat, $())$}\tcp*[f]{trivial sat}
	}
	\If(\tcp*[f]{global conflict}){$\exists i \in [m].\; \rvect{a}{i} = 0 \land b_i < 0 \land \rvect{f}{i} \geq 0$}{
			\Return{$(\unsat, \{ i' \mid f_{i,i'} \neq 0 \})$} 
	} 
	\boxchngd{a}{0.92}
	\boxchngdstart{a}
	\If(\tcp*[f]{local conflict}){$\exists i \in [m].\; \rvect{a}{i} = 0 \land b_i < 0 \land \rvect{f}{i} \ngeq 0$}{
		$i := \arg\min_{i \in [m]}\{ \texttt{bt\_lvl}(i) \mid \rvect{a}{i} = 0 \land b_i < 0 \}$\;
		\Return $(\partialunsat,\texttt{bt\_lvl}(i)-1,\{ i' \mid f_{i,i'} \neq 0 \})$ \;
	}
	\boxchngdend{a}%
	\chngd{$K := \emptyset$} \;
	\textbf{choose} $(x_j,V) \in \textit{branch\_choices}(\matr{a}\vect{x} \leq \vect{b},\chng{$\{ \mathcal{B}^{-1}(i) \mid i \in I \}$})$\;
	\ForEach{$i \in V$}{
		\textbf{compute} $\matr{a'}\vect{x} \leq \vect{b'} := \fmpproj{\matr{a}\vect{x} \leq \vect{b}}{j}{i}$ with projection matrix $\matr{f'}$ \chngd{and backtrack levels $\texttt{bt\_lvl}'$} \;
		\chng{\textbf{compute} $\mathcal{N}'$ := ($\mathcal{N} \cup \{ \mathcal{B}(i) \}$ \textbf{ if }  $i \neq \bot$ \textbf{ else }   $\mathcal{N}$) and $\mathcal{B}'$ from $\mathcal{N}'$ and $F'$}\;
		\Switch{\FCheck$(\sys{\widehat{a}}{\widehat{b}};\matr{a'}\vect{x} \leq \vect{b'},\matr{f'}\matr{f},$\chng{$\mathcal{N}', \mathcal{B}', I$}$,\chngd{$\texttt{\upshape lvl}+1,\texttt{\upshape bt\_lvl}'$})$}{
			\lCase{$(\unsat, K')$}{\Return{$(\unsat, K')$}}
			\lCase{$(\sat, \alpha)$}{\Return{$(\sat, \alpha[x_j \mapsto r])$} for a suitable $r \in \rationals$}
			\boxchngd{b}{0.87}
			\boxchngdstart{b}
			\Case{$(\partialunsat, l, K')$}{
				\lIf{$l<\texttt{\upshape lvl}$}{
					\Return{$(\partialunsat, l, K')$}\tcp*[f]{backtrack} %
				}
				\lElse {
					$K := K \cup K'$ %
				}
			}
		}
		\boxchngdend{b}	\chng{$I$ := $I \cup \{ \mathcal{B}(i) \}$} \;\label{algo:backtracking:ignore}
	}
	\chngd{
	\label{algo:combined:lvl0} \lIf{$\texttt{\upshape lvl}=0$}{
		\Return{$(\unsat, K)$}
	}}\;
	\Return{$(\partialunsat, \chngd{\texttt{\upshape lvl-1}, K})$}

  \end{algorithm}

\subsection{Backtracking of Local Conflicts}

So far, we ignored local conflicts that witness the unsatisfiability of a given sub-problem.
In this section, we will cut off parts of the search tree based on local conflicts and examine the theoretical implications.

We applied Farkas' Lemma on conflicting rows in some sub-problem that are positive linear combinations of rows from the input system.
We can also apply Farkas' Lemma to conflicting rows which are positive linear combinations of some \emph{intermediate} system to conclude the unsatisfiability of the latter.
Whenever such a conflict occurs, we can backtrack to the parent system of that unsatisfiable system.
Instead of tracking the linear combinations of every row in terms of the rows of each preceding intermediate system, we can do an incomplete check: If a conflicting row was computed only by addition operations, then it is a positive linear combination of the involved rows.
Thus, we assign to every intermediate system a level, representing its depth in the search tree and store for every row the level where the last subtraction was applied to the row (i.e. a lower (upper) bound was subtracted from another lower (upper) bound).
If a row is conflicting, we can conclude that the intermediate system at this level is unsatisfiable, thus we can jump back to its parent.

Assume the current system is $\matr{a}\vect{x} \leq \vect{b}$ at level $\texttt{lvl}$ with $m$ rows whose backtracking levels are stored in $\texttt{bt\_lvl}: [m] \to ([n] \cup \{ 0 \})$.
If $\texttt{lvl}=0$, then $\texttt{bt\_lvl}$ maps all values to $0$.
When computing $\fmpproj{\matr{a}\vect{x} \leq \vect{b}}{j}{i}$ for some $x_j$ and $i$ with projection matrix $\matr{f}$, the backtracking levels of the rows in the resulting system $\matr{FA}\vect{x} \leq \matr{F}\vect{b}$ are stored in $\texttt{bt\_lvl}'$ where for each row $i''$
\[\texttt{bt\_lvl}'(i'') := \left.\begin{cases}
	\max\{\texttt{bt\_lvl}(i),\texttt{bt\_lvl}(i')\} & \text{ if } f_{i'',i}, f_{i'',i'} > 0 \text { and } f_{i'',k}=0,\  k \notin \{ i,i' \} \\
	\texttt{lvl} + 1 &  \text{ otherwise}.
\end{cases}\right.\]

The backtracking scheme is given in \refalgobacktracking\!, which returns additional information in the $\partialunsat$ case, that is the backtrack level $l$ of the given conflict, and a (possibly non-minimal) unsatisfiable subset $K$.


\begin{thm}
	Let $\texttt{FMplex}(\_;\matr{a}\vect{x} \leq \vect{b},\_,\_,\_,\texttt{\upshape lvl},\_)$ be a call to \refalgobacktracking\!, and consider a second call $\texttt{FMplex}(\_;\matr{a'}\vect{x} \leq \vect{b'},\_,\_,\_,\_,\texttt{\upshape bt\_lvl}')$ in the recursion tree of the first call.
	If $\matr{a'}\vect{x} \leq \vect{b'}$ has a local conflict in a row $i$ with $\texttt{\upshape bt\_lvl}'(i)=\texttt{\upshape lvl}$, then $\matr{a}\vect{x} \leq \vect{b}$ is unsatisfiable.
\end{thm}
\begin{proof}
	By construction of $\texttt{bt\_lvl}$', $\rvect{a'}{i}\;\vect{x} \leq b'_i$ is a positive sum of rows from $\matr{a}\vect{x} \leq \vect{b}$, i.e. there exists an $\vect{f} \in \rationals^{1\times m}$ such that $(\vect{f} \matr{a} \vect{x} \leq  \vect{f} \vect{b}) = (\rvect{a'}{i}\;\vect{x} \leq b'_i)$.
	Then by Farkas' Lemma, $\matr{a}\vect{x} \leq \vect{b}$ is unsatisfiable.
\end{proof}

While it is complete and correct, \refalgobacktracking does not always terminate with a \emph{global} conflict (i.e. \Cref{thm:global-conflict} does not hold anymore), explaining the need for \Cref{algo:combined:lvl0}:

