%     \end{aligned}
% \end{equation}




Using Equation~\eqref{tiaojian} and $E[D_i] = E[ E[D_i | Z_i] ]$, we have:
\begin{equation}
    E[D_i] = E[ Z_i(1 + \lambda_i Z_i / 2) ] = E[Z_i + \lambda_i Z_i^2 / 2]
\end{equation}

Using the linearity of expectation:
$$E[D_i] = E[Z_i] + \frac{\lambda_i}{2} E[Z_i^2]$$
For $Z_i \sim \text{Exp}(\mu_i)$, we know that $E[Z_i] = 1/\mu_i$ and $Var(Z_i) = 1/\mu_i^2$. Thus, $E[Z_i^2] = Var(Z_i) + (E[Z_i])^2 = 1/\mu_i^2 + (1/\mu_i)^2 = 2/\mu_i^2$.
Substituting these values yields:
\begin{equation}
    E[D_i] = \frac{1}{\mu_i} + \frac{\lambda_i}{2} \left( \frac{2}{\mu_i^2} \right) = \frac{1}{\mu_i} + \frac{\lambda_i}{\mu_i^2} = z_i + \lambda_i{z_i^2}.
\end{equation}

Next, we derive the variance $Var(D_i)$.
By the law of total variance: $$Var(D_i) = E[Var(D_i | Z_i)] + Var(E[D_i | Z_i])$$
We need to compute two terms: $E[Var(D_i | Z_i)]$ and $Var(E[D_i | Z_i])$.

\textit{Computing $Var(D_i | Z_i=z)$:}
Based on Theorem \ref{meanandvar}, we have:
\begin{equation}
    Var(D_i | Z_i=z)=\frac{1}{3} \lambda_i z^3.
\end{equation}

