Therefore,
$E[Var(D_i | Z_i)] = E\left[\frac{1}{3} \lambda_i Z_i^3\right] = \frac{\lambda_i}{3} E[Z_i^3]$.
For $Z_i \sim \text{Exp}(\mu_i)$, $E[Z_i^n] = n! / \mu_i^n$. Thus, $E[Z_i^3] = 3! / \mu_i^3 = 6 / \mu_i^3$.
$$E[Var(D_i | Z_i)] = \frac{\lambda_i}{3} \frac{6}{\mu_i^3} = \frac{2 \lambda_i}{\mu_i^3}$$

\textit{Computing the second term of the law of total variance: $Var(E[D_i | Z_i])$}
From Equation~\eqref{tiaojian}, we know that:
$$Var(E[D_i | Z_i]) = Var(Z_i(1 + \lambda_i Z_i / 2)) = Var(Z_i + \frac{\lambda_i}{2} Z_i^2)$$
Let $Y=E[D_i \mid Z_i]$. Using $Var(Y) = E[Y^2] - (E[Y])^2$, we know from the mean calculation that $E[Y] = E[Z_i + \frac{\lambda_i}{2} Z_i^2] = E[D_i] = \frac{1}{\mu_i} + \frac{\lambda_i}{\mu_i^2}$.
Therefore, we can obtain
% $E[Y^2] = E[(Z_i + \frac{\lambda_i}{2} Z_i^2)^2]
% = E[Z_i^2 + \lambda_i Z_i^3 + \frac{\lambda_i^2}{4} Z_i^4]
% =E[Z_i^2] + \lambda_i E[Z_i^3] + \frac{\lambda_i^2}{4} E[Z_i^4] 
% = \frac{2}{\mu_i^2} + \frac{6\lambda_i}{\mu_i^3} + \frac{6\lambda_i^2}{\mu_i^4}$.


\begin{equation}
    \begin{aligned}
        E[Y^2] &= E[(Z_i + \frac{\lambda_i}{2} Z_i^2)^2]\\
&= E[Z_i^2 + \lambda_i Z_i^3 + \frac{\lambda_i^2}{4} Z_i^4]\\
&=E[Z_i^2] + \lambda_i E[Z_i^3] + \frac{\lambda_i^2}{4} E[Z_i^4] \\ 
&= \frac{2}{\mu_i^2} + \frac{6\lambda_i}{\mu_i^3} + \frac{6\lambda_i^2}{\mu_i^4}.
    \end{aligned}
\end{equation}


Thus, we have,
\begin{equation}
    \begin{aligned}
    Var(E[D_i | Z_i]) &= \left( \frac{2}{\mu_i^2} + \frac{6\lambda_i}{\mu_i^3} + \frac{6\lambda_i^2}{\mu_i^4} \right) - \left( \frac{1}{\mu_i} + \frac{\lambda_i}{\mu_i^2} \right)^2 \\ 
    &= \frac{1}{\mu_i^2} + \frac{4\lambda_i}{\mu_i^3} + \frac{5\lambda_i^2}{\mu_i^4} 
    \end{aligned}
\end{equation}

Now we can compute the total variance $Var(D_i)$,
\begin{equation}
    \begin{aligned}
Var(D_i) &= E[Var(D_i | Z_i)] + Var(E[D_i | Z_i]) \\ &= \frac{2 \lambda_i}{\mu_i^3} + \left( \frac{1}{\mu_i^2} + \frac{4\lambda_i}{\mu_i^3} + \frac{5\lambda_i^2}{\mu_i^4} \right) \\ &= \frac{1}{\mu_i^2} + \frac{6 \lambda_i}{\mu_i^3} + \frac{5 \lambda_i^2}{\mu_i^4} \\
&= {z_i^2} +  6\lambda_iz_i^3+ 5 \lambda_i^2{z_i^4} .
    \end{aligned}
\end{equation}





