\subsubsection{Notation}
$x_t$: state, $\mu_t = \mathbb{E}[x_t]$, $\Sigma_t = \text{Cov}[x_t]$, 
$u_t$: control input, $y_t$: measurement, 
$f(\cdot)$: dynamics, $h(\cdot)$: measurement, 
$Q$, $R$: noise covariances, 
$A_t = \partial f / \partial x$, $H_t = \partial h / \partial x$, 
$\chi^{(i)}$: sigma points, $x_t^{[i]}$: particles, $w^{(i)}$: weights

\subsubsection{Extended Kalman Filter (EKF)} \label{subsub:EKF}

\small{
\begin{equation}
\begin{aligned}
\textit{Prediction:} \quad
& \mu^- = f(\mu, u), \\
& \Sigma^- = A \Sigma A^\top + Q \\
\textit{Update:} \quad
& K = \Sigma^- H^\top (H \Sigma^- H^\top + R)^{-1}, \\
& \mu = \mu^- + K(y - h(\mu^-)), \\
& \Sigma = (I - K H) \Sigma^-
\end{aligned}
\end{equation}
}

\subsubsection{Unscented Kalman Filter (UKF)}
The UKF formulation is shown below:

\small{
\begin{equation}
\begin{aligned}
\textit{Prediction:} \\
\chi^{(i)} &= \text{SigmaPts}(\mu, \Sigma), \quad
\chi^{-(i)} = f(\chi^{(i)}, u) \\
\mu^- &= \sum_i w_m^{(i)} \chi^{-(i)}, \\ 
\Sigma^- &= \sum_i w_c^{(i)} (\chi^{-(i)} - \mu^-)(\cdot)^\top + Q \\
\textit{Update:} \\
\zeta^{(i)} &= h(\chi^{-(i)}), \quad
\hat{y} = \sum_i w_m^{(i)} \zeta^{(i)} \\
K &= \sum_i w_c^{(i)} (\chi^{-(i)} - \mu^-)(\zeta^{(i)} - \hat{y})^\top \\
& \quad \cdot \left[\sum_i w_c^{(i)} (\zeta^{(i)} - \hat{y})(\cdot)^\top + R\right]^{-1} \\
\mu &= \mu^- + K(y - \hat{y}), \quad
\Sigma = \Sigma^- - K(\cdot)K^\top
\end{aligned}
\end{equation}
}

\subsubsection{Particle Filter (PF)}
The PF represents the belief over the state \( x_t \) using a set of \( N\) weighted samples \( \{x_t^{[i]}, w_t^{[i]}\}_{i=1}^N \). It propagates the posterior distribution through a sequence of sampling and resampling steps:

\small{
\begin{equation}
\begin{aligned}
\textit{Prediction:} \quad & x^{[i]} \sim p(x \mid x^{[i]}, u) \\
\textit{Update:} \quad & w^{[i]} \propto p(y \mid x^{[i]}), \quad
w^{[i]} \leftarrow \frac{w^{[i]}}{\sum_j w^{[j]}} \\
\textit{Resample:} \quad & x^{[i]} \sim \text{Resample}(\{x^{[j]}, w^{[j]}\})
\end{aligned}
\end{equation}
}

