\section{Preliminaries}
% \vspace{-0.5em}
We start by preliminaries on finite automata, after which we specify their extension with a single finite domain register we use for representing procedures.
% \vspace{-0.5em}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Finite automata
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\paragraph{Finite Automata.}
A \textit{nondeterministic finite automaton (NFA)} is a 5-tuple $A = (Q, \Sigma, \delta,\break I, F)$, where $Q$ is a~finite nonempty set of \emph{states}, $\Sigma$ is an \emph{input alphabet}, $\delta \subseteq Q \times \Sigma \times Q$ is a set of \emph{transitions} in the form $r \crightarrow{$\{a\}$} s$, where $r \in Q$ is a \emph{source state}, $a \in \Sigma$ is an \emph{input symbol}, and $s \in Q$ is a \emph{target state}, $I \subseteq Q$ is a~nonempty set of \emph{initial states}, and $F \subseteq Q$ is a set of \emph{final states}.
%
A \textit{run} over a word $w = a_1\cdot a_2\cdots a_n \in \Sigma^*$ is a sequence of transitions $\transition{r_0}{a_1}{r_1}, \transition{r_1}{a_2}{r_2}, \cdots, \transition{r_{n-1}}{a_n}{r_n}$, where $\transition{r_i}{a_{i+1}}{r_{i+1}} \in \delta$ for all $0 \leq i < n$. The run is \textit{accepting} if $r_0 \in I$ and $r_n \in F$. The \textit{language} $L(A) \subseteq \Sigma^*$ of $A$ is a set of words for which $A$ has an accepting run.

A \emph{sub-graph} of $A$ induced by a set of states $P\subseteq Q$ is pair $(P,\delta')$ where $\delta'\subseteq \delta$ contains the transitions of $\delta$ with both end-points in $P$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Single-finite-register automata
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% \vspace{-0.75em}
\paragraph{Single-Finite-Register Automata.}
%
A \textit{single-finite-register automaton (SRA)} is a~6-tuple $A = (Q, \Sigma, \Gamma, \delta, I, F)$ such that $(Q, \Sigma \times \Gamma_{\hspace{-0.5ex}\bot, *} \times \Gamma_{\hspace{-0.5ex}\bot,*}, \delta, I, F)$ is an NFA, $\Gamma$ is a finite \emph{register alphabet} and $\Gamma_{\hspace{-0.5ex}\bot,*} = \Gamma \cup \{\bot, *\}$, with $\bot \notin \Gamma$ being a \textit{default register value} and $* \notin \Gamma$ being a \textit{wildcard}.
We denote transitions of the SRA as $r\crightarrow{$\{a,\alpha/\beta\}$}s$, where $a \in \Sigma$ is an \emph{input symbol}, $\alpha \in \Gamma_{\hspace{-0.5ex}\bot,*}$ is a \emph{test symbol}, and $\beta \in \Gamma_{\hspace{-0.5ex}\bot,*}$ a \emph{set symbol}.
%
A~\textit{configuration} of the SRA is a~tuple $(q, \alpha) \in Q \times \Gamma_{\hspace{-0.5ex}\bot}$.
%
The \textit{induced} NFA of $A$ is a 6-tuple $A' = (Q', \Sigma, \delta', I', F')$, where $Q' \subseteq Q \times \Gamma_{\hspace{-0.5ex}\bot}$ are configurations of SRA, $I' \subseteq I \times \{\bot\}$ are initial configurations, $F' \subseteq Q'$ are final configurations, and $\delta' = \{\transition{(r, \alpha)}{a}{(s,\beta)}\,|\, (\transition{r}{a,\alpha,\beta}{s} \in \delta) \lor (\alpha = \beta \land \transition{r}{a,*/*}{s} \in \delta )\}$ represents transitions between SRA's configurations.
%
Intuitively, a~transition $r \crightarrow{$\{a,\alpha/\beta\}$} s$ can be taken if the register value matches the test symbol $\alpha$, in which case the new register value is set to $\beta$. Furthermore, a transition $r \crightarrow{$\{a,*/*\}$} s$ can be taken regardless of the register value, and the register value remains unchanged.
We denote by $\mathit{Reach}(A)$ a set of configurations that can be reached by a run starting from $I'$.
%
The language of SRA $A$ can be defined as the language of the induced NFA, $L(A) = L(A')$.

