%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Constructing a Procedure from Similarity Graph
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Constructing a Procedure from Similarity Graph}
% \vspace{-0.5em}

The automata reduction by procedure finding iterates two steps.
First, it identifies pairs of similar sub-graphs that are to be understood as procedure invocations (e.g., sub-graphs induced by states $q_1, q_3, q_5$ and $q_2, q_4, q_6$ in Figure \ref{fig:aa}a).
%
The search returns a~\emph{similarity graph} that defines a partial isomorphism between the two invocations (e.g., Figure \ref{fig:aa}b).
The two invocations are then replaced by a~single procedure, constructed from the similarity graph (e.g., Figure \ref{fig:aa}c).
We will first concentrate on the creation of a~procedure from a~given similarity graph.

Formally, a \textit{similarity graph} of SRA $A = (Q, \Sigma, \Gamma, \delta, I, F)$ relates two similar disjoint sub-graphs of $A$, that can be then represented as one procedure.
%
It is a directed graph $G = (V, E)$.
%
Its vertices $V \subseteq Q \setminus (I \cup F) \times Q\setminus(I \cup F)$ represent pairs of \textit{similar states}.%
\footnote{For simplicity, we exclude initial and final states from participating in the procedure based reduction. This is without loss of generality since every NFA can be easily transformed to an equivalent one with at most two states in $I\cup F$ (add a new initial state $i$, a final state $f$, and make $i$ also final if $\epsilon\in L(A)$, and every transition to $f$/from $i$ for every original transition to/from a final/an initial state, respectively). The exclusion of the two states is negligible.}
Let $\pi_k$ be a~projection onto the $k$-th element in a set of pairs.
Then $\pi_1(V)$ and $\pi_2(V)$ are states of the \emph{first} and the \emph{second procedure invocation} and
we call the elements of their union $G_Q = \pi_1(V) \cup \pi_2(V)$ jointly the \emph{invocation states}.
The edges $E \subseteq V \times V$ represent pairs of \emph{similar transitions}, namely, an edge $((r_1, r_2), (s_1, s_2))$
indicates the existence of a transition pair
$\transition{r_1}{a,\eta_1/\eta_1}{s_1}$ and
$\transition{r_2}{a,\eta_2/\eta_2}{s_2}$ where $\eta_1, \eta_2 \in \{\bot, *\}$ (note that these transitions do not update the register).
%
We also require that each similarity graph satisfies the following assumptions:

\vspace*{0.25em}
\begin{adjustwidth}{3ex}{}
\begin{enumerate}
    \item[SG1]
    \label{SG:root}
     It must be \emph{rooted}, and we denote by $\mathit{root(G)}$ the root of a graph $G$,
    \item[SG2]
    \label{SG:no_register} each state from one invocation has to have exactly one similar state in the other invocation, i.e., $V$ is a bijection from $\pi_1(V)$ to $\pi_2(V)$,
    \item[SG3] states of each of the two invocations have the same signatures, i.e.,
    for any $r, s \in \pi_i(V),i\in\{1,2\}$, $\mathit{Sig}(r) = \mathit{Sig}(s)$.
    \item[SG4]
    \label{SG:disjoint}
    the signatures of the two invocations are disjoint, that is, for any $r \in \pi_1(V),s\in \pi_2(V)$, $\mathit{Sig}(r) \cap \mathit{Sig}(s) = \emptyset$.
\end{enumerate}
\end{adjustwidth}
%
These assumptions, together with the requirement that similar transitions do not update the register, will allow us to easily show that the introduction of a new procedure preserves the existing ones and does not break the nested structure (Lemma~\ref{lemma:correctness}).

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Procedure Creation
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% \vspace*{-0.5em}
\subsection{Procedure Creation}
% \vspace{-0.5em}
\begin{wrapfigure}{r}{0.59\linewidth}
    \vspace*{-2.55em}
    \begin{algorithm}[H]
        \caption{createProcedure}
        \footnotesize
        \label{alg:mapProcedure}
        \DontPrintSemicolon
        \KwIn{SRA $A = (Q, \Sigma, \Gamma, \delta, q_0, F)$,\\
        \hspace*{\widthof{\KwIn{}}}\mbox{similarity graph of $A$ as $G = (V \subseteq Q \times Q, E)$}}
        \KwOut{SRA $B = (\algout{Q}, \Sigma, \algout{\Gamma}, \algout{\delta}, q_0, F)$}

        \vspace*{0.3em}
        \mbox{$B \gets A, Q_{proc} \gets \emptyset, (r_1, r_2) \gets root(V)$}\;
        \mbox{$\mathit{Id}(r_1) \gets \begin{cases} \{B.\mathit{newIdSymbol}()\} & \text{if } \mathit{Sig}(r_1) = \emptyset\\[-0.85mm] \mathit{Sig}(r_1) & \text{otherwise} \end{cases}$}\;%\vspace*{-1.1em}
        \mbox{$\mathit{Id}(r_2) \gets \begin{cases} \{B.\mathit{newIdSymbol}()\} & \text{if } \mathit{Sig}(r_2) = \emptyset\\[-0.85mm] \mathit{Sig}(r_2) & \text{otherwise} \end{cases}$}\;%\vspace*{-1.1em}
        $\algout{\Gamma} \gets \algout{\Gamma} \cup \mathit{Id}(r_1) \cup \mathit{Id}(r_2)$\;

        \ForAll{$(q_1, q_2) \in V$}
        {
            $q_{1,2} \gets B.\mathit{newState}()$\;
            $Q_{\mathit{proc}}(q_1) \gets q_{1,2}, Q_{\mathit{proc}}(q_2) \gets q_{1,2}$\;
            $\algout{Q} \gets \algout{Q} \cup \{q_{1,2}\}$\;
            $\mathit{Id}(q_1) \gets \mathit{Id}(r_1), \mathit{Id}(q_2) \gets \mathit{Id}(r_2)$\;
        }
        \mbox{$B \gets\mathit{createProcedureTransitions}(B, G, \mathit{Id}, Q_{\mathit{proc}})$}\;\vspace*{-1.1em}
        $B.\mathit{removeIncidentTransitions}(G_Q)$\;
        $B.\mathit{removeStates}(G_Q)$\;
        \Return{$B$}
        \normalsize
    \end{algorithm}
    \vspace*{-3em}
\end{wrapfigure}

In Algorithm \ref{alg:mapProcedure}, the procedure is constructed based on the similarity graph $G$ of the SRA $A$, and a new SRA with this procedure is returned.
%
To differentiate between the two original invocations, the algorithm assigns a unique \textit{invocation Id} to each.
Technically, the invocation Id is assigned to \emph{each state} of the invocation by the function $\mathit{Id} : Q \rightarrow 2^\Gamma$.
%
A new invocation Id is generated if the invocation does not belong to any procedure yet (i.e., if its signature is empty). Otherwise, the invocation reuses the existing signature of a state as its invocation Id. Here we rely on the assumption SG\ref{SG:disjoint} of the invocation signature disjointness that guarantees that the two invocations can indeed be distinguished by their signatures. The union of the two invocation Ids will later become the signature of the new procedure.
In lines \verb|2-3|, the invocation Id is assigned to the root states $r_1$ and $r_2$ of the similarity graph and then, in line \verb|9|, it is propagated to all states of the invocation.
%
In lines \verb|5-8|, the algorithm creates a new \textit{procedure state} $q_{1,2}$ for each pair of similar states $(q_1, q_2)$ from $V$. Which pair of invocation states corresponds to which procedure state is stored in the mapping $Q_{proc} : G_Q \rightarrow Q'$ to be later used by Algorithm \ref{alg:mapTransitions}, called on line \verb|10| to generate procedure transitions. In lines \verb|11-12|, the invocation states and their transitions that were used to create the procedure are removed from the automaton, as their functionality is now simulated by the procedure.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Generating Procedure Transitions
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% \vspace{-0.5em}
\subsection{Generating Procedure Transitions}
\vspace{-0.5em}
Algorithm \ref{alg:mapTransitions} creates procedure transitions.
Intuitively, we are replacing the original invocations, states $G_Q$, and incident transitions,
by a single procedure with the states $Q'$ and new transitions. The new transitions are supposed to simulate the original transitions of one invocation or the other depending on the register value, which is a symbol from one or the other invocation Id.
The rest of the section elaborates on the technical details of the implementation of this intuition.

Algorithm \ref{alg:mapTransitions} consists of five for-loops that generate five types of procedure transitions, each of them constructed from a different type of original invocation transition.
Lines \verb|2-7| generate new procedure transitions from \textit{invocation entry transitions}, lines \verb|8-16| from \textit{invocation exit transitions}, lines \verb|17-19| from \textit{invocation common transitions}, lines \verb|20-28| from \textit{invocation unique transitions}, and lines \verb|29-33| from \textit{invocation switch transitions}.
The function $pick$ is used to select an arbitrary element of a set.

\vspace*{-2em}

\begin{algorithmNoBottom}[!htp]
    \caption{createProcedureTransitions}
    \label{alg:mapTransitions}
    \footnotesize
    \DontPrintSemicolon
    \KwIn{SRA $A = (Q, \Sigma, \Gamma, \delta_{in}, I, F)$, similarity graph of $A$ as $G = (V \subseteq Q \times Q,E),$\\
    \hspace*{\widthof{\KwIn{}}}invocation state to invocation Id mapping $\mathit{Id} : G_Q \rightarrow 2^{\Gamma}$,\\
    \hspace*{\widthof{\KwIn{}}}invocation state to procedure state mapping $Q_{\mathit{proc}}: G_Q \rightarrow Q$}
    \KwOut{SRA $B = (Q, \Sigma, \Gamma, \algout{\delta}, I, F)$}
    \vspace*{0.1em}
    $B \gets A$\;
    % \vspace*{0.25em}
    \ForAll(\tcp*[f]{Paragraph Invocation Entry}){$r \crightarrow{$\{a, \alpha/\beta\}$} s \in \mathit{Entry}(G)$} {
        $s' \gets Q_{\mathit{proc}}(s)$\;
        \uIf(\tcp*[f]{new (Point 1)}){$\beta = \bot$} {
            $\beta' \gets \mathit{pick}(\mathit{Id}(s))$\;
            $\algout{\delta}.\mathit{add}(\transition{r}{a,\alpha/\beta'}{s})$\;

        }
        \textbf{else} {
            $\algout{\delta}.\mathit{add}(\transition{r}{a,\alpha/\beta}{s'})$\tcp*{copy (Point 2)}
        }
    }
    % \vspace*{0.25em}
    \ForAll(\tcp*[f]{Paragraph Invocation Exit}){$r \crightarrow{$\{a, \alpha/\beta\}$} s \in \mathit{Exit}(G)$} {
        $r' \gets Q_{\mathit{proc}}(r)$\;
        \uIf(\tcp*[f]{new (Point 1)}){$\alpha = \bot$} {
            $\alpha' \gets \mathit{pick}(\mathit{Id}(r))$\;
            $\algout{\delta}.\mathit{add}(\transition{r'}{a,\alpha'/\beta}{s})$\;
        } \uElseIf(\tcp*[f]{expand (Point 2)}){$\alpha = * \land \beta = *$} {
            \ForAll{$\eta \in \mathit{Id}(r)$} {
                $\algout{\delta}.\mathit{add}(\transition{r'}{a,\eta/\eta}{s})$\;
            }
        } \textbf{else} {
            $\algout{\delta}.\mathit{add}(\transition{r'}{a,\alpha/\beta}{s})$\tcp*{copy (Point 3)}
        }
    }

    % \vspace*{0.25em}
    \ForAll(\tcp*[f]{Paragraph Invocation Common}){$r \crightarrow{$\{a, \alpha/\beta\}$} s \in \mathit{Common}(G)$} {
        $r' \gets Q_{\mathit{proc}}(r), s' \gets Q_{\mathit{proc}}(s)$\;
        $\algout{\delta}.\mathit{add}(\transition{r'}{a,*/*}{s'})$\;
    }

    % \vspace*{0.5em}
    \ForAll(\tcp*[f]{Paragraph Invocation Unique}){$r \crightarrow{$\{a, \alpha/\beta\}$} s \in \mathit{Unique}(G)$} {
        $r' \gets Q_{\mathit{proc}}(r), s' \gets Q_{\mathit{proc}}(s)$\;
        \uIf(\tcp*[f]{new (Point 1)}){$\alpha = \bot \land \beta = \bot$} {
            $\eta \gets \mathit{pick}(\mathit{Id}(r))$\;
            $\algout{\delta}.\mathit{add}(\transition{r'}{a,\eta/\eta}{s'})$\;
        } \uElseIf(\tcp*[f]{expand (Point 2)}){$\alpha = * \land \beta = *$} {
            \ForAll{$\eta \in \mathit{Id}(r)$} {
                $\algout{\delta}.\mathit{add}(\transition{r'}{a,\eta/\eta}{s'})$\;
            }
        }
        \textbf{else} {
            $\algout{\delta}.\mathit{add}(\transition{r'}{a,\alpha/\beta}{s'})$\tcp*{copy (Point 3)}
        }
    }
\end{algorithmNoBottom}
\newpage
\begin{algorithmNoTop}[!htp]
    \vspace*{-0.25em}
    \DontPrintSemicolon
    \setcounter{AlgoLine}{28}
    % \vspace*{0.5em}
    \ForAll(\tcp*[f]{Paragraph Invocation Switch}){$r \crightarrow{$\{a, \alpha/\beta\}$} s \in \mathit{Switch}(G)$} {
        $r' \gets Q_{\mathit{proc}}(r), s' \gets Q_{\mathit{proc}}(s)$\;
        $\alpha' \gets \begin{cases}
                        \mathit{pick}(\mathit{Id}(r)) & \text{if } \alpha = \bot\hspace{5ex}\tcp*[f]{new}\\
                        \alpha & \text{otherwise}\hspace{3ex}\tcp*{copy}
                    \end{cases}$\;
        $\beta' \gets \begin{cases}
                        \mathit{pick}(\mathit{Id}(s)) & \text{if } \beta = \bot\hspace{5ex}\tcp*{new}\\
                        \beta & \text{otherwise}\hspace{3ex}\tcp*{copy}
                    \end{cases}$\;
        $\algout{\delta}.\mathit{add}(\transition{r'}{a,\alpha'/\beta'}{s'})$\;
    }
    % \vspace*{0.5em}
    \Return{$B$}
    \vspace*{-1.5em}
\end{algorithmNoTop}
