\section{Preliminaries}\label{preliminareis}



\subsection{Counting problems}\label{preCSP}
    %This article studies counting problems over a Boolean domain, where variables can only take values in $\{0,1\}$. 
      For a string $\alpha=\alpha_1\dots\alpha_k \in \{0,1\}^k$, the \textit{Hamming weight} of $\alpha$ is the number of $1$s in $\alpha$, denoted as $HW(\alpha)$. We use $\overline{\alpha}$ to denote the string that differs from $\alpha$ at every bit, which means $\alpha_i+\overline{\alpha}_i=1$ for each $1\le i\le k$. A \textit{signature}, or a \textit{constraint function}, is a function $f:\{0,1\}^k \to\mathbb{C}$ that maps a string of length $k$ to a complex number, where $k$ is denoted as the \textit{arity} of $f$.   A signature $f$ is said to be \textit{symmetric} if the value of $f$ depends only on the Hamming weight of the input. A symmetric signature $f$ of arity $k$ can be denoted as $[f_0,f_1,...,f_k]_k$, or simply $[f_0,f_1,...,f_k]$ when $k$ is clear from the context, where for $0\le i\le k$, $f_i$ is the value of $f$ when the Hamming weight of the input is $i$. For $c\in \mathbb{C}$, we also use the notation $c[f_0,f_1,...,f_k]$ to denote the signature $[cf_0,cf_1,...,cf_k]$. We use $\leq_T$ and $\equiv_T$ to respectively denote polynomial-time Turing reduction and equivalence. 

     We denote by $f^{x_i=c}$ the signature that pins the $i$th variable to $c\in\{0,1\}$:

     $$f^{x_i=c}(x_1,...,x_{i-1},x_{i+1},...,x_{k})=f(x_1,...,x_{i-1},c,x_{i+1},...,x_{k})$$
     For a string $\alpha\in \{0,1\}^q, q\le k$, we also define $f^\alpha=f^{x_1=\alpha_1,x_2=\alpha_2,...,x_q=\alpha_q}$, where $\alpha_i$ is the $i$th bit of $\alpha$ for $1\le i\le q$. That is, $f^\alpha$ is obtained from $f$ by pinning the first $q$ bits of $f$ to $\alpha_1,...,\alpha_q$. Equivalently speaking, $\alpha$ can be seen as an assignment to the $q$ variables $\alpha:\{1,\dots,q\}\to \{0,1\}$. In the case of a slight overuse, the notation $f^\alpha$ is sometimes employed to indicate the signature by pinning specific $q$ bits of $f$ to $\alpha_1,...,\alpha_q$ when the $q$ bits are clear from the context. 

    Two frameworks of counting problems, namely $\text{\#CSP}$ problem and $\text{Holant}$ problem, are of great significance as they are capable of expressing a wide range of problems. For example, problems in \cite{vertigan2005computational,cai2017holographic,cai2012spin,cai2012gadgets} can be expressed in the form of a $\text{\#CSP}$ problem and characterized by the result in \cite{guo2020complexity}. Furthermore, $\text{\#CSP}$ problem and $\text{\#PM}$ problem can be expressed in the form of $\text{Holant}$ problem. We present their definitions as follows.
    \subsubsection{\#PM}\label{PMstudy}
        For a graph $G=(V,E)$, a \textit{matching} is an edge set $M\subseteq E$ such that no pair of edges in $M$ shares a common endpoint.  Besides, if the vertices that $M$ contains are exactly $V(M)=V$, then $M$ is denoted as a \textit{perfect matching} of $G$.
        %i.e. $\forall e,f\in M, e\cap f=\emptyset$.

        An instance of \#PM is a graph $G=(V,E)$ with weighted edges $w:E\to \mathbb{C}$. The weight of a matching $M$ is $w(M)=\prod_{e\in M}w(e)$. The output of the instance is the sum of the weights of all perfect matchings in $G$:

        $$\text{\#PM}(G)=\sum_{M: M\text{ is a perfect matching of }G}w(M)$$
        When $w(e)=1$ for each $e\in E$, the output of the instance is just the number of perfect matchings in the graph, and we denote this kind of problems as standard \#PM.

       % The study of $\text{\#PM}$ has attracted considerable interest from two distinct perspectives. One is concerned with the complexity of $\text{\#PM}$ on different graph classes, whereas the other is focused on  the investigation of counting problems that are $\text{\#P}$-hard in general but polynomial-time computable on planar graphs.




     \subsubsection{\#CSP problems}
       A \textit{counting constraint satisfaction problem} $\text{\#CSP}(\mathcal{F})$ \cite{creignou2001complexity} requires the value of an instance, which is the sum of the values over all configurations. Here, $\mathcal{F}$ is a fixed and finite set of signatures. An instance of $\text{\#CSP}(\mathcal{F})$ is specified as follows:

      \begin{definition}
            An \textit{instance $I$ of $\text{\#CSP}(\mathcal{F})$} has $n$ variables and $m$ signatures from $\mathcal{F}$ depending on these variables. The value of the instance then can be written as

        $$Z(I)=\sum_{(x_1,...,x_n)\in \{0,1\}^n}\prod_{1\le i\le m} f_i(x_{i_1},...,x_{i_k})$$

        where $f_1,\dots,f_m$ are signatures in $I$ and $f_i$ depends on $x_{i_1},...,x_{i_k}$ for each $1\le i\le m$.
          \label{defCSP}
      \end{definition}
       %A \textit{configuration} of $I$ is an assignment of the values of all the variables. \textit{The value of a configuration} is the product of the values of all the signatures in the instance under the assignment.
        The \textit{underlying graph} of a $\text{\#CSP}(\mathcal{F})$ instance $I$ is a bipartite graph $G=(U,V,E)$, where for every constraint $f$ there is a $u_f\in U$, for every variable $x$ there is a $v_x\in V$, and $(u_f,v_x)\in E$ if and only if $f$ depends on $x$. Sometimes we also denote the value $Z(I)$ as $Z(G)$ for convenience. If each constraint function in $\mathcal{F}$ is restricted to be symmetric, we denote this kind of problem as symmetric \#CSP, or sym-\#CSP for short. 

        If we restrict the maximum degree of the vertices in $V$ to be no more than a constant $D$, this kind of problem is denoted as $\#R_D$-CSP in \cite{cai2014complexity}.
        If we restrict $G$ to be a planar graph with a certain planar embedding, in which the variables that $f_u$ depends are ordered counterclockwise for each $u\in U$, then we denote this problem as Pl-\#CSP.
        Pl-$\#R_D$-CSP is defined similarly.
        \begin{remark}  \label{remembd}
       It is worth noticing that $\text{Pl-\#CSP}(\mathcal{F})$ is not exactly $\text{\#CSP}(\mathcal{F})\langle \mathcal{PL}\rangle$ (\#CSP on planar graphs). In $\text{Pl-\#CSP}(\mathcal{F})$, it is not sufficient for the underlying graph of each instance to be planar; rather, each signature within the instance must also be positioned in an appropriate manner. %
   \end{remark}
        \subsubsection{Holant problems}
        A \textit{Holant problem} $\text{Holant}(\mathcal{F})$ can be seen as a $\text{\#CSP}(\mathcal{F})$ problem with the restriction that all the variables must appear exactly twice. 

        \begin{definition}
        An instance of $\text{Holant}(\mathcal{F})$ has an underlying graph $G=(V,E)$. Each vertex $v\in V$ is assigned a signature from $\mathcal{F}$ and each edge in $E$ represents a variable.  Here, $\mathcal{F}$ is a fixed set of signatures and usually finite. The signature assigned to the vertex $v$ is denoted as $f_v$. An assignment of $E$ is a mapping $\sigma:E\to \{0,1\}$, which can also be expressed as an assignment string $\sigma\in \{0,1\}^{|E|}$, and the value of the assignment is defined as

         $$\omega(\sigma)=\prod_{v\in V} f_v(\sigma)$$
        where $f_v(\sigma)=f_v(\sigma({e_{v_1}}),...,\sigma({e_{v_k}}))$ and $v$ is incident to $e_{v_1},...,e_{v_k}$.
        \par The output of the instance, or the value of $G$, is the sum of the values of all possible assignments of $E$, denoted as:

        $$Z(G)=\sum_{\sigma\in \{0,1\}^{|E|}}\omega(\sigma)$$ 
            \label{defHol}
        \end{definition}

        Furthermore, we use $\text{Holant}(\mathcal{F}_1|\mathcal{F}_2)$ represents $\text{Holant}(\mathcal{F}_1\cup \mathcal{F}_2)$ with the restriction that the underlying graph $G=(U,V,E)$ is bipartite, and each vertex $u\in U$ is assigned a signature from $\mathcal{F}_1$ while each vertex $v\in V$ is assigned a signature from $\mathcal{F}_2$.
         We denote by $\mathcal{EQ}$ the set of all equality functions. In other words, $\mathcal{EQ}=\{=_k|k\ge1\}$ where $=_k$ is the signature $[1,0,...,0,1]_k$. We also denote $\{=_k|1\le k\le D\}$ by $\mathcal{EQ}_{\le D}$ for each integer $D\ge 1$.  
         By definition, we have the following lemma. Also see Figure \ref{fig:CSPholant} for an example.
         \begin{lemma}
         Let $\mathcal{C}$ be an arbitrary graph class, $\mathcal{F}$ be an arbitrary signature set and $D\ge 1$ be an integer. Then,

             $$\text{\#CSP}(\mathcal{F})\langle \mathcal{C}\rangle\equiv_T\text{Holant}(\mathcal{F}|\mathcal{EQ})\langle \mathcal{C}\rangle$$ 
              $$\#R_D\text{-CSP}(\mathcal{F})\langle \mathcal{C}\rangle\equiv_T\text{Holant}(\mathcal{F}|\mathcal{EQ}_{\le D})\langle \mathcal{C}\rangle$$ 
             \label{lemcsp=hol}
         \end{lemma}


         Besides, standard \#PM is exactly $\text{Holant}(\{[0,1,0,...,0]_k|k\in \mathbb{N}^+\})$. Suppose that $G=(V,E)$ is a graph with each vertex of degree $k$ assigned $[0,1,0,...,0]_k$. For each  assignment $\sigma$ of $E$, $\omega(\sigma)$ can only be either 0 or 1 since the value of each signature can only provide a multiplier with value 0 or 1. Furthermore, $\omega(\sigma)=1$ if and only if all edges assigned the value 1 form a perfect matching of $G$. Consequently, we have \#PM$(G)=Z(G)$. In addition, by exchanging 0 and 1, standard \#PM can also be expressed as $\text{Holant}(\{[0,...,0,1,0]_k|k\in \mathbb{N}^+\})$. Similarly, \#PM is exactly $\text{Holant}(\{[0,...,0,1,0]_k|k\in \mathbb{N}^+\}|\{[1,0,c]|c\in \mathbb{C}\})$ since $\{[1,0,c]|c\in \mathbb{C}\}$ is capable of expressing the weight of each edge.
     \begin{figure}
            \centering
            \includegraphics[height=0.2\textheight]{CSPins.png}
            \caption{The underlying graph of a $\text{\#CSP}(\mathcal{F})$ instance if $f,g,h\in \mathcal{F}$ and $x,y,z$ are 3 variables; or that of a $\text{Holant}(\mathcal{F}|\mathcal{EQ})$ instance if we treat $x,y,z$ as $=_3,=_2,=_1$ and the edges as the variables instead.}
            \label{fig:CSPholant}
        \end{figure}







\subsection{Reduction methods}
%This section presents three kinds of common methods used in reductions in counting complexity.

\subsubsection{Constructing gadgets}

  A \textit{gadget} of $\text{Holant}(\mathcal{F})$ has an underlying graph $GG=(V,E,D)$, where $E$ is the set of normal edges and $D$ is the set of edges with only one endpoint, called \textit{dangling edges} \footnote{In order to differentiate from the notation of a graph, we use two capital letters to represent a gadget.}. Each vertex in $GG$ is still assigned a signature from $\mathcal{F}$. A signature $f$ of arity $|D|$ is said to be \textit{realized} by $GG=(V,E,D)$, if for each assignment $\alpha : D \to \{0,1\}$, $f(\alpha)=\sum_{\sigma\in \{0,1\}^{|E|}}\omega(\alpha\sigma)$, where $\alpha\sigma$ is the assignment of edges in $D\cup E$. In this case, we also say $f$ can be realized by $\mathcal{F}$. 
        By constructing gadgets with existing signatures, we are able to realize desired signatures.

        \begin{lemma}
            If $f$ can be realized by $\mathcal{F}$, then $\text{Holant}(\mathcal{F})\equiv_T\text{Holant}(\mathcal{F}\cup\{f\})$.
        \end{lemma}

        Also, we present some derivative concepts related to the concept of a gadget. A \textit{left-side gadget} of $\text{Holant}(\mathcal{F}_1|\mathcal{F}_2)$ has a bipartite underlying graph $GG=(U,V,E,D)$, where each vertex $u\in U$ is assigned a signature from $\mathcal{F}_1$, each vertex $v\in V$ is assigned a signature from $\mathcal{F}_2$, $E$ is the set of normal edges and $D$ is the set of dangling edges. Furthermore, the endpoint of each dangling edge must belong to $U$. It is easy to verify that, if $f$ can be realized by $GG$, then $\text{Holant}(\mathcal{F}_1|\mathcal{F}_2)\equiv_T\text{Holant}(\mathcal{F}_1\cup\{f\}|\mathcal{F}_2)$. The \textit{right-side gadget} is defined similarly except that the endpoint of each dangling edge must belong to $V$.

%        Besides, for a graph $G=(V,E)$ and $V'\subseteq V$, a \textit{gadget induced by} $V'$ is a gadget $GG=(V',E_{V'},D_{V'})$, where $E_{V'}=\{uv\in E|u,v\in {V'}\}$ and $D_{V'}$ contains a dangling edge connecting to $u\in {V'}$ for each edge in $\{uv\in E|u\in {V'},v\in V-{V'}\}$.  

\subsubsection{Holographic Transformation}
     Let $T$ be a binary signature, and we denote the two dangling edges corresponding to the input variables of it as a left edge and a right edge. Its value then can be written as a matrix $T=\begin{pmatrix}
          t_{00}&t_{01}\\
          t_{10}&t_{11}
      \end{pmatrix}$, where $t_{ij}$ is the value of $T$ when the value of left edge is $i$ and that of the right edge is $j$.


    This notation is conducive to the efficient calculation of the gadget's value. Let us consider two binary signatures, $T$ and $P$, with the right edge of $T$ connected to the left edge of $P$. $T$ and $P$ now form a binary gadget. Subsequently, it can be demonstrated that the value of the resulting gadget is precisely $TP$, which represents the matrix multiplication of $T$ and $P$.

      For a signature $f$ of arity $n$ and a binary signature $T$, we use $Tf/fT$ to denote the signature ``$f$ transformed by $T$'', which is a signature of arity $n$ obtained by connecting the right/left edge of $T$ to every dangling edge of $f$. For a set $\mathcal{F}$ of signatures, we also define $T\mathcal{F}=\{Tf|f\in \mathcal{F}\}$. Similarly we define $\mathcal{F}T$. The following theorem demonstrates the relationship between the initial and transformed problems: 
      \begin{theorem}[{Holographic Transformation}{\cite{valiant2008holographic,cai2007valiant}}]
          $Holant(\mathcal{F}|\mathcal{G}) \equiv_T Holant(\mathcal{F}T^{-1}|T\mathcal{G})$
          \label{thmHT}
      \end{theorem}
      Let $H_2=\begin{pmatrix}
          1&1\\
          1&-1
      \end{pmatrix}$. For a set of signatures $\mathcal{F}$, we use $\widehat{\mathcal{F}}$ to denote $H_2\mathcal{F}$. As $H_2^{-1}=\frac{1}{2}H_2$, by Theorem \ref{thmHT} we have:

      $$Holant(\mathcal{F}|\mathcal{G}) \equiv_T Holant(\widehat{\mathcal{F}}|\widehat{\mathcal{G}})$$

     We additionally present the following fact as a lemma for future reference.
     \begin{lemma}
         For each $k\ge 1$, $\widehat{=_k}=[1,0,1,0,1,0,\dots]_k$. For example, $\widehat{=_1}=[1,0], \widehat{=_2}=[1,0,1], \widehat{=_3}=[1,0,1,0]$. Consequently, $\widehat{\mathcal{EQ}}= \{[1,0,1,0,1,0,\dots]_k| k\ge 1\}$ and for an integer $D\ge 1$, $\widehat{\mathcal{EQ}_{\le D}}= \{[1,0,1,0,1,0,\dots]_k| 1\le k\le D\}$.
         \label{transEQ}
     \end{lemma}

\subsection{Matchgate signatures}
 \begin{definition}
          A matchgate is a planar graph $G=(V,E)$ with weighted edges $w:E\to \mathbb{C}$, and together with some external nodes $U\subseteq V$ on its outer face labelled by $\{1,2,...,|U|\}$ in a clockwise order. The signature $f$ of a matchgate $G$ is a Boolean signature of arity $|U|$ and for each $\alpha\in \{0,1\}^{|U|}$,

          $$f(\alpha)=\#PM(G-X),$$
          where $X\subseteq U$ and a vertex in $U$ with label $i$ belongs to $X$ if and only if the $i$th bit of $\alpha$ is 1.
          %In other words, if each vertex in $G$ of degree $k$ is assigned $[0,1,0,...,0]_k$, $f(\alpha)=Z(G^\alpha)=\#PM(G-X)$.
          \par A signature $f$ is a matchgate signature if it is the signature of some matchgate.
           $\mathscr{M}$ denotes all the matchgate signatures.
          \label{defMG}
      \end{definition}

      Some particularly useful properties of matchgates are as follows: 
      \begin{lemma}[\cite{cai2013matchgates}]
          A matchgate signature of arity $k$ can be realized by a matchgate with at most $O(k^4)$ vertices, which can be constructed in $O(k^4)$ time.
          \label{lemMG}
      \end{lemma}
          Furthermore, an algebraic representation of the matchgate signatures can be formulated.
      %This together with Definition \ref{defMG} give a complete definition of $\widehat{\mathscr{M}}$. 
\begin{theorem}[MGI]
    Suppose $f$ is a signature of arity $k$. Then $f$ is a matchgate signature if and only if the following identity, denoted as MGI, is satisfied:

    For each $\beta,\gamma\in\{0,1\}^k$, let $P=\{1\le j\le k| \beta_j\neq\gamma_j\}$, $l=|P|$. Let $p_j\in P$ be the $j$th smallest number in $P$ and let $e_{p_j}\in\{0,1\}^k$ denotes a string with a 1 in the $p_j$th index, and 0 elsewhere. Then

    $$\sum_{j=1}^n(-1)^jf(\beta\oplus e_{p_j})f(\gamma\oplus e_{p_j})=0$$
\end{theorem}











\section{Dichotomies for \#CSP}\label{sec:preprocessing}

\subsection{Previous results for \#CSP}
We introduce two more sets of signatures related to the dichotomies for \#CSP.
\begin{definition}
        A signature $f$ with arity $k$ is of \textit{affine type} if it has the form:
        $$\lambda\chi_{AX=b}\cdot \mathfrak{i}^{\sum_{1\le i\le n}a_i{x_i}^2+2\sum_{1\le i< j\le n} b_{ij}x_ix_j}$$
        where $\mathfrak{i}$ denotes the imaginary unit, $a_i,b_{ij}\in\{0,1\},\lambda\in \mathbb{C}$, $AX=b$ is a system of linear equations on $\mathbb{Z}_2$ and
        \begin{equation}
            \chi_{AX=b}=\begin{cases}
                1, & \text{if } AX=b; \\
                0, & \text{otherwise}.\notag
            \end{cases}
        \end{equation}
        \par $\mathscr{A}$ denotes the set of all the signatures of affine type.
        \label{defA}
    \end{definition}
       \begin{definition}
        A signature $f$ is an $\mathcal{E}$\textit{-signature} if it has value 0 except for 2 complementary supports. A signature $f$ with arity $k$ is of \textit{product type} if it can be expressed as a tensor product of $\mathcal{E}$-signatures.

        \par $\mathscr{P}$ denotes the set of all the signatures of product type.
         \label{defP}
    \end{definition}


      The existing dichotomy for \#CSP, $\#R_D$-CSP and Pl-\#CSP can be stated as follows:  
\begin{theorem}[\cite{cai2014complexity}]
        If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$, $\text{\#CSP}(\mathcal{F})$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.
        \label{genCSP}
    \end{theorem}

\begin{theorem}[\cite{cai2014complexity}]
        Suppose $D\ge 3$ is an integer. If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$, $\#R_D\text{-CSP}(\mathcal{F})$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.
        \label{genRDCSP}
    \end{theorem}



    \begin{theorem}[\cite{cai2017holographicuni}]
        If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$ or $\mathcal{F}\subseteq \widehat{\mathscr{M}}$, $\text{Pl-\#CSP}(\mathcal{F})$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.
        \label{plCSP}
    \end{theorem}

\subsection{Dichotomy for Pl-\#$R_D$-CSP}\label{sec:easyplrdcsp}

The dichotomy for Pl-$\#R_D$-CSP is stated as follows.

\begin{theorem} \label{plRDCSP}
    Suppose $D\ge3$ is an integer. If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$ or $\mathcal{F}\subseteq \widehat{\mathscr{M}}$, Pl-$\#R_D$-CSP$(\mathcal{F})$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.
\end{theorem}


We delay the full proof of Theorem \ref{plRDCSP} to Appendix \ref{sec:plrdcsp}, as it is similar to that of Theorem \ref{genRDCSP} originally presented in in \cite[Section 6]{cai2014complexity}. Here, we only remark the major differences between the two proofs.
\begin{itemize}
    \item All the gadgets in our proof are constructed in the setting of Pl-$\#R_D$-CSP instead of $\#R_D$-CSP;
    \item Unlike \cite[Lemma 6.5]{cai2014complexity}, we realize $[0,0,1]=[0,1]^{\otimes 2}$ instead of $[0,1]^{\otimes m}$ in Lemma  \ref{lem:plr3obtaind1};
    \item Unlike \cite[Lemma 6.2]{cai2014complexity}, instead of realizing a single non-degenerate binary signature $h$, we realize $h^{\otimes 2}$ and use them to form a non-degenerate binary signature $g=h^Th$ in Lemma \ref{lem:plr3obtainh}.
\end{itemize}






