    Now, we make a partition over all the pairings. We may assume that the number of stable points $2s$ is greater than, or equal to, the number of mutual point $2p-2s$. This is because $F$ remains a matchgate signature under the permutation $(234\dots (2p)1)$, and this permutation makes all the stable points become mutual and all the mutual points become stable. We use $\mathcal{M}_g$ to denote the set of all pairings of $\{b_1,\dots ,b_{2p}\}$ that contain exactly $g$ SS pairs and $\mathcal{M}_g'$ to denote the set of all pairings of $\{a_1,\dots ,a_{2p}\}$ that contain exactly $g$ SS pairs. We let $m_g=\sum_{M\in \mathcal{M}_g}(-1)^{c(M)}\prod_{b_ib_j\in M}F(a_ia_j)$ and $m_g'=\sum_{M\in \mathcal{M}_g'}(-1)^{c(M_\pi)}\prod_{a_ia_j\in M_\pi}F(a_ia_j)$. Using these notations, it is sufficient to demonstrate that
    \[\sum_{g=0}^s m_g=\sum_{g=0}^s m_g'\]

   If $S$ is a subset of $\{b_1,\dots,b_{2p}\}$, we use $\pi(S)$ to denote the set $\{a_i|b_i\in S\}$. Let $S_1,S_2$ be a partition of $\{b_1,\dots,b_{2p}\}$ and $S_1$ only contains stable points. We emphasize that except for the appearance of specific remark, the restriction that $S_1$ only contains stable points always exists in the following analysis, even though it is omitted in some summations using $S_1$ as a symbol. By Lemma \ref{lem:partcross}, we know that for arbitrary pairing $M_1$ of $S_1$ and $M_2$ of $S_2$, $c(M_1,M_2)\mod 2$ is a constant. Assume $S_1=\{b_{i_1},\dots,b_{i_{2q}}\}$ satisfying $b_{i_1}<\dots<b_{i_{2q}}$, by setting $M_1=\{b_{i_1}b_{i_2},\dots,b_{i_{2q-1}}b_{i_{2q}}\}$, we have 
    \begin{align*}
        &c(M_1,M_2)\mod 2\\
        =&\sum_{ab\in M_1} c(ab,M_2) \mod 2\\
        =&\sum_{j=1}^q {i_{2j}-i_{2j-1}-1}\mod 2\\
        =&\sum_{j=1}^q {i_{2j}+i_{2j-1}+1}\mod 2\\
        =&q+\sum_{j=1}^{2q} {i_{j}}\mod 2
    \end{align*}


    Similarly, we have $c(\pi(S_1),\pi(S_2))=q+\sum_{j=1}^{2q} {\tau(i_{j})}\mod 2$. Since all vertices in $S_1$ are stable, for each $1\le j\le 2q$, $i_j\mod 2=\tau(i_j)\mod 2$ and as a result $c(S_1,S_2)\mod 2=c(\pi(S_1),\pi(S_2))\mod 2$. 

    Now we define $\Omega(S_1)$ to be the summation over all pairings that can be separated into a pairing of $S_1$ and a pairing of $S_2$. $\Omega(S_1)$ can be written as the following form.
    \begin{align*}
        \Omega(S_1)=&\sum_{M:M=M_1\cup M_2, M_1,M_2\text{ is a pairing of } S_1,S_2\text{ respectively}}{(-1)^{c(M)}\prod_{b_ib_j\in M}F(b_ib_j)}\\
        =&\sum_{M:\dots\text{(same as the last line)}}{(-1)^{c(M_1)+c(M_2)+c(M_1,M_2)}\prod_{b_ib_j \in M_1} F(b_ib_j) \prod_{b_ib_j\in M_2} F(b_ib_j)}\\
        =&(-1)^{c(S_1,S_2)}(\sum_{M_1:M_1\text{ is a pairing of } S_1}{(-1)^{c(M_1)}\cdot\prod_{b_ib_j\in M_1}F(a_ia_j)})\\
        &\text{  \  \ \  \ \ }\cdot (\sum_{M_2:M_2\text{ is a pairing of } S_2}{(-1)^{c(M_2)}\prod_{b_ib_j\in M_2}F(a_ia_j)})\\
    \end{align*}

    If $S_1,S_2\neq \emptyset$, from the induction condition and the fact that $c(S_1,S_2)\mod 2=c(\pi(S_1),\pi(S_2))\mod 2$ we have
    \begin{align*}
        \Omega(S_1)=&(-1)^{c(S_1,S_2)}(\sum_{M:M\text{ is a pairing of } S_1}{(-1)^{c(M)}\cdot\prod_{b_ib_j\in M}F(a_ia_j)})\\
        &\text{  \  \ \  \ \ }\cdot (\sum_{N:N\text{ is a pairing of } S_2}{(-1)^{c(N)}\prod_{b_ib_j\in N}F(a_ia_j)})\\
        =&(-1)^{c(\pi(S_1),\pi(S_2))}(\sum_{M_\pi:M_\pi\text{ is a pairing of }\pi(S_1)}(-1)^{c(M_\pi)}\cdot\prod_{a_ia_j\in M_\pi}F(a_ia_j))\\
        &\text{  \  \ \  \ \ }\cdot (\sum_{N_\pi:N_\pi\text{ is a pairing of }\pi(S_2)}(-1)^{c(N_\pi)}\prod_{a_ia_j\in N_\pi}F(a_ia_j))\\
        =&\Omega(\pi(S_1))
    \end{align*}

    If we consider the summation $\sum_{|S_1|=2}\Omega(S_1)$, we can find that each pairing in $\mathcal{M}_g$ appears in the summation $g$ times. Consequently, we have\footnote{Here we also omit the restriction to $S_1$ that it is composed of stable points.\label{ft:omit}}
    \[\sum_{g=1}^s gm_g=\sum_{|S_1|=2}\Omega(S_1)=\sum_{|S_1|=2}\Omega(\pi(S_1))=\sum_{g=1}^s gm_g'\]  
    If $s=p$, all the points are stable points and $m_g=m_g'=0$ for each $0\le g\le s-1$. Then by this equation we also have $m_s=m_s'$ and complete the proof.

    Now we may assume $s<p$. Similarly, for each $1\le t\le s$, we can also get that\footref{ft:omit}
    \[\sum_{g=t}^s \binom{g}{t} m_g=\sum_{|S_1|=2t}\Omega(S_1)=\sum_{|S_1|=2t}\Omega(\pi(S_1))=\sum_{g=t}^s \binom{g}{t}m_g'\]
     We remark that the equation still holds when $t=s$ since $s<p$ and consequently $S_2\neq \emptyset$. These $s$ equations form a system whose coefficient matrix is an upper triangular matrix. As a result, this system implies that $m_g=m_g'$ for $g=1,\dots ,s$.

    If the number of stable points is strictly greater than the number of mutual point, then $\mathcal{M}_0=\emptyset$ and $m_0=m_0'=0$, which completes the proof.     
    Otherwise, $s=p/2$. We take two stable points and two mutual points as $S_1=\{b_{i_1},\dots,b_{i_4}\}$. We remark that although this selection of $S_1$ violates the restriction described above, $c(S_1,S_2)\mod 2=2+\sum_{j=1}^4 i_j\mod 2=2+2+\sum_{j=1}^4 \tau(i_j)\mod 2=c(\pi(S_1),\pi(S_2))$ still holds and the above analysis still works. Consequently, we have $\Omega(S_1)=\Omega(\pi(S_1))$. For a pairing in $\mathcal{M}_0$, each pair is a SM pair. Therefore, each pairing in $\mathcal{M}_0$ is counted $\binom{2s}{2}$ times in $\sum_{S_1}\Omega(S_1)$\footnote{Here the omitted restriction is that $S_1$ is composed of two stable points and two mutual points.}. For a pairing in $\mathcal{M}_g$, it is composed of $2s-2g$ SM pairs, $g$ SS pairs and $g$ MM pairs. Therefore, each pairing in $\mathcal{M}_g$  is counted $\binom{2s-2g}{2}+g^2$ times in $\sum_{S_1}\Omega(S_1)$. Consequently,
    \[\sum_{g=0}^s (\binom{2s-2g}{2}+g^2)m_g=\sum_{S_1}\Omega(S_1)=\sum_{S_1}\Omega(\pi(S_1))=\sum_{g=0}^s (\binom{2s-2g}{2}+g^2)m_g'\]
    As $m_g=m_g'$ for each $1\le g\le s$, $m_0=m_0'$.
\end{proof}

\subsection{Permutable matchgate signatures}\label{sec:easyMP}
\begin{definition}\label{def:MP}
    Suppose $f$ is a signature of arity $n$. For a permutation $\pi\in S_n$, we use $f_\pi$ to denote the signature

$$f_\pi(x_1,\dots,x_n)=f(\pi(x_1),\dots,\pi(x_n))$$
If for each $\pi\in S_n$, $f_\pi$ is a matchgate signature, we say $f$ is a permutable matchgate signature.

We use $\mathscr{M}_{P}$ to denote the set of all the permutable matchgate signatures.
\end{definition}

The following property can be easily verified.
  \begin{lemma}
        If $f$ is a permutable matchgate signature of arity $k$, then for arbitrary $1\le p\le k$ and $\alpha\in \{0,1\}^p$, $f^\alpha$ is also a permutable matchgate signature.
        \label{lemPin}
    \end{lemma}

The following theorem shows that $\mathscr{M}_{P}$ is closely related to the dichotomy for $\text{\#CSP}\langle \mathcal{PL}\rangle$ and $\#R_D\text{-CSP}\langle \mathcal{PL}\rangle$, which can be derived from Theorem \ref{plCSP} and \ref{plRDCSP} respectively.

\begin{theorem} \label{thmCSPpl}
    If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$ or $\mathcal{F}\subseteq \widehat{\mathscr{M}_P}$, $\text{\#CSP}(\mathcal{F})\langle \mathcal{PL}\rangle$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.

    If $\mathcal{F}\subseteq \mathscr{A}$ or $\mathcal{F}\subseteq \mathscr{P}$ or $\mathcal{F}\subseteq \widehat{\mathscr{M}_P}$, $\#R_D\text{-CSP}\langle \mathcal{PL}\rangle$ is computable in polynomial time; otherwise it is $\text{\#P}$-hard.
\end{theorem}
\begin{proof}
    Let $\mathcal{F'}=\{f_\pi|f\in \mathcal{F},\text{arity}(f)=n, \pi\in S_{n}\}$. By Remark \ref{remembd}, we have 

    $$\text{\#CSP}(\mathcal{F})\langle \mathcal{PL}\rangle\equiv_T\text{Pl-\#CSP}(\mathcal{F'})$$

    By Definitions \ref{defA} and \ref{defP}, $\mathcal{F'}\subseteq \mathscr{A}$ or $\mathscr{P}$ if and only if $\mathcal{F}\subseteq \mathscr{A}$ or $\mathscr{P}$ respectively. Furthermore,  $\mathcal{F'}\subseteq \widehat{\mathscr{M}}$ if and only if $\mathcal{F}\subseteq \widehat{\mathscr{M}_P}$ by Definition \ref{def:MP} and Theorem \ref{thmHT}. Consequently, we are done by replacing the tractable criteria for $\mathcal{F'}$ in Theorem \ref{plCSP} with those for $\mathcal{F}$. The same argument holds for $\#R_D\text{-CSP}\langle \mathcal{PL}\rangle$ as well.
\end{proof}

\subsection{Characterizations of permutable matchgate signatures}\label{sec:MpSymGad}
By Theorem \ref{lem:4andpiMG}, we can use the following property to characterize the permutable matchgate signature.

\begin{corollary}
    Suppose $F$ is a normalized matchgate signature of arity $n$. Then $F$ is a permutable matchgate signature if and only if for each $1\le a<b<c<d
    \le n$, $F(ab)F(cd)=F(ac)F(bd)=F(ad)F(bc)$.
    \label{coro:4MPequal}
\end{corollary}

\begin{proof}
    By Theorem \ref{lem:4andpiMG}, $F$ is a permutable matchgate signature if and only if for any permutation $\pi\in S(n)$ and integers $1\le a<b<c<d
    \le n$, $F_{\pi}(abcd)=F_{\pi}(ab)F_{\pi}(cd)-F_{\pi}(ac)F_{\pi}(bd)+F_{\pi}(ad)F_{\pi}(bc)$. Notice that $F(abcd)=F_{\pi}(\pi^{-1}(a)\pi^{-1}(b)\pi^{-1}(c)\pi^{-1}(d))$ also holds for arbitrary $\pi$, hence by taking different $\pi$, we have the following equation.

    \begin{align*}
        F(abcd)=&F(ab)F(cd)+F(ac)F(bd)-F(ad)F(bc)\\
        =&F(ab)F(cd)-F(ac)F(bd)+F(ad)F(bc)\\
        =&-F(ab)F(cd)+F(ac)F(bd)+F(ad)F(bc)
    \end{align*}
    which implies $F(ab)F(cd)=F(ac)F(bd)=F(ad)F(bc)$.

    On the other hand, if $F(ab)F(cd)=F(ac)F(bd)=F(ad)F(bc)$ holds for arbitrary $1\le a<b<c<d
    \le n$, then for any $\pi$, $F_{\pi}(abcd)=F(\pi(a)\pi(b))F(\pi(c)\pi(d))=F_{\pi}(ab)F_{\pi}(cd)-F_{\pi}(ac)F_{\pi}(bd)+F_{\pi}(ad)F_{\pi}(bc)$.
\end{proof}

Using the description above, we are able to classify and characterize the normalized permutable matchgate signatures in the following way.

\begin{lemma}
    For a normalized permutable matchgate signature $F$ of arity $n\ge 4$, one of the following holds:
    \begin{enumerate}
        \item (Pinning type) For any distinct $1\le a,b\le n$, we have $F(ab)=0$.
        \item (Parity type 1) There exist distinct $1\le a,b,c,d\le n$, such that $F(ab)F(cd)\neq 0$.
        \item (Parity type 2) There exist distinct $1\le a,b,c\le n$, such that $F(ab)F(ac)F(bc)\neq 0$.
        \item (Matching type) There exist distinct $1\le a,b,c,d\le n$, such that $F(bc),F(bd),F(cd)=0$, but $F(ab)\neq 0$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Suppose otherwise. As $F$ is not of Pinning type, there exists $1\le a,b\le n$ such that $F(ab)\neq 0$. Then for any distinct $1\le c,d \le n$ and $c,d\neq a,b$, if $F(cd)\neq 0$, $F$ is of Parity type 1, so we may assume $F(cd)=0$. 

    As $F$ is not of Parity type 1, $F(ac)F(bd)=F(ad)F(bc)=0$. As $F$ is not of Parity type 2, $F(ac)F(bc)=0$ and $F(ad)F(bd)=0$. Consequently, either $F(ac),F(ad)=0$, or $F(bc),F(bd)=0$. In either case $F$ is of Matching type, a contradiction.
\end{proof}
If $F$ is of Parity type 1, then there exist distinct $1\le a,b,c,d\le n$, such that $F(ac)F(bd)=F(ad)F(bc)=F(ab)F(cd)\neq 0$, and we have $F(ab)F(ac)F(bc)\neq 0$, indicating that $F$ is also of Parity type 2. Consequently, Parity type 1 and 2 can be concluded into a single type, denoted as \textit{Parity type}, in which each signature satisfy the condition of Parity type 2.
\begin{lemma}
    If $F$ is a normalized permutable matchgate signature of arity $n$ of Parity type, then there exist a function $G:\{1,\dots,n\}\to \mathbb{C}$ such that for any distinct $1\le a,b \le n$, $F(ab)=G(a)G(b)$.
    \label{lem:paritytypeproperty}
\end{lemma}

\begin{proof}
    As $F$ is of Parity type, there exist distinct $1\le a,b,c\le n$, such that $F(ab)F(ac)F(bc)\neq 0$.
    To avoid ambiguity, we use $\sqrt{F(ab)}$ to denote a specific complex number $r_{ab}$ satisfying $r_{ab}^2=F(ab)$. We also use $\sqrt{F(ab)F(ac)/F(bc)}$ to denote the complex number $\sqrt{F(ab)}\sqrt{F(ac)}/\sqrt{F(bc)}$. Let $G(a)=\sqrt{F(ab)F(ac)/F(bc)}\neq 0$, $G(b)=\sqrt{F(ab)F(bc)/F(ac)}$ and  $G(c)=\sqrt{F(ac)F(bc)/F(ab)}$.
    For each $1\le d\le n, d\neq a,b,c$, let $G(d)=F(ad)/G(a)$. Since $F(ab)F(ac)F(bc)\neq 0$, $G$ is well-defined.

    It is easy to verify that $F(ab)=G(a)G(b),F(ac)=G(a)G(c),F(bc)=G(b)G(c)$. For each $1\le d\le n, d\neq a,b,c$,

    $$G(a)G(d)=F(ad)$$
    $$G(b)G(d)=\frac{F(ad)G(b)G(c)}{G(a)G(c)}=\frac{F(ad)F(bc)}{F(ac)}=\frac{F(bd)F(ac)}{F(ac)}=F(bd)$$
  $$G(c)G(d)=\frac{F(ad)G(c)G(b)}{G(a)G(b)}=\frac{F(ad)F(bc)}{F(ab)}=\frac{F(cd)F(ab)}{F(ab)}=F(cd)$$

    For any distinct $1\le d,e\le n$ satisfying $d,e\neq a,b,c$,

    $$G(d)G(e)=\frac{F(ad)F(be)}{G(a)G(b)}=\frac{F(de)F(ab)}{F(ab)}=F(de)$$
\end{proof}
Now we analyze the property of normalized permutable matchgate signatures of Matching type.
\begin{lemma}
     Suppose $F$ is a normalized permutable matchgate signature of arity $n$ of Matching type. If $F$ is not of Parity type, then there exists an integer $1\le x\le n$ such that for any distinct $1\le s,t\le n$, if $s,t\neq x$, $F(st)=0$.
     Furthermore, if $2\le k\le n/2$ and $1\le b_1<\dots<b_{2k}\le n$, then $F(b_1\dots b_{2k})=0$.
     \label{lem:matchingtypeproperty}
\end{lemma}
\begin{proof}
Suppose otherwise. Since $F$ is of Matching type, there exist distinct $1\le a,b\le n$ such that $F(ab)\neq 0$. There are three possible cases.
\begin{enumerate}
    \item There exist distinct $1\le s,t\le n, s,t\neq a,b$ such that $F(st)\neq 0$. It is obvious that $a,b,s,t$ can serve as a certificate that $F$ is of Parity type 1.
    \item There exist distinct $1\le s,t\le n, s,t\neq a,b$ such that $F(as)F(bt)\neq 0$. Again, $a,b,s,t$ can serve as a certificate that $F$ is of Parity type 1.
    \item There exist $1\le s\le n, s\neq a,b$ such that $F(as)F(bs)\neq 0$. In this case, $a,b,s$ can serve as a certificate that $F$ is of Parity type 2.
\end{enumerate} 

In each case, $F$ is of Parity type, which is a contradiction.

By Lemma \ref{lem:MGvalue}, if $2\le k\le n/2$ and $1\le b_1<\dots<b_{2k}\le n$, then $F(b_1\dots b_{2k})=\sum_{M:M\text{ is a pairing of }\{b_1,\dots ,b_{2k}\}}{(-1)^{c(M)}\prod_{b_ib_j\in M}F(b_ib_j)}=0$, since for each $M$ of size greater than 2 there always exists $st\in M$ such that $s,t\neq x$. 
\end{proof}

\begin{theorem}\label{lem:SymGadRealize}
    Each permutable matchgate signature $F'$ of arity $n$ can be realized by a symmetric matchgate signature $g$ and $O(n)$ symmetric binary matchgate signatures up to a constant factor in the following way. 
    \begin{enumerate}
        \item If $F'$ is of Pinning type after normalization, then $h=[1,0,\dots,0]$ and $O(n)$ symmetric binary signatures $[0,1,0]$ can realize $F'$.
        \item If $F'$ is of Parity type after normalization, then $h=[1,0,1,0,\dots]$ or $[0,1,0,1,\dots]$ and the $O(n)$ symmetric binary signatures with the form $[1,0,y]$ or $[0,0,1]$ can realize $F'$.
        \item If $F'$ is of Matching type, not of Pinning type and not of Parity type after normalization, then $h=[0,1,0,0,\dots]$ and the $O(n)$ symmetric binary signatures with the form $[1,0,y]$ or $[0,1,0]$ can realize $F'$.
    \end{enumerate}
\end{theorem}
\begin{proof}
   Suppose $f$ (or the index expression $F$ of $f$) is a normalization of $F'$. For each case, we first realize $F$, then we analyze $F'$ through Lemma \ref{lem:normalize}. 

   If $F$ is of Pinning type, by Lemma \ref{lem:MGvalue} $f=[1,0,0,\dots,0]$. By Lemma \ref{lem:normalize}, $F'$ can be realized by connecting a $[0,1,0]$ signature to some variables of $F$. 

   If $F$ is of Parity type, by Lemma \ref{lem:paritytypeproperty} there exists a function $G$ such that for any distinct $1\le a,b\le n$, $F(ab)=G(a)G(b)$. Then we can use the following gadget to realize $F$: for each $1\le a\le n$, we connect a $[1,0,G(a)]$ signature to the $a$th variable of $h'=[1,0,1,0,\dots]$. By Lemma \ref{lem:normalize}, $F'$ can be realized by connecting a $[0,1,0]$ signature to some variables of $F$. 

   Now for some variables of $h'$, they are connected to a $[1,0,G(a)]$ signature, then a $[0,1,0]$ signature, where $a$ is the index of the variable. For each such variable, we replace the $[1,0,G(a)]$ with a $[0,1,0]$ and the $[0,1,0]$ with a $[G(a),0,1]$ respectively. The signature of the gadget remains the same after the replacement as  $\begin{pmatrix}
          1&0\\
          0&G(a)
      \end{pmatrix}\begin{pmatrix}
          0&1\\
          1&0
      \end{pmatrix}=\begin{pmatrix}
          0&1\\
          G(a)&0
      \end{pmatrix}=\begin{pmatrix}
          0&1\\
          1&0
      \end{pmatrix}\begin{pmatrix}
          G(a)&0\\
          0&1
      \end{pmatrix}$.

   Now consider the gadget formed by $h'=[1,0,1,0,\dots]$ and all the $[0,1,0]$ connecting to it. If there is an odd number of $[0,1,0]$ signatures, the signature of the gadget is $h=[0,1,0,1,\dots]$. If there is an even number of $[0,1,0]$ signatures, the signature of the gadget is $h=[1,0,1,0,\dots]$. For each $1\le a\le n$, the binary signature connecting to the $a$th variable of $h$ is either $[1,0,G(a)]$ or $[G(a),0,1]$, which has the form $[1,0,y]$ or $[0,0,1]$ up to a constant factor.

   If $F$ is of Matching type, not of Pinning type and not of Parity type, then by Lemma \ref{lem:matchingtypeproperty} there exists $1\le x\le n$ such that the following holds: for any distinct $1\le a,b\le n$, if $F(ab)\neq 0$, then $x\in \{a,b\}$. Let $G(x)=1$ and $G(a)=F(ax)$ for each $1\le a\le n, a\neq x$. It can be verified that the following gadget realize $F$: for each $1\le a\le n, a\neq x$, we connect a $[1,0,G(a)]$ signature to the $a$th variable of $h=[0,1,0,0,\dots]$; we also connect a $[0,1,0]$ signature to the $x$th variable. By Lemma \ref{lem:normalize}, $F'$ can be realized by connecting a $[0,1,0]$ signature to some variables of $F$, which completes the proof. Besides, if there are two $[0,1,0]$ connecting to the $x$th variable of $h$, we can remove them  without changing the signature of the gadget for future convenience. 
\end{proof}

We denote the gadget in the above lemma as the \textit{star gadget} $ST_F$ of $F$, and $h$ as the \textit{central signature} $h_F$ of $ST_F$.
For each $1\le a\le n$, all the binary signatures connecting to the $a$th variable of $h$ in a line form a gadget, and the signature of the gadget is denoted as the \textit{$a$th edge signature}.


\subsection{Realize symmetric signatures}\label{sec:Redctosym}
In this section, we prove the following lemma by gadget construction.  
\begin{theorem} \label{lem:AsymtoSym}
    For each signature $F\in \mathscr{M}_P-\mathscr{A}$ of arity $n$, a symmetric signature $g\in \mathscr{M}-\mathscr{A}$ can be realized by $\{F\}\mid\{[1,0],[1,0,1],[1,0,1,0]\}$ as a planar left-side gadget.
\end{theorem}
  We remark that $[1,0],[1,0,1],[1,0,1,0]\in \mathscr{M}$ and $\mathscr{M}$ is closed under gadget construction. Hence when proving the above lemma, we only need to ensure that the obtained $g$ is symmetric and does not belong to $\mathscr{A}$. 

  Besides, such $g$ must have one of the following forms:
\begin{lemma}[\cite{guo2020complexity}]
    Suppose $g\in \mathscr{M}-\mathscr{A}$ and is symmetric. Then $g$ has one of the following forms.
    \begin{enumerate}
        \item $[0,1,0,...,0]_k,k\ge3$;
        \item $[0,...,0,1,0]_k,k\ge3$;
        \item $[1,0,r], r^4\neq 0,1$;
        \item $[1,0,r,0,r^2,...]_k,k\ge3, r^2\neq 0,1$;
        \item $[0,1,0,r,0,r^2,...]_k,k\ge3, r^2\neq 0,1$.
    \end{enumerate}
    \label{M-Aform}
\end{lemma}

\begin{remark}
     In the following, we always construct the left-side gadget of $\text{Holant}(\{f\} | \{[1,0],[1,0,1],[1,0,1,0]\})$. For future convenience, whenever $uv$ is an edge and both $u$ and $v$ are assigned $f$ in a gadget, we actually mean that we replace $uv$ with $uw,wv$ where $w$ is assigned a $[1,0,1]$ signature in the gadget. Besides, if a gadget is formed by connecting two existing gadgets together, we also automatically replace the connecting edge $uv$ with $uw,wv$, where $w$ is assigned a $[1,0,1]$ signature. These operations would not change the signature of the gadget. Consequently, it can be verified that each obtained gadget always remains a left-side gadget in our following constructions.
     \label{remGadConstruct}
\end{remark}



If $F$ is of Pinning type, we have $F\in \mathscr{A}$ as $[1,0,0,0,\dots],[0,1,0]\in \mathscr{A}$ and $\mathscr{A}$ is closed under gadget construction. Consequently, $F$ is either of Parity type, or of Matching type and not of Parity type.


\subsubsection{Parity type case}
Suppose $F$ is of Parity type. By Theorem \ref{lem:SymGadRealize}, three kinds of binary signatures may connect to the central signature $h_F$ in the star gadget $ST_F$, which are $[1,0,0],[0,0,1]$ and $[1,0,y],y\neq 0$ respectively. Suppose $p$ $[1,0,0]$ and $q$ $[0,0,1]$ are connected to $h_F$. Then we have $F=F'\otimes [1,0]^{\otimes p}\otimes [0,1]^{\otimes q}$ where $F'\in\mathscr{M}_P-\mathscr{A}$ is also of Parity type. 

By assigning $n-p-q$ $[1,0]$ signature to $F'$, we realize $[1,0]^{\otimes p}\otimes [0,1]^{\otimes q}$. By assigning $[1,0]^{\otimes p}\otimes [0,1]^{\otimes q}$ back to $F$ again we can realize the $F'$ signature in a planar way. Consequently, we may assume all the signatures connected to $h_F$ has the form $[1,0,y],y\neq 0$ since we can eliminate all of the $[1,0]$s and $[0,1]$s by gadget construction. We also assume that for each $1\le a \le n$, the $a$th variable of $h_F$ is connected to the binary signature $[1,0,y_a]$.

\textbf{Case 1: $h_F=[1,0,1,0,\dots]$.} If $n=2$, $F$ is already symmetric and we are done. Now we assume $n\ge 3$. For distinct $1\le a,b\le n$, if we connect a $[1,0]$ signature to each variable of $F$ except for the $a$th and the $b$th one, we realize the $[1,0,y_ay_b]$ signature. If $(y_ay_b)^4\neq 1$, $[1,0,y_ay_b]\notin \mathscr{A}$ and we are done. 

Now we suppose for any distinct $1\le a,b\le n$, $(y_ay_b)^4=1$. For any distinct $1\le a,b,c\le n$, we have $y_a^8=(y_ay_b\cdot y_ay_c/y_by_c)^4=1$. If $y_a^4=1$ and $y_b^4=-1$, again we are done since $(y_ay_b)^4=-1\neq 1$. If for each $1\le a\le n$, $y_a^4=1$, then $[1,0,y_a]\in \mathscr{A}$. And since $[1,0,1,0,\dots]\in \mathscr{A}$ and $\mathscr{A}$ is closed under gadget construction, we have $F\in \mathscr{A}$, which is a contradiction. 

 Otherwise, for each $1\le a\le n$, $y_a^4=-1$. Let $\alpha=\sqrt{\ii}=e^{2\pi \ii/8}$, then $y_a=\pm\alpha,\pm\ii\alpha$, and $[1,0,y_ay_b]$ is either $[1,0,\ii]$ or $[1,0,-\ii]$. Notice that each element in $\{\pm\alpha,\pm\ii\alpha\}$ can become $\alpha$ by multiplying $\ii$ or $-\ii$ 0 to 3 times. Consequently, we may connect 0 to 3 $[1,0,\ii]$ or $[1,0,-\ii]$ to each variable of $F$ to get a gadget $ST$, such that after replacing $F$ with the gadget $ST_F$, each edge signature of the obtained star gadget $ST_F'$ is exactly $[1,0,\alpha]$. It can be then verified that, the signature of $ST$, which is also the signature of $ST_F'$, is exactly $[1,0,\ii,0,-1,0,-\ii,0,1,\dots]_{n}$. We are done since $[1,0,\ii,0,-1,0,-\ii,0,1,\dots]_{n}\notin \mathscr{A}$ when $n\ge 3$.

 \textbf{Case 2:$h_F=[0,1,0,1,\dots]$.} If $n=2$, we suppose $F(1)=1,F(2)=y$ despite the presence of a constant factor. In other words, $f=\begin{pmatrix}
          0&y\\
          1&0
      \end{pmatrix}$. Because $F\notin\mathscr{A}$, $y^4\neq 1$. By connecting the first variables of two $F$ signatures to each other, we realize $[1,0,y^2]$. If $y^8=(y^2)^4\neq 1$, we are done. Otherwise, $y=\pm\alpha,\pm\ii\alpha$. By connecting the second variables of three $F$ signatures to $[1,0,1,0]$, as shown in Figure \ref{fig:mod3}, we realize $[0,y^2,0,1]$, which is either $[0,\ii,0,1]\notin \mathscr{A}$ or $[0,-\ii,0,1]\notin \mathscr{A}$.

Otherwise, $n\ge 3$. For distinct $1\le a,b\le n$, if we connect a $[1,0]$ signature to each variable of $F$ except for the $a$th and the $b$th one, we realize the $\neq_2^{y_a,y_b}=\begin{pmatrix}
          0&y_b\\
          y_a&0
      \end{pmatrix}$ signature. By connecting the second variable of $\neq_2^{y_a,y_b}$ to the $a$th variable of $F$, we construct a gadget $GG_{F_a}$ whose signature is $F_a$. 

      Now we analyze the properties of $F_a$. By replacing $F$ with the corresponding star gadget $ST_F$ in $GG_{F_a}$, we obtain the gadget $ST_a$ with central signature $h_F=[0,1,0,1,\dots]$. For the $a$th variable of $h_F$, it is connected to a $[1,0,y_a]$ signature, then a $\neq_2^{y_a,y_b}$ signature. We replace the $[1,0,y_a]$ with $[0,1,0]$ and the $\neq_2^{y_a,y_b}$ with $[1,0,y_b]$ respectively. As $\begin{pmatrix}
          0&y_b\\
          y_a&0
      \end{pmatrix}\begin{pmatrix}
          1&0\\
          0&y_a
      \end{pmatrix}=\begin{pmatrix}
          0&y_ay_b\\
          y_a&0
      \end{pmatrix}=y_ay_b\begin{pmatrix}
          1&0\\
          0&1/y_b
      \end{pmatrix}\begin{pmatrix}
          0&1\\
          1&0
      \end{pmatrix}$, the signature of the gadget remains the same up to a constant factor after the replacement.  

      Now consider the gadget formed by $h_F=[0,1,0,1,\dots]$ and the $[0,1,0]$ connecting to the $a$th variable of it. The signature of the gadget is $h=[1,0,1,0,\dots]$, which means that $F_a$ belongs to Parity type Case 1. Consequently, we are done unless for each $1\le c\le n, c\neq a$, $y_c^4=1$. 

      By connecting the first variable of $\neq_2^{y_a,y_b}$ to the $b$th variable of $F$, we construct a gadget $GG_{F_b}$ whose signature is $F_b$. Similarly, we are done unless for each $1\le c\le n, c\neq b$, $y_c^4=1$. As a result, the only case left is that for each $1\le c\le n$, $y_c^4=1$. In this case, for each $1\le c\le n$, $[1,0,y_c]\in\mathscr{A}$. Since $[0,1,0,1,\dots]\in\mathscr{A}$ and $\mathscr{A}$ is closed under gadget construction, $F\in \mathscr{A}$, a contradiction.
