\subsection{Notations}



For each subject, the multi-channel \gls{eeg} signals are denoted by a 4-th order tensor. For source subjects, the available training data are represented by
\begin{equation}
    \{\boldsymbol{\mathcal{X}}^{S_n}\in \mathbb{R}^{N_f\times N_c\times N_s \times N_{sb}}\}_{n=1}^{N_{src}} \nonumber
\end{equation} 
with entries $\boldsymbol{\mathcal{X}}^{S_n}(i,p,q,h)\in \mathbb{R}$, where $n$ and $N_{src}$ denote the index and total number of source subjects, respectively. For the target subject, the available training data are represented by 
\begin{equation}
    \boldsymbol{\mathcal{X}}^{T_a}\in \mathbb{R}^{N_f\times N_c\times N_s \times N_{tb}} \nonumber
\end{equation} 
with entries $\boldsymbol{\mathcal{X}}^{T_{a}}(i,p,q,j)\in \mathbb{R}$. The indices and dimensions of tensors are defined as follows:
\begin{itemize}[label=\scalebox{0.7}{$\bullet$}]
    \item $i$ and $N_f$: The index and total number of stimuli.
    \item $p$ and $N_c$: The index and total number of channels.
    \item $q$ and $N_s$: The index and total number of samples.
    \item $h$ and $N_{sb}$: The index and total number of source blocks.
    \item $j$ and $N_{tb}$: The index and total number of target blocks.
\end{itemize}
For simplicity, we will use the source subject's tensor $\boldsymbol{\mathcal{X}}^{S_n}$ as an example to introduce the definition of notation. For the $n$-th source subject and $i$-th stimulus, a single trial in the $h$-th block is denoted as the 2-D matrix $\mathbf X_{i,h}^{S_n}=\boldsymbol{\mathcal{X}}^{S_n}(i,:,:,h)\in\mathbb{R}^{N_c\times N_s}$, trials from all blocks are denoted as $\mathbf X_i^{S_n}=\boldsymbol{\mathcal{X}}^{S_n}(i,:,:,:)\in\mathbb{R}^{N_c\times N_s \times N_{sb}}$, the individual template is the grand average across all blocks, i.e., $\bar{\mathbf X}_i^{S_n} = 1/N_{sb}\sum_{h=1}^{N_{sb}}\mathbf{X}_{i,h}^{S_n} \in \mathbb{R}^{N_c\times N_s}$, and their ground truth label is the visual stimulus frequency $f_i$. These rules of notation definition also apply to the target subject's tensor $\boldsymbol{\mathcal{X}}^{T_a}$.

In this study, we consider $N_f$ visual stimuli at frequencies $f_1, f_2,\ldots, f_{N_f}$. Given a test trial $\mathbf{\Tilde{X} }\in \mathbb{R}^{N_c\times N_s}$ from the target subject, we aim to recognize the corresponding stimulus frequency $\hat f\in \{f_1, f_2, \ldots, f_{N_f}\}$, using both training data from the target subject $\boldsymbol{\mathcal{X}}^{T_a}$ and source subjects $\{\boldsymbol{\mathcal{X}}^{S_n}\}_{n=1}^{N_{src}}$.

\subsection{\gls{itrca}}

\gls{itrca} is a transfer learning framework for \gls{ssvep} cross-subject recognition, incorporating both subject-general and subject-specific features. Inspired by the concept of instance-based transfer learning \cite{wang_2023_TF_WangJindong}, \gls{itrca} computes the \glspl{trc} of source subjects as source instances and then projects them into a latent space, where these source instances and the target subject's template exhibit maximal correlation. This latent space captures the underlying characteristics of SSVEP responses shared between source and target subjects, while accounting for the varying contributions of individual source subjects. Meanwhile, \gls{itrca} captures target subject's individual characteristics using \gls{trca}. The overall framework is illustrated in Fig. \ref{fig:iTRCA} and includes following steps.

\subsubsection{Compute the source instances} 
\gls{trc}, which is the single-channel signal spatially filtered from multi-channel \gls{eeg} signal based on \gls{trca} \cite{nakanishi_2017_TRCA}, is chosen as the instance of each source subject due to its low-dimensional nature and demonstrated effectiveness in recovering SSVEP characteristics \cite{tanaka_2020_gtrca, lan_2023_TransRCA}.

For the $n$-th source subject and $i$-th stimulus, the spatial filter $\mathbf{w}_i^{S_n}\in\mathbb{R}^{N_c}$ is invariant across different trials. First, the spatially filtered inter-trial covariance across all combinations is summed together


\begin{align}
        &\sum_{\substack{h_1,h_2=1 \\ h_2\neq h_1}}^{N_{sb}} 
            \mathrm{Cov}\left( (\mathbf{w}_i^{S_n})^{\mathsf{T}}\mathbf{X}_{i,h_1}^{S_n},(\mathbf{w}_i^{S_n})^{\mathsf{T}}\mathbf{X}_{i,h_2}^{S_n} \right) \nonumber
     \\ = & \sum_{\substack{h_1,h_2=1 \\ h_2\neq h_1}}^{N_{sb}} 
            (\mathbf{w}_i^{S_n})^{\mathsf{T}}   
            \mathrm{Cov}(\mathbf{X}_{i,h_1}^{S_n},\mathbf{X}_{i,h_2}^{S_n}) 
            \mathbf{w}_i^{S_n} \nonumber
     \\ = & (\mathbf{w}_i^{S_n})^{\mathsf{T}}
            \mathbf{S}_i^{S_n} 
            \mathbf{w}_i^{S_n},
\label{eq:inter-trial covariance}
\end{align}
where 
\begin{equation}
\begin{aligned}
     \mathbf{S}_i^{S_n} = \sum_{\substack{h_1,h_2=1 \\ h_2\neq h_1}}^{N_{sb}}  
                          \mathrm{Cov}(\mathbf{X}_{i,h_1}^{S_n},\mathbf{X}_{i,h_2}^{S_n}).
\end{aligned}
\end{equation}
Then, the variance of the spatially filtered signal is constrained to 1
\begin{align}
               & \sum_{h=1}^{N_{sb}} 
                 \mathrm{Cov}\left( (\mathbf{w}_i^{S_n})^{\mathsf{T}}\mathbf{X}_{i,h}^{S_n},(\mathbf{w}_i^{S_n})^{\mathsf{T}}\mathbf{X}_{i,h}^{S_n} \right) \nonumber
           \\ = & \sum_{\substack{h=1}}^{N_{sb}} 
                (\mathbf{w}_i^{S_n})^{\mathsf{T}}   
                 \mathrm{Cov}(\mathbf{X}_{i,h}^{S_n},\mathbf{X}_{i,h}^{S_n}) 
                 \mathbf{w}_i^{S_n} \nonumber 
           \\ = & (\mathbf{w}_i^{S_n})^{\mathsf{T}}
                 \mathbf{Q}_i^{S_n} 
                 \mathbf{w}_i^{S_n}  \nonumber 
           \\ = & 1, 
\label{eq:recovered trial variance}
\end{align}
where 
\begin{equation}
\begin{aligned}
     \mathbf{Q}_i^{S_n} = \sum_{\substack{h=1}}^{N_{sb}}  
                          \mathrm{Cov}(\mathbf{X}_{i,h}^{S_n},\mathbf{X}_{i,h}^{S_n}).
\end{aligned}
\end{equation}
The spatial filter $\mathbf{w}_i^{S_n}$ is computed by maximizing (\ref{eq:inter-trial covariance}) under the constraint (\ref{eq:recovered trial variance}), which is in the form of Rayleigh Quotient \cite{horn_2012_matrixAnalysis(RayleighRitz)}
\begin{equation}
    \mathbf{\hat w}_i^{S_n} 
    = \mathop{\arg\max}\limits_{\mathbf{w}_i^{S_n}} 
      \frac{(\mathbf{w}_i^{S_n})^{\mathsf{T}}\mathbf{S}_i^{S_n}\mathbf{w}_i^{S_n}}
           {(\mathbf{w}_i^{S_n})^{\mathsf{T}}\mathbf{Q}_i^{S_n}\mathbf{w}_i^{S_n}}.
\label{eq:Rayleigh Quotient}
\end{equation}
Therefore, the optimal spatial filter can be solved as the eigenvector of matrix $(\mathbf{Q}_i^{S_n})^{-1}\mathbf{S}_i^{S_n}$ corresponding to the largest eigenvalue. For simplicity, the calculation of $\mathbf{\hat w}_i^{S_n} $  from (\ref{eq:inter-trial covariance}) to (\ref{eq:Rayleigh Quotient}) is defined as the following function
\begin{equation}
    \mathbf{\hat w}_i^{S_n} = \mathrm{TRCA}(\mathbf{X}_i^{S_n}),
\label{eq:TRCA}
\end{equation}
where the input $\mathbf{X}_i^{S_n}$ represents all training trials for the $n$-th source subject and $i$-th stimulus.
The single-channel \gls{trc} $\mathbf{y}_i^{S_n}$ is extracted from the individual template $\mathbf{\Bar{X}}_i^{S_n}$
\begin{equation}
    \mathbf{y}_i^{S_n} =  (\mathbf{\hat w}_i^{S_n})^{\mathsf{T}} \mathbf{\Bar{X}}_i^{S_n} \in \mathbb{R}^{1\times N_s}.
\end{equation}
The \glspl{trc} from all source subjects are vertically concatenated as the source template, 
\begin{equation}   
\label{eq:source instances}
\mathbf{Y}_i^S = \left[\begin{array}{c} \mathbf{y}_i^{S_1} \\
                                        \mathbf{y}_i^{S_2} \\
                                          \vdots \\
                                \;\;\;\;\mathbf{y}_i^{S_{N_{src}}} \\
                       \end{array}\right] 
\in \mathbb{R}^{N_{src}\times N_s},
\end{equation}
which is the unified representation of source subjects.

