\TITLE{Towards Full-Scenario Safety Evaluation of Automated Vehicles: A Volume-Based Method}

\ARTICLEAUTHORS{%

\AUTHOR{Hang Zhou$^1$, Chengyuan Ma$^1$, Shiyu Shen$^2$, Zhaohui Liang$^1$, Xiaopeng Li\footnote{Corresponding author. Email: xli2485@wisc.edu}$^1$}
\AFF{$^1$ Department of Civil and Environmental Engineering, University of Wisconsin-Madison}
