    	    \centering
    	    \includegraphics[width=\textwidth]{figs/VECTOR/ideal_data_plot_r2}
    	    \caption{Parameter study of DDI with coefficient of determination $R^2$ for mechanical and material states depending on (a) the ratio of $N^*$ and number of quadrature points $N^\text{quad}$ times the number of snapshots $N^\text{snap}$ with prescribed pseudo stiffness tensor $\mathbb{C} := \SI{1}{\mega\pascal} \,\mathbbm 1$ as well as (b) the pseudo stiffness $C$ with number $N^* := \lceil  0.01 \cdot N^\text{quad}\cdot N^\text{snap}\rceil$ of material states.
    	    }
