    %% This declares a command \Comment
    %% The argument will be surrounded by /* ... */
    \SetKwComment{Comment}{/* }{ */}
    \SetKwInOut{Input}{Require}
    \SetKwInOut{Output}{Result}
    \RestyleAlgo{ruled}
    \DontPrintSemicolon
    \begin{table}
    % \centering
    \small
    % \caption{Plane-stress data-driven identification solver for the updated Lagrangian formulation}
    \begin{algorithm}[H]
    \label{alg:data-driven_updated_Lagrange}
    \caption{Plane-stress data-driven identification solver for the updated Lagrangian formulation}
    \BlankLine
    \BlankLine
    \Input{
    \textbullet ~ discretized  geometry under loading in the snapshots $\tau \in \{1, \dots, N^\text{snap}\}$ with numbered nodes
    \\
    \phantom{\textbullet ~} $\alpha \in \{1, \dots, N^\text{node}\}$ and numbered quadrature points $g \in \{1, \dots, N^\text{quad}\}$ of the linear elements
    \\
    \ \textbullet ~ connectivity encoded by ${}^\tau\!b_{\!abc}^{\alpha g}$
    \\
    \ \textbullet ~ nodal displacements ${}^\tau\!u_a^\alpha$ and nodal forces ${}^\tau\!\!f_a^\alpha$ with $\pi(\alpha) = 1$
    \\
    \ \textbullet ~ element area ${}^\tau\!\!J^g_{\!\!\vartriangle}$ and thickness ${}^\tau\!h^g$ in deformed configuration 
    \\
    \ \textbullet ~ number of material states $N^*$ and pseudo stiffness $c_{klmn}$
    }

    \BlankLine
    %\KwResult{Dehnungen $\varepsilon_e$ und Spannungen $\sigma_e$.}
    \Output{
    \textbullet ~ mechanical stresses ${}^\tau\!\sigma_{ab}^g$ and Lagrangian parameter ${}^\tau\!\eta_a^\alpha$
    \\
    \ \textbullet ~ database of material strains $e_{kl}^{*z}$ and stresses $\sigma_{ab}^{*z}$
    \\
    \ \textbullet ~ discrete mapping $s(g,\tau)$ between mechanical and material states
    \\
    \ \textbullet ~ nodal forces ${}^\tau\!\zeta_a^\beta$ with $\pi(\beta) = 0$ from equilibrium} 


    \hrulefill

    \BlankLine
    \BlankLine
    \textbf{(I)} $i = 0$. Calculate mechanical strains ${}^\tau\!e_{kl}^g$ from nodal displacements. Initialize discrete mapping $s(g,\tau)_{{}_{(i)}}$.

    %\Comment*[r]{This is a comment}

    \BlankLine
    \textbf{(II)} Solve the linear equation system for all $\sigma_{{ab}_{(i)}}^{*z}$ and ${}^\tau\!\eta_{c_{(i)}}^\alpha$:
    \begin{align}
    \label{eq:alg_snapshots_equation_UL_system_1}
    &\qquad - \sum_\tau\!\!\!\sum_{\substack{\alpha \\ \pi(\alpha) = 1}}\!\!\!\sum_g w^g {}^\tau\!\!J^g_{\!\!\vartriangle} {}^\tau\!h^g {}^\tau\!b_{\!abc}^{\alpha g} \ \delta_{s(g,\tau)_{{}_{(i)}}\!z} \ {}^\tau\!\eta_{{c}_{(i)}}^\alpha = 0\; ,
       \\ \label{eq:alg_snapshots_equation_UL_system_2}
       &\qquad \!\!\!\!\sum_{\substack{\beta \\ \pi(\beta) = 1}}\!\!\!\! \sum_g w^g {}^\tau\!\!J^g_{\!\!\vartriangle} {}^\tau\!h^g {}^\tau\!b_{\!abc}^{\alpha g} c_{abde} {}^\tau\!b_{\!de\!f}^{\beta g} {}^\tau\!\eta_{{\!f}_{\!(i)}}^\beta + \sum_g w^g {}^\tau\!\!J^g_{\!\!\vartriangle} {}^\tau\!h^g {}^\tau\!b_{\!abc}^{\alpha g} \ \delta_{s(g,\tau)_{{}_{(i)}}\!z} \ \sigma_{{ab}_{(i)}}^{*z} = {}^\tau\!\!f_c^\alpha \; .
    \end{align}

    \textbf{(III)} Calculate the mechanical stresses.
    \\
    \For{$\tau = 1,\dots, N^\mathrm{snap}$ $\text{\upshape and}$ $g = 1,\dots, N^\mathrm{quad}$}{
    \begin{align}
    \label{eq:alg_snapshots_equation_UL_update_stress}
    \qquad {}^\tau\!\sigma_{{ab}_{(i)}}^g = \sigma_{{ab}_{(i)}}^{*s(g,\tau)_{{}_{(i)}}} + \!\!\!\!\sum_{\substack{\alpha \\ \pi(\alpha) = 1}}\!\!\!\! c_{abcd} {}^\tau\!b_{\!cde}^{\alpha g} {}^\tau\!\eta_{{e}_{(i)}}^\alpha
    \end{align}
    }

    \BlankLine
    \BlankLine
    \textbf{(IV)} Calculate the material strains.
    \\
    \For{$z = 1,\dots, N^*$}{
    \begin{align}
    \label{eq:alg_snapshots_equation_UL_update_strain}
       \qquad e_{{kl}_{(i)}}^{*z} = \dfrac{1}{\sum\limits_\tau\sum\limits_g w^g {}^\tau\!\!J^g_{\!\!\vartriangle} {}^\tau\!h^g \delta_{s(g,\tau)_{{}_{(i)}}\!z}} \sum_\tau\sum_g w^g {}^\tau\!\!J^g_{\!\!\vartriangle} {}^\tau\!h^g \ \delta_{s(g,\tau)_{{}_{(i)}}\!z} \ {}^\tau\!e_{kl}^g
    \end{align}
    }

    \BlankLine
    \BlankLine
    \textbf{(V)} Update discrete mapping $s(g,\tau)_{{}_{(i)}}$.
    \\
    \For{$\tau = 1,\dots, N^\mathrm{snap}$ $\text{\upshape and}$ $g = 1,\dots, N^\mathrm{quad}$}{
    Select $\big(e_{{kl}_{(i+1)}}^{*z}, \sigma_{{ab}_{(i+1)}}^{*z}\big)$ closest to mechanical state $\big({}^\tau\!e_{{kl}_{(i)}}^g, {}^\tau\!\sigma_{{ab}_{(i)}}^g\big)$ with respect to loss function $L^\mathrm{UL}$.
    }

    \BlankLine
    \BlankLine
    \textbf{(VI)} Test for convergence.
    \\
    \uIf{$s(g,\tau)_{{}_{(i+1)}} = s(g,\tau)_{{}_{(i)}}$ $\text{\upshape for all}$ $\tau = 1, \dots, N^\mathrm{snap}$ $\text{\upshape and}$ $g = 1, \dots, N^\mathrm{quad}$}
    {
    $\text{\upshape Calculate unknown nodal forces ${}^\tau\!\zeta_a^\beta$ with $\pi(\beta) = 0$ from equilibrium, if requested.}$
    \\
    \textbf{exit}
    }
    \Else{
    $i \gets i + 1$, \textbf{goto} \textbf{(II)}.
    }
    \end{algorithm}
    \end{table}

