    \subsection{Adapted total Lagrangian DDI algorithm}\label{app:adapted_lagrange_ddi}

    The algorithm for the adapted total Lagrangian formulation of the data-driven identification is shown in Alg.~\ref{alg:data-driven_adapted_total_Lagrange}. Derivations of the corresponding equations are provided in Sect.~\ref{sec:ddi_total_lagrange}.
    The main difference to Alg.~\ref{alg:data-driven_updated_Lagrange} lies in the fact that the pseudo stiffness tensor at each quadrature point is variable, i.e. it depends on the deformation gradient. This leads, among other things, to a modified update step~\eqref{eq:alg_snapshots_equation_TL_update_strain} of the strains of the material states.

    %
    %% This declares a command \Comment
    %% The argument will be surrounded by /* ... */
    \SetKwComment{Comment}{/* }{ */}
    \SetKwInOut{Input}{Require}
    \SetKwInOut{Output}{Result}
    \RestyleAlgo{ruled}
    \DontPrintSemicolon
    \begin{table}
    % \centering
    \small
    % \caption{Plane-stress data-driven identification solver for the updated Lagrangian formulation}
    \begin{algorithm}[H]
    \label{alg:data-driven_adapted_total_Lagrange}
    \caption{Plane-stress data-driven identification solver for the adapted total Lagrangian formulation}
    \BlankLine
    \BlankLine
    \Input{
    \textbullet ~ discretized  geometry under loading in the snapshots $\tau \in \{1, \dots, N^\text{snap}\}$ with numbered nodes
    \\
    \phantom{\textbullet ~} $\alpha \in \{1, \dots, N^\text{node}\}$ and numbered quadrature points $g \in \{1, \dots, N^\text{quad}\}$ of the linear elements
    \\
    \ \textbullet ~ connectivity encoded by ${}^\tau\!B_{\!ABc}^{\alpha g}$
    \\
    \ \textbullet ~ nodal displacements ${}^\tau\!u_a^\alpha$ and nodal forces ${}^\tau\!\!f_a^\alpha$ with $\pi(\alpha) = 1$
    \\
    \ \textbullet ~ element area $J^g_{0,\vartriangle}$ and thickness $h^g_{0,\vartriangle}$ in undeformed configuration 
    \\
    \ \textbullet ~ number of material states $N^*$ and pseudo stiffness ${}^\tau C_{K\!L M\!N}^g$
    }

    \BlankLine
    %\KwResult{Dehnungen $\varepsilon_e$ und Spannungen $\sigma_e$.}
    \Output{
    \textbullet ~ mechanical stresses ${}^\tau T_{\!AB}^g$ and Lagrangian parameter ${}^\tau\!\eta_a^\alpha$
    \\
    \ \textbullet ~ database of material strains $E_{\!K\!L}^{*z}$ and stresses $T_{\!AB}^{*z}$
    \\
    \ \textbullet ~ discrete mapping $s(g,\tau)$ between mechanical and material states
    \\
    \ \textbullet ~ nodal forces ${}^\tau\!\zeta_a^\beta$ with $\pi(\beta) = 0$ from equilibrium} 


    \hrulefill

    \BlankLine
    \BlankLine
    \textbf{(I)} $i = 0$. Calculate mechanical strains ${}^\tau\!E_{\!K\!L}^g$ from nodal displacements. Initialize discrete mapping $s(g,\tau)_{{}_{(i)}}$.

    %\Comment*[r]{This is a comment}

    \BlankLine
    \textbf{(II)} Solve the linear equation system for all $T_{{\!AB}_{(i)}}^{*z}$ and ${}^\tau\!\eta_{c_{(i)}}^\alpha$:
    \begin{align}
    \label{eq:alg_snapshots_equation_TL_system_1}
    &\qquad - \sum_\tau\!\!\!\sum_{\substack{\alpha \\ \pi(\alpha) = 1}}\!\!\!\sum_g w^g J^g_{0,\vartriangle} h^g_{0,\vartriangle} {}^\tau\!B_{\!ABc}^{\alpha g} \ \delta_{s(g,\tau)_{{}_{(i)}}\!z} \ {}^\tau\!\eta_{{c}_{(i)}}^\alpha = 0\; ,
       \\ \label{eq:alg_snapshots_equation_UL_system_2}
       &\qquad \!\!\!\!\sum_{\substack{\beta \\ \pi(\beta) = 1}}\!\!\!\! \sum_g w^g J^g_{0,\vartriangle} h^g_{0,\vartriangle} {}^\tau\!B_{\!ABc}^{\alpha g} {}^\tau C_{\!A\!BD\!E}^g {}^\tau\!B_{\!D\!E\!f}^{\beta g} {}^\tau\!\eta_{{\!f}_{\!(i)}}^\beta + \sum_g w^g J^g_{0,\vartriangle} h^g_{0,\vartriangle} {}^\tau\!B_{\!ABc}^{\alpha g} \ \delta_{s(g,\tau)_{{}_{(i)}}\!z} \ T_{{\!AB}_{(i)}}^{*z} = {}^\tau\!\!f_c^\alpha \; .
    \end{align}

    \textbf{(III)} Calculate the mechanical stresses.
    \\
    \For{$\tau = 1,\dots, N^\mathrm{snap}$ $\text{\upshape and}$ $g = 1,\dots, N^\mathrm{quad}$}{
    \begin{align}
    \label{eq:alg_snapshots_equation_TL_update_stress}
    \qquad {}^\tau T_{{\!AB}_{(i)}}^g = T_{{\!AB}_{(i)}}^{*s(g,\tau)_{{}_{(i)}}} + \!\!\!\!\sum_{\substack{\alpha \\ \pi(\alpha) = 1}}\!\!\!\! {}^\tau C_{\!A\!B C\!D}^g {}^\tau\!B_{\!C\!Da}^{\alpha g} {}^\tau\!\eta_{{a}_{(i)}}^\alpha
    \end{align}
    }

    \BlankLine
    \BlankLine
    \textbf{(IV)} Calculate the material strains.
    \\
    \For{$z = 1,\dots, N^*$}{
    \begin{align}
    \label{eq:alg_snapshots_equation_TL_update_strain}
       \qquad E_{{\!K\!L}_{(i)}}^{*z} = \bigg(\sum\limits_\tau\sum\limits_g w^g J^g_{0,\vartriangle} h^g_{0,\vartriangle} {}^\tau C_{K\!L M\!N}^g\delta_{s(g,\tau)_{{}_{(i)}}\!z}\bigg)^{-1} \sum_\tau\sum_g w^g J^g_{0,\vartriangle} h^g_{0,\vartriangle} {}^\tau C_{\!M\!N\!PQ}^g {}^\tau\!E_{PQ}^g \delta_{s(g,\tau)_{{}_{(i)}}\!z}
    \end{align}
    }

    \BlankLine
    \BlankLine
    \textbf{(V)} Update discrete mapping $s(g,\tau)_{{}_{(i)}}$.
    \\
    \For{$\tau = 1,\dots, N^\mathrm{snap}$ $\text{\upshape and}$ $g = 1,\dots, N^\mathrm{quad}$}{
    Select $\big(E_{{\!K\!L}_{(i+1)}}^{*z}, T_{{\!AB}_{(i+1)}}^{*z}\big)$ closest to mechanical state $\big({}^\tau E_{{\!K\!L}_{(i)}}^g, {}^\tau T_{{\!AB}_{(i)}}^g\big)$ with respect to loss function $L^\mathrm{TL}$ with adapted pseudo stiffness.
    }

    \BlankLine
    \BlankLine
    \textbf{(VI)} Test for convergence.
    \\
    \uIf{$s(g,\tau)_{{}_{(i+1)}} = s(g,\tau)_{{}_{(i)}}$ $\text{\upshape for all}$ $\tau = 1, \dots, N^\mathrm{snap}$ $\text{\upshape and}$ $g = 1, \dots, N^\mathrm{quad}$}
    {
    $\text{\upshape Calculate unknown nodal forces ${}^\tau\!\zeta_a^\beta$ with $\pi(\beta) = 0$ from equilibrium, if requested.}$
    \\
    \textbf{exit}
    }
    \Else{
    $i \gets i + 1$, \textbf{goto} \textbf{(II)}.
    }

    \end{algorithm}
    \end{table}

