In both graphs of $\C$, $\{Z\}$ is a valid backdoor set. As a result, any causal query $P\left(y \mid \Do(x)\right)$ is identified by the formula $P\left(y \mid \Do(x)\right) = \sum_z P\left(y \mid x, z\right) P(z)$.

\end{example}

Identifiability by common backdoor in summary causal graphs has been studied in \citet{10.5555/3702676.3702683}, and was later extended into a complete criterion for identifiability by common adjustment by \citet{multivariateICA}. In a different framework, \citet{perkovic_complete_2018} established a sound and complete criterion for identifiability by common adjustment in Markov equivalence classes of ancestral graphs.

\section{Properties of Identifiability notions in collections of graphs}
\label{sec:prop} 

\subsection{A Property Valid for All Graphical Notions}

All notions of identifiability relying solely on the collection of graphs may be difficult to apply in practice because the collection \(\mathcal{C}\) can be very large. However, it is possible to reduce the size of \(\mathcal{C}\) without affecting the identifiability of the collection. Since edges in a graph represent dependencies, removing an edge preserves the graphical independences present in the original graph. This intuition is formalized in Lemma~\ref{lemma:Identifiabilite_et_inclusion}.


\begin{lemma}
    \label{lemma:Identifiabilite_et_inclusion}
    Let $\V$ denotes the set of observable variables. Let $\G_1$ and $\G_2$ be two causal diagrams on $\V$ and let \(\X,\Y,\Z\subseteq\V\) be pairwise disjoint. If $\G_2$ is a subgraph of $\G_1$, then the following propositions hold:
    \begin{enumerate}
        \item Any causal estimand valid in $\G_1$ for \(P\bigl(\mathbf{y}\mid \Do(\mathbf{x}),\,\mathbf{z}\bigr)\) is valid in $\G_2$ for \(P\bigl(\mathbf{y}\mid \Do(\mathbf{x}),\,\mathbf{z}\bigr)\).
        \item Any proof of do-calculus that holds in $\G_1$ also holds in $\G_2$.

        \item Any graphical criterion satisfied in $\G_1$ is satisfied in $\G_2$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    Let us prove the different points:
    \begin{enumerate}
        \item  Let $\F_1$ be a causal estimand valid in $\G_1$ for \(P\bigl(\mathbf{y}\mid \Do(\mathbf{x}),\,\mathbf{z}\bigr)\). Let $\M_2$ be an SCM inducing $\G_2$. By adding missing arguments in the structural functions of $\M_2$, we can construct an SCM $\M_1$ inducing $\G_1$ such that $P_{\M_1}(\V) = P_{\M_2}(\V)$ and $P_{\M_1} \bigl(\mathbf{y} \mid \Do(\mathbf{x}), \mathbf{z}\bigr) = P_{\M_2}\bigl(\mathbf{y} \mid \Do(\mathbf{x}), \mathbf{z}\bigr)$:

        Indeed, for all $V_i \in \V$, we know that $\Pa(V_i,\G_2) \subseteq \Pa(V_i,\G_1)$. For any variable $A$, let $\mathcal{X}_A$ denote its valuation space.
        We construct $\M_1$ by keeping the same exogenous variables $\U$, endogenous variables $\V$, and exogenous distribution $P(\U)$ as in $\M_2$, and by defining new structural functions $f_i^{(1)} \in \F_{\M_1}$ for each $V_i \in \V$ as:
        \[
        f_i^{(1)} :
        \begin{cases}
        \mathcal{X}_{\Pa(V_i,\G_1)} \times \mathcal{X}_{\U_i} \to \mathcal{X}_{V_i} \\
        (x_{\Pa(V_i,\G_1)}, u_i) \mapsto f_i^{(2)}(x_{\Pa(V_i,\G_2)}, u_i)
        \end{cases}
        \]
        where $f_i^{(2)} \in \F_{\M_2}$ is the corresponding structural function in $\M_2$. That is, $f_i^{(1)}$ coincides with $f_i^{(2)}$ and ignores the arguments in $\Pa(V_i,\G_1) \setminus \Pa(V_i,\G_2)$. As a result, $\M_1$ and $\M_2$ induce the same observational and interventional distributions, while $\M_1$ respects the structural dependencies encoded in $\G_1$.

        Hence, $\F_1(P_{\M_2}(\V)) = \F_1(P_{\M_1}(\V)) =  P_{\M_1}\bigl(\mathbf{y} \mid \Do(\mathbf{x}), \mathbf{z}\bigr) = P_{\M_2} \bigl(\mathbf{y} \mid \Do(\mathbf{x}), \mathbf{z}\bigr)$. Therefore, $\F_1$ is valid in $\G_2$.

        \item Since $\G_2$ is a subgraph of $\G_1$, every graphical independence that holds in $\G_1$ also holds in $\G_2$. Therefore, the proof of do-calculus also holds in $\G_2$.

        \item Since $\G_2$ is a subgraph of $\G_1$, every graphical independence that holds in $\G_1$ also holds in $\G_2$. Therefore, any graphical criterion satisfied in $\G_1$ is satisfied in $\G_2$.
    \end{enumerate}
\end{proof}

Lemma~\ref{lemma:Identifiabilite_et_inclusion} implies that, to determine identifiability through graphs in the collection $\mathcal{C}$, it is sufficient to consider only the maximal graphs in $\mathcal{C}$ (with respect to subgraph inclusion). This is formalized in Theorem~\ref{th:identifiabilite_et_elements_maximaux}.

\begin{theorem}
\label{th:identifiabilite_et_elements_maximaux}
Let $\mathcal{C}$ be a class of causal diagrams over a set of variables~$\mathcal{V}$, and let $\mathbf{X}, \mathbf{Y}, \mathbf{Z} \subseteq \mathcal{V}$ be pairwise disjoint. Let \(\C^{\max}\) denote the subcollection of maximal elements of \(\C\) under graph inclusion. Consider any graphical notion of identifiability as described above (i.e. IG, ICD, ICGC, ICB, ICF). Then the following propositions are equivalent:
\begin{enumerate}
    \item \(P\bigl(\mathbf{y}\mid \Do(\mathbf{x}),\,\mathbf{z}\bigr)\) is identifiable in $\mathcal{C}$.
    \item  \(P\bigl(\mathbf{y}\mid \Do(\mathbf{x}),\,\mathbf{z}\bigr)\) is identifiable in \(\C^{\max}\).
\end{enumerate}
\end{theorem}

\begin{proof}
To treat all identifiability notions uniformly, we define an \emph{identification object} as either a causal estimand, a do‐calculus proof, or a graphical criterion, and say it \emph{applies} to \(\G\) if it is valid in \(\G\), holds in \(\G\), or is satisfied in \(\G\), respectively. Let us prove the two implications:

%\begin{itemize}
     \textbf{(1)} $ \Rightarrow$ \textbf{(2)}:  
    Suppose \(P\bigl(\mathbf{y} \mid \Do(\mathbf{x}),\, \mathbf{z}\bigr)\) is identifiable in $\mathcal{C}$. \(\C^{\max}\) is a subcollection of $\C$. Hence, the query is identifiable in \(\C^{\max}\).\\

     \textbf{(2)} $\Rightarrow$ \textbf{(1)}:
    Suppose now that \(P(\mathbf{y}\mid\Do(\mathbf{x}),\mathbf{z})\) is identifiable in \(\C^{\max}\). By definition, there exists an identification object \(\theta^{\max}\) applying to every \(\G^{\max}\in\C^{\max}\). Let $\G$ be any causal diagram in $\C$. Then, by definition of maximality, there exists $\G^{\max} \in \C^{\max}$ such that $\G$ is a subgraph of $\G^{\max}$. By Lemma~\ref{lemma:Identifiabilite_et_inclusion}, \(\theta^{\max}\) also applies to \(\G\). Then the query is identifiable in \(\C\). 
%\end{itemize}
\end{proof}

Theorem~\ref{th:identifiabilite_et_elements_maximaux} shows that identifying a causal effect becomes computationally easier when the subcollection of maximal elements under graph inclusion is small. As formalized in Corollary~\ref{cor:single_max}, if this subcollection reduces to a singleton, then identifiability in the entire class $\mathcal{C}$ reduces to identifiability in a single graph. 

\begin{corollary}
\label{cor:single_max}
    If $\mathcal{C}$ contains a greatest element under graphical inclusion, then IG is equivalent to ICD.
\end{corollary}

This situation arises, for example, in Cluster DAGs \citep{anand_causal_2023}, where the partition admissibility assumption ensures that there is a unique maximal element under inclusion. Designing causal abstractions that induce few maximal elements therefore appears to be a good practice when aiming for tractable identifiability conditions.



