    \centering
    \includegraphics[width = 0.9 \linewidth]{TCAD_Figure/connection3.pdf}
    \vspace{-10pt}
    \caption{Illustration of newly established two-hop dataflow connection macro cluster-cell cluster-cell cluster.}
