    \centering
    \includegraphics[width=0.95\linewidth]{Figures/swerv-macro-cell-cell.pdf}
    \vspace{-5pt}
    \caption{Comparison between one-hop connected cell cluster (only macro cluster-cell cluster) and two-hop connected cell cluster (after considering macro cluster-cell cluster-cell cluster) in an example design {\tt swerv\_wrapper}. }
